INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收集材料后整理、撰写成书或文稿。", "primary_collocate": null, "pronunciation": "biān xiě", "ipa": "pjɛn˥ ɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他收集了很多资料，准备编写一本地方历史书。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们查了很多材料，才编写出这份报告。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了两年时间，编写了一本家乡的民间故事集。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们访问老人，再编写一份社区历史。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本科学小册子是几个人用了半年编写的。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把村里的老故事一个一个记下来，编写成书。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请了几位老师，一起编写校史。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先收集故事，然后编写了一本童话书。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编写这本手册之前，我们先看了很多资料。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她整理了二十年的笔记，编写出一本养花书。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编写了", "label": "完成体"}, {"form": "编写过", "label": "经历体"}, {"form": "编写者", "label": "复合"}, {"form": "編寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "先收集资料，再整理撰写成书或文稿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”的对象是食物，不能用于历史书。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”的宾语是水平、质量，不说“提高一本历史书”。"}, {"text": "编写", "is_correct": true, "explanation": "“编写”指把资料整理撰写成书，与“收集了很多资料”“地方历史书”相合。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”用于树枝、花草，不能用于历史书。"}], "explanations": {"烹饪": "语义：“烹饪”的对象是食物，不能用于历史书。", "提高": "搭配：“提高”的宾语是水平、质量，不说“提高一本历史书”。", "编写": "“编写”指把资料整理撰写成书，与“收集了很多资料”“地方历史书”相合。", "修剪": "语义：“修剪”用于树枝、花草，不能用于历史书。"}, "sentence_index": 0, "correct_answer": "编写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上都编写作业，很辛苦。", "explanation": "这里应该用〈写〉。作业是写出来的，“编写”指把材料整理成书或文稿。"}, {"text": "她每年冬天都为家人编写毛衣。", "explanation": "这里应该用〈编织〉。毛衣是用毛线编织出来的，“编写”用于书籍、文稿等资料。"}, {"text": "他又编写了一顿晚饭。", "explanation": "这里应该用〈做〉。晚饭是做出来的，“编写”指把材料整理成书或文稿，不能用于做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”的对象是植物，不能用于校史。"}, {"text": "腌制", "is_correct": false, "explanation": "语义：“腌制”的对象是食物，不能用于校史。"}, {"text": "编写", "is_correct": true, "explanation": "“编写”指把资料整理写成书，与“学校请了几位老师”“校史”相合。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”用于衣物，不说熨烫校史。"}], "explanations": {"浇灌": "语义：“浇灌”的对象是植物，不能用于校史。", "腌制": "语义：“腌制”的对象是食物，不能用于校史。", "编写": "“编写”指把资料整理写成书，与“学校请了几位老师”“校史”相合。", "熨烫": "搭配：“熨烫”用于衣物，不说熨烫校史。"}, "sentence_index": 6, "correct_answer": "编写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里编写饺子。", "explanation": "这里应该用〈包〉或〈煮〉。饺子是包出来、煮出来的，“编写”不能用于做饭。"}, {"text": "他在墙上编写了一幅壁画。", "explanation": "这里应该用〈绘制〉。壁画是用颜料绘制出来的，“编写”指把资料整理成文字或书籍。"}, {"text": "孩子们在沙滩上编写了一座城堡。", "explanation": "这里应该用〈搭〉。城堡是用沙子搭建出来的，“编写”不指堆砌或搭建实体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把资料编写到了一本手册。", "corrected_sentence": "老师把资料编写成了一本手册。", "error_description": "错误：“编写到”。应为“编写成”。“成”表示结果，即资料被整理成一本手册；“到”不能表示这种结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一个人把一本英语教材编写。", "corrected_sentence": "她一个人把一本英语教材编写完了。", "error_description": "错误：“把”字句中“编写”后缺少补语。应为“编写完了”。“完了”表示这本教材已经编写完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窗户", "is_correct": false, "explanation": "窗户是建筑的组成部分，与“美事”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头是自然物，与“美事”没有反义关系。"}, {"text": "坏事", "is_correct": true, "explanation": "坏事指令人不愉快的事，与“让人高兴的好事”意思相反。"}, {"text": "道理", "is_correct": false, "explanation": "道理指事物的规律或看法，与“美事”没有反义关系。"}], "correct_answer": "坏事", "explanations": {"窗户": "窗户是建筑的组成部分，与“美事”没有反义关系。", "石头": "石头是自然物，与“美事”没有反义关系。", "坏事": "坏事指令人不愉快的事，与“让人高兴的好事”意思相反。", "道理": "道理指事物的规律或看法，与“美事”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与“美事”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然物，与“美事”没有反义关系。"}, {"text": "图书", "is_correct": false, "explanation": "图书指书籍，与“美事”没有反义关系。"}, {"text": "坏事", "is_correct": true, "explanation": "坏事指令人不愉快的事，与“让人高兴的好事”意思相反。"}], "correct_answer": "坏事", "explanations": {"桌子": "桌子是家具，与“美事”没有反义关系。", "河流": "河流是自然物，与“美事”没有反义关系。", "图书": "图书指书籍，与“美事”没有反义关系。", "坏事": "坏事指令人不愉快的事，与“让人高兴的好事”意思相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "美事是让人高兴的好事。", "primary_collocate": null, "pronunciation": "měi shì", "ipa": "meɪ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老朋友多年后又见面，真是一件美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能和家人一起吃饭，对我来说就是美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为帮助别人是一件美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天去公园散步，真是人生一大美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你们要结婚了，这可是一件美事！", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在安静的下午喝茶看书，是我心里的美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，两家人成为亲戚是美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子考上了好学校，全家人都觉得这是美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们都说，儿女回家过年是最大的美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对大家都有好处，真是美事一桩。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}], "register": "中性", "sense_fingerprint": "让人高兴、称心的好事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错误", "is_correct": false, "explanation": "语义：“错误”指做得不对的地方，与老朋友见面的喜悦相反。"}, {"text": "美事", "is_correct": true, "explanation": "“美事”指令人高兴的好事，与“老朋友多年后又见面”的喜悦相合。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：“烦恼”让人苦恼，与句中“真是”所表达的高兴相反。"}, {"text": "糟心事", "is_correct": false, "explanation": "语义：“糟心事”指令人烦心的事，与句中“真是”所表达的喜悦相反。"}], "explanations": {"错误": "语义：“错误”指做得不对的地方，与老朋友见面的喜悦相反。", "美事": "“美事”指令人高兴的好事，与“老朋友多年后又见面”的喜悦相合。", "烦恼": "语义：“烦恼”让人苦恼，与句中“真是”所表达的高兴相反。", "糟心事": "语义：“糟心事”指令人烦心的事，与句中“真是”所表达的喜悦相反。"}, "sentence_index": 0, "correct_answer": "美事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天去公园散步，大家在湖边眺望美事。", "explanation": "这里应该用〈美景〉。眺望的对象是风景，“美事”指让人高兴的好事，不能眺望。"}, {"text": "春天去公园野餐，大家一起品尝美事。", "explanation": "这里应该用〈美食〉。品尝的对象是食物，“美事”不指吃的东西。"}, {"text": "春天去公园散步，身边走着一位美事。", "explanation": "这里应该用〈美人〉。“美人”指人，“美事”指事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丑闻", "is_correct": false, "explanation": "语义：“丑闻”指令人难堪的事，与“大家都说”的赞许不符。"}, {"text": "累赘", "is_correct": false, "explanation": "语义：“累赘”指多余而麻烦的东西，不能用来形容两家结亲。"}, {"text": "美事", "is_correct": true, "explanation": "“美事”指令人高兴的好事，与“两家人成为亲戚”的喜事相合。"}, {"text": "灾祸", "is_correct": false, "explanation": "语义：“灾祸”指重大的不幸，与“两家人成为亲戚”这件喜事正相反。"}], "explanations": {"丑闻": "语义：“丑闻”指令人难堪的事，与“大家都说”的赞许不符。", "累赘": "语义：“累赘”指多余而麻烦的东西，不能用来形容两家结亲。", "美事": "“美事”指令人高兴的好事，与“两家人成为亲戚”的喜事相合。", "灾祸": "语义：“灾祸”指重大的不幸，与“两家人成为亲戚”这件喜事正相反。"}, "sentence_index": 6, "correct_answer": "美事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的菜很好吃，大家都来品尝美事。", "explanation": "这里应该用〈美食〉。品尝的对象是食物，“美事”指让人高兴的好事，不能品尝。"}, {"text": "这个公园风景很好，大家都来欣赏美事。", "explanation": "这里应该用〈美景〉。欣赏的对象是风景，“美事”指让人高兴的好事，不是风景。"}, {"text": "这个女孩长得很漂亮，大家都说她是个美事。", "explanation": "这里应该用〈美人〉。“美人”指漂亮的人，“美事”指事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们都平安回家，真是一只美事。", "corrected_sentence": "孩子们都平安回家，真是一件美事。", "error_description": "错误：“一只美事”。应为“一件美事”。“只”用于动物或成对器官中的一个，“美事”要用“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都为他们俩高兴，这是一本美事。", "corrected_sentence": "大家都为他们俩高兴，这是一件美事。", "error_description": "错误：“一本美事”。应为“一件美事”。“本”用于书册，“美事”是事情，要用“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "钥匙", "is_correct": false, "explanation": "钥匙是开锁的工具，与“美事”没有反义关系。"}, {"text": "杯子", "is_correct": false, "explanation": "杯子是盛水的器具，与“美事”没有反义关系。"}, {"text": "坏事", "is_correct": true, "explanation": "坏事指令人不愉快的事，与“美好的事情”意思相反。"}, {"text": "树木", "is_correct": false, "explanation": "树木是植物，与“美事”没有反义关系。"}], "correct_answer": "坏事", "explanations": {"钥匙": "钥匙是开锁的工具，与“美事”没有反义关系。", "杯子": "杯子是盛水的器具，与“美事”没有反义关系。", "坏事": "坏事指令人不愉快的事，与“美好的事情”意思相反。", "树木": "树木是植物，与“美事”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "皮鞋", "is_correct": false, "explanation": "皮鞋是穿的物品，与“美事”没有反义关系。"}, {"text": "坏事", "is_correct": true, "explanation": "坏事指令人不愉快的事，与“美好的事情”意思相反。"}, {"text": "汽车", "is_correct": false, "explanation": "汽车是交通工具，与“美事”没有反义关系。"}, {"text": "河水", "is_correct": false, "explanation": "河水是自然界的水，与“美事”没有反义关系。"}], "correct_answer": "坏事", "explanations": {"皮鞋": "皮鞋是穿的物品，与“美事”没有反义关系。", "坏事": "坏事指令人不愉快的事，与“美好的事情”意思相反。", "汽车": "汽车是交通工具，与“美事”没有反义关系。", "河水": "河水是自然界的水，与“美事”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "美好的事情。", "primary_collocate": null, "pronunciation": "měi shì", "ipa": "meɪ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "生活里有很多小小的美事，让人心里暖暖的，要用心去发现。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每天遇到的美事都写在本子上。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起唱歌、跳舞，是人间美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后看到彩虹，是一件让人难忘的美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是跟我分享身边的美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读一本好书，也是一件安静的美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇里发生过不少美事，大家常常讲起。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在海边看日出，是旅行中的一件美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她相信，多做好事就会遇到更多美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的晚上，一家人坐着聊天，真是美事。", "target_word": "美事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}], "register": "中性", "sense_fingerprint": "生活中令人感到美好、愉快的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山川", "is_correct": false, "explanation": "体貌：山川体积庞大，不能用“小小的”形容。"}, {"text": "美事", "is_correct": true, "explanation": "“美事”指生活中令人美好、愉快的事，与“要用心去发现”相合。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”指不幸的事，与“美好”相反，不适合用心去发现。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，不是值得用心去发现的美好事情。"}], "explanations": {"山川": "体貌：山川体积庞大，不能用“小小的”形容。", "美事": "“美事”指生活中令人美好、愉快的事，与“要用心去发现”相合。", "灾难": "语义：“灾难”指不幸的事，与“美好”相反，不适合用心去发现。", "垃圾": "语义：“垃圾”是废弃物，不是值得用心去发现的美好事情。"}, "sentence_index": 0, "correct_answer": "美事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨后的山上，我们站在高处眺望美事。", "explanation": "这里应该用〈美景〉。眺望的对象是风景，“美事”指美好的事情，不能眺望。"}, {"text": "妈妈做了一桌美事，大家吃得很开心。", "explanation": "这里应该用〈美食〉。一桌饭菜是食物，“美事”不指吃的东西。"}, {"text": "她长得很漂亮，大家都说她是个美事。", "explanation": "这里应该用〈美人〉。“美人”指漂亮的人，“美事”指事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高山", "is_correct": false, "explanation": "搭配：“发生”的宾语应是事件，不说“发生高山”。"}, {"text": "农药", "is_correct": false, "explanation": "语义：“农药”是化学物质，不是可以发生或被大家讲起的事件。"}, {"text": "美事", "is_correct": true, "explanation": "“美事”指美好的事情，与“发生过不少”和“大家常常讲起”相合。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“河流”是自然物，不说“发生河流”。"}], "explanations": {"高山": "搭配：“发生”的宾语应是事件，不说“发生高山”。", "农药": "语义：“农药”是化学物质，不是可以发生或被大家讲起的事件。", "美事": "“美事”指美好的事情，与“发生过不少”和“大家常常讲起”相合。", "河流": "搭配：“河流”是自然物，不说“发生河流”。"}, "sentence_index": 6, "correct_answer": "美事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的晚上，一家人坐在阳台上眺望美事。", "explanation": "这里应该用〈美景〉。眺望的对象是风景，“美事”指好事，不能眺望。"}, {"text": "夏天的晚上，一家人坐在院子里品尝美事。", "explanation": "这里应该用〈美食〉。品尝的对象是食物，“美事”不指吃的东西。"}, {"text": "夏天的晚上，一家人坐在一起，身边坐着一位美事。", "explanation": "这里应该用〈美人〉。“美人”指人，“美事”指事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "和朋友久别重逢，是一块美事。", "corrected_sentence": "和朋友久别重逢，是一件美事。", "error_description": "错误：“一块美事”。应为“一件美事”。“块”用于块状的东西，“美事”要用“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一起种花，真是一张美事。", "corrected_sentence": "他们一起种花，真是一件美事。", "error_description": "错误：“一张美事”。应为“一件美事”。“张”用于平展的东西，“美事”要用“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
