INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96077, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "万一是说也许会发生，但是发生的可能很小。", "primary_collocate": null, "pronunciation": "wàn yī", "ipa": "wan˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "万一明天下雨，我们就在家看电影。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "带上伞吧，万一下雨呢？", "target_word": "万一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你多带点钱，万一路上有急事，也不怕。", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一我迟到了，你们先吃饭，不用等我。", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机要充满电，万一没电就麻烦了。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提前出门，万一路上堵车，也不会晚。", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一他今天不来，这个会就开不成了。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把门锁好，万一小偷进来就不好了。", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一你找不到我，就给我打电话。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次考试前都多检查几遍，万一有错呢？", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "连词，假设某事也许发生但可能性很小，多用于提醒防备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万一", "is_correct": true, "explanation": "万一表示可能性极小的假设，与“明天下雨”的语境相符。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，句中没有需要转折的前文，与假设关系不合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果结论，不能引出“明天下雨”这一假设条件。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示补充理由，需接在前文之后，不能在句首引出“明天下雨”这样的假设。"}], "explanations": {"万一": "万一表示可能性极小的假设，与“明天下雨”的语境相符。", "但是": "语义：“但是”表示转折，句中没有需要转折的前文，与假设关系不合。", "因此": "语义：“因此”表示因果结论，不能引出“明天下雨”这一假设条件。", "况且": "语义：“况且”表示补充理由，需接在前文之后，不能在句首引出“明天下雨”这样的假设。"}, "sentence_index": 0, "correct_answer": "万一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "万一每天都下雨，我们就每天在家吃饭。", "explanation": "这里应该用〈要是〉。万一只用于不太可能发生的假设，不能表示经常发生的条件；每天如此要说要是。"}, {"text": "万一他一定会迟到，我们就先走吧。", "explanation": "这里应该用〈既然〉。万一只用于可能性很小的假设，与“一定会”矛盾；已确定的情况要说既然。"}, {"text": "万一天气不好，我们取消了活动。", "explanation": "这里应该用〈因为〉。万一表示假设，不能用于叙述已经发生的原因；说明实际原因要用因为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万一", "is_correct": true, "explanation": "万一表示可能性极小的假设，与“他今天不来”的语境相符。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，前文没有需要转折的内容，句子不通。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”表示递进，需接在并列或递进的前文之后，句首直接引出假设不成立。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示时间先后，与“这个会就开不成了”的假设关系不合。"}], "explanations": {"万一": "万一表示可能性极小的假设，与“他今天不来”的语境相符。", "不过": "语义：“不过”表示转折，前文没有需要转折的内容，句子不通。", "而且": "搭配：“而且”表示递进，需接在并列或递进的前文之后，句首直接引出假设不成立。", "然后": "语义：“然后”表示时间先后，与“这个会就开不成了”的假设关系不合。"}, "sentence_index": 6, "correct_answer": "万一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "万一明天肯定会下雨，我们就带伞吧。", "explanation": "这里应该用〈既然〉。万一只用于可能性很小的假设，与“肯定会”矛盾；已确定的情况要说既然。"}, {"text": "万一他每天都练琴，就能弹好钢琴了。", "explanation": "这里应该用〈只要〉。万一只用于可能性很小的假设，不能表示只要做到就有结果的一般条件；这里要说只要。"}, {"text": "万一他生病了，所以今天没来上班。", "explanation": "这里应该用〈由于〉。万一表示假设，不能用于说明已经发生的原因；实际原因要说由于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "万一手机万一没电了，就用我的充电宝。", "corrected_sentence": "万一手机没电了，就用我的充电宝。", "error_description": "错误：“万一”重复，“万一手机万一没电了”；正确：“万一手机没电了”。“万一”只引出一次假设，同一分句中不能叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "万一下大雨，我们就万一改去室内看展。", "corrected_sentence": "万一下大雨，我们就改去室内看展。", "error_description": "错误：“万一”重复，同一结果分句中出现了两个“万一”；正确：只用一个，即“万一下大雨，我们就改去室内看展。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
