INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96078, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示可能性极小的假设；也指意外的变故。", "primary_collocate": null, "pronunciation": "wàn yī", "ipa": "wan˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "万一出了事，谁来负责？", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车要小心，万一出事就晚了。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "万一飞机晚点，我们就改坐火车吧。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "万一我生病了，你能帮我照顾孩子吗？", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一老板不同意，我们该怎么办？", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕万一失败，所以不敢试。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "万一钥匙丢了，你可以去找房东拿备用的。", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一下大雪，路上很危险，你别开车去。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们多买一点吃的，万一客人来得多呢。", "target_word": "万一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一电脑坏了，所有的资料都会不见。", "target_word": "万一", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "连词，提出可能性极小的假设，担心出现意外或不好的变故", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万一", "is_correct": true, "explanation": "万一表示可能性极小的意外，与“出了事”的语境相符。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结论，不能引出“出了事”这一假设，句子语义不通。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示时间先后，与“谁来负责”的追问不搭。"}, {"text": "况且", "is_correct": false, "explanation": "语域：“况且”多用于说理补充，用在这种突然的追问里不自然。"}], "explanations": {"万一": "万一表示可能性极小的意外，与“出了事”的语境相符。", "所以": "语义：“所以”表示因果结论，不能引出“出了事”这一假设，句子语义不通。", "然后": "语义：“然后”表示时间先后，与“谁来负责”的追问不搭。", "况且": "语域：“况且”多用于说理补充，用在这种突然的追问里不自然。"}, "sentence_index": 0, "correct_answer": "万一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "万一太阳从东边升起来，我们就出发。", "explanation": "这里应该用〈等〉。太阳从东边升起是一定会发生的事，不能用表示极小可能性的“万一”；说必然要发生的事用“等”。"}, {"text": "万一明天必然下雨，我们就取消野餐。", "explanation": "这里应该用〈若是〉。万一只用于可能性很小的假设，与“必然”矛盾；确定会发生的情况要说若是。"}, {"text": "万一雨下得很大，所以运动会取消了。", "explanation": "这里应该用〈由于〉。万一表示假设，不能用于说明已经发生的原因；实际原因要说由于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万一", "is_correct": true, "explanation": "万一表示可能性极小的假设，与“钥匙丢了”的语境相符。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，前文没有需要转折的内容，句子不通。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进，前文没有并列或递进的基础，接在句首不通。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结论，前文没有原因可接，句首直接接“钥匙丢了”不通。"}], "explanations": {"万一": "万一表示可能性极小的假设，与“钥匙丢了”的语境相符。", "不过": "语义：“不过”表示转折，前文没有需要转折的内容，句子不通。", "而且": "语义：“而且”表示递进，前文没有并列或递进的基础，接在句首不通。", "所以": "语义：“所以”表示因果结论，前文没有原因可接，句首直接接“钥匙丢了”不通。"}, "sentence_index": 6, "correct_answer": "万一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "万一他确定会来，我们就多买些菜吧。", "explanation": "这里应该用〈如果〉。万一只用于可能性很小的假设，与“确定会”矛盾；确定会发生的情况要说如果。"}, {"text": "万一他昨天生病了，所以没来上课。", "explanation": "这里应该用〈因为〉。万一表示对未发生的事的假设，不能说明已经发生的原因；说明原因要用“因为”。"}, {"text": "万一春天到了，花就都开了。", "explanation": "这里应该用〈等〉。春天一定会到，不能用表示极小可能性的“万一”；说必然要发生的事用“等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "万一出了车祸，万一保险公司会赔偿。", "corrected_sentence": "万一出了车祸，保险公司会赔偿。", "error_description": "错误：“万一”重复，“万一保险公司会赔偿”；正确：“万一出了车祸，保险公司会赔偿”。“万一”只引出一次假设，后一分句不能再用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "万一保险单万一找不到呢？", "corrected_sentence": "万一保险单找不到呢？", "error_description": "错误：“万一”重复，同一分句中出现了两个“万一”；正确：只用一个，即“万一保险单找不到呢？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
