INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "着法是下棋时走的一步。", "primary_collocate": null, "pronunciation": "zhāo fǎ", "ipa": "ʈʂau˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这步着法很聪明。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了一个好着法，我输了。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个着法不对。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时，每一个着法都要想清楚。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的最后一个着法让对手很吃惊。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋里有一个着法很特别。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这个着法，你能说说吗？", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷想了很久，才走出这个着法。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个着法太冒险，对手很容易赢。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个着法一走，黑棋就没有办法了。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "下棋时走的一步棋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "着法", "is_correct": true, "explanation": "正确：着法指下棋时走的一步，即听到的 zhāo fǎ。"}, {"text": "章法", "is_correct": false, "explanation": "zhāng（第一声）与 zhāo 韵母不同（ang 与 ao），意思是文章或做事的条理。"}, {"text": "刀法", "is_correct": false, "explanation": "dāo 与 zhāo 声母不同（d 与 zh），意思是刀的运用技法。"}, {"text": "烧法", "is_correct": false, "explanation": "shāo 与 zhāo 声母不同（sh 与 zh），意思是烧制的方法。"}], "explanations": {"着法": "正确：着法指下棋时走的一步，即听到的 zhāo fǎ。", "章法": "zhāng（第一声）与 zhāo 韵母不同（ang 与 ao），意思是文章或做事的条理。", "刀法": "dāo 与 zhāo 声母不同（d 与 zh），意思是刀的运用技法。", "烧法": "shāo 与 zhāo 声母不同（sh 与 zh），意思是烧制的方法。"}, "sentence_index": null, "correct_answer": "着法"}, "level_3": {"options": [{"text": "着法", "is_correct": true, "explanation": "正确：“这步”量的是一步走法，“着法”指下棋时走的一步，可以说“很聪明”。"}, {"text": "棋子", "is_correct": false, "explanation": "搭配：“这步”量的是走法，不能量“棋子”，“棋子”也不说“很聪明”。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是放棋子的器具，不是走的一步，不能“很聪明”。"}, {"text": "棋局", "is_correct": false, "explanation": "语义：棋局指整盘棋的形势，不是一步，“这步棋局”说不通。"}], "explanations": {"着法": "正确：“这步”量的是一步走法，“着法”指下棋时走的一步，可以说“很聪明”。", "棋子": "搭配：“这步”量的是走法，不能量“棋子”，“棋子”也不说“很聪明”。", "棋盘": "语义：棋盘是放棋子的器具，不是走的一步，不能“很聪明”。", "棋局": "语义：棋局指整盘棋的形势，不是一步，“这步棋局”说不通。"}, "sentence_index": 0, "correct_answer": "着法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃掉了对方一个着法，这盘棋就赢了。", "explanation": "这里应该用〈棋子〉。着法是一步走法，是抽象的，不能被“吃掉”，只有棋子可以。"}, {"text": "我的着法被将死了，这盘棋就输了。", "explanation": "这里应该用〈王〉。着法是一步走法，不会被将死，只有王才会被将死。"}, {"text": "他的着法很甜，大家都想尝一尝。", "explanation": "这里应该用〈点心〉。着法没有味道，不能说“很甜”，只有食物才有甜味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着法", "is_correct": true, "explanation": "正确：“看不懂”的是一步走法，可以请人“说说”它的道理。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看不懂”针对可以理解的东西，不说“看不懂味道”，味道要说“尝”。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是听的，不是看的，不能“看不懂”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是数值，不存在“看不懂”的问题，也不需要请人“说说”。"}], "explanations": {"着法": "正确：“看不懂”的是一步走法，可以请人“说说”它的道理。", "味道": "搭配：“看不懂”针对可以理解的东西，不说“看不懂味道”，味道要说“尝”。", "歌声": "语义：歌声是听的，不是看的，不能“看不懂”。", "温度": "语义：温度是数值，不存在“看不懂”的问题，也不需要请人“说说”。"}, "sentence_index": 6, "correct_answer": "着法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按下了着法，然后认真想下一步。", "explanation": "这里应该用〈棋钟〉。着法是抽象的走法，不是能按下的机器，不能“按下”。"}, {"text": "他擦干净了着法，又开始下棋。", "explanation": "这里应该用〈棋盘〉。着法没有实体，不能被擦干净，只有棋盘可以。"}, {"text": "我打败了着法，赢得了比赛。", "explanation": "这里应该用〈对手〉。着法不是有意志的对象，不能被打败，只有对手可以。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对手这只着法很特别，我没有想到。", "corrected_sentence": "对手这步着法很特别，我没有想到。", "error_description": "错误形式：“这只着法”；正确形式：“这步着法”。“只”多用于动物、手等，而着法是一步走法，应用量词“步”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看出了对手这一块着法的漏洞。", "corrected_sentence": "他看出了对手这一步着法的漏洞。", "error_description": "错误形式：“这一块着法”；正确形式：“这一步着法”。“块”多用于成块的东西，着法是一步走法，应用量词“步”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
