INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96080, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下棋的步骤或招数；也指办法。", "primary_collocate": null, "pronunciation": "zhāo fǎ", "ipa": "ʈʂau˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的下棋着法很多，我学不完。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的着法很特别，对手猜不到。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想赢这盘棋，你要先学会几种基本着法。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的着法很厉害，每次都能赢。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下到残局时换了一个新着法，局势就变了。", "target_word": "着法", "complexity_tier": "T3", "furigana": "tā xià dào cánjú shí huàn le yí gè xīn zhāofǎ, júshì jiù biàn le.", "sentence_source": "generated"}, {"text": "这盘棋局面复杂，我想了一个新着法。", "target_word": "着法", "complexity_tier": "T3", "furigana": "zhè pán qí júmiàn fùzá, wǒ xiǎng le yí gè xīn zhāofǎ.", "sentence_source": "generated"}, {"text": "老师教了我们几个开局的着法。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的开局很稳，你得换一个着法。", "target_word": "着法", "complexity_tier": "T3", "furigana": "tā de kāijú hěn wěn, nǐ děi huàn yí gè zhāofǎ.", "sentence_source": "generated"}, {"text": "他下棋的着法和别人不一样。", "target_word": "着法", "complexity_tier": "T3", "furigana": "tā xiàqí de zhāofǎ hé biérén bù yíyàng.", "sentence_source": "generated"}, {"text": "下棋有很多着法，你要多看多练。", "target_word": "着法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "下棋的招数、套路，也比喻处理事情的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "着法", "is_correct": true, "explanation": "正确：着法指下棋的招数或办事的办法，即听到的 zhāo fǎ。"}, {"text": "章法", "is_correct": false, "explanation": "zhāng（第一声）与 zhāo 韵母不同（ang 与 ao），意思是文章或做事的条理。"}, {"text": "刀法", "is_correct": false, "explanation": "dāo 与 zhāo 声母不同（d 与 zh），意思是刀的运用技法。"}, {"text": "烧法", "is_correct": false, "explanation": "shāo 与 zhāo 声母不同（sh 与 zh），意思是烧制的方法。"}], "explanations": {"着法": "正确：着法指下棋的招数或办事的办法，即听到的 zhāo fǎ。", "章法": "zhāng（第一声）与 zhāo 韵母不同（ang 与 ao），意思是文章或做事的条理。", "刀法": "dāo 与 zhāo 声母不同（d 与 zh），意思是刀的运用技法。", "烧法": "shāo 与 zhāo 声母不同（sh 与 zh），意思是烧制的方法。"}, "sentence_index": null, "correct_answer": "着法"}, "level_3": {"options": [{"text": "着法", "is_correct": true, "explanation": "正确：“下棋着法”指下棋的招数，“很多”“学不完”都说得通。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是器具，不能“学不完”，也不说“棋盘很多”的学习对象。"}, {"text": "棋具", "is_correct": false, "explanation": "语义：棋具指下棋的器材，“学不完”的应是方法而非器材。"}, {"text": "棋手", "is_correct": false, "explanation": "搭配：“学”的对象应是方法、知识，不说“学不完棋手”，棋手是人。"}], "explanations": {"着法": "正确：“下棋着法”指下棋的招数，“很多”“学不完”都说得通。", "棋盘": "语义：棋盘是器具，不能“学不完”，也不说“棋盘很多”的学习对象。", "棋具": "语义：棋具指下棋的器材，“学不完”的应是方法而非器材。", "棋手": "搭配：“学”的对象应是方法、知识，不说“学不完棋手”，棋手是人。"}, "sentence_index": 0, "correct_answer": "着法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的着法很香，大家都爱吃。", "explanation": "这里应该用〈饭菜〉。着法是招数或办法，没有气味，不能说“很香”。"}, {"text": "她的着法很动听，大家都喜欢。", "explanation": "这里应该用〈歌声〉。着法是抽象的，不能被听到，也不能“动听”。"}, {"text": "我家的着法会自己开门。", "explanation": "这里应该用〈自动门〉。着法是抽象的招数或办法，不会自己开门；只有自动门这类实物才能自己开合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着法", "is_correct": true, "explanation": "正确：“开局的着法”指开局时用的招数，老师可以教。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色是外观，“开局的颜色”说不通，老师不教颜色。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉的，老师不能“教”开局的声音。"}, {"text": "棋钟", "is_correct": false, "explanation": "搭配：“开局的”修饰的是步骤和招数，不能修饰“棋钟”。"}], "explanations": {"着法": "正确：“开局的着法”指开局时用的招数，老师可以教。", "颜色": "体貌：颜色是外观，“开局的颜色”说不通，老师不教颜色。", "声音": "语义：声音是听觉的，老师不能“教”开局的声音。", "棋钟": "搭配：“开局的”修饰的是步骤和招数，不能修饰“棋钟”。"}, "sentence_index": 6, "correct_answer": "着法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的着法很好看。", "explanation": "这里应该用〈款式〉。着法是招数或办法，不指衣服的样式，说衣服好看要用款式。"}, {"text": "这件衣服的着法很贵。", "explanation": "这里应该用〈价格〉。着法不能用金钱衡量，说“很贵”的应是价格。"}, {"text": "这碗汤的着法很鲜。", "explanation": "这里应该用〈味道〉。着法没有味道，不能说“很鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师着法很实用，学生们都受益。", "corrected_sentence": "这位老师的着法很实用，学生们都受益。", "error_description": "错误形式：“老师着法”；正确形式：“老师的着法”。“老师”修饰“着法”时，中间需要助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学生学会了一把新着法，棋下得更好了。", "corrected_sentence": "这个学生学会了一种新着法，棋下得更好了。", "error_description": "错误形式：“一把新着法”；正确形式：“一种新着法”。“把”多用于有柄的器具、椅子等，着法应用“种”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96081, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真诚", "is_correct": true, "explanation": "正确：“真诚”指真心实意，与“虚假”（装出来的、不是真心的）意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌或事物好看，与“虚假”不对立。"}, {"text": "快速", "is_correct": false, "explanation": "无反义关系：“快速”形容速度，与“虚假”的意思无关。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”的反义词是“吵闹”，不是“虚假”。"}], "correct_answer": "真诚", "explanations": {"真诚": "正确：“真诚”指真心实意，与“虚假”（装出来的、不是真心的）意思相反。", "漂亮": "无反义关系：“漂亮”形容外貌或事物好看，与“虚假”不对立。", "快速": "无反义关系：“快速”形容速度，与“虚假”的意思无关。", "安静": "无反义关系：“安静”的反义词是“吵闹”，不是“虚假”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
