INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96081, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是真心的，是装出来的。", "primary_collocate": null, "pronunciation": "xū jiǎ", "ipa": "ɕy˥ tɕja˨˩˦", "syllable_count": 2, "sentences": [{"text": "他对我的热情很虚假。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢她虚假的笑容。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑声听起来太虚假了，我不相信他。", "target_word": "虚假", "complexity_tier": "T3", "furigana": "xū jiǎ", "sentence_source": "generated"}, {"text": "他说想帮我，可是我觉得他的态度很虚假。", "target_word": "虚假", "complexity_tier": "T3", "furigana": "xū jiǎ", "sentence_source": "generated"}, {"text": "你的夸奖太虚假了，有话直接说吧。", "target_word": "虚假", "complexity_tier": "T3", "furigana": "xū jiǎ", "sentence_source": "generated"}, {"text": "他虚假的样子让大家都不舒服。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我能看出来，他的关心是虚假的。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得很虚假，眼睛里没有一点高兴。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人对你好，是真心还是虚假，你要看清楚。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他的道歉很虚假。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虛假", "label": "繁体"}, {"form": "虚假广告", "label": "复合"}], "register": "中性", "sense_fingerprint": "态度、笑容、感情不是真心的，是装出来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96081, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚假", "is_correct": true, "explanation": "正确：“虚假”表示不是真心、装出来的，与“热情”的语境相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“热情”与“冷淡”意思相反，“热情很冷淡”自相矛盾。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：“严肃”多形容神情或态度的庄重，一般不说“热情很严肃”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述人的身材，不能用来形容热情。"}], "explanations": {"虚假": "正确：“虚假”表示不是真心、装出来的，与“热情”的语境相符。", "冷淡": "语义：“热情”与“冷淡”意思相反，“热情很冷淡”自相矛盾。", "严肃": "搭配：“严肃”多形容神情或态度的庄重，一般不说“热情很严肃”。", "高大": "体貌：“高大”描述人的身材，不能用来形容热情。"}, "sentence_index": 0, "correct_answer": "虚假"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个钻石戒指是虚假的，只值几十块钱。", "explanation": "这里应该用〈假〉。“虚假”多用于消息、言论、感情等不真实的内容，实物的仿制品应说“假”。"}, {"text": "这只名牌包是虚假的，店员却说是正品。", "explanation": "这里应该用〈冒牌〉。“虚假”不用来修饰具体商品，冒充名牌的包要说“冒牌”。"}, {"text": "他病了很久，身体很虚假，走路都要人扶。", "explanation": "这里应该用〈虚弱〉。“虚假”指内容不真实，形容身体没有力气要用“虚弱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚假", "is_correct": true, "explanation": "正确：“虚假”说明关心不是真的，与“我能看出来”的语境吻合。"}, {"text": "圆形", "is_correct": false, "explanation": "搭配：“圆形”描述物体形状，不能修饰“关心”。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀具等物，不能说“关心是锋利的”。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描述身材，不能用来形容关心。"}], "explanations": {"虚假": "正确：“虚假”说明关心不是真的，与“我能看出来”的语境吻合。", "圆形": "搭配：“圆形”描述物体形状，不能修饰“关心”。", "锋利": "搭配：“锋利”形容刀具等物，不能说“关心是锋利的”。", "瘦小": "体貌：“瘦小”描述身材，不能用来形容关心。"}, "sentence_index": 6, "correct_answer": "虚假"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请沿着这条虚假的线把纸剪开。", "explanation": "这里应该用〈虚线〉。“虚假”指不真实，印在纸上表示剪开或折叠位置的线要说“虚线”。"}, {"text": "这双虚假的运动鞋质量很差，穿了两天就坏了。", "explanation": "这里应该用〈假冒〉。“虚假”不修饰仿造的商品，仿冒的鞋要说“假冒”。"}, {"text": "孩子长期营养不良，身体很虚假，经常生病。", "explanation": "这里应该用〈虚弱〉。“虚假”指内容不真实，形容身体缺乏力气要用“虚弱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的微笑很虚假地，我看得出来。", "corrected_sentence": "他的微笑很虚假，我看得出来。", "error_description": "错误：“地”需修饰后面的动词，这里“很虚假地”后面没有动词，多余的“地”应去掉，应说“很虚假”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她脸上带着虚假地笑容，大家都看出来了。", "corrected_sentence": "她脸上带着虚假的笑容，大家都看出来了。", "error_description": "错误形式：“虚假地笑容”；正确形式：“虚假的笑容”。修饰名词“笑容”要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96082, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真实", "is_correct": true, "explanation": "正确：“真实”与“虚假”意思相反，指与实际相符。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容明白、不模糊，与“虚假”的意思无关。"}, {"text": "快乐", "is_correct": false, "explanation": "无反义关系：“快乐”形容心情，与“虚假”不对立。"}, {"text": "便宜", "is_correct": false, "explanation": "无反义关系：“便宜”形容价格低，与“虚假”不对立。"}], "correct_answer": "真实", "explanations": {"真实": "正确：“真实”与“虚假”意思相反，指与实际相符。", "清楚": "无反义关系：“清楚”形容明白、不模糊，与“虚假”的意思无关。", "快乐": "无反义关系：“快乐”形容心情，与“虚假”不对立。", "便宜": "无反义关系：“便宜”形容价格低，与“虚假”不对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
