INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96082, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不真实的；与实际不符的。", "primary_collocate": null, "pronunciation": "xū jiǎ", "ipa": "ɕy˥ tɕja˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条虚假消息很快传开了。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多虚假广告，买东西要小心。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给老板看了虚假的数字。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的广告是虚假的，东西根本不是那样。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他说的话都是虚假的。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虚假的信息会让人做出错误的决定。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里的数据完全是虚假的。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用虚假的名字住进了这家酒店。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到虚假的新闻，先别发给朋友。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发布虚假广告，要付很多钱。", "target_word": "虚假", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虛假", "label": "繁体"}, {"form": "虚假广告", "label": "复合"}], "register": "中性", "sense_fingerprint": "消息、广告、数据等内容不真实，与事实不符", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚假", "is_correct": true, "explanation": "正确：“虚假”指消息内容与事实不符，与“很快传开”的语境吻合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述人或物的体型，不能修饰“消息”。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”一般形容环境或人的状态，不能说“安静消息”。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场面冷落，与“很快传开”的意思相矛盾。"}], "explanations": {"虚假": "正确：“虚假”指消息内容与事实不符，与“很快传开”的语境吻合。", "高大": "体貌：“高大”描述人或物的体型，不能修饰“消息”。", "安静": "搭配：“安静”一般形容环境或人的状态，不能说“安静消息”。", "冷清": "语义：“冷清”形容场面冷落，与“很快传开”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "虚假"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药是虚假的，吃了也不会有效果。", "explanation": "这里应该用〈假〉。“虚假”不用来指实物药品，假药要说“假”。"}, {"text": "这批虚假的电子产品很快就坏了。", "explanation": "这里应该用〈假冒〉。“虚假”不修饰仿造的商品，仿冒的产品要说“假冒”。"}, {"text": "这幅画是虚假的，博物馆不会收藏。", "explanation": "这里应该用〈赝品〉。“虚假”不能直接指仿造的艺术品，仿造的画要说“赝品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚假", "is_correct": true, "explanation": "正确：“虚假”指数据与事实不符，与“完全是……的”搭配。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”多形容外貌、景色，不说“数据是美丽的”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”描述人的情绪，数据不会有感情。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描述身材，不能用来形容报告里的数据。"}], "explanations": {"虚假": "正确：“虚假”指数据与事实不符，与“完全是……的”搭配。", "美丽": "搭配：“美丽”多形容外貌、景色，不说“数据是美丽的”。", "悲伤": "语义：“悲伤”描述人的情绪，数据不会有感情。", "瘦小": "体貌：“瘦小”描述身材，不能用来形容报告里的数据。"}, "sentence_index": 6, "correct_answer": "虚假"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只皮包是虚假的，店员却说是原装的。", "explanation": "这里应该用〈冒牌〉。“虚假”不修饰具体商品，冒充名牌的包要说“冒牌”。"}, {"text": "病了很久之后，她身体很虚假，说话都没有力气。", "explanation": "这里应该用〈虚弱〉。“虚假”指内容不真实，形容身体缺乏力气要用“虚弱”。"}, {"text": "请沿着这条虚假的线折叠纸张。", "explanation": "这里应该用〈虚线〉。“虚假”指不真实，印在纸上表示折叠位置的线要说“虚线”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条虚假地消息，大家别相信。", "corrected_sentence": "这是一条虚假的消息，大家别相信。", "error_description": "错误形式：“虚假地消息”；正确形式：“虚假的消息”。修饰名词“消息”要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家公司的宣传很虚假地，大家都不信。", "corrected_sentence": "那家公司的宣传很虚假，大家都不信。", "error_description": "错误：“地”需修饰后面的动词，这里“很虚假地”后面没有可修饰的动词，应去掉“地”，说“宣传很虚假”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
