INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96083, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "见天是每一天，天天。", "primary_collocate": null, "pronunciation": "jiàn tiān", "ipa": "tɕjɛn˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "爷爷见天去河边钓鱼，风雨无阻。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我见天喝一杯牛奶，身体不错。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见天练字，字越写越好。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个月，姐姐见天学英语。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李见天买报纸，已经成了习惯。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫见天趴在窗边等主人回来。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈见天给我做早饭，这么多年真不容易。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们见天在楼下聊天，聊到很晚。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王师傅见天骑着自行车去上班。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我见天走路上班，从来不坐车。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见天儿", "label": "儿化"}, {"form": "見天", "label": "繁体"}], "register": "口语", "sense_fingerprint": "见天：每一天，天天（口语副词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见天", "is_correct": true, "explanation": "见天：口语副词，表示每天，与“爷爷每天去河边钓鱼”的习惯相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生的一次动作，与“每天去河边钓鱼”的习惯不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上去做，与“每天去河边钓鱼”的规律不合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与表示习惯重复的“见天”不同。"}], "explanations": {"见天": "见天：口语副词，表示每天，与“爷爷每天去河边钓鱼”的习惯相合。", "忽然": "语义：“忽然”表示突然发生的一次动作，与“每天去河边钓鱼”的习惯不合。", "立刻": "语义：“立刻”表示马上去做，与“每天去河边钓鱼”的规律不合。", "正在": "体貌：“正在”表示动作正在进行，与表示习惯重复的“见天”不同。"}, "sentence_index": 0, "correct_answer": "见天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上周见天去了趟超市。", "explanation": "“见天”表示每天重复，“去了趟”是一次性动作，不能与“见天”搭配。"}, {"text": "今天下午，她见天参加会议。", "explanation": "“见天”表示每天，“今天下午”只是一个时段，不能与“见天”搭配。"}, {"text": "一个小时前，我见天吃了午饭。", "explanation": "“见天”表示每天，“一个小时前”指某一个时刻，不能与“见天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见天", "is_correct": true, "explanation": "见天：口语副词，表示每天，与“妈妈每天给我做早饭”的习惯相合。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“每天给我做早饭”的习惯不合。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示不久前的一次动作，与“真不容易”所说的长期付出不合。"}, {"text": "正要", "is_correct": false, "explanation": "体貌：“正要”表示动作即将开始，与“每天给我做早饭”的重复习惯不合。"}], "explanations": {"见天": "见天：口语副词，表示每天，与“妈妈每天给我做早饭”的习惯相合。", "突然": "语义：“突然”表示事情忽然发生，与“每天给我做早饭”的习惯不合。", "刚刚": "语义：“刚刚”表示不久前的一次动作，与“真不容易”所说的长期付出不合。", "正要": "体貌：“正要”表示动作即将开始，与“每天给我做早饭”的重复习惯不合。"}, "sentence_index": 6, "correct_answer": "见天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我生日那天见天吃蛋糕。", "explanation": "“见天”表示每天，“生日那天”只是一天，不能与“见天”搭配。"}, {"text": "昨晚我见天熬夜。", "explanation": "“见天”表示每天重复，“昨晚”指某一个晚上，不能与“见天”搭配。"}, {"text": "这次面试，他见天穿西装。", "explanation": "“见天”表示每天，“这次面试”只有一次，不能与“见天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
