INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96084, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每天；天天。", "primary_collocate": null, "pronunciation": "jiàn tiān", "ipa": "tɕjɛn˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "他见天早上六点起床跑步，从不偷懒。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶见天坐在门口晒太阳。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家见天吃面条，我都吃够了。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见天加班，没有时间陪孩子。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王见天迟到，老板很不高兴。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她见天给花浇水，花长得真好。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子见天玩手机，时间一长，眼睛越来越差。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张见天去公园下棋，风雨无阻。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年他见天写日记，一天也没有断过。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的小狗见天叫，吵得人睡不着。", "target_word": "见天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见天儿", "label": "儿化"}, {"form": "見天", "label": "繁体"}], "register": "口语", "sense_fingerprint": "见天：每天，天天（口语副词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见天", "is_correct": true, "explanation": "见天：口语副词，表示每天，与“每天早上六点起床跑步”的习惯相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生的一次动作，与“每天早上六点”的习惯不合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快就发生，与“每天早上六点起床跑步”的规律性不合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，不能表示经常重复的习惯。"}], "explanations": {"见天": "见天：口语副词，表示每天，与“每天早上六点起床跑步”的习惯相合。", "忽然": "语义：“忽然”表示突然发生的一次动作，与“每天早上六点”的习惯不合。", "马上": "语义：“马上”表示很快就发生，与“每天早上六点起床跑步”的规律性不合。", "正在": "体貌：“正在”表示动作正在进行，不能表示经常重复的习惯。"}, "sentence_index": 0, "correct_answer": "见天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他见天昨天去了一趟医院。", "explanation": "“见天”表示每天重复，不能和“昨天”这样指某一天的时间词搭配。"}, {"text": "这场比赛我见天看了。", "explanation": "“见天”表示每天重复，“这场比赛”只有一次，不能用“见天”。"}, {"text": "明年的春节，他见天回家。", "explanation": "“见天”表示每天，“明年的春节”是一次性的时间，不能与“见天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见天", "is_correct": true, "explanation": "见天：口语副词，表示每天，与“孩子每天玩手机”的重复习惯相合。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，不能说明每天重复玩手机。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示不久前发生的一次动作，与“眼睛越来越差”的长期变化不合。"}, {"text": "正要", "is_correct": false, "explanation": "体貌：“正要”表示动作即将发生，与“眼睛越来越差”的长期结果不合。"}], "explanations": {"见天": "见天：口语副词，表示每天，与“孩子每天玩手机”的重复习惯相合。", "突然": "语义：“突然”表示事情忽然发生，不能说明每天重复玩手机。", "刚刚": "语义：“刚刚”表示不久前发生的一次动作，与“眼睛越来越差”的长期变化不合。", "正要": "体貌：“正要”表示动作即将发生，与“眼睛越来越差”的长期结果不合。"}, "sentence_index": 6, "correct_answer": "见天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次聚会，他见天都很开心。", "explanation": "“见天”表示每天，“那次聚会”只发生一次，不能与“见天”搭配。"}, {"text": "这本书，我见天读完了。", "explanation": "“见天”表示每天重复，“读完”是一次完成的动作，这里不能用“见天”。"}, {"text": "昨晚，我见天熬夜。", "explanation": "“见天”表示每天重复，“昨晚”指某一个晚上，不能与“见天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
