INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96085, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "正式推广前，先行试验所选定的小范围地点或单位。", "primary_collocate": null, "pronunciation": "shì diǎn", "ipa": "ʂʅ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个小镇是新办法的试点。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司选了一家店做试点。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个试点的结果很好。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这个村子当成试点。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校成了教育改革的试点。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试点的范围不大，只有两个班。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里选了三个小区作试点。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个试点让大家看到了新办法的好处。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们班是新课本的试点。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在试点里发现了不少问题。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "試點", "label": "繁体"}, {"form": "试点工作", "label": "复合"}], "register": "中性", "sense_fingerprint": "先行试验的小范围地点或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96085, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试点", "is_correct": true, "explanation": "正确答案：试点（shì diǎn），指正式推广前先行试验的小地方或单位。"}, {"text": "十点", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是十点钟。"}, {"text": "四点", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是四点钟。"}, {"text": "时点", "is_correct": false, "explanation": "声调混淆：shí（第二声）与 shì（第四声）只差声调，意思是时间点。"}, {"text": "市电", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，意思是城市供电。"}], "explanations": {"试点": "正确答案：试点（shì diǎn），指正式推广前先行试验的小地方或单位。", "十点": "shí（第二声）与 shì（第四声）声调不同，意思是十点钟。", "四点": "sì 与 shì 声母不同（s 与 sh），意思是四点钟。", "时点": "声调混淆：shí（第二声）与 shì（第四声）只差声调，意思是时间点。", "市电": "diàn（第四声）与 diǎn（第三声）声调不同，意思是城市供电。"}, "sentence_index": null, "correct_answer": "试点"}, "level_3": {"options": [{"text": "试点", "is_correct": true, "explanation": "“新办法的试点”指先行试验新办法的地方或单位，与句中语境相合。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”是测量高度的数值，不能指一种新办法的地点或单位。"}, {"text": "信号灯", "is_correct": false, "explanation": "语义：“信号灯”是交通设施，不是可以先行试验新办法的地方。"}, {"text": "尾声", "is_correct": false, "explanation": "搭配：“尾声”指事情接近结束的阶段，不能与“这个小镇是……的”搭配。"}], "explanations": {"试点": "“新办法的试点”指先行试验新办法的地方或单位，与句中语境相合。", "海拔": "语义：“海拔”是测量高度的数值，不能指一种新办法的地点或单位。", "信号灯": "语义：“信号灯”是交通设施，不是可以先行试验新办法的地方。", "尾声": "搭配：“尾声”指事情接近结束的阶段，不能与“这个小镇是……的”搭配。"}, "sentence_index": 0, "correct_answer": "试点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从这批产品里抽出一个试点检验。", "explanation": "这里应该用〈样本〉。试点指先行推广的地方或单位，不是可以拿来检验的样品。"}, {"text": "这里是敌人的一个重要试点。", "explanation": "这里应该用〈据点〉。试点指先行推广的地方，不指军队驻守的据点。"}, {"text": "老师发下了期末试点，大家认真做。", "explanation": "这里应该用〈试卷〉。试点指先行试验的地方或单位，不指考试用的卷子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试点", "is_correct": true, "explanation": "“作试点”指把选定的小区作为先行推广的地方，与“选”和“作”相合。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：小区不能作为礼物送出。"}, {"text": "标语", "is_correct": false, "explanation": "语义：“标语”是写在墙上或纸上的口号，不是可以选定的地方。"}, {"text": "奖牌", "is_correct": false, "explanation": "搭配：“作”之后接的应是身份或功能，“奖牌”是实物，不能与“三个小区”搭配。"}], "explanations": {"试点": "“作试点”指把选定的小区作为先行推广的地方，与“选”和“作”相合。", "礼物": "语义：小区不能作为礼物送出。", "标语": "语义：“标语”是写在墙上或纸上的口号，不是可以选定的地方。", "奖牌": "搭配：“作”之后接的应是身份或功能，“奖牌”是实物，不能与“三个小区”搭配。"}, "sentence_index": 6, "correct_answer": "试点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位学者收集了许多昆虫试点。", "explanation": "这里应该用〈标本〉。试点指地方或单位，不是可以收集的实物。"}, {"text": "这棵树结出了很多试点。", "explanation": "这里应该用〈果实〉。试点指地方或单位，不能指植物结出的果实。"}, {"text": "这位作家的试点很有名。", "explanation": "这里应该用〈作品〉。试点指先行推广的地方或单位，不能指文学作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县被选为新政策的一件试点。", "corrected_sentence": "这个县被选为新政策的一个试点。", "error_description": "量词错误：“试点”指地方或单位，用量词“个”；“件”用于物品或事情，不能数“试点”。应为“一个试点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全国有很多试点们，各有特色。", "corrected_sentence": "全国有很多试点，各有特色。", "error_description": "词缀错误：“们”只加在指人的名词后面，“试点”指地方或单位，不能加“们”。应为“很多试点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
