INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96086, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "正式推广前，先在小范围内进行试验。", "primary_collocate": null, "pronunciation": "shì diǎn", "ipa": "ʂʅ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个城市先试点垃圾分类。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校打算先在一个班试点新办法。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想在一家店试点自助收银。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先在三个小区试点，再推广。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院从下个月起试点网上挂号。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区去年开始试点免费公交。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行先在北京试点这项服务。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在两所小学试点新课本。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新办法先试点，没问题再推广。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里决定在这个区试点共享单车。", "target_word": "试点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "試點", "label": "繁体"}, {"form": "试点工作", "label": "复合"}], "register": "中性", "sense_fingerprint": "推广前先小范围试验", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDE