INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96086, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试点", "is_correct": true, "explanation": "正确答案：试点（shì diǎn），指正式推广前先在小范围内试验。"}, {"text": "十点", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是十点钟。"}, {"text": "四点", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是四点钟。"}, {"text": "时点", "is_correct": false, "explanation": "声调混淆：shí（第二声）与 shì（第四声）只差声调，意思是时间点。"}, {"text": "市电", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，意思是城市供电。"}], "explanations": {"试点": "正确答案：试点（shì diǎn），指正式推广前先在小范围内试验。", "十点": "shí（第二声）与 shì（第四声）声调不同，意思是十点钟。", "四点": "sì 与 shì 声母不同（s 与 sh），意思是四点钟。", "时点": "声调混淆：shí（第二声）与 shì（第四声）只差声调，意思是时间点。", "市电": "diàn（第四声）与 diǎn（第三声）声调不同，意思是城市供电。"}, "sentence_index": null, "correct_answer": "试点"}, "level_3": {"options": [{"text": "试点", "is_correct": true, "explanation": "“先试点”指正式推广前先在小范围内试行，与“先”的语境相合。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉”的对象是农田或庄稼，不能灌溉“垃圾分类”。"}, {"text": "失眠", "is_correct": false, "explanation": "配价：“失眠”是不及物动词，后面不能直接带“垃圾分类”作宾语。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是器物或设备，“垃圾分类”不能被修理。"}], "explanations": {"试点": "“先试点”指正式推广前先在小范围内试行，与“先”的语境相合。", "灌溉": "语义：“灌溉”的对象是农田或庄稼，不能灌溉“垃圾分类”。", "失眠": "配价：“失眠”是不及物动词，后面不能直接带“垃圾分类”作宾语。", "修理": "语义：“修理”的对象是器物或设备，“垃圾分类”不能被修理。"}, "sentence_index": 0, "correct_answer": "试点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新冰箱先试点一个星期，没问题再买。", "explanation": "这里应该用〈试用〉。试点指在选定地区或单位先行推广，不用于个人试用一件物品。"}, {"text": "公司每年都要试点员工的表现。", "explanation": "这里应该用〈考核〉。试点的对象是地区、方案或单位，不用来评价员工的表现。"}, {"text": "医生每天都要试点病人的反应。", "explanation": "这里应该用〈观察〉。试点不用于对病人的反应进行观察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试点", "is_correct": true, "explanation": "“先在北京试点”指先在一个地方推广这项服务，与“先”和“在北京”相合。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”的对象是动物，不能饲养“这项服务”。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”用于枝叶等，“这项服务”不能被修剪。"}, {"text": "倒闭", "is_correct": false, "explanation": "配价：“倒闭”是不及物动词，不能带“这项服务”作宾语。"}], "explanations": {"试点": "“先在北京试点”指先在一个地方推广这项服务，与“先”和“在北京”相合。", "饲养": "语义：“饲养”的对象是动物，不能饲养“这项服务”。", "修剪": "语义：“修剪”用于枝叶等，“这项服务”不能被修剪。", "倒闭": "配价：“倒闭”是不及物动词，不能带“这项服务”作宾语。"}, "sentence_index": 6, "correct_answer": "试点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民每天都要试点几十头猪。", "explanation": "这里应该用〈喂养〉。试点用于方案或地区的先行推广，不用来指饲养动物。"}, {"text": "师傅在试点坏掉的自行车。", "explanation": "这里应该用〈修理〉。试点不用于修理器物。"}, {"text": "质检员每天试点几百件产品。", "explanation": "这里应该用〈检验〉。试点是先行推广，不用来检验产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司先在三个门店了试点新系统。", "corrected_sentence": "这家公司先在三个门店试点新系统。", "error_description": "动态助词“了”不能放在状语“在三个门店”与动词“试点”之间，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司打算在老城区很试点无人配送车。", "corrected_sentence": "公司打算在老城区试点无人配送车。", "error_description": "程度副词“很”不能修饰动词“试点”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
