INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96087, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "议是大家一起商量、讨论一件事。", "primary_collocate": null, "pronunciation": "yì", "ipa": "i˥˩", "syllable_count": 1, "sentences": [{"text": "这事明天再议。", "target_word": "议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐下来议一议。", "target_word": "议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家在会上议了半天。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们聚在一起议这次春游的事。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人在村口议了一上午，谁也不想走。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们分成小组，议一议这篇课文。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家的想法不同，议来议去也没有结果。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们议过好几次，还是没有决定去哪儿。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很重要，我们得把大家请来一起议。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把明年的计划交给各部门议一议。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议了", "label": "体标"}, {"form": "议过", "label": "体标"}, {"form": "商议", "label": "复合"}, {"form": "議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "议｜大家聚在一起商量一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96087, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议", "is_correct": true, "explanation": "议（yì，第四声）指大家一起说、商量一件事，正是本句所指的意思。"}, {"text": "衣", "is_correct": false, "explanation": "衣（yī，第一声）与议（yì，第四声）声调不同，意思是衣服。"}, {"text": "医", "is_correct": false, "explanation": "医（yī，第一声）与议（yì，第四声）声调不同，意思是医生、治病。"}, {"text": "椅", "is_correct": false, "explanation": "椅（yǐ，第三声）与议（yì，第四声）声调不同，意思是椅子。"}, {"text": "移", "is_correct": false, "explanation": "移（yí，第二声）与议（yì，第四声）声调不同，意思是移动、转移。"}, {"text": "以", "is_correct": false, "explanation": "以（yǐ，第三声）与议（yì，第四声）声调不同，意思是用、凭借，如“以后”。"}, {"text": "姨", "is_correct": false, "explanation": "姨（yí，第二声）与议（yì，第四声）声调不同，意思是母亲的姐妹，如“阿姨”。"}], "explanations": {"议": "议（yì，第四声）指大家一起说、商量一件事，正是本句所指的意思。", "衣": "衣（yī，第一声）与议（yì，第四声）声调不同，意思是衣服。", "医": "医（yī，第一声）与议（yì，第四声）声调不同，意思是医生、治病。", "椅": "椅（yǐ，第三声）与议（yì，第四声）声调不同，意思是椅子。", "移": "移（yí，第二声）与议（yì，第四声）声调不同，意思是移动、转移。", "以": "以（yǐ，第三声）与议（yì，第四声）声调不同，意思是用、凭借，如“以后”。", "姨": "姨（yí，第二声）与议（yì，第四声）声调不同，意思是母亲的姐妹，如“阿姨”。"}, "sentence_index": null, "correct_answer": "议"}, "level_3": {"options": [{"text": "议", "is_correct": true, "explanation": "议指大家一起商量、讨论；“这事明天再议”即明天再商量这件事。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“事”是抽象的事情，不能被吃，“这事明天再吃”不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等具体物品，不能与“事”搭配。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“事”不能被踢，“这事明天再踢”不成立。"}], "explanations": {"议": "议指大家一起商量、讨论；“这事明天再议”即明天再商量这件事。", "吃": "语义：“事”是抽象的事情，不能被吃，“这事明天再吃”不通。", "洗": "搭配：“洗”的对象是衣物、身体等具体物品，不能与“事”搭配。", "踢": "语义：“事”不能被踢，“这事明天再踢”不成立。"}, "sentence_index": 0, "correct_answer": "议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师一人议了这篇课文。", "explanation": "这里应该用〈讲〉。议指大家一起商量；老师一个人讲课，不用“议”。"}, {"text": "他一个人在图书馆议历史。", "explanation": "这里应该用〈研究〉。议需要大家一起商量，“一个人”做的事不用“议”。"}, {"text": "他正在独自议这篇论文的结构。", "explanation": "这里应该用〈研究〉。议指大家一起商量，对论文结构的个人钻研要用“研究”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96087, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议", "is_correct": true, "explanation": "议（yì，第四声）指大家一起说、商量一件事，正是本句所指的意思。"}, {"text": "依", "is_correct": false, "explanation": "依（yī，第一声）与议（yì，第四声）声调不同，意思是依靠、依照。"}, {"text": "倚", "is_correct": false, "explanation": "倚（yǐ，第三声）与议（yì，第四声）声调不同，意思是靠、依靠。"}, {"text": "疑", "is_correct": false, "explanation": "疑（yí，第二声）与议（yì，第四声）声调不同，意思是怀疑、疑问。"}, {"text": "仪", "is_correct": false, "explanation": "仪（yí，第二声）与议（yì，第四声）声调不同，意思是仪式、仪器。"}, {"text": "遗", "is_correct": false, "explanation": "遗（yí，第二声）与议（yì，第四声）声调不同，意思是遗失、遗憾。"}], "explanations": {"议": "议（yì，第四声）指大家一起说、商量一件事，正是本句所指的意思。", "依": "依（yī，第一声）与议（yì，第四声）声调不同，意思是依靠、依照。", "倚": "倚（yǐ，第三声）与议（yì，第四声）声调不同，意思是靠、依靠。", "疑": "疑（yí，第二声）与议（yì，第四声）声调不同，意思是怀疑、疑问。", "仪": "仪（yí，第二声）与议（yì，第四声）声调不同，意思是仪式、仪器。", "遗": "遗（yí，第二声）与议（yì，第四声）声调不同，意思是遗失、遗憾。"}, "sentence_index": null, "correct_answer": "议"}, "level_3": {"options": [{"text": "议", "is_correct": true, "explanation": "议来议去指反复商量、讨论；这里说想法不同，反复讨论也没有结果。"}, {"text": "染", "is_correct": false, "explanation": "语义：“染”是给物体上色，不能用于“想法”，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是具体的物体，不与“想法”搭配。"}, {"text": "抓", "is_correct": false, "explanation": "语义：“抓”是用手握住具体的东西，与抽象的“想法”不搭。"}], "explanations": {"议": "议来议去指反复商量、讨论；这里说想法不同，反复讨论也没有结果。", "染": "语义：“染”是给物体上色，不能用于“想法”，句子不通。", "擦": "搭配：“擦”的对象是具体的物体，不与“想法”搭配。", "抓": "语义：“抓”是用手握住具体的东西，与抽象的“想法”不搭。"}, "sentence_index": 6, "correct_answer": "议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们议了一瓶水。", "explanation": "这里应该用〈喝〉。议用于商量事情，“水”是可以喝的东西，不能作“议”的对象。"}, {"text": "这台机器议了半天。", "explanation": "这里应该用〈工作〉。议的主语必须是能商量的人或团体，机器不能“议”。"}, {"text": "他们议了一张桌子。", "explanation": "这里应该用〈搬〉。议的对象是事情、问题，不能是“桌子”这样的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们议了完这件事。", "corrected_sentence": "我们议完了这件事。", "error_description": "补语“完”要紧跟动词，“了”放在补语后面：应说“议完了”，不说“议了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们议了来议去，还是没有结论。", "corrected_sentence": "他们议来议去，还是没有结论。", "error_description": "“议来议去”是固定格式，中间不能插入“了”：应说“议来议去”，不说“议了来议去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
