INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96088, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商量；讨论。", "primary_collocate": null, "pronunciation": "yì", "ipa": "i˥˩", "syllable_count": 1, "sentences": [{"text": "这个问题以后再议。", "target_word": "议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家先议计划，再做决定。", "target_word": "议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事明天开会再议。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长和老师们议了一上午，才定下新规定。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案已经议过两次了。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事不能一个人决定，要大家一起议。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "具体办法下周再议。", "target_word": "议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题我们议了三次，大家的意见还是不一样。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先和家人议一议，再告诉你我的决定。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱怎么用，得先让大家议一议。", "target_word": "议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议了", "label": "体标"}, {"form": "议过", "label": "体标"}, {"form": "议论", "label": "复合"}, {"form": "議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "议｜就某个问题商量、讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96088, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议", "is_correct": true, "explanation": "议（yì，第四声）指商量、讨论，是本句所指的意思。"}, {"text": "一", "is_correct": false, "explanation": "一（yī，第一声）与议（yì，第四声）声调不同，意思是数字“一”。"}, {"text": "已", "is_correct": false, "explanation": "已（yǐ，第三声）与议（yì，第四声）声调不同，意思是已经。"}, {"text": "宜", "is_correct": false, "explanation": "宜（yí，第二声）与议（yì，第四声）声调不同，意思是适宜、合适。"}, {"text": "乙", "is_correct": false, "explanation": "乙（yǐ，第三声）与议（yì，第四声）声调不同，意思是天干的第二位，如“甲乙”。"}, {"text": "怡", "is_correct": false, "explanation": "怡（yí，第二声）与议（yì，第四声）声调不同，意思是愉快、和悦。"}], "explanations": {"议": "议（yì，第四声）指商量、讨论，是本句所指的意思。", "一": "一（yī，第一声）与议（yì，第四声）声调不同，意思是数字“一”。", "已": "已（yǐ，第三声）与议（yì，第四声）声调不同，意思是已经。", "宜": "宜（yí，第二声）与议（yì，第四声）声调不同，意思是适宜、合适。", "乙": "乙（yǐ，第三声）与议（yì，第四声）声调不同，意思是天干的第二位，如“甲乙”。", "怡": "怡（yí，第二声）与议（yì，第四声）声调不同，意思是愉快、和悦。"}, "sentence_index": null, "correct_answer": "议"}, "level_3": {"options": [{"text": "议", "is_correct": true, "explanation": "议指商量、讨论；“这个问题以后再议”即以后再商量这个问题。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“问题”不能被穿，“这个问题以后再穿”不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”一般用于具体物品，不与“问题”搭配。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“问题”不能买卖，“以后再卖”不成立。"}], "explanations": {"议": "议指商量、讨论；“这个问题以后再议”即以后再商量这个问题。", "穿": "语义：“问题”不能被穿，“这个问题以后再穿”不通。", "扔": "搭配：“扔”一般用于具体物品，不与“问题”搭配。", "卖": "语义：“问题”不能买卖，“以后再卖”不成立。"}, "sentence_index": 0, "correct_answer": "议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人在屋里议了一上午。", "explanation": "这里应该用〈思考〉。议需要大家一起商量，“一个人”想问题不用“议”。"}, {"text": "老师给我们议了一个故事。", "explanation": "这里应该用〈讲〉。议需要大家一起商量，单向讲给别人听不用“议”。"}, {"text": "这只猫议了很久。", "explanation": "这里应该用〈睡〉。议的主语必须是能商量的人，猫不能“议”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96088, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议", "is_correct": true, "explanation": "议（yì，第四声）指商量、讨论，是本句所指的意思。"}, {"text": "衣", "is_correct": false, "explanation": "衣（yī，第一声）与议（yì，第四声）声调不同，意思是衣服。"}, {"text": "椅", "is_correct": false, "explanation": "椅（yǐ，第三声）与议（yì，第四声）声调不同，意思是椅子。"}, {"text": "移", "is_correct": false, "explanation": "移（yí，第二声）与议（yì，第四声）声调不同，意思是移动、转移。"}, {"text": "姨", "is_correct": false, "explanation": "姨（yí，第二声）与议（yì，第四声）声调不同，意思是母亲的姐妹，如“阿姨”。"}, {"text": "以", "is_correct": false, "explanation": "以（yǐ，第三声）与议（yì，第四声）声调不同，意思是用、凭借，如“以后”。"}], "explanations": {"议": "议（yì，第四声）指商量、讨论，是本句所指的意思。", "衣": "衣（yī，第一声）与议（yì，第四声）声调不同，意思是衣服。", "椅": "椅（yǐ，第三声）与议（yì，第四声）声调不同，意思是椅子。", "移": "移（yí，第二声）与议（yì，第四声）声调不同，意思是移动、转移。", "姨": "姨（yí，第二声）与议（yì，第四声）声调不同，意思是母亲的姐妹，如“阿姨”。", "以": "以（yǐ，第三声）与议（yì，第四声）声调不同，意思是用、凭借，如“以后”。"}, "sentence_index": null, "correct_answer": "议"}, "level_3": {"options": [{"text": "议", "is_correct": true, "explanation": "议指商量、讨论；“具体办法下周再议”即下周再商量具体办法。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“办法”不是能洗的东西，“下周再洗”不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能“唱办法”。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“办法”不能被穿，句子不成立。"}], "explanations": {"议": "议指商量、讨论；“具体办法下周再议”即下周再商量具体办法。", "洗": "语义：“办法”不是能洗的东西，“下周再洗”不通。", "唱": "搭配：“唱”的对象是歌，不能“唱办法”。", "穿": "语义：“办法”不能被穿，句子不成立。"}, "sentence_index": 6, "correct_answer": "议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们议了三百块钱。", "explanation": "这里应该用〈花〉。议指商量、讨论，不表示花费；“三百块钱”要用“花”。"}, {"text": "他们议了一碗面条。", "explanation": "这里应该用〈吃〉。议用于商量事情，“面条”是食物，不能作“议”的对象。"}, {"text": "我们议了一个西瓜。", "explanation": "这里应该用〈切〉。议的对象是事情、问题，不能是“西瓜”这样的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们议了定新规定。", "corrected_sentence": "我们议定了新规定。", "error_description": "“议定”是动补结构，“了”要放在补语“定”后面：应说“议定了”，不说“议了定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一起把议这件事。", "corrected_sentence": "大家一起议这件事。", "error_description": "错误：“议”前不能直接加“把”，“把”字句要先有宾语再接动词。正确：“一起议这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
