INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "身材是人身体的高矮胖瘦。", "primary_collocate": null, "pronunciation": "shēn cái", "ipa": "ʂən˥˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "她身材很高，像个模特。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，所以身材一直很好。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥身材很胖，衣服要买大号的。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小，不适合他的身材。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身材又高又瘦，穿什么都好看。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球运动员的身材一般都很高大。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保持身材，他晚上不吃饭。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身材矮小，可是跑得特别快。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我的身材跟爸爸很像。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买衣服要先看自己的身材。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人身体的高矮胖瘦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "身材", "is_correct": true, "explanation": "身材（shēn cái）指人身体的高矮胖瘦，是正确答案。"}, {"text": "神采", "is_correct": false, "explanation": "神采（shén cǎi）两个音节的声调都与身材（shēn cái）不同，意思是精神和光彩。"}, {"text": "生财", "is_correct": false, "explanation": "生财（shēng cái）第一个音节韵母为 -eng，与 shēn 的 -en 不同，意思是使财富增加。"}, {"text": "深藏", "is_correct": false, "explanation": "深藏（shēn cáng）第二个音节韵母为 -ang，与 cái 的 -ai 不同，意思是藏得很深。"}, {"text": "身残", "is_correct": false, "explanation": "身残（shēn cán）第二个音节韵母为 -an，与 cái 的 -ai 不同，意思是身体有残疾。"}], "explanations": {"身材": "身材（shēn cái）指人身体的高矮胖瘦，是正确答案。", "神采": "神采（shén cǎi）两个音节的声调都与身材（shēn cái）不同，意思是精神和光彩。", "生财": "生财（shēng cái）第一个音节韵母为 -eng，与 shēn 的 -en 不同，意思是使财富增加。", "深藏": "深藏（shēn cáng）第二个音节韵母为 -ang，与 cái 的 -ai 不同，意思是藏得很深。", "身残": "身残（shēn cán）第二个音节韵母为 -an，与 cái 的 -ai 不同，意思是身体有残疾。"}, "sentence_index": null, "correct_answer": "身材"}, "level_3": {"options": [{"text": "身材", "is_correct": true, "explanation": "身材指人身体的高矮胖瘦，这里说她身材很高，像个模特。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不说“很高”，“脾气很高”不成立。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”一般说“开朗”“温和”，不说“很高”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重很高”指重量大，与“像个模特”的纤瘦形象矛盾。"}], "explanations": {"身材": "身材指人身体的高矮胖瘦，这里说她身材很高，像个模特。", "脾气": "搭配：“脾气”不说“很高”，“脾气很高”不成立。", "性格": "搭配：“性格”一般说“开朗”“温和”，不说“很高”。", "体重": "语义：“体重很高”指重量大，与“像个模特”的纤瘦形象矛盾。"}, "sentence_index": 0, "correct_answer": "身材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身材有一米八。", "explanation": "这里应该用〈身高〉。身材指体型，不说具体的高度数字，“一米八”要用“身高”。"}, {"text": "他有一只好身材。", "explanation": "这里应该用〈副〉。身材用量词“副”，不用“只”（“只”多用于动物或成对物品中的一个）。"}, {"text": "他的身材很响亮。", "explanation": "这里应该用〈声音〉。“响亮”形容声音，身材是体型，不能说“很响亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": true, "explanation": "身材指体型，“为了保持身材”即为了维持体型。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：不吃饭是为了保持身材，“颜色”与这一目的不搭，句子不通。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“保持”一般不与“学历”搭配，句子不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”不能被保持，与“为了”后的目的不搭。"}], "explanations": {"身材": "身材指体型，“为了保持身材”即为了维持体型。", "颜色": "语义：不吃饭是为了保持身材，“颜色”与这一目的不搭，句子不通。", "学历": "搭配：“保持”一般不与“学历”搭配，句子不通。", "地址": "语义：“地址”不能被保持，与“为了”后的目的不搭。"}, "sentence_index": 6, "correct_answer": "身材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把身材放在桌子上。", "explanation": "这里应该用〈模型〉。身材指人身体的高矮胖瘦，是抽象的体型，不能像模型一样放在桌上。"}, {"text": "他一脚把身材踢出去了。", "explanation": "这里应该用〈球〉。身材指体型，不是可以被踢的东西；“踢”的对象应是球这类实物。"}, {"text": "他的身材会说话。", "explanation": "这里应该去掉〈身材〉，改为“他会说话”。身材是体型，不会说话；会说话的应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一张好身材。", "corrected_sentence": "她有一副好身材。", "error_description": "身材的量词是“副”，不用“张”（“张”多用于纸张、桌面等平面的东西）：应说“一副好身材”，不说“一张好身材”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坚持锻炼以后，有了一条好身材。", "corrected_sentence": "他坚持锻炼以后，有了一副好身材。", "error_description": "身材的量词是“副”，不用“条”（“条”多用于裤子、河流等长形的东西）：应说“一副好身材”，不说“一条好身材”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
