INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "人的身体的高矮胖瘦的样子。", "primary_collocate": null, "pronunciation": "shēn cái", "ipa": "ʂən˥˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "那个演员的身材真让人羡慕。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生了孩子以后，身材变了很多。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子能让你的身材更好看。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身材像运动员一样结实。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天到了，很多人开始减肥，想要好身材。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她身材苗条，穿旗袍特别漂亮。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的身材太胖，要少吃肉。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片上的她身材高高的，笑得很甜。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很在意自己的身材，常常去健身房。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师身材不高，声音却很大。", "target_word": "身材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人的身体高矮胖瘦的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96090, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "身材", "is_correct": true, "explanation": "身材（shēn cái）指人身体的高矮胖瘦，是正确答案。"}, {"text": "神采", "is_correct": false, "explanation": "神采（shén cǎi）两个音节的声调都与身材（shēn cái）不同，意思是精神和光彩。"}, {"text": "生财", "is_correct": false, "explanation": "生财（shēng cái）第一个音节韵母为 -eng，与 shēn 的 -en 不同，意思是使财富增加。"}, {"text": "深藏", "is_correct": false, "explanation": "深藏（shēn cáng）第二个音节韵母为 -ang，与 cái 的 -ai 不同，意思是藏得很深。"}, {"text": "身残", "is_correct": false, "explanation": "身残（shēn cán）第二个音节韵母为 -an，与 cái 的 -ai 不同，意思是身体有残疾。"}], "explanations": {"身材": "身材（shēn cái）指人身体的高矮胖瘦，是正确答案。", "神采": "神采（shén cǎi）两个音节的声调都与身材（shēn cái）不同，意思是精神和光彩。", "生财": "生财（shēng cái）第一个音节韵母为 -eng，与 shēn 的 -en 不同，意思是使财富增加。", "深藏": "深藏（shēn cáng）第二个音节韵母为 -ang，与 cái 的 -ai 不同，意思是藏得很深。", "身残": "身残（shēn cán）第二个音节韵母为 -an，与 cái 的 -ai 不同，意思是身体有残疾。"}, "sentence_index": null, "correct_answer": "身材"}, "level_3": {"options": [{"text": "身材", "is_correct": true, "explanation": "身材指人身体的高矮胖瘦，这里指演员的体型令人羡慕。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热的程度，不能被羡慕，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人的属性，“演员的天气”搭配不通。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“方向”不说“真让人羡慕”，不能与“演员的”搭配。"}], "explanations": {"身材": "身材指人身体的高矮胖瘦，这里指演员的体型令人羡慕。", "温度": "语义：“温度”是冷热的程度，不能被羡慕，句子不通。", "天气": "语义：“天气”不是人的属性，“演员的天气”搭配不通。", "方向": "搭配：“方向”不说“真让人羡慕”，不能与“演员的”搭配。"}, "sentence_index": 0, "correct_answer": "身材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身材有九十公斤。", "explanation": "这里应该用〈体重〉。身材指体型，不说具体重量，“九十公斤”要用“体重”。"}, {"text": "他有一张结实的身材。", "explanation": "这里应该用〈副〉。身材用量词“副”，“张”多用于纸、桌子等平面的东西。"}, {"text": "他的身材很香。", "explanation": "这里应该用〈苗条〉这类体型词。“香”形容气味，身材指高矮胖瘦，不能说“很香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": true, "explanation": "身材指体型，这里说他的体型太胖，医生建议少吃肉。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不能用“太胖”来形容，与“太胖”搭配不通。"}, {"text": "作风", "is_correct": false, "explanation": "搭配：“作风”一般不说“太胖”，句子不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”不能说胖，“眼睛太胖”不合常理，与医生的建议不搭。"}], "explanations": {"身材": "身材指体型，这里说他的体型太胖，医生建议少吃肉。", "脾气": "语义：“脾气”不能用“太胖”来形容，与“太胖”搭配不通。", "作风": "搭配：“作风”一般不说“太胖”，句子不通。", "眼睛": "语义：“眼睛”不能说胖，“眼睛太胖”不合常理，与医生的建议不搭。"}, "sentence_index": 6, "correct_answer": "身材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师把身材放进了箱子里。", "explanation": "这里应该用〈行李〉。身材指人身体的高矮胖瘦，不是能装进箱子的物品。"}, {"text": "这位老师的身材会唱歌。", "explanation": "这里应该用〈嗓子〉。身材是体型，不会唱歌；会唱歌的是嗓子。"}, {"text": "这位老师一脚把身材踢开了。", "explanation": "这里应该用〈门〉。身材是体型，不能被踢开；“踢开”的对象应是门这类实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只苗条的身材。", "corrected_sentence": "她有一副苗条的身材。", "error_description": "身材的量词用“副”，不用“只”（“只”多用于动物或成对物品中的一个）：应说“一副苗条的身材”，不说“一只苗条的身材”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她减肥以后，有了一条苗条的身材。", "corrected_sentence": "她减肥以后，有了一副苗条的身材。", "error_description": "身材的量词是“副”，不用“条”（“条”多用于裤子、河流等长形的东西）：应说“一副苗条的身材”，不说“一条苗条的身材”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
