INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军号是军队里吹的一种小喇叭。", "primary_collocate": null, "pronunciation": "jūn hào", "ipa": "tɕyn˥ xɑu˥˩", "syllable_count": 2, "sentences": [{"text": "早上六点，军号响了。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想吹军号。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵拿起军号，用力吹了起来。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一把旧军号。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把军号是爷爷留下的。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对闪亮的军号很好奇。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在部队里学会了吹军号。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吹响军号，声音在山谷里传得很远。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那把铜军号擦得很亮。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老兵把军号放在桌子上。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军号声", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队里吹的小喇叭，指乐器本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军号", "is_correct": true, "explanation": "“军号”是能发出声音的乐器，“响了”符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“响”指发出声音，太阳不会发声，不能说“太阳响了”。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”是时间，不是能发声的事物，与“响”不合。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮不会发出声音，不能与“响”搭配。"}], "explanations": {"军号": "“军号”是能发出声音的乐器，“响了”符合句意。", "太阳": "搭配：“响”指发出声音，太阳不会发声，不能说“太阳响了”。", "早晨": "语义：“早晨”是时间，不是能发声的事物，与“响”不合。", "月亮": "搭配：月亮不会发出声音，不能与“响”搭配。"}, "sentence_index": 0, "correct_answer": "军号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用军号敲钉子。", "explanation": "这里应该用〈锤子〉。军号是吹奏的乐器，不能用来敲钉子，这里把它当成了锤子。"}, {"text": "他用军号给花浇水。", "explanation": "这里应该用〈水壶〉。军号是乐器，不能用来浇水，这里把它当成了水壶。"}, {"text": "他是一位军号，每天负责吹号。", "explanation": "这里应该用〈号兵〉。军号是乐器，不是人，把它说成人是不对的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军号", "is_correct": true, "explanation": "“军号”是吹奏的乐器，“吹”与它搭配，符合句意。"}, {"text": "吉他", "is_correct": false, "explanation": "搭配：吉他靠弹奏，不能说“吹吉他”。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴靠弹奏，不能说“吹钢琴”。"}, {"text": "军歌", "is_correct": false, "explanation": "语义：“军歌”是歌曲，不是乐器，不能被吹奏。"}], "explanations": {"军号": "“军号”是吹奏的乐器，“吹”与它搭配，符合句意。", "吉他": "搭配：吉他靠弹奏，不能说“吹吉他”。", "钢琴": "搭配：钢琴靠弹奏，不能说“吹钢琴”。", "军歌": "语义：“军歌”是歌曲，不是乐器，不能被吹奏。"}, "sentence_index": 6, "correct_answer": "军号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老兵把军号煮了一锅汤。", "explanation": "这里应该用〈食材〉。军号是吹奏的乐器，不能煮来吃，这里把它当成了食材。"}, {"text": "孩子们拉着线，把军号放上了天。", "explanation": "这里应该用〈风筝〉。军号是吹奏的乐器，不能拉着线放上天，这里把它当成了风筝。"}, {"text": "她出门前用军号涂了涂嘴唇。", "explanation": "这里应该用〈口红〉。军号是乐器，不能用来涂嘴唇，这里把它当成了口红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一张旧军号，一直很珍惜。", "corrected_sentence": "他有一把旧军号，一直很珍惜。", "error_description": "错误：量词“张”。军号是乐器，计量要用“把”；“张”用于平面的东西，应说“一把旧军号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那把军号擦很亮。", "corrected_sentence": "他把那把军号擦得很亮。", "error_description": "错误：缺少“得”。“擦”后面带表示结果的补语，要用“擦得……”，应说“擦得很亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队中用来发信号的号角。", "primary_collocate": null, "pronunciation": "jūn hào", "ipa": "tɕyn˥ xɑu˥˩", "syllable_count": 2, "sentences": [{"text": "军号一响，战士们马上集合。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到冲锋的军号，大家都向前跑。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点，熄灯的军号准时响起。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起床的军号把大家叫醒了。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗开始前，军号先响了三遍。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军号就是命令，战士们都听得懂。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "营地里每天都有军号提醒大家做事。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集合的军号传遍了整个营地。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军号告诉战士们该休息了。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一亮，军号就把大家叫起来。", "target_word": "军号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军号声", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队用来发出集合、起床等信号的号角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军号", "is_correct": true, "explanation": "“军号”是发出信号的号角，“一响”后战士们集合，符合句意。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是饭食，不会发出声音，不能说“早饭一响”。"}, {"text": "战士", "is_correct": false, "explanation": "搭配：“一响”用于能发出声音的事物，不能用于人。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会发出信号，不能说“月亮一响，战士们集合”。"}], "explanations": {"军号": "“军号”是发出信号的号角，“一响”后战士们集合，符合句意。", "早饭": "语义：早饭是饭食，不会发出声音，不能说“早饭一响”。", "战士": "搭配：“一响”用于能发出声音的事物，不能用于人。", "月亮": "语义：月亮不会发出信号，不能说“月亮一响，战士们集合”。"}, "sentence_index": 0, "correct_answer": "军号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军号响了，他赶紧接起来。", "explanation": "这里应该用〈电话〉。军号是发信号的号角，不能接听，“接起来”是电话的用法，这里把军号当成了电话。"}, {"text": "这部电影的军号讲了一个爱情故事。", "explanation": "这里应该用〈剧情〉。军号是发信号的号角，不能讲故事，这里把它当成了电影的情节。"}, {"text": "这个军号很甜，我们尝一尝。", "explanation": "这里应该用〈糖果〉。军号是发信号的号角，不能吃，“很甜”和“尝一尝”说的是食物，这里把军号当成了糖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军号", "is_correct": true, "explanation": "“军号”能发出信号提醒人做事，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会发出信号，不能提醒大家做事。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪不能发出信号，不能提醒大家做事。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会发出提醒，不能说“椅子提醒大家做事”。"}], "explanations": {"军号": "“军号”能发出信号提醒人做事，符合句意。", "石头": "语义：石头不会发出信号，不能提醒大家做事。", "草坪": "语义：草坪不能发出信号，不能提醒大家做事。", "椅子": "语义：椅子不会发出提醒，不能说“椅子提醒大家做事”。"}, "sentence_index": 6, "correct_answer": "军号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天一亮，军号就去上班了。", "explanation": "这里应该用〈士兵〉。军号是乐器，不会去上班，这里把它当成了人。"}, {"text": "天一亮，军号就吃完了早饭。", "explanation": "这里应该用〈士兵〉。军号不会吃饭，这里同样把它当成了人。"}, {"text": "天一亮，军号就去跑步锻炼了。", "explanation": "这里应该用〈战士〉。军号是乐器，不能锻炼身体，这里把它当成了人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到一声的军号，大家都起来了。", "corrected_sentence": "听到一声军号，大家都起来了。", "error_description": "错误：“一声”与“军号”之间多加了“的”。数量词直接修饰名词时不加“的”，应说“一声军号”，不说“一声的军号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军号响很远，传到了山谷。", "corrected_sentence": "军号响得很远，传到了山谷。", "error_description": "错误：缺少“得”。“响”后面带表示程度的补语，要用“响得很远”，不能直接说“响很远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
