INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96093, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "办学是开一所学校，让孩子们来读书。", "primary_collocate": null, "pronunciation": "bàn xué", "ipa": "pan⁵¹ ɕɥe³⁵", "syllable_count": 2, "sentences": [{"text": "他想在村里办学，让孩子们有书读。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一直想办学，帮助山里的孩子。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里没有学校，大家决定一起办学。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的钱都用来办学了。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时就有办学的梦想。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的孩子太多，所以老王想办学。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办学需要老师，也需要教室。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在河边办学，孩子们每天都来读书。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后回老家办学，教孩子们认字。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友想办学，可是还没有找到地方。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办学了", "label": "体标"}, {"form": "办学者", "label": "复合"}, {"form": "辦學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开办一所学校，让孩子有地方读书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办学", "is_correct": true, "explanation": "正确：“办学”指开办学校，与“让孩子们有书读”的目的相吻合。"}, {"text": "烧书", "is_correct": false, "explanation": "语义：“烧书”会让孩子们没有书读，与句中“让孩子们有书读”的目的正相反。"}, {"text": "停课", "is_correct": false, "explanation": "搭配：“停课”是停止上课，不能用来表示为孩子们提供读书机会的目的。"}, {"text": "逃学", "is_correct": false, "explanation": "语义：“逃学”指学生不去上学，与“让孩子们有书读”的意思相矛盾。"}], "explanations": {"办学": "正确：“办学”指开办学校，与“让孩子们有书读”的目的相吻合。", "烧书": "语义：“烧书”会让孩子们没有书读，与句中“让孩子们有书读”的目的正相反。", "停课": "搭配：“停课”是停止上课，不能用来表示为孩子们提供读书机会的目的。", "逃学": "语义：“逃学”指学生不去上学，与“让孩子们有书读”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "办学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上七点去办学。", "explanation": "这里应该用〈上学〉。“办学”指创办学校，学生到学校学习要说“上学”。"}, {"text": "我们公司每年办学，展示新产品。", "explanation": "这里应该用〈办展〉。“办学”指创办学校，公司举办展览要说“办展”。"}, {"text": "这场比赛由大学办学。", "explanation": "这里应该用〈承办〉。“办学”指创办学校，大学承办比赛要说“承办”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办学", "is_correct": true, "explanation": "正确：“办学”作主语，指办学这件事需要老师和教室，语境吻合。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”不需要老师和教室，“吃饭需要教室”说不通。"}, {"text": "开会", "is_correct": false, "explanation": "语义：“开会”不需要老师，“开会需要老师，也需要教室”说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是个人休息，与“需要老师，也需要教室”的语境毫不相干。"}], "explanations": {"办学": "正确：“办学”作主语，指办学这件事需要老师和教室，语境吻合。", "吃饭": "语义：“吃饭”不需要老师和教室，“吃饭需要教室”说不通。", "开会": "语义：“开会”不需要老师，“开会需要老师，也需要教室”说不通。", "睡觉": "语义：“睡觉”是个人休息，与“需要老师，也需要教室”的语境毫不相干。"}, "sentence_index": 6, "correct_answer": "办学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的朋友去年办学，生产了很多家具。", "explanation": "这里应该用〈办厂〉。“办学”指创办学校，办工厂生产产品要说“办厂”。"}, {"text": "我的朋友每周办学，去健身房。", "explanation": "这里应该用〈健身〉。“办学”指创办学校，个人锻炼要说“健身”。"}, {"text": "我的朋友在超市办学，卖水果。", "explanation": "这里应该用〈开店〉。“办学”指创办学校，做买卖要说“开店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老王山里办学，让孩子们有书读。", "corrected_sentence": "老王在山里办学，让孩子们有书读。", "error_description": "错误：“山里办学”。正确：“在山里办学”。地点状语“山里”前必须加介词“在”，才能修饰动词“办学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她办学得很成功。", "corrected_sentence": "她办学办得很成功。", "error_description": "错误：“办学得很成功”。正确：“办学办得很成功”。带补语的动宾结构要重复动词，格式为“动词+宾语+动词+得+补语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
