INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创办和经营学校。", "primary_collocate": null, "pronunciation": "bàn xué", "ipa": "pan⁵¹ ɕɥe³⁵", "syllable_count": 2, "sentences": [{"text": "这家教育公司已经办学十年了。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司办学二十年，培养了很多人才。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府鼓励社会力量办学，提高教育质量。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家教育公司在全国办学，学生很多。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府支持私人办学，也要管好质量。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他办学多年，学校越办越大。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构一直坚持公益办学。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办学要花很多钱，管理也很难。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生用三十年的时间办学，学校有两千名学生。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校由三家企业共同办学。", "target_word": "办学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办学了", "label": "体标"}, {"form": "办学者", "label": "复合"}, {"form": "辦學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "创办并长期经营学校或教育机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办学", "is_correct": true, "explanation": "正确：“办学”指创办并经营学校，与“教育公司”及“已经……十年了”的语境吻合。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”的主语应是学生，公司不能上学，说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主语应是人，公司不能结婚。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”是个人行为，与“教育公司”组合不搭配。"}], "explanations": {"办学": "正确：“办学”指创办并经营学校，与“教育公司”及“已经……十年了”的语境吻合。", "上学": "语义：“上学”的主语应是学生，公司不能上学，说不通。", "结婚": "语义：“结婚”的主语应是人，公司不能结婚。", "睡觉": "搭配：“睡觉”是个人行为，与“教育公司”组合不搭配。"}, "sentence_index": 0, "correct_answer": "办学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从六岁开始办学。", "explanation": "这里应该用〈上学〉。“办学”指创办学校，孩子到学校读书要说“上学”。"}, {"text": "这家餐厅办学了十年。", "explanation": "这里不能用〈办学〉。“办学”只用于教育机构，餐厅属于餐饮行业，应说〈开〉餐厅。"}, {"text": "这家商场明天办学，展示新产品。", "explanation": "这里应该用〈办展〉。“办学”指创办和经营学校，商场举办展览要说“办展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办学", "is_correct": true, "explanation": "正确：“办学”指创办学校，与“坚持公益”的语境吻合。"}, {"text": "营利", "is_correct": false, "explanation": "语义：“营利”指以赚钱为目的，与“坚持公益”的意思相反。"}, {"text": "收费", "is_correct": false, "explanation": "搭配：“收费”与“公益”的意思相对，不说“公益收费”。"}, {"text": "炒股", "is_correct": false, "explanation": "语义：“炒股”是个人投资行为，与机构“坚持公益”的语境不符。"}], "explanations": {"办学": "正确：“办学”指创办学校，与“坚持公益”的语境吻合。", "营利": "语义：“营利”指以赚钱为目的，与“坚持公益”的意思相反。", "收费": "搭配：“收费”与“公益”的意思相对，不说“公益收费”。", "炒股": "语义：“炒股”是个人投资行为，与机构“坚持公益”的语境不符。"}, "sentence_index": 6, "correct_answer": "办学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三家企业去年共同办学，生产汽车零件。", "explanation": "这里应该用〈办厂〉。“办学”指创办和经营学校，企业共同办工厂生产要说“办厂”。"}, {"text": "这场运动会由三家企业共同办学。", "explanation": "这里应该用〈承办〉。“办学”指创办和经营学校，承办运动会要说“承办”。"}, {"text": "学生们在这里办学。", "explanation": "这里应该用〈上课〉。“办学”指创办学校，学生在这里学习要说“上课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位校长办学得很好。", "corrected_sentence": "这位校长办学办得很好。", "error_description": "错误：“办学得很好”。正确：“办学办得很好”。带补语的动宾结构要重复动词，格式为“动词+宾语+动词+得+补语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校城里办学，学生很多。", "corrected_sentence": "这所学校在城里办学，学生很多。", "error_description": "错误：“城里办学”。正确：“在城里办学”。地点状语“城里”前必须加介词“在”，才能修饰动词“办学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
