INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96095, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "连任是一个人接着做同一个工作，做了又做。", "primary_collocate": null, "pronunciation": "lián rèn", "ipa": "lyɛn˧˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "他连任了两届市长。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明已经连任三届班长了。", "target_word": "连任", "complexity_tier": "T3", "furigana": "xiǎo míng yǐ jīng lián rèn sān jiè bān zhǎng le", "sentence_source": "generated"}, {"text": "她希望明年能连任校长。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理连任成功了。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连任过两次会长。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都支持他连任。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李先生连任主席已经五年了。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长连任后，村里变化很大。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没能连任，心里很难过。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的班长想连任下一届。", "target_word": "连任", "complexity_tier": "T3", "furigana": "wǒ men de bān zhǎng xiǎng lián rèn xià yí jiè", "sentence_source": "generated"}], "morphological_forms": [{"form": "连任了", "label": "体标"}, {"form": "连任过", "label": "体标"}, {"form": "连选连任", "label": "复合"}], "register": "正式", "sense_fingerprint": "接着做同一个工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任命", "is_correct": false, "explanation": "语义：“任命”的施事是上级，“他任命了两届市长”说的是他在委派别人，与句中“他”是市长的语境不符。"}, {"text": "连任", "is_correct": true, "explanation": "正确：“连任”指接着做同一职务，与“两届市长”相符。"}, {"text": "担负", "is_correct": false, "explanation": "搭配：“担负”搭配的是责任、任务，不能说“担负了两届市长”。"}, {"text": "选举", "is_correct": false, "explanation": "语义：“选举”的对象是被选出的人，“他选举了两届市长”说的是他参与选人，与他本人担任市长不符。"}], "explanations": {"任命": "语义：“任命”的施事是上级，“他任命了两届市长”说的是他在委派别人，与句中“他”是市长的语境不符。", "连任": "正确：“连任”指接着做同一职务，与“两届市长”相符。", "担负": "搭配：“担负”搭配的是责任、任务，不能说“担负了两届市长”。", "选举": "语义：“选举”的对象是被选出的人，“他选举了两届市长”说的是他参与选人，与他本人担任市长不符。"}, "sentence_index": 0, "correct_answer": "连任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他卸任两年后，又连任了班长。", "explanation": "这里应该用〈当选〉。连任要求任期连续，卸任之后再次上任是当选，不能说连任。"}, {"text": "他连任了前任的校长职务。", "explanation": "这里应该用〈继任〉。连任指本人接着做同一职务，接替前任要用继任。"}, {"text": "他竞选失败，连任了。", "explanation": "这里应该用〈落选〉。连任的前提是已经当选并继续任职，竞选失败的人不能说连任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聘用", "is_correct": false, "explanation": "语义：“聘用”的施事是雇主，“李先生聘用主席”说的是他雇用别人，与句中“李先生”担任主席的语境不符。"}, {"text": "连任", "is_correct": true, "explanation": "正确：“连任”指接着担任同一职务，与“主席已经五年了”相符。"}, {"text": "解聘", "is_correct": false, "explanation": "语义：“解聘”的施事是解除聘任的一方，“李先生解聘主席”与他本人担任主席的语境不符。"}, {"text": "退休", "is_correct": false, "explanation": "配价：“退休”是不及物动词，后面不能直接带“主席”作宾语。"}], "explanations": {"聘用": "语义：“聘用”的施事是雇主，“李先生聘用主席”说的是他雇用别人，与句中“李先生”担任主席的语境不符。", "连任": "正确：“连任”指接着担任同一职务，与“主席已经五年了”相符。", "解聘": "语义：“解聘”的施事是解除聘任的一方，“李先生解聘主席”与他本人担任主席的语境不符。", "退休": "配价：“退休”是不及物动词，后面不能直接带“主席”作宾语。"}, "sentence_index": 6, "correct_answer": "连任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚当上班长，就已经连任了。", "explanation": "这里应该用〈上任〉。连任要求此前已在该职务上任满一届，刚就职的人只能说上任。"}, {"text": "他连任了前任班长。", "explanation": "这里应该用〈接任〉。接替前任要用接任，连任指本人继续担任同一职务。"}, {"text": "他连任班长，但没有成功。", "explanation": "这里应该用〈竞选〉。连任已经表示当选并继续任职，不能同时说“没有成功”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这次没有连任了，决定回家照顾父母。", "corrected_sentence": "她这次没有连任，决定回家照顾父母。", "error_description": "“没有”否定已经发生的“连任”时，“了”不能再附在“连任”之后，应为“没有连任”；错误在“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村长把连任了，村民都很高兴。", "corrected_sentence": "村长连任了，村民都很高兴。", "error_description": "“把”字句中“把”后必须带受处置的宾语，此句“把”后没有宾语；“村长连任了”不需要“把”，应删去“把”；错误在“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
