INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "连续担任同一职务。", "primary_collocate": null, "pronunciation": "lián rèn", "ipa": "lyɛn˧˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "总经理连任了三届，任期从未中断。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第二次连任市长。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生会主席不能连任。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的总统可以连任一次。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张老师连任校长十年了。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家投票让她连任会长。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经连任两届，不想再做了。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的经理连任过五年。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她连任后，工作更忙了。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想连任，可是家人不同意。", "target_word": "连任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连任了", "label": "体标"}, {"form": "连任过", "label": "体标"}, {"form": "连选连任", "label": "复合"}], "register": "正式", "sense_fingerprint": "连续担任同一职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：退休是离开工作岗位，与“任期从未中断”相矛盾。"}, {"text": "连任", "is_correct": true, "explanation": "正确：“连任”指连续担任同一职务，与“三届”“任期从未中断”相符。"}, {"text": "担负", "is_correct": false, "explanation": "搭配：“担负”搭配的是责任、任务，不能说“担负了三届”。"}, {"text": "任命", "is_correct": false, "explanation": "语义：“任命”是委派他人担任职务，不能表达本人“任期从未中断”的连续任职。"}], "explanations": {"退休": "语义：退休是离开工作岗位，与“任期从未中断”相矛盾。", "连任": "正确：“连任”指连续担任同一职务，与“三届”“任期从未中断”相符。", "担负": "搭配：“担负”搭配的是责任、任务，不能说“担负了三届”。", "任命": "语义：“任命”是委派他人担任职务，不能表达本人“任期从未中断”的连续任职。"}, "sentence_index": 0, "correct_answer": "连任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从来没当过总统，却连任了总统。", "explanation": "这里应该用〈当选〉。连任指接着做同一职务，他从未担任过，只能说当选。"}, {"text": "她连任了前任的会长。", "explanation": "这里应该用〈继任〉。连任指本人继续担任同一职务，接替前任要用继任。"}, {"text": "她竞选会长失败，连任了。", "explanation": "这里应该用〈落选〉。连任的前提是已经当选并继续任职，竞选失败的人不能说连任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选举", "is_correct": false, "explanation": "语义：“选举”的对象是被选出的人，“他已经选举两届”说的是他参与选人，与句中“他”连续任职的语境不符。"}, {"text": "连任", "is_correct": true, "explanation": "正确：“连任”指接着担任同一职务，与“两届”和“不想再做了”相符。"}, {"text": "辞去", "is_correct": false, "explanation": "配价：“辞去”后面必须带所辞的职务作宾语，“他已经辞去两届”缺少宾语。"}, {"text": "罢免", "is_correct": false, "explanation": "语义：“罢免”的对象是别人，不能用来说自己连续担任同一职务。"}], "explanations": {"选举": "语义：“选举”的对象是被选出的人，“他已经选举两届”说的是他参与选人，与句中“他”连续任职的语境不符。", "连任": "正确：“连任”指接着担任同一职务，与“两届”和“不想再做了”相符。", "辞去": "配价：“辞去”后面必须带所辞的职务作宾语，“他已经辞去两届”缺少宾语。", "罢免": "语义：“罢免”的对象是别人，不能用来说自己连续担任同一职务。"}, "sentence_index": 6, "correct_answer": "连任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚当上会长，就已经连任了。", "explanation": "这里应该用〈上任〉。连任要求此前已在该职务上任满一届，刚就职的人只能说上任。"}, {"text": "她连任了哥哥的班长职务。", "explanation": "这里应该用〈接任〉。连任指本人继续担任同一职务，接替哥哥要用接任。"}, {"text": "她连任学生会主席，却没有成功。", "explanation": "这里应该用〈竞选〉。连任已经表示当选并继续任职，不能与“没有成功”并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次没有连任了，决定退休。", "corrected_sentence": "他这次没有连任，决定退休。", "error_description": "“没有”否定“连任”时，“了”不能附在“连任”之后，应为“没有连任”；错误在“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生会主席可以连任连选。", "corrected_sentence": "学生会主席可以连选连任。", "error_description": "“连选连任”是固定的复合词，顺序不能颠倒，应为“连选连任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "连比是数学里把三个或更多的数放在一起比。", "primary_collocate": null, "pronunciation": "lián bǐ", "ipa": "ljɛn˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "连比就是把三个数放在一起比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "配制蛋糕时，面粉、糖和油的连比是五比二比一。", "target_word": "连比", "complexity_tier": "T3", "furigana": "pèi zhì dàn gāo shí, miàn fěn, táng hé yóu de lián bǐ shì wǔ bǐ èr bǐ yī.", "sentence_source": "generated"}, {"text": "请写出这三条边的连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连比里至少要有三个数。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂连比，所以做错了这道题。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水、牛奶和糖的连比是十比五比一。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个班的人数连比是三比四比五。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天数学课学的是连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三种颜料的连比是一比一比二。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把两个比变成连比，再算答案。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連比", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "数学：三个或更多的数放在一起比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea7a4939-1ea5-4472-88d4-95bdbfe97d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和", "is_correct": false, "explanation": "语义：“和”是加法的结果，不能说“就是把三个数放在一起比”。"}, {"text": "连比", "is_correct": true, "explanation": "连比：把三个或更多的数放在一起比，与句子的解释相合。"}, {"text": "乘积", "is_correct": false, "explanation": "语义：“乘积”是相乘的结果，不是把数放在一起比的关系。"}, {"text": "方程", "is_correct": false, "explanation": "搭配：“方程”通常与“解”搭配，不与“就是把……放在一起比”搭配。"}], "explanations": {"和": "语义：“和”是加法的结果，不能说“就是把三个数放在一起比”。", "连比": "连比：把三个或更多的数放在一起比，与句子的解释相合。", "乘积": "语义：“乘积”是相乘的结果，不是把数放在一起比的关系。", "方程": "搭配：“方程”通常与“解”搭配，不与“就是把……放在一起比”搭配。"}, "sentence_index": 0, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "甲和乙两个数的连比是三比四。", "explanation": "这里用错了〈连比〉。连比要求三个或三个以上的量，甲和乙只有两个数，两个数之间的比只能叫“比”。"}, {"text": "我在本子上写了一条连比。", "explanation": "这里应该用〈个〉。条用于细长的东西，不能用来数连比。"}, {"text": "这块布的长和宽的连比是三比二。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总数", "is_correct": false, "explanation": "语义：“总数”表示数量的总和，不能与“比”组成三个班人数的关系。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”表示两数相减的结果，不是三个班人数之间的比。"}, {"text": "连比", "is_correct": true, "explanation": "连比：三个或三个以上的量之间的比，与“三个班的人数……是三比四比五”相合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说的是人的重量，不能用来说“三个班的人数”。"}], "explanations": {"总数": "语义：“总数”表示数量的总和，不能与“比”组成三个班人数的关系。", "差": "语义：“差”表示两数相减的结果，不是三个班人数之间的比。", "连比": "连比：三个或三个以上的量之间的比，与“三个班的人数……是三比四比五”相合。", "体重": "搭配：“体重”说的是人的重量，不能用来说“三个班的人数”。"}, "sentence_index": 6, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的面粉与糖的连比是五比一。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}, {"text": "老师让我们画出一块连比。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数连比。"}, {"text": "他拿出一只连比给我看。", "explanation": "这里应该用〈个〉。只用于动物等，不能用来数连比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们写一条连比。", "corrected_sentence": "老师让我们写一个连比。", "error_description": "量词错误：错误形式是“一条连比”，正确形式是“一个连比”。“条”用于细长的东西，不用来数连比。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在本子上写了一只连比。", "corrected_sentence": "他在本子上写了一个连比。", "error_description": "量词错误：错误形式是“一只连比”，正确形式是“一个连比”。“只”用于动物等，不能用来数连比。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学上指三个或三个以上的量之间的比。", "primary_collocate": null, "pronunciation": "lián bǐ", "ipa": "ljɛn˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这三个数的连比是二比三比五。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样用连比表示三个量的关系。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红球、白球和黑球的个数连比是一比二比三。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要先求出三个角的连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "配水泥、沙子和石头时，要按连比来算。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲、乙、丙的连比是三比四比五。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两个比合成了一个连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人的钱数连比是二比三比四。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学连比以前，你要先懂得什么是比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长、宽、高的连比是四比三比二。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連比", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "数学：三个以上的量之间的比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea7a4939-1ea5-4472-88d4-95bdbfe97d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和", "is_correct": false, "explanation": "语义：“和”是加法的结果，不能与“比”组成比的关系。"}, {"text": "连比", "is_correct": true, "explanation": "连比：三个或三个以上的量之间的比，与“这三个数的……是二比三比五”相合。"}, {"text": "乘积", "is_correct": false, "explanation": "语义：“乘积”是相乘的结果，不是三个数之间的比。"}, {"text": "倍数", "is_correct": false, "explanation": "搭配：“倍数”一般与“是几倍”搭配，不与“比”的形式连用。"}], "explanations": {"和": "语义：“和”是加法的结果，不能与“比”组成比的关系。", "连比": "连比：三个或三个以上的量之间的比，与“这三个数的……是二比三比五”相合。", "乘积": "语义：“乘积”是相乘的结果，不是三个数之间的比。", "倍数": "搭配：“倍数”一般与“是几倍”搭配，不与“比”的形式连用。"}, "sentence_index": 0, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "甲和乙两个数的连比是三比四。", "explanation": "这里用错了〈连比〉。连比要求三个或三个以上的量，甲和乙只有两个数，两个数之间的比只能叫“比”。"}, {"text": "这块布的长和宽的连比是三比二。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}, {"text": "我算出一条连比。", "explanation": "这里应该用〈个〉。条用于细长的东西，不用来数连比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "语义：“面积”是平面的大小，不能由两个比合成。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热的程度，不能由两个比合成。"}, {"text": "连比", "is_correct": true, "explanation": "连比：把两个比合成的三个或更多量的比，与句中“合成”的结果相合。"}, {"text": "乐章", "is_correct": false, "explanation": "语域：“乐章”是文艺用语，与前面的数学语境不协调。"}], "explanations": {"面积": "语义：“面积”是平面的大小，不能由两个比合成。", "温度": "语义：“温度”是冷热的程度，不能由两个比合成。", "连比": "连比：把两个比合成的三个或更多量的比，与句中“合成”的结果相合。", "乐章": "语域：“乐章”是文艺用语，与前面的数学语境不协调。"}, "sentence_index": 6, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种饮料的水与糖的连比是五比一。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}, {"text": "他写下了一块连比。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数连比。"}, {"text": "他写了一只连比。", "explanation": "这里应该用〈个〉。只用于动物等，不能用来数连比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他算出了一条连比。", "corrected_sentence": "他算出了一个连比。", "error_description": "量词错误：错误形式是“一条连比”，正确形式是“一个连比”。“条”用于细长的东西，不能用来数连比。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在黑板上写了一张连比。", "corrected_sentence": "老师在黑板上写了一个连比。", "error_description": "量词错误：错误形式是“一张连比”，正确形式是“一个连比”。“张”用于纸、桌子等平面的东西，不能用来数连比。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
