INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96099, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇上是在路上或事情中正好碰到。", "primary_collocate": null, "pronunciation": "yù shàng", "ipa": "y˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我在回家的路上遇上了一位老同学。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天出门时，我正好遇上大雨。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们去山里玩，遇上了一场大雪。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末逛街时，她遇上了以前的老师。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐公共汽车时，遇上了堵车。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车去上班，他在路口遇上了红灯。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我遇上过一位很热心的司机。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天去超市，我遇上了邻居张阿姨。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在火车站遇上了多年没见的朋友。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬山时遇上了一群可爱的小猴子。", "target_word": "遇上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇上了", "label": "完成体"}, {"form": "遇上过", "label": "经历体"}, {"form": "遇不上", "label": "可能补语否定"}], "register": "中性", "sense_fingerprint": "在路上或做事时正好碰到某人或某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96099, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遇上", "is_correct": true, "explanation": "遇上（yù shàng）是正确答案，意思是碰到、遇见。"}, {"text": "续上", "is_correct": false, "explanation": "xù 与 yù 声母不同（x 与 y），意思是接续、接上。"}, {"text": "右上", "is_correct": false, "explanation": "yòu 与 yù 韵母不同（ou 与 ü），意思是右边的上方。"}, {"text": "御膳", "is_correct": false, "explanation": "shàn 与 shàng 韵尾不同（-n 与 -ng），意思是皇帝的饭菜。"}], "explanations": {"遇上": "遇上（yù shàng）是正确答案，意思是碰到、遇见。", "续上": "xù 与 yù 声母不同（x 与 y），意思是接续、接上。", "右上": "yòu 与 yù 韵母不同（ou 与 ü），意思是右边的上方。", "御膳": "shàn 与 shàng 韵尾不同（-n 与 -ng），意思是皇帝的饭菜。"}, "sentence_index": null, "correct_answer": "遇上"}, "level_3": {"options": [{"text": "遇上", "is_correct": true, "explanation": "遇上：表示偶然碰到老同学，与“了”搭配表示已经发生。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”的宾语是食物，不能接人作宾语。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”后接场所或物品，不能接人作宾语。"}, {"text": "烤", "is_correct": false, "explanation": "配价：“烤”的宾语是食物，不能接人作宾语。"}], "explanations": {"遇上": "遇上：表示偶然碰到老同学，与“了”搭配表示已经发生。", "煮": "配价：“煮”的宾语是食物，不能接人作宾语。", "打扫": "配价：“打扫”后接场所或物品，不能接人作宾语。", "烤": "配价：“烤”的宾语是食物，不能接人作宾语。"}, "sentence_index": 0, "correct_answer": "遇上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天要跟朋友遇上，一起吃午饭。", "explanation": "这里应该用〈见面〉。遇上 指偶然碰到，已经约好的会面要用见面。"}, {"text": "我们终于遇上了北京。", "explanation": "这里应该用〈到达〉。遇上 只用于碰到人或事，不能指到达某个地方。"}, {"text": "这份报告我遇上了三天。", "explanation": "这里应该用〈写〉。遇上 指偶然碰到，不表示花费一段时间去做某件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遇上", "is_correct": true, "explanation": "遇上：表示偶然碰到某人，与“过”搭配表示曾经有过这样的经历。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”后接交通工具，不能接人作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”要求食物作宾语，不能用于司机。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”要求具体的物件作宾语，不能用于人。"}], "explanations": {"遇上": "遇上：表示偶然碰到某人，与“过”搭配表示曾经有过这样的经历。", "坐": "配价：“坐”后接交通工具，不能接人作宾语。", "吃": "语义：“吃”要求食物作宾语，不能用于司机。", "拆": "配价：“拆”要求具体的物件作宾语，不能用于人。"}, "sentence_index": 6, "correct_answer": "遇上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在车站遇上了半个小时，车才来。", "explanation": "这里应该用〈等〉。遇上 指偶然碰到，不能表示持续等待一段时间，等待要用等。"}, {"text": "我们约好在车站遇上远方来的客人。", "explanation": "这里应该用〈接〉。遇上 指偶然碰到，事先约好去车站迎接客人要用接。"}, {"text": "他遇上我度过了童年。", "explanation": "这里应该用〈陪伴〉。遇上 只表示偶然碰到，不表示长期陪在身边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在超市遇上着一位老朋友。", "corrected_sentence": "我昨天在超市遇上了一位老朋友。", "error_description": "错误：“遇上”表示一下子碰到，是瞬间动作，不能加持续体“着”。正确：昨天已经发生的事要用完成体“了”，应为“遇上了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没遇上了这么热心的司机。", "corrected_sentence": "我从来没遇上过这么热心的司机。", "error_description": "错误：“从来没……”表示没有过的经历，动词后要用“过”，不能用“了”。应为“遇上过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
