INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96101, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "运气是好事或坏事，不知怎么就落在你身上。", "primary_collocate": null, "pronunciation": "yùn qi", "ipa": "yn˥˩ tɕʰi", "syllable_count": 2, "sentences": [{"text": "今天我运气真好。", "target_word": "运气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他运气不好，出门就下雨。", "target_word": "运气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试，我的运气很不错。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好运气和坏运气，有时候都来得很突然。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直觉得，自己的运气不太好。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前两天我在路边捡到一个钱包，真是运气。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她运气好，刚到车站车就来了。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运气来了，挡也挡不住。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天的运气差极了，钱包也丢了。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运气会落在谁身上，没人知道。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "運氣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "无缘无故落到身上的好事或坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运气", "is_correct": true, "explanation": "“运气”指无缘无故落到身上的好事，符合“今天我……真好”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能用来说“我”的好坏。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不说“真好”，“真好”搭配的是运气、心情之类。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁与“我”的状态无关，句子说的是个人遭遇。"}], "explanations": {"运气": "“运气”指无缘无故落到身上的好事，符合“今天我……真好”的语境。", "天气": "语义：天气是自然现象，不能用来说“我”的好坏。", "身高": "搭配：“身高”不说“真好”，“真好”搭配的是运气、心情之类。", "地铁": "语义：地铁与“我”的状态无关，句子说的是个人遭遇。"}, "sentence_index": 0, "correct_answer": "运气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的运气很强，能一个人扛起整个项目。", "explanation": "这里应该用〈能力〉。“运气”指无缘无故落到身上的好坏事，不说强弱，形容人的本领要用“能力”。"}, {"text": "这位老师的运气很高，讲课很清楚。", "explanation": "这里应该用〈水平〉。“运气”不是可以高低来比的教学本领，形容教学质量要用“水平”。"}, {"text": "她每天早上都做运气，身体很好。", "explanation": "这里应该用〈运动〉。“运气”不是可以去做的活动，“做运动”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运气", "is_correct": true, "explanation": "“运气”指碰巧落到身上的好事，与“她……好，刚到车站车就来了”的因果相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气好与车刚到站没有因果关系，句子说的是运气。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩好与车来不来无关，句中的因果不成立。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能说“她”的好坏，“她天空好”不通。"}], "explanations": {"运气": "“运气”指碰巧落到身上的好事，与“她……好，刚到车站车就来了”的因果相合。", "脾气": "语义：脾气好与车刚到站没有因果关系，句子说的是运气。", "成绩": "语义：成绩好与车来不来无关，句中的因果不成立。", "天空": "搭配：“天空”不能说“她”的好坏，“她天空好”不通。"}, "sentence_index": 6, "correct_answer": "运气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子运气很倔，谁也劝不住。", "explanation": "这里应该用〈脾气〉。“运气”指无缘无故落到身上的好坏事，不能用来形容性情。"}, {"text": "他把坏运气装进箱子，准备带去旅行。", "explanation": "这里应该用〈行李〉。“运气”是抽象的遭遇，不能像东西一样装进箱子。"}, {"text": "他花了很多时间练习，运气越来越熟练。", "explanation": "这里应该用〈技术〉。“运气”是碰巧落到身上的好坏事，不能用“熟练”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天运气好很，中了奖。", "corrected_sentence": "我今天运气很好，中了奖。", "error_description": "语序错误：“很”应放在形容词“好”前面，说“很好”，不能说“好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天遇到了一只好运气。", "corrected_sentence": "他今天遇到了好运气。", "error_description": "量词错误：“只”用于动物等，“运气”不能用“只”计量，应去掉量词，说“遇到了好运气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
