INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命运；指碰巧得到的好或坏的机会。", "primary_collocate": null, "pronunciation": "yùn qi", "ipa": "yn˥˩ tɕʰi", "syllable_count": 2, "sentences": [{"text": "我想去试试运气。", "target_word": "运气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想碰碰运气，看能不能买到票。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事只能看运气了。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想靠运气，想靠自己努力。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的运气一直不错，总能遇到贵人。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，不只是运气，也靠努力。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能一直有好运气。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次能进决赛，运气成分不小。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去碰碰运气，说不定能找到工作。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己的运气不好，总是遇到麻烦。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "運氣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "碰巧得到的机会或命运", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运气", "is_correct": true, "explanation": "“运气”指碰巧得到的机会，“试试运气”是常用说法，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“试试”不搭配天气，不说“试试天气”。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”是时间，不能被“试试”，不说“试试昨天”。"}, {"text": "尴尬", "is_correct": false, "explanation": "搭配：“试试”后接的是可以尝试的事物，“尴尬”不能被尝试。"}], "explanations": {"运气": "“运气”指碰巧得到的机会，“试试运气”是常用说法，符合句意。", "天气": "搭配：“试试”不搭配天气，不说“试试天气”。", "昨天": "搭配：“昨天”是时间，不能被“试试”，不说“试试昨天”。", "尴尬": "搭配：“试试”后接的是可以尝试的事物，“尴尬”不能被尝试。"}, "sentence_index": 0, "correct_answer": "运气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用运气搬动了那块大石头。", "explanation": "这里应该用〈力气〉。“运气”是碰巧的机会，不能当作搬东西的力量。"}, {"text": "这位作家的运气很高，写得很好。", "explanation": "这里应该用〈才华〉。“运气”不能用来形容人的写作能力，要用“才华”。"}, {"text": "他的运气胖了五斤，医生让他多运动。", "explanation": "这里应该用〈身体〉。“运气”是抽象的机会，不能像身体一样长胖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运气", "is_correct": true, "explanation": "“运气”指碰巧得到的好机会，“有好运气”符合句意。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“有好……”后接的是可以拥有的好事物，“饥饿”不能被拥有。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡不是可以“一直有好”的东西，句子说的是人的机遇。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本与句子中“碰巧的机会”的含义不符。"}], "explanations": {"运气": "“运气”指碰巧得到的好机会，“有好运气”符合句意。", "饥饿": "搭配：“有好……”后接的是可以拥有的好事物，“饥饿”不能被拥有。", "灯泡": "语义：灯泡不是可以“一直有好”的东西，句子说的是人的机遇。", "课本": "语义：课本与句子中“碰巧的机会”的含义不符。"}, "sentence_index": 6, "correct_answer": "运气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车运气很快，一会儿就到了。", "explanation": "这里应该用〈速度〉。“运气”不能用来形容快慢。"}, {"text": "他把运气挂在墙上，像挂一幅画。", "explanation": "这里应该用〈照片〉。“运气”是抽象的机会或命运，不能像照片一样挂在墙上。"}, {"text": "这碗汤运气很鲜，大家都喜欢。", "explanation": "这里应该用〈味道〉。“运气”是偶然的机会或命运，不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一张彩票，想试试一只运气。", "corrected_sentence": "我买了一张彩票，想试试运气。", "error_description": "量词错误：“运气”不能用“只”计量，应直接说“试试运气”，去掉多余的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次成功，运气的成分大很。", "corrected_sentence": "这次成功，运气的成分很大。", "error_description": "语序错误：“很”应放在形容词“大”前面，说“很大”，不能说“大很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收工", "is_correct": true, "explanation": "正确。“收工”指干完活结束工作，与“开工”相对。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指悠闲地走路，与工人开工无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发出乐音，与开工不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指休息入睡，与开工不构成反义。"}], "correct_answer": "收工", "explanations": {"收工": "正确。“收工”指干完活结束工作，与“开工”相对。", "散步": "“散步”指悠闲地走路，与工人开工无关。", "唱歌": "“唱歌”指发出乐音，与开工不构成反义。", "睡觉": "“睡觉”指休息入睡，与开工不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收工", "is_correct": true, "explanation": "正确。“收工”指干完活结束工作，与“开工”相对。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中活动，与开工不构成反义。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”指快速地跑，与开工不构成反义。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”指用笔写出文字，与开工不构成反义。"}], "correct_answer": "收工", "explanations": {"收工": "正确。“收工”指干完活结束工作，与“开工”相对。", "游泳": "“游泳”指在水中活动，与开工不构成反义。", "跑步": "“跑步”指快速地跑，与开工不构成反义。", "写字": "“写字”指用笔写出文字，与开工不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开工是工人开始做工。", "primary_collocate": null, "pronunciation": "kāi gōng", "ipa": "kʰaɪ˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "早上七点，工人们准时开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，大家今天八点开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，工人们马上开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过完年，他回到工厂开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅们吃完早饭就开工了。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们戴上安全帽，准备开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天还没亮，他们就开工了。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天人不够，没办法开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完午饭，大家一起开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们九点才开工，很晚。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开工了", "label": "体标"}], "register": "中性", "sense_fingerprint": "工人开始一天或一段时间的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开工", "is_correct": true, "explanation": "开工（kāi gōng）：工人开始做工。"}, {"text": "开通", "is_correct": false, "explanation": "gōng（第一声）与 tōng（第一声）声母不同（g 与 t），开通的意思是使通畅，如开通线路。"}, {"text": "开封", "is_correct": false, "explanation": "gōng 与 fēng 声母、韵母都不同（g/f，-ong/-eng）；开封指打开封口，也是城市名。"}, {"text": "开关", "is_correct": false, "explanation": "gōng 与 guān 韵母不同（-ong 与 -uan）；开关指控制电路的装置。"}, {"text": "开耕", "is_correct": false, "explanation": "gōng 与 gēng 韵母不同（-ong 与 -eng），开耕的意思是开始耕种。"}], "explanations": {"开工": "开工（kāi gōng）：工人开始做工。", "开通": "gōng（第一声）与 tōng（第一声）声母不同（g 与 t），开通的意思是使通畅，如开通线路。", "开封": "gōng 与 fēng 声母、韵母都不同（g/f，-ong/-eng）；开封指打开封口，也是城市名。", "开关": "gōng 与 guān 韵母不同（-ong 与 -uan）；开关指控制电路的装置。", "开耕": "gōng 与 gēng 韵母不同（-ong 与 -eng），开耕的意思是开始耕种。"}, "sentence_index": null, "correct_answer": "开工"}, "level_3": {"options": [{"text": "开工", "is_correct": true, "explanation": "正确。“早上七点”之后要表示工人开始一天的工作。"}, {"text": "收工", "is_correct": false, "explanation": "语义：“收工”指干完活收工，早上七点不会收工。"}, {"text": "下班", "is_correct": false, "explanation": "语义：“下班”指一天的工作结束，与“早上七点”相矛盾。"}, {"text": "上课", "is_correct": false, "explanation": "搭配：“上课”指学生听课，不能用于描述工人。"}], "explanations": {"开工": "正确。“早上七点”之后要表示工人开始一天的工作。", "收工": "语义：“收工”指干完活收工，早上七点不会收工。", "下班": "语义：“下班”指一天的工作结束，与“早上七点”相矛盾。", "上课": "搭配：“上课”指学生听课，不能用于描述工人。"}, "sentence_index": 0, "correct_answer": "开工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座公园明天上午开工，欢迎大家来玩。", "explanation": "这里应该用〈开园〉。开园指公园对游人开放，开工指工人开始做工。"}, {"text": "展览会今天下午开工，请大家准时到场。", "explanation": "这里应该用〈开幕〉。开幕指展览、会议开始，开工指工人开始做工。"}, {"text": "这档节目下周一开工，每晚七点播出。", "explanation": "这里应该用〈开播〉。开播指节目开始播出，开工指工人开始做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开工", "is_correct": true, "explanation": "正确。“天还没亮”之后表示工人一早开始干活。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指停止工作休息，与“天还没亮就开始”相矛盾。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：“打烊”只用于商店、饭馆结束营业，不能用于工人。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指人离开工作岗位，不是一天工作的开始。"}], "explanations": {"开工": "正确。“天还没亮”之后表示工人一早开始干活。", "放假": "语义：“放假”指停止工作休息，与“天还没亮就开始”相矛盾。", "打烊": "搭配：“打烊”只用于商店、饭馆结束营业，不能用于工人。", "退休": "语义：“退休”指人离开工作岗位，不是一天工作的开始。"}, "sentence_index": 6, "correct_answer": "开工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们九点才开工，很晚。", "explanation": "这里应该用〈上课〉。开工指工人开始做工，学生开始学习应说上课。"}, {"text": "这场比赛明天上午开工。", "explanation": "这里应该用〈开赛〉。开赛指比赛开始，开工指工人开始做工。"}, {"text": "考试九点开工，大家准时进场。", "explanation": "这里应该用〈开考〉。开考指考试开始，开工指工人开始做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们每天六点半开工了。", "corrected_sentence": "他们每天六点半开工。", "error_description": "错误：表示习惯的“每天”句中误加“了”（开工了）；“每天”表示经常性的动作，应说“每天六点半开工”，不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们还没开工了。", "corrected_sentence": "工人们还没开工。", "error_description": "“还没”表示尚未发生，与“了”不能同用，应说“工人们还没开工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
