INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "工厂、工地开始工作；工程开始动工。", "primary_collocate": null, "pronunciation": "kāi gōng", "ipa": "kʰaɪ˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "新年过后，工厂初八就开工了。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工地下个月开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新桥明天上午正式开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雨，工地今天没开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂放假十天，明天开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线今年春天开工了。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新楼什么时候开工？", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地一开工，附近就很吵。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节后，很多工厂陆续开工。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的新楼已经开工三个月了。", "target_word": "开工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开工了", "label": "体标"}], "register": "中性", "sense_fingerprint": "工厂、工地或工程开始运转、动工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开工", "is_correct": true, "explanation": "开工（kāi gōng）：工厂、工地开始工作。"}, {"text": "开通", "is_correct": false, "explanation": "gōng（第一声）与 tōng（第一声）声母不同（g 与 t），开通的意思是使通畅，如开通线路。"}, {"text": "开封", "is_correct": false, "explanation": "gōng 与 fēng 声母、韵母都不同（g/f，-ong/-eng）；开封指打开封口，也是城市名。"}, {"text": "开关", "is_correct": false, "explanation": "gōng 与 guān 韵母不同（-ong 与 -uan）；开关指控制电路的装置。"}, {"text": "开耕", "is_correct": false, "explanation": "gōng 与 gēng 韵母不同（-ong 与 -eng），开耕的意思是开始耕种。"}], "explanations": {"开工": "开工（kāi gōng）：工厂、工地开始工作。", "开通": "gōng（第一声）与 tōng（第一声）声母不同（g 与 t），开通的意思是使通畅，如开通线路。", "开封": "gōng 与 fēng 声母、韵母都不同（g/f，-ong/-eng）；开封指打开封口，也是城市名。", "开关": "gōng 与 guān 韵母不同（-ong 与 -uan）；开关指控制电路的装置。", "开耕": "gōng 与 gēng 韵母不同（-ong 与 -eng），开耕的意思是开始耕种。"}, "sentence_index": null, "correct_answer": "开工"}, "level_3": {"options": [{"text": "开工", "is_correct": true, "explanation": "正确。“新年过后”之后要表示工厂初八开始动工或生产。"}, {"text": "开学", "is_correct": false, "explanation": "语义：“开学”指学校开始新学期，工厂不能开学。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学生完成学业，主语不能是工厂。"}, {"text": "开播", "is_correct": false, "explanation": "搭配：“开播”只用于节目、电台、电视，不能用于工厂。"}], "explanations": {"开工": "正确。“新年过后”之后要表示工厂初八开始动工或生产。", "开学": "语义：“开学”指学校开始新学期，工厂不能开学。", "毕业": "语义：“毕业”指学生完成学业，主语不能是工厂。", "开播": "搭配：“开播”只用于节目、电台、电视，不能用于工厂。"}, "sentence_index": 0, "correct_answer": "开工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所小学下周开工，新生都已经报到了。", "explanation": "这里应该用〈开学〉。开学指学校开始新学期，开工用于工厂、工地动工或开始生产。"}, {"text": "这家超市下个月开工，欢迎大家来买东西。", "explanation": "这里应该用〈开业〉。开业指商店、公司开始营业，开工用于工厂、工地。"}, {"text": "电影下午两点开工，请大家准时入场。", "explanation": "这里应该用〈开演〉。开演指电影、演出开始，开工用于工厂、工地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开工", "is_correct": true, "explanation": "正确。“什么时候”问的是新楼何时开始施工。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指课程结束，只用于学校或课堂，不能用于新楼。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指人离开工作岗位，主语不能是楼房。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：“打烊”只用于商店、饭馆结束营业，不能用于楼房施工。"}], "explanations": {"开工": "正确。“什么时候”问的是新楼何时开始施工。", "下课": "语义：“下课”指课程结束，只用于学校或课堂，不能用于新楼。", "退休": "语义：“退休”指人离开工作岗位，主语不能是楼房。", "打烊": "搭配：“打烊”只用于商店、饭馆结束营业，不能用于楼房施工。"}, "sentence_index": 6, "correct_answer": "开工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座博物馆下个月开工，免费对外开放。", "explanation": "这里应该用〈开馆〉。开馆指博物馆等对外开放，开工用于工厂、工地动工。"}, {"text": "这场展览下周开工，欢迎大家来参观。", "explanation": "这里应该用〈开幕〉。开幕指展览、会议正式开始，开工用于工厂、工地动工。"}, {"text": "这场足球比赛下周开工，欢迎大家来看。", "explanation": "这里应该用〈开赛〉。开赛指比赛开始，开工用于工厂、工地动工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂下周一开工了。", "corrected_sentence": "这家工厂下周一开工。", "error_description": "错误：表示将来的“开工”后误加“了”（开工了）；“下周一”是将来时间，动作尚未发生，应说“下周一开工”，不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工地到现在还没开工了。", "corrected_sentence": "这个工地到现在还没开工。", "error_description": "“还没”表示尚未发生，与“了”不能同用，应说“还没开工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
