INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开本是一本书有多大。", "primary_collocate": null, "pronunciation": "kāi běn", "ipa": "kʰaɪ˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书的开本很大。", "target_word": "开本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢小开本的书，因为方便带。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这本词典是什么开本吗？", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志的开本比课本大。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小开本的笔记本可以放进口袋。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社决定把开本改小一点。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的故事书多是大开本，图片很大。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买书以前，我先看一下开本。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种开本的书拿在手里很轻。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一本开本合适的字典。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大开本", "label": "复合"}, {"form": "小开本", "label": "复合"}], "register": "中性", "sense_fingerprint": "书的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开本", "is_correct": true, "explanation": "正确：“开本”指书的幅面大小，可以说“很大”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，没有大小，“作者很大”说不通。"}, {"text": "书名", "is_correct": false, "explanation": "搭配：“很大”形容体积，书名一般说“很长”，不说“很大”。"}, {"text": "版权", "is_correct": false, "explanation": "语义：版权是法律权利，没有大小，“版权很大”说不通。"}], "explanations": {"开本": "正确：“开本”指书的幅面大小，可以说“很大”。", "作者": "语义：作者是人，没有大小，“作者很大”说不通。", "书名": "搭配：“很大”形容体积，书名一般说“很长”，不说“很大”。", "版权": "语义：版权是法律权利，没有大小，“版权很大”说不通。"}, "sentence_index": 0, "correct_answer": "开本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块屏幕的开本比那块大。", "explanation": "这里应该用〈尺寸〉。开本专指书刊的幅面，屏幕不用开本来说大小。"}, {"text": "这个网页的开本很清楚。", "explanation": "这里应该用〈版式〉。开本指书刊幅面，网页的排版不能用开本来说。"}, {"text": "这本书的开本很有名。", "explanation": "这里应该用〈作者〉。开本只指书刊的幅面大小，作者有名不能用开本来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开本", "is_correct": true, "explanation": "正确：“大开本”指幅面大的书，与“图片很大”前后呼应。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“大”形容大小，不说“大颜色”。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“大”不修饰字数，要说“字数多”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是幅面，“大价格”说不通，应说“价格高”。"}], "explanations": {"开本": "正确：“大开本”指幅面大的书，与“图片很大”前后呼应。", "颜色": "搭配：“大”形容大小，不说“大颜色”。", "字数": "搭配：“大”不修饰字数，要说“字数多”。", "价格": "语义：价格不是幅面，“大价格”说不通，应说“价格高”。"}, "sentence_index": 6, "correct_answer": "开本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的开本合适。", "explanation": "这里应该用〈大小〉。开本专指书刊的幅面，箱子的大小不用开本来说。"}, {"text": "这台机器的开本很高。", "explanation": "这里应该用〈规格〉。开本只用于书刊，机器的规格不用开本。"}, {"text": "这个水杯的开本很小。", "explanation": "这里应该用〈体积〉。开本指书刊幅面，水杯的体积不能用开本来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只开本的书比较小，方便携带。", "corrected_sentence": "这种开本的书比较小，方便携带。", "error_description": "错误形式：“这只开本”；正确形式：“这种开本”。“开本”是书刊幅面的类别，应用量词“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典的开本比课本多。", "corrected_sentence": "这本词典的开本比课本大。", "error_description": "错误形式：“开本比课本多”；正确形式：“开本比课本大”。“开本”说的是书的大小，要用“大/小”，不能用“多/少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
