INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "书刊的幅面大小，以全张纸裁成的张数表示。", "primary_collocate": null, "pronunciation": "kāi běn", "ipa": "kʰaɪ˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "十六开是最常见的开本。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一张全张纸裁成十六张，开本就叫十六开。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开本的大小要看纸裁成几张。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在核对这本书的开本。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社的教材大多用同一种开本。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开本越大，每一页能印的字越多。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师先选好开本，再排版面。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画册常用大开本，方便印大图。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的开本需要不同的印刷机器。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开本不同，书的宽和高也不同。", "target_word": "开本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大开本", "label": "复合"}, {"form": "十六开本", "label": "复合"}], "register": "中性", "sense_fingerprint": "按纸张裁数表示的书刊幅面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开本", "is_correct": true, "explanation": "正确：“十六开”是书刊幅面，“最常见的开本”说得通。"}, {"text": "印刷机", "is_correct": false, "explanation": "语义：印刷机是机器，不是幅面，与“十六开”无关。"}, {"text": "字号", "is_correct": false, "explanation": "搭配：“十六开”说的是幅面，字号应说“几号字”，不说“十六开的字号”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不能是“十六开”这种幅面的类别。"}], "explanations": {"开本": "正确：“十六开”是书刊幅面，“最常见的开本”说得通。", "印刷机": "语义：印刷机是机器，不是幅面，与“十六开”无关。", "字号": "搭配：“十六开”说的是幅面，字号应说“几号字”，不说“十六开的字号”。", "作者": "语义：作者是人，不能是“十六开”这种幅面的类别。"}, "sentence_index": 0, "correct_answer": "开本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的开本很高，性能很好。", "explanation": "这里应该用〈规格〉。开本只用于书刊的幅面，不能用来说机器的规格。"}, {"text": "这件衣服的开本很合适。", "explanation": "这里应该用〈尺码〉。开本指书刊幅面，衣服的大小不用开本来说。"}, {"text": "这本书的开本很便宜。", "explanation": "这里应该用〈价钱〉。开本是书刊的幅面大小，不能用来说价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开本", "is_correct": true, "explanation": "正确：设计师排版前先定下书刊的幅面，即开本。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“选好”后再排版的对象，语义不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“选好”后接价格不说，应说“定价格”。"}, {"text": "版权", "is_correct": false, "explanation": "语义：版权是权利，不能在排版前“选好”。"}], "explanations": {"开本": "正确：设计师排版前先定下书刊的幅面，即开本。", "天气": "语义：天气不是可以“选好”后再排版的对象，语义不通。", "价格": "搭配：“选好”后接价格不说，应说“定价格”。", "版权": "语义：版权是权利，不能在排版前“选好”。"}, "sentence_index": 6, "correct_answer": "开本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋面粉的开本不轻。", "explanation": "这里应该用〈重量〉。开本指书刊幅面，面粉的重量不用开本来说。"}, {"text": "这个水杯的开本很大。", "explanation": "这里应该用〈体积〉。开本只用于书刊的幅面，水杯的体积不能用开本来说。"}, {"text": "这个箱子的开本合适。", "explanation": "这里应该用〈大小〉。开本专指书刊幅面，箱子的大小不用开本来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只开本的书一般更方便翻阅。", "corrected_sentence": "这种开本的书一般更方便翻阅。", "error_description": "错误形式：“这只开本”；正确形式：“这种开本”。“开本”是书刊幅面的类别，应用量词“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "设计师要先选定开本地大小，再排版面。", "corrected_sentence": "设计师要先选定开本大小，再排版面。", "error_description": "错误形式：“开本地大小”；正确形式：“开本大小”。“地”用于修饰动词或形容词，“开本”修饰名词“大小”时不用“地”，语序和其他成分都不变。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关门", "is_correct": true, "explanation": "正确。“关门”与“开门”互为反义，指把门关上。"}, {"text": "读书", "is_correct": false, "explanation": "读书与“开门”没有反义关系，不能构成这一对反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步与“开门”没有反义关系，只是另一类动作。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡与“开门”没有反义关系，二者不在同一对语义之中。"}], "correct_answer": "关门", "explanations": {"关门": "正确。“关门”与“开门”互为反义，指把门关上。", "读书": "读书与“开门”没有反义关系，不能构成这一对反义词。", "散步": "散步与“开门”没有反义关系，只是另一类动作。", "洗澡": "洗澡与“开门”没有反义关系，二者不在同一对语义之中。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关门", "is_correct": true, "explanation": "正确。“关门”与“开门”互为反义，指把门关上。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“开门”没有反义关系，只是另一类运动。"}, {"text": "写字", "is_correct": false, "explanation": "写字与“开门”没有反义关系，二者不在同一对语义之中。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与“开门”没有反义关系，不能构成这一对反义词。"}], "correct_answer": "关门", "explanations": {"关门": "正确。“关门”与“开门”互为反义，指把门关上。", "跑步": "跑步与“开门”没有反义关系，只是另一类运动。", "写字": "写字与“开门”没有反义关系，二者不在同一对语义之中。", "游泳": "游泳与“开门”没有反义关系，不能构成这一对反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开门是把门打开。", "primary_collocate": null, "pronunciation": "kāi mén", "ipa": "kʰaɪ˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "他拿出钥匙开门。", "target_word": "开门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子太矮，自己没法开门。", "target_word": "开门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先开门，让大家进来。", "target_word": "开门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在睡觉，你慢慢开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙断了，我没办法开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到敲门声，他从沙发上站起来去开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开门以后，狗一下子就冲了出去。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一手拿着书，一手开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你开门时，要注意小狗。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开门的时候，风吹进来了。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了门", "label": "体标"}, {"form": "开过门", "label": "体标"}], "register": "口语", "sense_fingerprint": "把门打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开门", "is_correct": true, "explanation": "正确。拿出钥匙之后，用“开门”指用钥匙把门打开。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“拿出钥匙”的动作无关，无法用钥匙完成，句子不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：拿出钥匙是为了开锁、开门，和“下雨”没有关系，句子不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：拿出钥匙不是为了“生病”，前后动作没有联系，句子不通。"}], "explanations": {"开门": "正确。拿出钥匙之后，用“开门”指用钥匙把门打开。", "唱歌": "语义：“唱歌”与“拿出钥匙”的动作无关，无法用钥匙完成，句子不通。", "下雨": "语义：拿出钥匙是为了开锁、开门，和“下雨”没有关系，句子不通。", "生病": "语义：拿出钥匙不是为了“生病”，前后动作没有联系，句子不通。"}, "sentence_index": 0, "correct_answer": "开门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在高速公路上一边开门一边打电话。", "explanation": "这里应该用〈开车〉。在路上操纵方向盘是“开车”，“开门”指打开门，不能用于行驶中的车。"}, {"text": "电脑开门要等很久，你先坐一会儿。", "explanation": "这里应该用〈开机〉。启动电脑说“开机”，“开门”只表示打开门或商店营业，不能用于电脑。"}, {"text": "明天的活动推迟了，大家先在办公室开门讨论方案。", "explanation": "这里应该用〈开会〉。集体讨论事情说“开会”，“开门”不能表示讨论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开门", "is_correct": true, "explanation": "正确。“开门以后，狗一下子就冲了出去”，门打开后狗才能跑出去。"}, {"text": "关门", "is_correct": false, "explanation": "语义：门关着，狗就冲不出去，与“一下子就冲了出去”矛盾。"}, {"text": "锁门", "is_correct": false, "explanation": "语义：锁门同样把门关住，狗无法冲出去，语义矛盾。"}, {"text": "锁", "is_correct": false, "explanation": "配价：“锁”是及物动词，这里没有宾语，不能单独放在“以后”前面。"}], "explanations": {"开门": "正确。“开门以后，狗一下子就冲了出去”，门打开后狗才能跑出去。", "关门": "语义：门关着，狗就冲不出去，与“一下子就冲了出去”矛盾。", "锁门": "语义：锁门同样把门关住，狗无法冲出去，语义矛盾。", "锁": "配价：“锁”是及物动词，这里没有宾语，不能单独放在“以后”前面。"}, "sentence_index": 6, "correct_answer": "开门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月社区要开门一场环保宣传活动，大家都来参加。", "explanation": "这里应该用〈开展〉。组织活动、宣传说“开展”，“开门”只表示打开门或商店营业，不能用于活动。"}, {"text": "这条新路下个月开门，车辆就能通行了。", "explanation": "这里应该用〈开通〉。道路、线路投入使用说“开通”，“开门”只表示打开门或商店营业，不能用于道路。"}, {"text": "春天到了，院子里的桃花开门了。", "explanation": "这里应该用〈开花〉。花朵绽放说“开花”，“开门”只用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿着钥匙给开门。", "corrected_sentence": "他拿着钥匙去开门。", "error_description": "错误形式：“给开门”；正确形式：“去开门”。表示为了做某事而前往做，要用“去”引出目的，“给”不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才开门过，现在又关上了。", "corrected_sentence": "他刚才开门了，现在又关上了。", "error_description": "错误形式：“开门过”；正确形式：“开门了”。“过”表示曾经做过，必须紧跟动词说“开过门”，不能放在宾语“门”后面；这里说刚才完成的动作，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关门", "is_correct": true, "explanation": "正确。“关门”与“开门”互为反义，指把门关上，商店也可以指停止营业。"}, {"text": "读书", "is_correct": false, "explanation": "读书与“开门”没有反义关系，不能构成这一对反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步与“开门”没有反义关系，只是另一类动作。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡与“开门”没有反义关系，二者不在同一对语义之中。"}], "correct_answer": "关门", "explanations": {"关门": "正确。“关门”与“开门”互为反义，指把门关上，商店也可以指停止营业。", "读书": "读书与“开门”没有反义关系，不能构成这一对反义词。", "散步": "散步与“开门”没有反义关系，只是另一类动作。", "洗澡": "洗澡与“开门”没有反义关系，二者不在同一对语义之中。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关门", "is_correct": true, "explanation": "正确。“关门”与“开门”互为反义，指把门关上，商店也可以指停止营业。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“开门”没有反义关系，只是另一类运动。"}, {"text": "写字", "is_correct": false, "explanation": "写字与“开门”没有反义关系，二者不在同一对语义之中。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与“开门”没有反义关系，不能构成这一对反义词。"}], "correct_answer": "关门", "explanations": {"关门": "正确。“关门”与“开门”互为反义，指把门关上，商店也可以指停止营业。", "跑步": "跑步与“开门”没有反义关系，只是另一类运动。", "写字": "写字与“开门”没有反义关系，二者不在同一对语义之中。", "游泳": "游泳与“开门”没有反义关系，不能构成这一对反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打开门；也指商店等开始营业。", "primary_collocate": null, "pronunciation": "kāi mén", "ipa": "kʰaɪ˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "请你帮我开门。", "target_word": "开门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有人敲门，妈妈去开门了。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店早上八点开门。", "target_word": "开门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行周末也开门吗？", "target_word": "开门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我忘了带钥匙，没法开门。", "target_word": "开门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市几点开门，几点关门？", "target_word": "开门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天一亮，老板就开门做生意。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆中午十一点才开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口有人等着，老板赶快开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，很多商店都不开门。", "target_word": "开门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了门", "label": "体标"}, {"form": "开过门", "label": "体标"}], "register": "口语", "sense_fingerprint": "开门，也指商店开始营业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开门", "is_correct": true, "explanation": "正确。“开门”指打开门，符合“请你帮我”后面要完成的动作。"}, {"text": "开学", "is_correct": false, "explanation": "语义：“开学”指学校开始上课，不能用来请人帮忙，这里说不通。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”说的是植物绽放，不能用于请人帮忙做事。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，别人没法“帮我下雨”，句子说不通。"}], "explanations": {"开门": "正确。“开门”指打开门，符合“请你帮我”后面要完成的动作。", "开学": "语义：“开学”指学校开始上课，不能用来请人帮忙，这里说不通。", "开花": "语义：“开花”说的是植物绽放，不能用于请人帮忙做事。", "下雨": "语义：下雨是天气现象，别人没法“帮我下雨”，句子说不通。"}, "sentence_index": 0, "correct_answer": "开门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议一开门，主持人就宣布了三项决定。", "explanation": "这里应该用〈开始〉。“开门”指打开门或商店开始营业，不能用来说会议的开始。"}, {"text": "他明天去银行开门，办一张新卡。", "explanation": "这里应该用〈开户〉。银行为新客户设立账户叫开户，“开门”不能表示这个意思。"}, {"text": "这里的春天一来，花就开门了。", "explanation": "这里应该用〈开花〉。花朵绽放说“开花”，“开门”只用于门或商店营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开门", "is_correct": true, "explanation": "正确。“天一亮，老板就开门做生意”，指早上开始营业。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”与“做生意”无关，老板不会去上学做生意，语境不合。"}, {"text": "下班", "is_correct": false, "explanation": "语义：“下班”表示结束工作，与“天一亮就做生意”矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：天亮后老板“睡觉”就不能同时做生意，与“做生意”矛盾。"}], "explanations": {"开门": "正确。“天一亮，老板就开门做生意”，指早上开始营业。", "上学": "语义：“上学”与“做生意”无关，老板不会去上学做生意，语境不合。", "下班": "语义：“下班”表示结束工作，与“天一亮就做生意”矛盾。", "睡觉": "语义：天亮后老板“睡觉”就不能同时做生意，与“做生意”矛盾。"}, "sentence_index": 6, "correct_answer": "开门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电脑开门要等很久，我先去倒杯水。", "explanation": "这里应该用〈开机〉。启动电脑、手机等设备叫“开机”，“开门”只表示打开门或商店营业，不能用于电脑。"}, {"text": "他买了新车，每天上班都要开门。", "explanation": "这里应该用〈开车〉。驾驶汽车上班说“开车”，“开门”指打开门，不能用来说驾车。"}, {"text": "下午的活动取消了，我们改在办公室开门讨论方案。", "explanation": "这里应该用〈开会〉。集体讨论事情说“开会”，“开门”不能表示讨论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "钥匙找不到，我开不了开门。", "corrected_sentence": "钥匙找不到，我开不了门。", "error_description": "错误形式：“我开不了开门”；正确形式：“我开不了门”。“开门”已是动宾结构，“开”已在“开不了”中出现，后面不能再重复一个“开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天药店没开了门。", "corrected_sentence": "今天药店没开门。", "error_description": "错误形式：“没开了门”；正确形式：“没开门”。否定词“没”表示动作未发生，不能与“了”同用，“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
