INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "详细而明白地论述。", "primary_collocate": null, "pronunciation": "chǎn shù", "ipa": "tʂʰan˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他在书中阐述了自己的教育观点。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者阐述过很多经济问题。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文第二部分阐述了研究的结果。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告阐述了公司明年的发展目标。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在演讲中阐述了对环境的看法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书阐述了中国历史的变化。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章先阐述问题，再提出办法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家在会议上阐述了新的政策。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章阐述得又详细又明白。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家阐述过自己的写作经验。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阐述了", "label": "体标：了"}, {"form": "阐述过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "在文章或发言中详细论述观点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0852457c-e1ba-4d09-aa2e-60b101208aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是有形的物体，不能用于“观点”。"}, {"text": "阐述", "is_correct": true, "explanation": "正确：“在书中阐述自己的教育观点”指详细论述观点，与“书中”“教育观点”相合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对器物的损坏，与“教育观点”的论述无关。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品，不能用于“观点”。"}], "explanations": {"搬运": "搭配：“搬运”的对象是有形的物体，不能用于“观点”。", "阐述": "正确：“在书中阐述自己的教育观点”指详细论述观点，与“书中”“教育观点”相合。", "修理": "语义：“修理”针对器物的损坏，与“教育观点”的论述无关。", "收藏": "搭配：“收藏”的对象是物品，不能用于“观点”。"}, "sentence_index": 0, "correct_answer": "阐述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师阐述了新买的书包。", "explanation": "这里应该用〈展示〉。“阐述”用于详细论述道理、观点，把物品拿给别人看要用〈展示〉。"}, {"text": "画家阐述了秋天的树林。", "explanation": "这里应该用〈描绘〉。“阐述”用于论述道理、观点，描绘景物要用〈描绘〉。"}, {"text": "他用眼神阐述了愤怒。", "explanation": "这里应该用〈表达〉。“阐述”用于论述道理、观点，表达情绪要用〈表达〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是有形的东西，不能用于“问题”。"}, {"text": "阐述", "is_correct": true, "explanation": "正确：“先阐述问题，再提出办法”指先讲清问题的道理，与后半句的语境相合。"}, {"text": "观赏", "is_correct": false, "explanation": "语义：“观赏”指欣赏美好的事物，与“先……再提出办法”的分析语境不合。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”的对象是物体，不能用于“问题”。"}], "explanations": {"擦": "搭配：“擦”的对象是有形的东西，不能用于“问题”。", "阐述": "正确：“先阐述问题，再提出办法”指先讲清问题的道理，与后半句的语境相合。", "观赏": "语义：“观赏”指欣赏美好的事物，与“先……再提出办法”的分析语境不合。", "烧": "搭配：“烧”的对象是物体，不能用于“问题”。"}, "sentence_index": 6, "correct_answer": "阐述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向妈妈阐述了昨天买的衣服。", "explanation": "这里应该用〈介绍〉。“阐述”用于详细论述道理、观点，向别人讲解物品要用〈介绍〉。"}, {"text": "他向别人阐述消息。", "explanation": "这里应该用〈打听〉。“阐述”的对象是道理、观点，询问消息要用〈打听〉。"}, {"text": "她向朋友阐述工作太忙。", "explanation": "这里应该用〈抱怨〉。“阐述”用于讲清道理、观点，诉说工作的辛苦要用〈抱怨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把自己的理论阐述了很清楚。", "corrected_sentence": "她把自己的理论阐述得很清楚。", "error_description": "补语错误：“阐述”后带描写性补语“很清楚”时，要用“得”连接（状态补语），不能用“了”。正确为“阐述得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位教授你阐述了研究思路。", "corrected_sentence": "这位教授向你阐述了研究思路。", "error_description": "介词漏用：“阐述”引出听者时通常要用介词“向”，应说“向你阐述”，不能省去“向”直接接代词“你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
