INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96111, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "险是有可能受伤，很不安全。", "primary_collocate": null, "pronunciation": "xiǎn", "ipa": "ɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条山路很险。", "target_word": "险", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "悬崖边又高又险，别靠近。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段路很险，我差点摔下来。", "target_word": "险", "complexity_tier": "T3", "furigana": "zhè duàn lù hěn xiǎn, wǒ chà diǎn shuāi xià lái", "sentence_source": "generated"}, {"text": "那座木桥太险了，我不敢走。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶的路又窄又险，走的时候要小心。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个滑雪道特别险，新手容易受伤。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水很急，过河的地方看起来很险。", "target_word": "险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，山路变得更险了。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爬到那么险的地方，真让人担心。", "target_word": "险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那段路险得很，开车时我一直握着方向盘。", "target_word": "险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "險", "label": "繁体"}, {"form": "危险", "label": "复合"}, {"form": "冒险", "label": "复合"}], "register": "口语", "sense_fingerprint": "险：路或地方让人可能受伤，很不安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96111, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "险", "is_correct": true, "explanation": "险（xiǎn）是正确答案，意思是有危险、不安全。"}, {"text": "先", "is_correct": false, "explanation": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是先、首先。"}, {"text": "闲", "is_correct": false, "explanation": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是空闲。"}, {"text": "现", "is_correct": false, "explanation": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是现在、出现。"}], "explanations": {"险": "险（xiǎn）是正确答案，意思是有危险、不安全。", "先": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是先、首先。", "闲": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是空闲。", "现": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是现在、出现。"}, "sentence_index": null, "correct_answer": "险"}, "level_3": {"options": [{"text": "险", "is_correct": true, "explanation": "险：形容路很危险、不安全，与句意相符。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”用于价格或商品，不能用来形容山路。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，山路没有智力。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容道路。"}], "explanations": {"险": "险：形容路很危险、不安全，与句意相符。", "便宜": "搭配：“便宜”用于价格或商品，不能用来形容山路。", "聪明": "语义：“聪明”形容人的智力，山路没有智力。", "胖": "体貌：“胖”形容人或动物的体形，不能用来形容道路。"}, "sentence_index": 0, "correct_answer": "险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤太险了，我喝不下去。", "explanation": "这里应该用〈咸〉。险 形容路或地方让人可能受伤，不能用来说汤的味道。"}, {"text": "这份礼物很险，我很喜欢。", "explanation": "这里应该用〈贵重〉。险 指有危险，不能用来形容礼物的价值。"}, {"text": "这首歌很险，我每天都听。", "explanation": "这里应该用〈好听〉。险 不能用来评价歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96111, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "险", "is_correct": true, "explanation": "险（xiǎn）是正确答案，意思是有危险、不安全。"}, {"text": "线", "is_correct": false, "explanation": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是线条、线路。"}, {"text": "贤", "is_correct": false, "explanation": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是贤能、有德行。"}, {"text": "鲜", "is_correct": false, "explanation": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是新鲜。"}], "explanations": {"险": "险（xiǎn）是正确答案，意思是有危险、不安全。", "线": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是线条、线路。", "贤": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是贤能、有德行。", "鲜": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是新鲜。"}, "sentence_index": null, "correct_answer": "险"}, "level_3": {"options": [{"text": "险", "is_correct": true, "explanation": "险：形容过河的地方有危险，与句意相符。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”形容人的饥饿感，不能用来形容地方。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”形容人的情绪或态度，地方不具备这种特征。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”用于价格，不能用来形容过河的地方。"}], "explanations": {"险": "险：形容过河的地方有危险，与句意相符。", "饿": "语义：“饿”形容人的饥饿感，不能用来形容地方。", "冷静": "语义：“冷静”形容人的情绪或态度，地方不具备这种特征。", "贵": "搭配：“贵”用于价格，不能用来形容过河的地方。"}, "sentence_index": 6, "correct_answer": "险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很险，光线很好。", "explanation": "这里应该用〈明亮〉。险 指有危险，不用来形容房间的光线。"}, {"text": "这件衣服很险，我买得起。", "explanation": "这里应该用〈便宜〉。险 不能用来说衣服的价格。"}, {"text": "这朵花很险，颜色很漂亮。", "explanation": "这里应该用〈好看〉。险 不能用来形容花的颜色和样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
