INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96112, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "危险；不安全。", "primary_collocate": null, "pronunciation": "xiǎn", "ipa": "ɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "夜里一个人走这条路太险了。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法太险，别试了。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的浪很大，游泳很险。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开车开得很快，我觉得有点险。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个地方又黑又险，晚上最好别去。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好，出海太险了。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你站在窗台上多险啊！", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么大的雨，过桥很险，你再等一等吧。", "target_word": "险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上结了冰，走起来特别险。", "target_word": "险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路已经很险了，别再把车开快了。", "target_word": "险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "險", "label": "繁体"}, {"form": "危险", "label": "复合"}, {"form": "冒险", "label": "复合"}], "register": "口语", "sense_fingerprint": "险：做法或环境危险，不安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL