INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96112, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "险", "is_correct": true, "explanation": "险（xiǎn）是正确答案，意思是危险、不安全。"}, {"text": "先", "is_correct": false, "explanation": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是先、首先。"}, {"text": "闲", "is_correct": false, "explanation": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是空闲。"}, {"text": "现", "is_correct": false, "explanation": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是现在、出现。"}], "explanations": {"险": "险（xiǎn）是正确答案，意思是危险、不安全。", "先": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是先、首先。", "闲": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是空闲。", "现": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是现在、出现。"}, "sentence_index": null, "correct_answer": "险"}, "level_3": {"options": [{"text": "险", "is_correct": true, "explanation": "险：形容夜里独自走这条路有危险，与句意相符。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”描述食物的味道，不能用来形容走夜路。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”用于价格，不能用来形容一条路。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容道路。"}], "explanations": {"险": "险：形容夜里独自走这条路有危险，与句意相符。", "咸": "语义：“咸”描述食物的味道，不能用来形容走夜路。", "便宜": "搭配：“便宜”用于价格，不能用来形容一条路。", "胖": "体貌：“胖”形容人或动物的体形，不能用来形容道路。"}, "sentence_index": 0, "correct_answer": "险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆花很险，每天都要浇水。", "explanation": "这里应该用〈娇贵〉。险 形容做法或环境有危险，不能用来说植物需要照顾。"}, {"text": "这个包很险，颜色特别漂亮。", "explanation": "这里应该用〈好看〉。险 不能用来形容包的颜色和样子。"}, {"text": "妈妈的声音很险，大家都很安静。", "explanation": "这里应该用〈好听〉。险 不能用来形容声音的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96112, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "险", "is_correct": true, "explanation": "险（xiǎn）是正确答案，意思是危险、不安全。"}, {"text": "限", "is_correct": false, "explanation": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是限制、界限。"}, {"text": "贤", "is_correct": false, "explanation": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是贤能、有德行。"}, {"text": "鲜", "is_correct": false, "explanation": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是新鲜。"}], "explanations": {"险": "险（xiǎn）是正确答案，意思是危险、不安全。", "限": "声调不同：xiàn（第四声）与 xiǎn（第三声）不同，意思是限制、界限。", "贤": "声调不同：xián（第二声）与 xiǎn（第三声）不同，意思是贤能、有德行。", "鲜": "声调不同：xiān（第一声）与 xiǎn（第三声）不同，意思是新鲜。"}, "sentence_index": null, "correct_answer": "险"}, "level_3": {"options": [{"text": "险", "is_correct": true, "explanation": "险：形容站在窗台上很危险，与句意相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，与站在窗台上的情境不合。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”描述味道，不能用来形容人站在窗台上的状态。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”用于价格，不能用来形容人站在窗台上的状态。"}], "explanations": {"险": "险：形容站在窗台上很危险，与句意相符。", "甜": "语义：“甜”描述味道，与站在窗台上的情境不合。", "咸": "语义：“咸”描述味道，不能用来形容人站在窗台上的状态。", "贵": "搭配：“贵”用于价格，不能用来形容人站在窗台上的状态。"}, "sentence_index": 6, "correct_answer": "险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章很险，老师讲得很清楚。", "explanation": "这里应该用〈易懂〉。险 不能用来形容文章是否清楚。"}, {"text": "这顿饭很险，大家吃得很开心。", "explanation": "这里应该用〈好吃〉。险 不能用来形容饭菜的味道。"}, {"text": "这个名字很险，我记不住。", "explanation": "这里应该用〈好记〉。险 不能用来形容名字容不容易记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座桥险很，过的时候要慢。", "corrected_sentence": "那座桥很险，过的时候要慢。", "error_description": "错误：程度副词“很”放在了“险”之后。正确：“很”应放在形容词“险”之前，即“很险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨一大，这条路就越来越了险。", "corrected_sentence": "雨一大，这条路就越来越险了。", "error_description": "错误：“了”放在“越来越险”中间。正确：“了”应放在“险”之后，表示变化已经发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
