INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "隐私是一个人不想让别人知道的自己的事。", "primary_collocate": null, "pronunciation": "yǐn sī", "ipa": "in˨˩ sɿ˥˥", "syllable_count": 2, "sentences": [{"text": "每个人都有自己的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要问我的隐私。", "target_word": "隐私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从不跟别人说自己的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间也要尊重对方的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的日记里有很多隐私，不想给人看。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想谈家里的隐私。", "target_word": "隐私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你怎么能偷看我的隐私？", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的隐私告诉了最好的朋友。", "target_word": "隐私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，需要有自己的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居总是打听别人的隐私，大家都不喜欢他。", "target_word": "隐私", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐私权", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人不想让别人知道的自己的事，多用于日常生活和人际交往", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隐私", "is_correct": true, "explanation": "正确：隐私，意思是个人不愿让别人知道的私事。"}, {"text": "隐士", "is_correct": false, "explanation": "shì（第四声）与 sī（第一声）声母和声调都不同，意思是隐居的人。"}, {"text": "饮食", "is_correct": false, "explanation": "shí（第二声）与 sī（第一声）声母和声调都不同，意思是吃和喝。"}, {"text": "银丝", "is_correct": false, "explanation": "yín（第二声）与 yǐn（第三声）声调不同，意思是银色的细丝。"}, {"text": "引子", "is_correct": false, "explanation": "zi（轻声）与 sī（第一声）声母和声调都不同，意思是开头的部分。"}], "explanations": {"隐私": "正确：隐私，意思是个人不愿让别人知道的私事。", "隐士": "shì（第四声）与 sī（第一声）声母和声调都不同，意思是隐居的人。", "饮食": "shí（第二声）与 sī（第一声）声母和声调都不同，意思是吃和喝。", "银丝": "yín（第二声）与 yǐn（第三声）声调不同，意思是银色的细丝。", "引子": "zi（轻声）与 sī（第一声）声母和声调都不同，意思是开头的部分。"}, "sentence_index": null, "correct_answer": "隐私"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人人都能拥有的私人之物，“每个人都有自己的天气”不成立。"}, {"text": "隐私", "is_correct": true, "explanation": "正确：“隐私”指个人不愿让别人知道的事，与“每个人都有自己的”相符。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球是全人类共有的，不能说“每个人都有自己的地球”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是人人共享的，不是个人所有之物，“每个人都有自己的空气”不成立。"}], "explanations": {"天气": "语义：天气是自然现象，不是人人都能拥有的私人之物，“每个人都有自己的天气”不成立。", "隐私": "正确：“隐私”指个人不愿让别人知道的事，与“每个人都有自己的”相符。", "地球": "语义：地球是全人类共有的，不能说“每个人都有自己的地球”。", "空气": "语义：空气是人人共享的，不是个人所有之物，“每个人都有自己的空气”不成立。"}, "sentence_index": 0, "correct_answer": "隐私"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请填写你的隐私。", "explanation": "这里应该用〈个人信息〉。隐私是不愿让人知道的私事，不能用来填写表格。"}, {"text": "这份文件涉及国家隐私，不能外传。", "explanation": "这里应该用〈机密〉。隐私指个人不愿公开的私事，国家的机密事项要说机密，不能说隐私。"}, {"text": "这台机器的隐私很详细，可以参考。", "explanation": "这里应该用〈说明书〉。隐私指个人不愿公开的私事，不能用来指产品的说明文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以被偷看的东西，“偷看我的时间”不成立。"}, {"text": "隐私", "is_correct": true, "explanation": "正确：“隐私”是个人不愿让别人知道的事，与“偷看”相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不是可以被偷看的内容，与“你怎么能偷看我的”不相配。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“偷看”不搭配“心情”，心情不能像日记那样被偷看。"}], "explanations": {"时间": "语义：时间不是可以被偷看的东西，“偷看我的时间”不成立。", "隐私": "正确：“隐私”是个人不愿让别人知道的事，与“偷看”相符。", "影子": "语义：影子是光线形成的暗影，不是可以被偷看的内容，与“你怎么能偷看我的”不相配。", "心情": "搭配：“偷看”不搭配“心情”，心情不能像日记那样被偷看。"}, "sentence_index": 6, "correct_answer": "隐私"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察终于查明了事件的隐私。", "explanation": "这里应该用〈真相〉。隐私指个人不愿公开的私事，不能用来指事件的真实情况。"}, {"text": "请输入你的账号和隐私。", "explanation": "这里应该用〈密码〉。隐私是不愿公开的私事，不是需要输入的字符。"}, {"text": "警察在现场找到了重要隐私。", "explanation": "这里应该用〈证据〉。隐私是个人不愿公开的私事，不能用来指办案时找到的证据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些隐私们，不能告诉别人。", "corrected_sentence": "这些隐私，不能告诉别人。", "error_description": "“们”只用于指人的名词之后，不能附在“隐私”后，应去掉“们”；错误在“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只隐私，从不告诉别人。", "corrected_sentence": "他有一件隐私，从不告诉别人。", "error_description": "“隐私”的量词应为“件”，“只”用于动物等，不能修饰隐私，应把“只”改为“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
