INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人不愿公开的私事。", "primary_collocate": null, "pronunciation": "yǐn sī", "ipa": "in˨˩ sɿ˥˥", "syllable_count": 2, "sentences": [{"text": "医院要保护病人的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机里的照片是我的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的个人隐私要小心保护。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件会泄露用户的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者不应该公开明星的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不能随便查看员工的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在网上发别人的照片，是侵犯隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律保护每个人的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很注意保护自己的隐私，从不在网上写住址。", "target_word": "隐私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店很重视客人的隐私。", "target_word": "隐私", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐私权", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人不愿公开的私事，多用于信息、法律和保护的语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96114, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隐私", "is_correct": true, "explanation": "正确：隐私，意思是个人不愿公开的私事。"}, {"text": "隐士", "is_correct": false, "explanation": "shì（第四声）与 sī（第一声）声母和声调都不同，意思是隐居的人。"}, {"text": "饮食", "is_correct": false, "explanation": "shí（第二声）与 sī（第一声）声母和声调都不同，意思是吃和喝。"}, {"text": "银丝", "is_correct": false, "explanation": "yín（第二声）与 yǐn（第三声）声调不同，意思是银色的细丝。"}, {"text": "引子", "is_correct": false, "explanation": "zi（轻声）与 sī（第一声）声母和声调都不同，意思是开头的部分。"}], "explanations": {"隐私": "正确：隐私，意思是个人不愿公开的私事。", "隐士": "shì（第四声）与 sī（第一声）声母和声调都不同，意思是隐居的人。", "饮食": "shí（第二声）与 sī（第一声）声母和声调都不同，意思是吃和喝。", "银丝": "yín（第二声）与 yǐn（第三声）声调不同，意思是银色的细丝。", "引子": "zi（轻声）与 sī（第一声）声母和声调都不同，意思是开头的部分。"}, "sentence_index": null, "correct_answer": "隐私"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是病人的所有物，不能被医院保护。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球不是某个病人的所有物，“保护病人的地球”不成立。"}, {"text": "隐私", "is_correct": true, "explanation": "正确：“保护病人的隐私”符合医院保护患者权益的语境。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“保护”搭配的是人、权益等，“保护季节”搭配不当。"}], "explanations": {"天气": "语义：天气是自然现象，不是病人的所有物，不能被医院保护。", "地球": "语义：地球不是某个病人的所有物，“保护病人的地球”不成立。", "隐私": "正确：“保护病人的隐私”符合医院保护患者权益的语境。", "季节": "搭配：“保护”搭配的是人、权益等，“保护季节”搭配不当。"}, "sentence_index": 0, "correct_answer": "隐私"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请填写用户的隐私。", "explanation": "这里应该用〈个人信息〉。隐私是个人不愿公开的私事，不能用来填写表格。"}, {"text": "这个软件的安装隐私需要几分钟。", "explanation": "这里应该用〈程序〉。隐私指个人不愿公开的私事，不能用来指软件的安装过程。"}, {"text": "他忘记了邮箱的隐私，只好重新注册。", "explanation": "这里应该用〈密码〉。隐私是个人不愿公开的私事，不是可以忘记的登录凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不能被侵犯，与“侵犯”的对象不符。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“侵犯”一般搭配权利、利益，不能说“侵犯时间”。"}, {"text": "隐私", "is_correct": true, "explanation": "正确：“侵犯隐私”是常用搭配，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“侵犯颜色”不成立，颜色不是可被侵犯的权益。"}], "explanations": {"天空": "语义：天空不能被侵犯，与“侵犯”的对象不符。", "时间": "搭配：“侵犯”一般搭配权利、利益，不能说“侵犯时间”。", "隐私": "正确：“侵犯隐私”是常用搭配，与句意相符。", "颜色": "搭配：“侵犯颜色”不成立，颜色不是可被侵犯的权益。"}, "sentence_index": 6, "correct_answer": "隐私"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请出示你的隐私。", "explanation": "这里应该用〈身份证〉。隐私是不愿公开的私事，不是证件，不能出示。"}, {"text": "请输入你的隐私。", "explanation": "这里应该用〈密码〉。隐私不是需要输入的字符。"}, {"text": "这门课程的隐私很丰富，同学们都很喜欢。", "explanation": "这里应该用〈内容〉。隐私是个人不愿公开的私事，不能用来指课程的教学内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这类隐私们不能随便公开。", "corrected_sentence": "这类隐私不能随便公开。", "error_description": "“们”只用于指人的名词之后，不能附在“隐私”后，应去掉“们”；错误在“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只隐私，不想让人知道。", "corrected_sentence": "他有一件隐私，不想让人知道。", "error_description": "“隐私”的量词应为“件”，“只”用于动物等，不能修饰隐私，应把“只”改为“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
