INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96115, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预言是在事情发生前，先说出它会怎样。", "primary_collocate": null, "pronunciation": "yù yán", "ipa": "y˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他预言球队会赢。", "target_word": "预言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶预言今晚会下雨。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济学家预言明年的物价会上涨。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他预言这次考试会很难。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师预言我以后会当作家。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家预言未来的城市会很干净。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预言过自己会成功，后来真的成功了。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能预言这件事最后怎么样。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预言明年会有很大的变化。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友预言我们的公司明年会更大。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预言了", "label": "体标"}, {"form": "预言过", "label": "体标"}, {"form": "预言家", "label": "复合"}], "register": "中性", "sense_fingerprint": "预言：在事情发生前先说它会怎样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96115, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预言", "is_correct": true, "explanation": "预言：在事情发生前先说它会怎样（yù yán）。"}, {"text": "语言", "is_correct": false, "explanation": "语言 yǔ yán 与 预言 yù yán 只有第一音节声调不同（第三声与第四声），意思是“语言”。"}, {"text": "预演", "is_correct": false, "explanation": "预演 yù yǎn 与 预言 yù yán 只有第二音节声调不同（第三声与第二声），意思是“正式前先演练”。"}, {"text": "一言", "is_correct": false, "explanation": "一言 yì yán 与 预言 yù yán 第一音节韵母不同（i 与 ü），声调相同，意思是“一句话”。"}], "explanations": {"预言": "预言：在事情发生前先说它会怎样（yù yán）。", "语言": "语言 yǔ yán 与 预言 yù yán 只有第一音节声调不同（第三声与第四声），意思是“语言”。", "预演": "预演 yù yǎn 与 预言 yù yán 只有第二音节声调不同（第三声与第二声），意思是“正式前先演练”。", "一言": "一言 yì yán 与 预言 yù yán 第一音节韵母不同（i 与 ü），声调相同，意思是“一句话”。"}, "sentence_index": null, "correct_answer": "预言"}, "level_3": {"options": [{"text": "预言", "is_correct": true, "explanation": "预言：在事情发生前先说它会怎样，与“球队会赢”的语境相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆是想起过去的事，句中“球队会赢”指将来，不能回忆将来。"}, {"text": "看见", "is_correct": false, "explanation": "语义：看见是亲眼看到已经发生的事，“球队会赢”还没有发生，不能看见。"}, {"text": "嘱咐", "is_correct": false, "explanation": "配价：“嘱咐”需要受话人，如“嘱咐某人……”，这里缺少受话人。"}], "explanations": {"预言": "预言：在事情发生前先说它会怎样，与“球队会赢”的语境相符。", "回忆": "语义：回忆是想起过去的事，句中“球队会赢”指将来，不能回忆将来。", "看见": "语义：看见是亲眼看到已经发生的事，“球队会赢”还没有发生，不能看见。", "嘱咐": "配价：“嘱咐”需要受话人，如“嘱咐某人……”，这里缺少受话人。"}, "sentence_index": 0, "correct_answer": "预言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电台预言下周的节目安排。", "explanation": "这里应该用〈预告〉。预告是提前告知即将播出的节目，“预言”指断言未来，不用于节目安排。"}, {"text": "他预言饭菜已经做好了。", "explanation": "这里应该直接说〈做好了〉。“预言”只用于尚未发生的事，饭菜已经做好是既成事实。"}, {"text": "这些迹象预言着经济会好转。", "explanation": "这里应该用〈预示〉。迹象显示未来情况要用“预示”，“预言”的主语应是人，不用迹象作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预言", "is_correct": true, "explanation": "预言：在事情发生前先说它会怎样，与“自己会成功”的语境相符。"}, {"text": "看见", "is_correct": false, "explanation": "配价：“看见”的对象是具体可见的人或物，不能接“自己会成功”这样的内容。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”针对他人的言行，不能接“会成功”这样的内容。"}, {"text": "诅咒", "is_correct": false, "explanation": "搭配：“诅咒”的内容是不幸的事，不能接“会成功”。"}], "explanations": {"预言": "预言：在事情发生前先说它会怎样，与“自己会成功”的语境相符。", "看见": "配价：“看见”的对象是具体可见的人或物，不能接“自己会成功”这样的内容。", "嘲笑": "搭配：“嘲笑”针对他人的言行，不能接“会成功”这样的内容。", "诅咒": "搭配：“诅咒”的内容是不幸的事，不能接“会成功”。"}, "sentence_index": 6, "correct_answer": "预言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提前预言了下周二的门诊。", "explanation": "这里应该用〈预约〉。预约是事先约定时间或服务，“预言”指断言将要发生的事，两者不能互换。"}, {"text": "他昨晚预言了明天要学的生词。", "explanation": "这里应该用〈预习〉。预习是课前自学生词，“预言”指事先说出将要发生的事，不能用于学习。"}, {"text": "会议预言下午三点结束。", "explanation": "这里应该用〈预计〉。对会议等安排的估计要用“预计”，“预言”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没预言了这种事。", "corrected_sentence": "他从来没预言过这种事。", "error_description": "“从来没……过”表示从未有过的经历，动词后要用“过”，不用“了”。这里“预言了”是错误形式，应改为“预言过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他预言地很准。", "corrected_sentence": "他预言得很准。", "error_description": "“地”用于动词前修饰动词，动词后的补语要用“得”。这里“预言地很准”是错误形式，应改为“预言得很准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
