INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先说出将要发生的事。", "primary_collocate": null, "pronunciation": "yù yán", "ipa": "y˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他预言明年会有大雪。", "target_word": "预言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家预言今年夏天会很热。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人预言这场雨很快会停。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她早就预言了公司的失败。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人预言这个城市会越来越大。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他曾经预言过手机会改变我们的生活。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生预言他三个月以后就能走路。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能预言明天的天气会怎么样。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸预言明年的房价会下降。", "target_word": "预言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他预言了比赛的结果，最后真的对了。", "target_word": "预言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预言了", "label": "体标"}, {"form": "预言过", "label": "体标"}, {"form": "预言家", "label": "复合"}], "register": "中性", "sense_fingerprint": "预言：事先说出将要发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96116, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预言", "is_correct": true, "explanation": "预言：事先说出将要发生的事（yù yán）。"}, {"text": "语言", "is_correct": false, "explanation": "语言 yǔ yán 与 预言 yù yán 只有第一音节声调不同（第三声与第四声），意思是“语言”。"}, {"text": "预演", "is_correct": false, "explanation": "预演 yù yǎn 与 预言 yù yán 只有第二音节声调不同（第三声与第二声），意思是“正式前先演练”。"}, {"text": "一言", "is_correct": false, "explanation": "一言 yì yán 与 预言 yù yán 第一音节韵母不同（i 与 ü），声调相同，意思是“一句话”。"}], "explanations": {"预言": "预言：事先说出将要发生的事（yù yán）。", "语言": "语言 yǔ yán 与 预言 yù yán 只有第一音节声调不同（第三声与第四声），意思是“语言”。", "预演": "预演 yù yǎn 与 预言 yù yán 只有第二音节声调不同（第三声与第二声），意思是“正式前先演练”。", "一言": "一言 yì yán 与 预言 yù yán 第一音节韵母不同（i 与 ü），声调相同，意思是“一句话”。"}, "sentence_index": null, "correct_answer": "预言"}, "level_3": {"options": [{"text": "预言", "is_correct": true, "explanation": "预言：事先说出将要发生的事，与“明年会有大雪”的语境相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆是想起过去的事，句中“明年”指将来，不能回忆将来的事。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的对象是房间、地面等具体场所，不能接“明年会有大雪”这样的句子内容。"}, {"text": "嘱咐", "is_correct": false, "explanation": "配价：“嘱咐”需要受话人，如“嘱咐某人……”，这里缺少受话人。"}], "explanations": {"预言": "预言：事先说出将要发生的事，与“明年会有大雪”的语境相符。", "回忆": "语义：回忆是想起过去的事，句中“明年”指将来，不能回忆将来的事。", "打扫": "配价：“打扫”的对象是房间、地面等具体场所，不能接“明年会有大雪”这样的句子内容。", "嘱咐": "配价：“嘱咐”需要受话人，如“嘱咐某人……”，这里缺少受话人。"}, "sentence_index": 0, "correct_answer": "预言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我预言这个菜已经凉了。", "explanation": "这里应该用〈发现〉。“预言”只用于尚未发生的事，菜已经凉了是眼前的事实。"}, {"text": "影视公司预言了下个月的新片。", "explanation": "这里应该用〈预告〉。预告是提前告知即将上映的内容，预言不用于宣传节目或影片。"}, {"text": "我们预言了今天的菜单。", "explanation": "这里应该用〈定下〉。菜单是人为安排的，不是事先断言会发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预言", "is_correct": true, "explanation": "预言：事先说出将要发生的事，与“三个月以后就能走路”的预测相符。"}, {"text": "看见", "is_correct": false, "explanation": "配价：“看见”的对象是具体可见的人或物，不能接“他三个月以后就能走路”这样的内容。"}, {"text": "负责", "is_correct": false, "explanation": "搭配：“负责”后接工作或事务，不能接“他三个月以后就能走路”这样的预测。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆是想起过去的事，句中“三个月以后”指将来，不能回忆将来的事。"}], "explanations": {"预言": "预言：事先说出将要发生的事，与“三个月以后就能走路”的预测相符。", "看见": "配价：“看见”的对象是具体可见的人或物，不能接“他三个月以后就能走路”这样的内容。", "负责": "搭配：“负责”后接工作或事务，不能接“他三个月以后就能走路”这样的预测。", "回忆": "语义：回忆是想起过去的事，句中“三个月以后”指将来，不能回忆将来的事。"}, "sentence_index": 6, "correct_answer": "预言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提前预言了下周二的门诊。", "explanation": "这里应该用〈预约〉。预约是事先约定时间或服务，预言指断言将要发生的事，两者不能互换。"}, {"text": "我昨晚预言了明天的课文。", "explanation": "这里应该用〈预习〉。预习是课前自学课文，“预言”指事先说出将要发生的事，不用于学习。"}, {"text": "我们预言了明天的酒店房间。", "explanation": "这里应该用〈预定〉。预定是提前订下房间或座位，“预言”不能表示订房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人没预言了地震。", "corrected_sentence": "这位老人没预言过地震。", "error_description": "否定词“没”之后不能再用“了”；未曾有过的经历要用“没……过”。这里“没预言了”是错误形式，应改为“没预言过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人预言地很准。", "corrected_sentence": "这位老人预言得很准。", "error_description": "“地”用于动词前修饰动词，动词后的补语要用“得”。这里“预言地很准”是错误形式，应改为“预言得很准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
