INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96117, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "领取是去把给你的东西拿回来。", "primary_collocate": null, "pronunciation": "lǐng qǔ", "ipa": "liŋ˨˩˦ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我去邮局领取包裹。", "target_word": "领取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在门口领取饮料。", "target_word": "领取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开会前请先领取资料。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人每个月都去领取补助。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她下班后去快递站领取了包裹。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以领取一件红色外套。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校通知大家下周一来领取成绩单。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经领取过奖状了。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你领取了号码牌，就可以进去了。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他排了两个小时队，终于领取了那张票。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "领取了", "label": "体标"}, {"form": "领取过", "label": "体标"}], "register": "中性", "sense_fingerprint": "领取：去把给自己的东西拿回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领取", "is_correct": true, "explanation": "领取：去把给自己的东西拿回来，与“去邮局”和“包裹”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱包裹。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“包裹”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语“包裹”。"}], "explanations": {"领取": "领取：去把给自己的东西拿回来，与“去邮局”和“包裹”的语境相符。", "唱": "搭配：“唱”的对象是歌曲，不能说唱包裹。", "笑": "配价：“笑”是不及物动词，不能带宾语“包裹”。", "睡": "配价：“睡”是不及物动词，不能带宾语“包裹”。"}, "sentence_index": 0, "correct_answer": "领取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人每个月都去银行领取水费。", "explanation": "这里应该用〈缴纳〉。领取是去拿回给自己的东西，每月去银行交水费要用“缴纳”。"}, {"text": "老人每个月都去超市领取电费。", "explanation": "这里应该用〈交〉。领取是去拿回发给自己的东西，每月去超市交电费要用“交”。"}, {"text": "物业每个月都向业主领取物业费。", "explanation": "这里应该用〈收取〉。物业向业主收费要用“收取”，“领取”不能表示收钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领取", "is_correct": true, "explanation": "领取：去拿回发给自己的东西，与“下周一来”和“成绩单”的语境相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指用力把东西分开，成绩单由学校发放，学生来取时不能说撕成绩单。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”针对污渍或表面，成绩单不能被擦。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料等液体，成绩单不能喝。"}], "explanations": {"领取": "领取：去拿回发给自己的东西，与“下周一来”和“成绩单”的语境相符。", "撕": "语义：“撕”指用力把东西分开，成绩单由学校发放，学生来取时不能说撕成绩单。", "擦": "搭配：“擦”针对污渍或表面，成绩单不能被擦。", "喝": "搭配：“喝”的对象是饮料等液体，成绩单不能喝。"}, "sentence_index": 6, "correct_answer": "领取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中领取了第一名。", "explanation": "这里应该用〈获得〉。领取是拿回发给自己的东西，比赛名次要用“获得”。"}, {"text": "他领取了一个月的假。", "explanation": "这里应该用〈请〉。请假是向单位申请休假，“领取”指拿到发给的东西，不能用于假期。"}, {"text": "他领取了一句道歉。", "explanation": "这里应该用〈听到〉。领取指拿到发给的东西，别人的道歉要用“听到”，不能用“领取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经领取着包裹。", "corrected_sentence": "我已经领取了包裹。", "error_description": "“已经”后面表示完成的动作要用“了”，“着”表示动作持续的状态。这里“领取着”是错误形式，应改为“领取了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没领取着奖状。", "corrected_sentence": "我从来没领取过奖状。", "error_description": "“从来没……过”表示否定的经历，动词后要用“过”，不能用表示动作持续状态的“着”。这里“领取着”是错误形式，应改为“领取过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
