INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96118, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取得发给的东西。", "primary_collocate": null, "pronunciation": "lǐng qǔ", "ipa": "liŋ˨˩˦ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "请到前台领取礼物。", "target_word": "领取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天可以领取新书。", "target_word": "领取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去银行领取了奖金。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生要在周五领取校服。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请带身份证来领取包裹。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，大家排队领取奖品。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还没有领取这个月的工资。", "target_word": "领取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天领取过一张入场券。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以拿着这张票去门口领取小礼物。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领取证书的人请在下午三点前到会议室。", "target_word": "领取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "领取了", "label": "体标"}, {"form": "领取过", "label": "体标"}], "register": "中性", "sense_fingerprint": "领取：取得别人发给自己的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领取", "is_correct": true, "explanation": "领取：取得发给的东西，与“到前台”和“礼物”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，礼物不能吃。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语“礼物”。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象一般是食物，“咬礼物”不符合语境。"}], "explanations": {"领取": "领取：取得发给的东西，与“到前台”和“礼物”的语境相符。", "吃": "搭配：“吃”的对象是食物，礼物不能吃。", "哭": "配价：“哭”是不及物动词，不能带宾语“礼物”。", "咬": "搭配：“咬”的对象一般是食物，“咬礼物”不符合语境。"}, "sentence_index": 0, "correct_answer": "领取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生要在周五领取学费。", "explanation": "这里应该用〈交〉。领取是从发放方拿到东西，交学费是把钱交给学校，方向相反。"}, {"text": "我在超市领取了煤气费。", "explanation": "这里应该用〈缴纳〉。领取是拿回发给自己的东西，交煤气费要用“缴纳”，不能用“领取”。"}, {"text": "饭店向客人领取服务费。", "explanation": "这里应该用〈收取〉。领取是接受发放的东西，向客人收费要用“收取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领取", "is_correct": true, "explanation": "领取：取得发给的东西，与“这个月的工资”的语境相符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指享用好处，工资是领取的报酬，不能说享受工资。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”指期待，句中说的是取得与否，不能用期待来表达。"}, {"text": "吐", "is_correct": false, "explanation": "搭配：“吐”的对象是口中的东西，工资不能吐，句子不成立。"}], "explanations": {"领取": "领取：取得发给的东西，与“这个月的工资”的语境相符。", "享受": "语义：“享受”指享用好处，工资是领取的报酬，不能说享受工资。", "盼望": "语义：“盼望”指期待，句中说的是取得与否，不能用期待来表达。", "吐": "搭配：“吐”的对象是口中的东西，工资不能吐，句子不成立。"}, "sentence_index": 6, "correct_answer": "领取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于领取了冠军。", "explanation": "这里应该用〈获得〉。领取是从发放处拿到已经分发的东西，比赛名次要用“获得”。"}, {"text": "警察从他那里领取了三包毒品。", "explanation": "这里应该用〈没收〉。领取是接受发给的东西，从人身上强制拿走违禁品要用“没收”。"}, {"text": "他按时领取了水电费。", "explanation": "这里应该用〈缴纳〉。领取是接收发放的东西，按时交水电费要用“缴纳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从没领取了任何奖金。", "corrected_sentence": "她从没领取过任何奖金。", "error_description": "“从没……过”表示从未有过的经历，要用“过”，不能用“了”。这里应改为“从没领取过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把奖金领取。", "corrected_sentence": "她把奖金领取了。", "error_description": "“把”字句中，动词后通常要带“了”“过”或其他补语等成分，单用“领取”句子不完整。这里应改为“把奖金领取了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
