INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "首位是排在第一的位置。", "primary_collocate": null, "pronunciation": "shǒu wèi", "ipa": "ʂou˨˩˦ wei˥˩", "syllable_count": 2, "sentences": [{"text": "学习应该放在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把安全放在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这次比赛中，他的成绩排在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对她来说，家人永远在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口居全国首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对学生来说，健康比成绩更应该放在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我心里，孩子的快乐永远排在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把客人放在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果的销量排在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作很重要，但是身体应该摆在首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "重要性、数量、名次上排第一的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首位", "is_correct": true, "explanation": "正确：“放在首位”表示把学习看得最重要，与句意相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：把学习放在“垃圾”的位置与“应该”的价值判断矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：学习与“冰箱”无关，句子说不通。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“放在厕所”只表示物理位置，与“学习”不搭配。"}], "explanations": {"首位": "正确：“放在首位”表示把学习看得最重要，与句意相符。", "垃圾": "语义：把学习放在“垃圾”的位置与“应该”的价值判断矛盾。", "冰箱": "语义：学习与“冰箱”无关，句子说不通。", "厕所": "搭配：“放在厕所”只表示物理位置，与“学习”不搭配。"}, "sentence_index": 0, "correct_answer": "首位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们首位合作，双方都很满意。", "explanation": "这里应该用〈首次〉。“首位”指排列次序上的第一位，不能表示第一次做某事，应说“首次”。"}, {"text": "买房时他先付了首位，剩下的分期还款。", "explanation": "这里应该用〈首付〉。“首位”指次序，购房时先交的那笔钱要说“首付”。"}, {"text": "首位，我们来讨论一下这个问题。", "explanation": "这里应该用〈首先〉。“首位”是名词，不能作副词放在句首引出步骤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首位", "is_correct": true, "explanation": "正确：“排在首位”表示快乐最重要，与“在我心里”的语境吻合。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“数字”不能表示排名位置，不说“排在数字”。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：“尾巴”指末端，快乐不能“排在尾巴”，与“在我心里”的重视语境矛盾。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”与快乐无关，句子说不通。"}], "explanations": {"首位": "正确：“排在首位”表示快乐最重要，与“在我心里”的语境吻合。", "数字": "搭配：“数字”不能表示排名位置，不说“排在数字”。", "尾巴": "语义：“尾巴”指末端，快乐不能“排在尾巴”，与“在我心里”的重视语境矛盾。", "账单": "语义：“账单”与快乐无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "首位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该首位考虑安全。", "explanation": "这里应该用〈优先〉。“首位”是名词，不能作状语修饰动词；“优先”表示先于其他来处理。"}, {"text": "这本书的首位写着作者的名字。", "explanation": "这里应该用〈首页〉。“首位”指次序，书的页面要说“首页”。"}, {"text": "这是故事的首位，我们慢慢读。", "explanation": "这里应该用〈开端〉。“首位”指排列次序，不能表示故事或过程的起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在这次比赛中，排在首位是他。", "corrected_sentence": "在这次比赛中，排在首位的是他。", "error_description": "错误：“排在首位”作主语时，中间要加“的”，应说“排在首位的是他”，不能说“排在首位是他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
