INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "第一位；最前面的位置。", "primary_collocate": null, "pronunciation": "shǒu wèi", "ipa": "ʂou˨˩˦ wei˥˩", "syllable_count": 2, "sentences": [{"text": "他站在队伍的首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首位客人已经到了。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在长桌的首位，大家都看着他。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的名字写在名单的首位。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首位上台的人是一个小女孩。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，首位出场的选手很紧张。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是首位到这里的客人，送你一份小礼物。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车来了，首位下车的是一位老人。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的首位读者是我妈妈。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走在队伍的首位，手里拿着一面旗。", "target_word": "首位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "次序上最前面的位置，或第一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首位", "is_correct": true, "explanation": "正确：“首位”指队伍中最前面的位置，与“站在队伍的”搭配。"}, {"text": "标题", "is_correct": false, "explanation": "语义：“标题”不能站立，与“站在队伍”的意思矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“站在”来说明位置，与“站在队伍的”不搭配。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：“秘密”不是人或物，无法“站在队伍”里。"}], "explanations": {"首位": "正确：“首位”指队伍中最前面的位置，与“站在队伍的”搭配。", "标题": "语义：“标题”不能站立，与“站在队伍”的意思矛盾。", "颜色": "搭配：“颜色”不能用“站在”来说明位置，与“站在队伍的”不搭配。", "秘密": "语义：“秘密”不是人或物，无法“站在队伍”里。"}, "sentence_index": 0, "correct_answer": "首位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "首位，请大家先安静下来。", "explanation": "这里应该用〈首先〉。“首位”是名词，不能作副词放在句首引出步骤。"}, {"text": "我首位来到中国，一切都很新鲜。", "explanation": "这里应该用〈首次〉。“首位”指次序上的第一位，不能表示第一次做某事，应说“首次”。"}, {"text": "这本书的首位是一个小故事。", "explanation": "这里应该用〈开头〉。“首位”指次序上的第一位，不能表示全书的开头部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首位", "is_correct": true, "explanation": "正确：“首位到这里的客人”表示第一个到的人，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是人，不能作“到这里的客人”的修饰语。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”不能用来修饰“客人”，两者搭配不上。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”不是人，不能“到这里”成为客人。"}], "explanations": {"首位": "正确：“首位到这里的客人”表示第一个到的人，与句意相符。", "桌子": "语义：“桌子”不是人，不能作“到这里的客人”的修饰语。", "钥匙": "搭配：“钥匙”不能用来修饰“客人”，两者搭配不上。", "雨水": "语义：“雨水”不是人，不能“到这里”成为客人。"}, "sentence_index": 6, "correct_answer": "首位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天戴了一套金色的首位，很漂亮。", "explanation": "这里应该用〈首饰〉。“首位”指次序，戴在身上的装饰品要说“首饰”。"}, {"text": "我们应该首位安排他。", "explanation": "这里应该用〈优先〉。“首位”是名词，不能作状语修饰动词。"}, {"text": "这本书的首位写着作者的名字。", "explanation": "这里应该用〈首页〉。“首位”指次序，书的页面要说“首页”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三位首位选手已经出场了。", "corrected_sentence": "首位选手已经出场了。", "error_description": "错误：“首位”本身已表示第一个，不能再与“三位”等数量词并用，应去掉“三位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是首位到这里的客人们。", "corrected_sentence": "她是首位到这里的客人。", "error_description": "错误：“首位”指第一个，只对应一个人，后面的“客人”不能加“们”，应说“首位到这里的客人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "党外", "is_correct": true, "explanation": "正确：“党外”指党的组织以外，与“党内”相对。"}, {"text": "民间", "is_correct": false, "explanation": "“民间”指民众之中，与“党内”不构成反义关系。"}, {"text": "人民", "is_correct": false, "explanation": "“人民”泛指全体国民，与“党内”不构成反义关系。"}, {"text": "会议", "is_correct": false, "explanation": "“会议”指集会，与“党内”不构成反义关系。"}], "correct_answer": "党外", "explanations": {"党外": "正确：“党外”指党的组织以外，与“党内”相对。", "民间": "“民间”指民众之中，与“党内”不构成反义关系。", "人民": "“人民”泛指全体国民，与“党内”不构成反义关系。", "会议": "“会议”指集会，与“党内”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "党外", "is_correct": true, "explanation": "正确：“党外”指党的组织以外，与“党内”相对。"}, {"text": "社会", "is_correct": false, "explanation": "“社会”泛指人类共同生活的整体，与“党内”不构成反义关系。"}, {"text": "国家", "is_correct": false, "explanation": "“国家”指政治实体，与“党内”不构成反义关系。"}, {"text": "小组", "is_correct": false, "explanation": "“小组”指较小的工作单位，与“党内”不构成反义关系。"}], "correct_answer": "党外", "explanations": {"党外": "正确：“党外”指党的组织以外，与“党内”相对。", "社会": "“社会”泛指人类共同生活的整体，与“党内”不构成反义关系。", "国家": "“国家”指政治实体，与“党内”不构成反义关系。", "小组": "“小组”指较小的工作单位，与“党内”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "党内是这个党的里面。", "primary_collocate": null, "pronunciation": "dǎng nèi", "ipa": "tɑŋ²¹⁴ nei⁵¹", "syllable_count": 2, "sentences": [{"text": "他在党内工作了二十年。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内有一千多名年轻人。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事在党内引起了讨论。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内的人都知道这个消息。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内开了一次大会。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是党内最年轻的人。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内和党外的朋友都来了。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内每个人都要遵守规定。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息先在党内传开了。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在党内认识很多老朋友。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "党内人士", "label": "复合"}, {"form": "党内职务", "label": "复合"}, {"form": "黨內", "label": "繁体"}], "register": "书面", "sense_fingerprint": "处在某个党的范围之中，与党外相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党内", "is_correct": true, "explanation": "正确：“党内”指党的范围之中，与“工作了二十年”的语境吻合。"}, {"text": "梦里", "is_correct": false, "explanation": "语义：“梦里”不是工作的场所，“在梦里工作了二十年”说不通。"}, {"text": "口袋里", "is_correct": false, "explanation": "搭配：“工作”要说在某个单位或地方，“口袋里”不能作工作的地点。"}, {"text": "镜子里", "is_correct": false, "explanation": "语义：“镜子里”只是影像所在，不能指人工作的地方，句意荒谬。"}], "explanations": {"党内": "正确：“党内”指党的范围之中，与“工作了二十年”的语境吻合。", "梦里": "语义：“梦里”不是工作的场所，“在梦里工作了二十年”说不通。", "口袋里": "搭配：“工作”要说在某个单位或地方，“口袋里”不能作工作的地点。", "镜子里": "语义：“镜子里”只是影像所在，不能指人工作的地方，句意荒谬。"}, "sentence_index": 0, "correct_answer": "党内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种手机只在党内销售。", "explanation": "这里应该用〈国内〉。“党内”指党组织的范围，销售范围要说“国内”。"}, {"text": "孩子们在党内玩。", "explanation": "这里应该用〈室内〉。“党内”只指党组织的范围，不指房间里面。"}, {"text": "他的党内有一颗蛀牙。", "explanation": "这里应该用〈口腔内〉。“党内”指党的内部范围，不指身体里面，牙齿在口腔内要说“口腔内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党内", "is_correct": true, "explanation": "正确：“党内”与“党外”相对，与“朋友都来了”的语境吻合。"}, {"text": "水底", "is_correct": false, "explanation": "语义：“水底”不是人聚集的地方，“水底和党外的朋友都来了”说不通。"}, {"text": "书包里", "is_correct": false, "explanation": "搭配：“朋友都来了”的主语是人，“书包里”不能与“朋友”组合。"}, {"text": "柜子里", "is_correct": false, "explanation": "语义：“柜子里”不能作人聚集的场所，句意荒谬。"}], "explanations": {"党内": "正确：“党内”与“党外”相对，与“朋友都来了”的语境吻合。", "水底": "语义：“水底”不是人聚集的地方，“水底和党外的朋友都来了”说不通。", "书包里": "搭配：“朋友都来了”的主语是人，“书包里”不能与“朋友”组合。", "柜子里": "语义：“柜子里”不能作人聚集的场所，句意荒谬。"}, "sentence_index": 6, "correct_answer": "党内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在党内做饭，做了很多菜。", "explanation": "这里应该用〈厨房里〉。“党内”指党的范围，不能指做饭的地点。"}, {"text": "爷爷在党内种菜。", "explanation": "这里应该用〈菜园里〉。“党内”指党的范围，不指种菜的地方。"}, {"text": "鱼在党内游。", "explanation": "这里应该用〈水里〉。“党内”只用于党组织范围，不能指鱼游动的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事只党内讨论。", "corrected_sentence": "这件事只在党内讨论。", "error_description": "错误：“只党内讨论”。正确：“只在党内讨论”。表示地点的“党内”前必须加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在党内里担任过职务。", "corrected_sentence": "他在党内担任过职务。", "error_description": "错误：“党内里担任过职务”。正确：“党内担任过职务”。“党内”本身已表示“党的里面”，后面不能再加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
