INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96124, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "党外", "is_correct": true, "explanation": "正确：“党外”指党的组织以外，与“党内”相对。"}, {"text": "社会", "is_correct": false, "explanation": "“社会”泛指人类共同生活的整体，与“党内”不构成反义关系。"}, {"text": "国家", "is_correct": false, "explanation": "“国家”指政治实体，与“党内”不构成反义关系。"}, {"text": "小组", "is_correct": false, "explanation": "“小组”指较小的工作单位，与“党内”不构成反义关系。"}], "correct_answer": "党外", "explanations": {"党外": "正确：“党外”指党的组织以外，与“党内”相对。", "社会": "“社会”泛指人类共同生活的整体，与“党内”不构成反义关系。", "国家": "“国家”指政治实体，与“党内”不构成反义关系。", "小组": "“小组”指较小的工作单位，与“党内”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "党的内部。", "primary_collocate": null, "pronunciation": "dǎng nèi", "ipa": "tɑŋ²¹⁴ nei⁵¹", "syllable_count": 2, "sentences": [{"text": "这个问题要先在党内解决。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内选举每五年进行一次。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内有不同的意见，大家都可以说。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责党内的宣传工作。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是党内的事，外人不用管。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内的规定比一般的规定更严。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直说党内要有民主。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件只在党内发放，不对外公开。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内出现了新的矛盾。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党内讨论过这个问题，还没有结果。", "target_word": "党内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "党内民主", "label": "复合"}, {"form": "党内职务", "label": "复合"}, {"form": "黨內", "label": "繁体"}], "register": "书面", "sense_fingerprint": "党的内部事务、关系和组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党内", "is_correct": true, "explanation": "正确：“党内”指党的内部，与“这个问题要先在……解决”的语境吻合。"}, {"text": "梦里", "is_correct": false, "explanation": "语义：“梦里”不是解决问题的场所，“在梦里解决”说不通。"}, {"text": "水底", "is_correct": false, "explanation": "语义：“水底”不是处理问题的地点，“在水底解决”句意荒谬。"}, {"text": "口袋里", "is_correct": false, "explanation": "搭配：“解决问题”要有具体的组织或场所，“口袋里”不能与之搭配。"}], "explanations": {"党内": "正确：“党内”指党的内部，与“这个问题要先在……解决”的语境吻合。", "梦里": "语义：“梦里”不是解决问题的场所，“在梦里解决”说不通。", "水底": "语义：“水底”不是处理问题的地点，“在水底解决”句意荒谬。", "口袋里": "搭配：“解决问题”要有具体的组织或场所，“口袋里”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "党内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料只在党内卖。", "explanation": "这里应该用〈国内〉。“党内”指党的内部范围，销售范围要说“国内”。"}, {"text": "小猫在党内睡觉。", "explanation": "这里应该用〈纸箱内〉。“党内”指党的内部范围，不指箱子里面。"}, {"text": "药物进入党内。", "explanation": "这里应该用〈体内〉。“党内”只指党的范围，人体内要说“体内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党内", "is_correct": true, "explanation": "正确：“党内”指党的内部，与“他一直说……要有民主”的语境吻合。"}, {"text": "书包里", "is_correct": false, "explanation": "搭配：“要有民主”的主语应是组织或群体，“书包里”不能作这类主语。"}, {"text": "柜子里", "is_correct": false, "explanation": "语义：“柜子里”是存放物品的地方，“柜子里要有民主”句意荒谬。"}, {"text": "镜子里", "is_correct": false, "explanation": "语义：“镜子里”只是影像所在，“镜子里要有民主”说不通。"}], "explanations": {"党内": "正确：“党内”指党的内部，与“他一直说……要有民主”的语境吻合。", "书包里": "搭配：“要有民主”的主语应是组织或群体，“书包里”不能作这类主语。", "柜子里": "语义：“柜子里”是存放物品的地方，“柜子里要有民主”句意荒谬。", "镜子里": "语义：“镜子里”只是影像所在，“镜子里要有民主”说不通。"}, "sentence_index": 6, "correct_answer": "党内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "党内种了很多花。", "explanation": "这里应该用〈园内〉。“党内”指党的内部范围，不指花园里面。"}, {"text": "货物放在党内。", "explanation": "这里应该用〈库内〉。“党内”只指党组织的范围，不指仓库。"}, {"text": "党内有电梯。", "explanation": "这里应该用〈楼内〉。“党内”只指党的范围，不指建筑物，“党内有电梯”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题只党内讨论。", "corrected_sentence": "这个问题只在党内讨论。", "error_description": "错误：“只党内讨论”。正确：“只在党内讨论”。表示地点的“党内”前必须加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在党内里传达了这个决定。", "corrected_sentence": "他们在党内传达了这个决定。", "error_description": "错误：“党内里传达了这个决定”。正确：“党内传达了这个决定”。“党内”本身已表示“党的里面”，后面不能再加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
