INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96125, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一向是从以前到现在，一直都是这样。", "primary_collocate": null, "pronunciation": "yí xiàng", "ipa": "i˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他一向很早起床。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一向不喝咖啡。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一向身体很好。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜一向很好吃。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一向对学生很好。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟一向怕黑。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一向喜欢安静，不爱去热闹的地方。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司一向重视质量。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一向说话算话，大家都相信他。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的冬天一向很冷。", "target_word": "一向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "副词：从过去到现在一直如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea7a4939-1ea5-4472-88d4-95bdbfe97d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一向", "is_correct": true, "explanation": "正确答案：一向 yí xiàng，副词，表示从过去到现在一直如此。"}, {"text": "意向", "is_correct": false, "explanation": "意向 yì xiàng：第一音节 yì（第四声）与 yí（第二声）声调不同，意思是意图、打算。"}, {"text": "意想", "is_correct": false, "explanation": "意想 yì xiǎng：第一音节声调与 yí 不同，第二音节 xiǎng（第三声）与 xiàng（第四声）声调也不同，意思是想象、预料（如“意想不到”）。"}, {"text": "一线", "is_correct": false, "explanation": "一线 yí xiàn：xiàn 与 xiàng 的韵尾不同（-n 与 -ng），意思是第一线、前线（如“一线城市”）。"}, {"text": "一下", "is_correct": false, "explanation": "一下 yí xià：xià 没有 xiàng 的韵尾 -ng，意思是一次、稍微（如“看一下”）。"}], "explanations": {"一向": "正确答案：一向 yí xiàng，副词，表示从过去到现在一直如此。", "意向": "意向 yì xiàng：第一音节 yì（第四声）与 yí（第二声）声调不同，意思是意图、打算。", "意想": "意想 yì xiǎng：第一音节声调与 yí 不同，第二音节 xiǎng（第三声）与 xiàng（第四声）声调也不同，意思是想象、预料（如“意想不到”）。", "一线": "一线 yí xiàn：xiàn 与 xiàng 的韵尾不同（-n 与 -ng），意思是第一线、前线（如“一线城市”）。", "一下": "一下 yí xià：xià 没有 xiàng 的韵尾 -ng，意思是一次、稍微（如“看一下”）。"}, "sentence_index": null, "correct_answer": "一向"}, "level_3": {"options": [{"text": "才", "is_correct": false, "explanation": "语义：“才”表示“到现在才”，说明时间偏晚，与“很早”矛盾。"}, {"text": "一向", "is_correct": true, "explanation": "正确：“一向”表示长期一贯如此，与“很早起床”的习惯相符。"}, {"text": "几乎", "is_correct": false, "explanation": "搭配：“几乎”表示接近但未达到，不能修饰“很早起床”这种习惯性动作。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生的一次性动作，不能表示长期习惯。"}], "explanations": {"才": "语义：“才”表示“到现在才”，说明时间偏晚，与“很早”矛盾。", "一向": "正确：“一向”表示长期一贯如此，与“很早起床”的习惯相符。", "几乎": "搭配：“几乎”表示接近但未达到，不能修饰“很早起床”这种习惯性动作。", "立刻": "语义：“立刻”表示马上发生的一次性动作，不能表示长期习惯。"}, "sentence_index": 0, "correct_answer": "一向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天他一向迟到了。", "explanation": "这里把“一向”用成了单次事件的意思；“一向”表示长期持续的状态，不能用来说某一天的事。"}, {"text": "明天我一向会去北京。", "explanation": "“一向”只能描述从过去到现在的情况，不能指将来，这句说的是明天，用法不对。"}, {"text": "他一向参加了一次比赛。", "explanation": "这里把“一向”用成了描述单次行为的意思；“一向”只表示一贯的习惯或状态，不能修饰一次性的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正", "is_correct": false, "explanation": "体貌：“正”表示动作正在进行，“喜欢”是状态动词，不能用进行的意思。"}, {"text": "一向", "is_correct": true, "explanation": "正确：“一向”表示长期一贯的喜好，与“喜欢安静、不爱热闹”相符。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示一下子发生的变化，不能说明长期的喜好。"}, {"text": "不再", "is_correct": false, "explanation": "语义：“不再”表示以前有、现在没有了，与“一向喜欢安静”的一贯状态相反。"}], "explanations": {"正": "体貌：“正”表示动作正在进行，“喜欢”是状态动词，不能用进行的意思。", "一向": "正确：“一向”表示长期一贯的喜好，与“喜欢安静、不爱热闹”相符。", "顿时": "语义：“顿时”表示一下子发生的变化，不能说明长期的喜好。", "不再": "语义：“不再”表示以前有、现在没有了，与“一向喜欢安静”的一贯状态相反。"}, "sentence_index": 6, "correct_answer": "一向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一向变胖了。", "explanation": "这里把“一向”用成了表示持续变化过程的意思；“一向”只说状态从过去到现在始终如此，不能用来说已经发生的变化。"}, {"text": "这里的天气一向变热了。", "explanation": "这里把“一向”用成了表示逐渐变化的意思；“一向”只说状态一直如此，不能用来说已经发生的变化。"}, {"text": "他一向病好了。", "explanation": "这里把“一向”用成了表示状态改变的意思；“一向”只表示一直如此，不能用来说已经完成的改变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一向了很晚睡。", "corrected_sentence": "她一向很晚睡。", "error_description": "错误：“一向”后面不能直接加“了”。正确：应说“她一向很晚睡”，“了”不放在“一向”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一向的很害羞。", "corrected_sentence": "她一向很害羞。", "error_description": "错误：“一向”是副词，后面不能加“的”再接谓语。正确：去掉“的”，应说“她一向很害羞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
