INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不止于；超出某个数量或范围。", "primary_collocate": null, "pronunciation": "bù zhǐ", "ipa": "pu˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他不止三十岁了。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服不止一百块。", "target_word": "不止", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "来参加会议的不止五十人。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影我不止看过一遍。", "target_word": "不止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京住了不止十年。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的菜不止一百种。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看他的样子，年纪不止六十岁。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我为这次考试准备了不止两个星期。", "target_word": "不止", "complexity_tier": "T3", "furigana": "wǒ wèi zhè cì kǎoshì zhǔnbèi le bù zhǐ liǎng gè xīngqī", "sentence_source": "generated"}, {"text": "他一个月的工资不止一万块。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我等了他不止一个小时，他还没来。", "target_word": "不止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "动词，后接数量，表示超过这个数目或范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不止", "is_correct": true, "explanation": "“不止”读 bù zhǐ，表示超出某个数量或范围。"}, {"text": "不知", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，“不知”意思是不知道。"}, {"text": "不值", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，“不值”意思是不划算。"}, {"text": "布置", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“布置”意思是安排、摆设。"}], "explanations": {"不止": "“不止”读 bù zhǐ，表示超出某个数量或范围。", "不知": "zhī（第一声）与 zhǐ（第三声）声调不同，“不知”意思是不知道。", "不值": "zhí（第二声）与 zhǐ（第三声）声调不同，“不值”意思是不划算。", "布置": "zhì（第四声）与 zhǐ（第三声）声调不同，“布置”意思是安排、摆设。"}, "sentence_index": null, "correct_answer": "不止"}, "level_3": {"options": [{"text": "不止", "is_correct": true, "explanation": "“不止”表示超过，与“三十岁”搭配，句意是年龄超过三十岁。"}, {"text": "缺", "is_correct": false, "explanation": "语义：“缺”表示不足，与“超过三十岁”的意思相反。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”表示增加（如“长一岁”），不表示超过某个数量；“他长三十岁了”意思不通。"}, {"text": "欠", "is_correct": false, "explanation": "语义：“欠”表示亏欠，用在年龄上句意不通。"}], "explanations": {"不止": "“不止”表示超过，与“三十岁”搭配，句意是年龄超过三十岁。", "缺": "语义：“缺”表示不足，与“超过三十岁”的意思相反。", "长": "语义：“长”表示增加（如“长一岁”），不表示超过某个数量；“他长三十岁了”意思不通。", "欠": "语义：“欠”表示亏欠，用在年龄上句意不通。"}, "sentence_index": 0, "correct_answer": "不止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的个子不止同龄人。", "explanation": "这里应该用〈超过〉。“不止”要接数量，不能直接拿“同龄人”作比较，应说“超过同龄人”。"}, {"text": "他的成绩不止我们班的平均分。", "explanation": "这里应该用〈超过〉。“不止”要接数量，不能直接拿“平均分”作比较，应说“超过平均分”。"}, {"text": "这辆车的车速不止限速的标准。", "explanation": "这里应该用〈超过〉。“不止”要接数量，不能直接拿“标准”作比较，应说“超过限速的标准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不止", "is_correct": true, "explanation": "“不止”表示超过，与“六十岁”搭配，说明年纪大于六十岁。"}, {"text": "剩", "is_correct": false, "explanation": "语义：“剩”表示余下，年纪不说“剩”。"}, {"text": "占", "is_correct": false, "explanation": "搭配：“占”用于比例或位置，不用于年龄。"}, {"text": "拖", "is_correct": false, "explanation": "语义：“拖”表示拉、延误，与年纪无关。"}], "explanations": {"不止": "“不止”表示超过，与“六十岁”搭配，说明年纪大于六十岁。", "剩": "语义：“剩”表示余下，年纪不说“剩”。", "占": "搭配：“占”用于比例或位置，不用于年龄。", "拖": "语义：“拖”表示拉、延误，与年纪无关。"}, "sentence_index": 6, "correct_answer": "不止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的热情不止我们的预期。", "explanation": "这里应该用〈超过〉。“不止”要接数量，不能直接拿“预期”作比较，应说“超过我们的预期”。"}, {"text": "这次考试的难度不止老师的水平。", "explanation": "这里应该用〈超过〉。“不止”要接数量，不能直接拿“水平”作比较，应说“超过老师的水平”。"}, {"text": "这个班的成绩不止我们年级。", "explanation": "这里应该用〈超过〉。“不止”要接数量，不能直接拿“年级”作比较，应说“超过我们年级”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班的学生不止四十多个。", "corrected_sentence": "这个班的学生不止四十个。", "error_description": "错误形式：“不止四十多个”。正确形式：“不止四十个”。“不止”已经表示超过这个数目，后面再加“多”就重复了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑的价格不止了五千块。", "corrected_sentence": "这台电脑的价格不止五千块。", "error_description": "错误形式：“不止了五千块”。正确形式：“不止五千块”。“不止”后面直接接数量，中间不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适当", "is_correct": true, "explanation": "适当与不当意思相反，指恰当、合适。"}, {"text": "热情", "is_correct": false, "explanation": "与不当没有反义关系，形容待人接物的态度。"}, {"text": "清脆", "is_correct": false, "explanation": "与不当没有反义关系，形容声音清亮悦耳。"}, {"text": "漂亮", "is_correct": false, "explanation": "与不当没有反义关系，形容外貌或事物好看。"}], "correct_answer": "适当", "explanations": {"适当": "适当与不当意思相反，指恰当、合适。", "热情": "与不当没有反义关系，形容待人接物的态度。", "清脆": "与不当没有反义关系，形容声音清亮悦耳。", "漂亮": "与不当没有反义关系，形容外貌或事物好看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适当", "is_correct": true, "explanation": "适当与不当意思相反，指恰当、合适。"}, {"text": "明亮", "is_correct": false, "explanation": "与不当没有反义关系，形容光线充足、明亮。"}, {"text": "辽阔", "is_correct": false, "explanation": "与不当没有反义关系，形容面积广大。"}, {"text": "缓慢", "is_correct": false, "explanation": "与不当没有反义关系，形容速度慢。"}], "correct_answer": "适当", "explanations": {"适当": "适当与不当意思相反，指恰当、合适。", "明亮": "与不当没有反义关系，形容光线充足、明亮。", "辽阔": "与不当没有反义关系，形容面积广大。", "缓慢": "与不当没有反义关系，形容速度慢。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不当是做得不对，不合适。", "primary_collocate": null, "pronunciation": "bù dàng", "ipa": "pu˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "穿衣不当容易感冒。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，教练的安排不当，球队输了。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病时，用药不当会很危险。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话不当，得罪了朋友。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样批评学生不当，会伤他的心。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的做法不当，请大家原谅。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时玩手机是不当的行为。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用不当，机器很快就坏了。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚给老板打电话，实在不当。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理承认自己的决定不当。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不當", "label": "繁体"}], "register": "书面", "sense_fingerprint": "做得不对、不合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：做法不对、不合适，是此处要听的词。"}, {"text": "不烫", "is_correct": false, "explanation": "tàng（第四声）与 dàng（第四声）声调相同，声母不同：t 为送气清塞音，d 为不送气清塞音，意思是“不烫”。"}, {"text": "不但", "is_correct": false, "explanation": "dàn 与 dàng 声调相同，韵尾不同：n 与 ng，dàn 意思是“不但”。"}, {"text": "不挡", "is_correct": false, "explanation": "dǎng（第三声）与 dàng（第四声）声调不同，意思是“不挡”。"}, {"text": "不大", "is_correct": false, "explanation": "dà 与 dàng 声调相同，少了韵尾 ng，意思是“不大”。"}], "explanations": {"不当": "不当：做法不对、不合适，是此处要听的词。", "不烫": "tàng（第四声）与 dàng（第四声）声调相同，声母不同：t 为送气清塞音，d 为不送气清塞音，意思是“不烫”。", "不但": "dàn 与 dàng 声调相同，韵尾不同：n 与 ng，dàn 意思是“不但”。", "不挡": "dǎng（第三声）与 dàng（第四声）声调不同，意思是“不挡”。", "不大": "dà 与 dàng 声调相同，少了韵尾 ng，意思是“不大”。"}, "sentence_index": null, "correct_answer": "不当"}, "level_3": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：穿衣方式不合适，与“容易感冒”相呼应。"}, {"text": "暖和", "is_correct": false, "explanation": "语义：穿得暖和不会容易感冒，与后句“容易感冒”矛盾。"}, {"text": "得当", "is_correct": false, "explanation": "语义：“得当”与“不当”意思相反，穿衣得当不会导致感冒，与后句矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材，不能用来形容穿衣。"}], "explanations": {"不当": "不当：穿衣方式不合适，与“容易感冒”相呼应。", "暖和": "语义：穿得暖和不会容易感冒，与后句“容易感冒”矛盾。", "得当": "语义：“得当”与“不当”意思相反，穿衣得当不会导致感冒，与后句矛盾。", "高大": "搭配：“高大”形容身材，不能用来形容穿衣。"}, "sentence_index": 0, "correct_answer": "不当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校很不当，要走一个小时。", "explanation": "这里应该用〈远〉。不当形容做法、措施不合适，距离远近要说远。"}, {"text": "这只小猫很不当，大家都喜欢它。", "explanation": "这里应该用〈可爱〉。不当形容做法、措施不合适，形容小动物讨人喜欢要说可爱。"}, {"text": "这个蛋糕很不当，很好吃。", "explanation": "这里应该用〈甜〉。不当形容做法、措施不合适，食物的味道要说甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：做法不对、不合适，是此处要听的词。"}, {"text": "不动", "is_correct": false, "explanation": "dòng 与 dàng 声调相同，韵母不同：ong 与 ang，dòng 意思是“不动”。"}, {"text": "不定", "is_correct": false, "explanation": "dìng 与 dàng 声调相同，韵母不同：ing 与 ang，dìng 意思是“不定”。"}, {"text": "不带", "is_correct": false, "explanation": "dài 与 dàng 声调相同，韵母不同：ai 与 ang，dài 意思是“不带”。"}], "explanations": {"不当": "不当：做法不对、不合适，是此处要听的词。", "不动": "dòng 与 dàng 声调相同，韵母不同：ong 与 ang，dòng 意思是“不动”。", "不定": "dìng 与 dàng 声调相同，韵母不同：ing 与 ang，dìng 意思是“不定”。", "不带": "dài 与 dàng 声调相同，韵母不同：ai 与 ang，dài 意思是“不带”。"}, "sentence_index": null, "correct_answer": "不当"}, "level_3": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：指玩手机这一行为不合适，与“开会时”的语境相呼应。"}, {"text": "正当", "is_correct": false, "explanation": "语义：“正当”说行为合理合法，与“开会时玩手机”的语境矛盾。"}, {"text": "文明", "is_correct": false, "explanation": "语义：“文明”说行为有礼貌，与“开会时玩手机”的语境矛盾。"}, {"text": "魁梧", "is_correct": false, "explanation": "体貌：“魁梧”只形容人的体格，不能用来形容行为。"}], "explanations": {"不当": "不当：指玩手机这一行为不合适，与“开会时”的语境相呼应。", "正当": "语义：“正当”说行为合理合法，与“开会时玩手机”的语境矛盾。", "文明": "语义：“文明”说行为有礼貌，与“开会时玩手机”的语境矛盾。", "魁梧": "体貌：“魁梧”只形容人的体格，不能用来形容行为。"}, "sentence_index": 6, "correct_answer": "不当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼很不当，有二十层。", "explanation": "这里应该用〈高〉。不当形容做法、措施不合适，楼的高度要说高。"}, {"text": "这片叶子很不当，像草一样。", "explanation": "这里应该用〈绿〉。不当形容做法、措施不合适，植物的颜色要说绿。"}, {"text": "这个球很不当，滚得很快。", "explanation": "这里应该用〈圆〉。不当形容做法、措施不合适，球的形状要说圆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他事情办不当，大家都不高兴。", "corrected_sentence": "他事情办得不当，大家都不高兴。", "error_description": "错误形式“办不当”漏掉了补语标记“得”；正确形式“办得不当”中“得”紧接动词“办”，“不当”作补语，说明办事的方式不合适。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种很不当做法，老师不同意。", "corrected_sentence": "这种很不当的做法，老师不同意。", "error_description": "错误形式“很不当做法”漏掉了定语标记“的”；正确形式“很不当的做法”中，“很不当”修饰“做法”时需加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适当", "is_correct": true, "explanation": "适当与不当意思相反，指恰当、合适。"}, {"text": "聪明", "is_correct": false, "explanation": "与不当没有反义关系，形容人的智力。"}, {"text": "漂亮", "is_correct": false, "explanation": "与不当没有反义关系，形容外貌或事物好看。"}, {"text": "热闹", "is_correct": false, "explanation": "与不当没有反义关系，形容场面或气氛的喧闹。"}], "correct_answer": "适当", "explanations": {"适当": "适当与不当意思相反，指恰当、合适。", "聪明": "与不当没有反义关系，形容人的智力。", "漂亮": "与不当没有反义关系，形容外貌或事物好看。", "热闹": "与不当没有反义关系，形容场面或气氛的喧闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适当", "is_correct": true, "explanation": "适当与不当意思相反，指恰当、合适。"}, {"text": "高大", "is_correct": false, "explanation": "与不当没有反义关系，形容人或物体的形体。"}, {"text": "清楚", "is_correct": false, "explanation": "与不当没有反义关系，形容事物明白易懂。"}, {"text": "迅速", "is_correct": false, "explanation": "与不当没有反义关系，形容速度快。"}], "correct_answer": "适当", "explanations": {"适当": "适当与不当意思相反，指恰当、合适。", "高大": "与不当没有反义关系，形容人或物体的形体。", "清楚": "与不当没有反义关系，形容事物明白易懂。", "迅速": "与不当没有反义关系，形容速度快。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不适当；不合适。", "primary_collocate": null, "pronunciation": "bù dàng", "ipa": "pu˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事处理不当，大家都不满意。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的用词不当，让老师有点生气。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法不当，所以没有成功。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在会上说那些话很不当。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饮食不当会让人生病。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他的做法不当。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的行为不当，应该向她道歉。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间安排不当，大家都很累。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得自己的话说得不当，马上道歉了。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司因为管理不当，损失了很多钱。", "target_word": "不当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不當", "label": "繁体"}], "register": "书面", "sense_fingerprint": "不适当、不合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：不适当、不合适，是此处要听的词。"}, {"text": "不烫", "is_correct": false, "explanation": "tàng（第四声）与 dàng（第四声）声调相同，声母不同：t 为送气清塞音，d 为不送气清塞音，意思是“不烫”。"}, {"text": "不但", "is_correct": false, "explanation": "dàn 与 dàng 声调相同，韵尾不同：n 与 ng，dàn 意思是“不但”。"}, {"text": "不挡", "is_correct": false, "explanation": "dǎng（第三声）与 dàng（第四声）声调不同，意思是“不挡”。"}, {"text": "不大", "is_correct": false, "explanation": "dà 与 dàng 声调相同，少了韵尾 ng，意思是“不大”。"}], "explanations": {"不当": "不当：不适当、不合适，是此处要听的词。", "不烫": "tàng（第四声）与 dàng（第四声）声调相同，声母不同：t 为送气清塞音，d 为不送气清塞音，意思是“不烫”。", "不但": "dàn 与 dàng 声调相同，韵尾不同：n 与 ng，dàn 意思是“不但”。", "不挡": "dǎng（第三声）与 dàng（第四声）声调不同，意思是“不挡”。", "不大": "dà 与 dàng 声调相同，少了韵尾 ng，意思是“不大”。"}, "sentence_index": null, "correct_answer": "不当"}, "level_3": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：指处理方式不合适，与“大家都不满意”相呼应。"}, {"text": "周到", "is_correct": false, "explanation": "语义：“周到”说处理得好，与后句“大家都不满意”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材或建筑，不能用来形容“处理”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音清亮悦耳，不能用来形容“处理”。"}], "explanations": {"不当": "不当：指处理方式不合适，与“大家都不满意”相呼应。", "周到": "语义：“周到”说处理得好，与后句“大家都不满意”矛盾。", "高大": "搭配：“高大”形容身材或建筑，不能用来形容“处理”。", "清脆": "搭配：“清脆”形容声音清亮悦耳，不能用来形容“处理”。"}, "sentence_index": 0, "correct_answer": "不当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题的答案很不当。", "explanation": "这里应该用〈不对〉。不当用于做法、措施不合适，答案错误要说不对。"}, {"text": "他的数学成绩很不当。", "explanation": "这里应该用〈差〉。不当形容做法、措施不合适，成绩好坏要说差。"}, {"text": "今天的天气很不当，不适合出门。", "explanation": "这里应该用〈不好〉。不当形容做法、措施不合适，天气好坏要说不好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：不适当、不合适，是此处要听的词。"}, {"text": "不动", "is_correct": false, "explanation": "dòng 与 dàng 声调相同，韵母不同：ong 与 ang，dòng 意思是“不动”。"}, {"text": "不定", "is_correct": false, "explanation": "dìng 与 dàng 声调相同，韵母不同：ing 与 ang，dìng 意思是“不定”。"}, {"text": "不带", "is_correct": false, "explanation": "dài 与 dàng 声调相同，韵母不同：ai 与 ang，dài 意思是“不带”。"}], "explanations": {"不当": "不当：不适当、不合适，是此处要听的词。", "不动": "dòng 与 dàng 声调相同，韵母不同：ong 与 ang，dòng 意思是“不动”。", "不定": "dìng 与 dàng 声调相同，韵母不同：ing 与 ang，dìng 意思是“不定”。", "不带": "dài 与 dàng 声调相同，韵母不同：ai 与 ang，dài 意思是“不带”。"}, "sentence_index": null, "correct_answer": "不当"}, "level_3": {"options": [{"text": "不当", "is_correct": true, "explanation": "不当：指行为不合适，与后文“应该道歉”相呼应。"}, {"text": "得体", "is_correct": false, "explanation": "语义：“得体”说行为恰当，与“应该向她道歉”矛盾。"}, {"text": "魁梧", "is_correct": false, "explanation": "体貌：“魁梧”只形容人的体格，不能用来形容行为。"}, {"text": "妥帖", "is_correct": false, "explanation": "语义：“妥帖”说行为合宜，与“应该向她道歉”矛盾。"}], "explanations": {"不当": "不当：指行为不合适，与后文“应该道歉”相呼应。", "得体": "语义：“得体”说行为恰当，与“应该向她道歉”矛盾。", "魁梧": "体貌：“魁梧”只形容人的体格，不能用来形容行为。", "妥帖": "语义：“妥帖”说行为合宜，与“应该向她道歉”矛盾。"}, "sentence_index": 6, "correct_answer": "不当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大楼很不当，有二十层。", "explanation": "这里应该用〈高〉。不当形容做法、措施不合适，楼的高度要说高。"}, {"text": "这个苹果很不当，已经不能吃了。", "explanation": "这里应该用〈坏〉。不当形容做法、措施不合适，食物变质要说坏。"}, {"text": "这批产品很不当，要退回去。", "explanation": "这里应该用〈不合格〉。不当形容做法、措施不合适，产品质量要说不合格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话说不当，让大家很尴尬。", "corrected_sentence": "他说话说得不当，让大家很尴尬。", "error_description": "错误形式“说不当”漏掉了补语标记“得”；正确形式“说得不当”中“得”紧接动词“说”，“不当”作补语，说明说话的方式不合适。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个很不当安排，大家都不满意。", "corrected_sentence": "这个很不当的安排，大家都不满意。", "error_description": "错误形式“这个很不当安排”漏掉了定语标记“的”；正确形式“这个很不当的安排”中，“很不当”修饰“安排”时需加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "“自然”与“不自然”互为反义：“不自然”指看起来别扭，“自然”指看起来和平时一样、不别扭。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容看得明白，与“不自然”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容好看，与“不自然”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容不吵闹，与“不自然”没有反义关系。"}], "correct_answer": "自然", "explanations": {"自然": "“自然”与“不自然”互为反义：“不自然”指看起来别扭，“自然”指看起来和平时一样、不别扭。", "清楚": "“清楚”形容看得明白，与“不自然”没有反义关系。", "漂亮": "“漂亮”形容好看，与“不自然”没有反义关系。", "安静": "“安静”形容不吵闹，与“不自然”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "“自然”与“不自然”互为反义，指说话、笑容不别扭、不拘谨。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“不自然”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”形容排列有序，与“不自然”没有反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”形容做事省力，与“不自然”没有反义关系。"}], "correct_answer": "自然", "explanations": {"自然": "“自然”与“不自然”互为反义，指说话、笑容不别扭、不拘谨。", "明亮": "“明亮”形容光线或颜色，与“不自然”没有反义关系。", "整齐": "“整齐”形容排列有序，与“不自然”没有反义关系。", "方便": "“方便”形容做事省力，与“不自然”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "看起来不像平时那样，有点别扭。", "primary_collocate": null, "pronunciation": "bú zì rán", "ipa": "pu³⁵ tsɨ⁵¹ ʐan³⁵", "syllable_count": 3, "sentences": [{"text": "他第一次上台，笑得很不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的表情看起来有点不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天说话的声音很不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，我笑得有点不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新发型让他觉得很不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看见老板，走路的样子变得不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的中文听起来不自然，像在背课文。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上西装，样子显得不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天怎么这么不自然，是不是有事？", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得不自然，我知道她不高兴。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不自然地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "看起来不像平时那样，有点别扭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不自然", "is_correct": true, "explanation": "“不自然”指第一次上台时笑得别扭、看起来不自在，与“笑得很”搭配，符合语境。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“笑”与“严肃”意思矛盾，笑得很严肃不合常理。"}, {"text": "黑", "is_correct": false, "explanation": "体貌：“黑”描写肤色，不能用来形容笑的程度。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，不能修饰“笑”的样子。"}], "explanations": {"不自然": "“不自然”指第一次上台时笑得别扭、看起来不自在，与“笑得很”搭配，符合语境。", "严肃": "语义：“笑”与“严肃”意思矛盾，笑得很严肃不合常理。", "黑": "体貌：“黑”描写肤色，不能用来形容笑的程度。", "高大": "体貌：“高大”描写身材，不能修饰“笑”的样子。"}, "sentence_index": 0, "correct_answer": "不自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完冷饮以后，我胃里很不自然。", "explanation": "这里应该用〈不舒服〉。不自然形容表情、动作、说话的样子，不用来描述身体的感觉。"}, {"text": "这道数学题很不自然，我不会做。", "explanation": "这里应该用〈难〉。不自然形容人的表情、动作、语气，不用来说题目的难易。"}, {"text": "他今天的体温很不自然，可能发烧了。", "explanation": "这里应该用〈不正常〉。不自然形容人的神态、动作是否别扭，不用来说体温等身体指标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不自然", "is_correct": true, "explanation": "“不自然”指中文听起来别扭、像在硬背，与“像在背课文”的语境相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容说话风趣，与“像在背课文”的机械感矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容态度温暖，与“像在背课文”的机械感矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描写身材，不能用来形容语言的听感。"}], "explanations": {"不自然": "“不自然”指中文听起来别扭、像在硬背，与“像在背课文”的语境相符。", "幽默": "语义：“幽默”形容说话风趣，与“像在背课文”的机械感矛盾。", "热情": "语义：“热情”形容态度温暖，与“像在背课文”的机械感矛盾。", "矮小": "体貌：“矮小”描写身材，不能用来形容语言的听感。"}, "sentence_index": 6, "correct_answer": "不自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些蔬菜放了三天，已经不自然了。", "explanation": "这里应该用〈不新鲜〉。不自然形容人的表情、动作、说话的样子，不用于食物的新鲜程度。"}, {"text": "这个房间很不自然，到处都是垃圾。", "explanation": "这里应该用〈不干净〉。不自然形容人的神情、言行，不用来说房间是否干净。"}, {"text": "这本书很不自然，我看了三天还没看完。", "explanation": "这里应该用〈厚〉。不自然形容人的神情、言行，不用来说书的厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他笑地很不自然，没有说话。", "corrected_sentence": "他笑得很不自然，没有说话。", "error_description": "补语标记应为“得”，不能用“地”。错误：“笑地很不自然”；正确：“笑得很不自然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他念那篇课文念地很不自然。", "corrected_sentence": "他念那篇课文念得很不自然。", "error_description": "补语标记应为“得”，不能用“地”。错误：“念地很不自然”；正确：“念得很不自然”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "“自然”与“不自然”互为反义，指说话不拘谨、不别扭。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音大而清楚，与“不自然”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容没有污物，与“不自然”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”形容价格低，与“不自然”没有反义关系。"}], "correct_answer": "自然", "explanations": {"自然": "“自然”与“不自然”互为反义，指说话不拘谨、不别扭。", "响亮": "“响亮”形容声音大而清楚，与“不自然”没有反义关系。", "干净": "“干净”形容没有污物，与“不自然”没有反义关系。", "便宜": "“便宜”形容价格低，与“不自然”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "“自然”与“不自然”互为反义，指说话不别扭、不拘谨。"}, {"text": "严格", "is_correct": false, "explanation": "“严格”形容要求高、不宽松，与“不自然”没有反义关系。"}, {"text": "深刻", "is_correct": false, "explanation": "“深刻”形容见解透彻，与“不自然”没有反义关系。"}, {"text": "平坦", "is_correct": false, "explanation": "“平坦”形容地面不起伏，与“不自然”没有反义关系。"}], "correct_answer": "自然", "explanations": {"自然": "“自然”与“不自然”互为反义，指说话不别扭、不拘谨。", "严格": "“严格”形容要求高、不宽松，与“不自然”没有反义关系。", "深刻": "“深刻”形容见解透彻，与“不自然”没有反义关系。", "平坦": "“平坦”形容地面不起伏，与“不自然”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不顺畅、不随便；不像平常那样自如。", "primary_collocate": null, "pronunciation": "bú zì rán", "ipa": "pu³⁵ tsɨ⁵¹ ʐan³⁵", "syllable_count": 3, "sentences": [{"text": "在陌生人面前，他的动作很不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚学跳舞，手脚都不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话读起来不自然，不太顺口。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她面对镜头，说话有些不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路的姿势有点不自然，像腿疼。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，孩子变得很不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次见女朋友的爸爸，他十分不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着话筒，站得很不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容太不自然，大家都看出来了。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一紧张，说话就变得不自然。", "target_word": "不自然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不自然地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "不顺畅、拘谨，不像平常那样自如", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不自然", "is_correct": true, "explanation": "“不自然”指在陌生人面前动作拘谨、别扭，与语境相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所或气氛，不能用来修饰人的动作。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描写身材，不能用来形容动作。"}, {"text": "憔悴", "is_correct": false, "explanation": "体貌：“憔悴”描写人的面容和神情，不能用来形容动作。"}], "explanations": {"不自然": "“不自然”指在陌生人面前动作拘谨、别扭，与语境相符。", "冷清": "语义：“冷清”形容场所或气氛，不能用来修饰人的动作。", "矮小": "体貌：“矮小”描写身材，不能用来形容动作。", "憔悴": "体貌：“憔悴”描写人的面容和神情，不能用来形容动作。"}, "sentence_index": 0, "correct_answer": "不自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个价格太高，很不自然。", "explanation": "这里应该用〈不合理〉。不自然形容人的表情、动作、语气，价格这类事物要用不合理。"}, {"text": "这个箱子很不自然，我搬不动。", "explanation": "这里应该用〈重〉。不自然形容人的动作、语气不自如，不用来说东西的轻重。"}, {"text": "这个方案的预算很不自然，领导不同意。", "explanation": "这里应该用〈不恰当〉。不自然形容人的表情、动作、语气，不用于预算、方案等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不自然", "is_correct": true, "explanation": "“不自然”指第一次见女朋友的爸爸时神态拘谨，与语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”说场面、气氛，不能用来形容人的状态。"}, {"text": "通顺", "is_correct": false, "explanation": "搭配：“通顺”用于文句，不能用来形容人的状态。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与人的神态不相符。"}], "explanations": {"不自然": "“不自然”指第一次见女朋友的爸爸时神态拘谨，与语境相符。", "热闹": "搭配：“热闹”说场面、气氛，不能用来形容人的状态。", "通顺": "搭配：“通顺”用于文句，不能用来形容人的状态。", "清脆": "语义：“清脆”形容声音，与人的神态不相符。"}, "sentence_index": 6, "correct_answer": "不自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两边的重量很不自然，天平一直往一边倒。", "explanation": "这里应该用〈不平衡〉。不自然形容人的言行、神情，不用于重量、分配等。"}, {"text": "这份资料很不自然，缺了两页。", "explanation": "这里应该用〈不完整〉。不自然不用于描述资料、物品是否齐全。"}, {"text": "两份报告的数字很不自然。", "explanation": "这里应该用〈不一致〉。不自然不用于描述数字、数据是否相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她第一次上台，唱歌唱地很不自然。", "corrected_sentence": "她第一次上台，唱歌唱得很不自然。", "error_description": "补语标记应为“得”，不能用“地”。错误：“唱歌唱地很不自然”；正确：“唱歌唱得很不自然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她第一次演讲，不自然的看着台下。", "corrected_sentence": "她第一次演讲，不自然地看着台下。", "error_description": "修饰动词的状语应用“地”，不能用“的”。错误：“不自然的看着台下”；正确：“不自然地看着台下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
