INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96135, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "世人是世界上的人们。", "primary_collocate": null, "pronunciation": "shì rén", "ipa": "ʂɻ̩˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "世人都想过好日子。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事世人都知道。", "target_word": "世人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位画家的作品让世人惊叹。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的故事感动了世人。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世人都说这座桥很美。", "target_word": "世人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位科学家的发现，造福了世人。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书告诉世人要爱护地球。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世人都爱好看的东西，也爱好听的话。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他希望自己的画能让世人看到。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世人都在等这个好消息。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "世界上的人们，指全人类或所有的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世人", "is_correct": true, "explanation": "世人（shì rén）：世上的人。"}, {"text": "十人", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是十个人。"}, {"text": "诗人", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗的人。"}, {"text": "使人", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是让人。"}, {"text": "四人", "is_correct": false, "explanation": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），意思是四个人。"}], "explanations": {"世人": "世人（shì rén）：世上的人。", "十人": "shí（第二声）与 shì（第四声）声调不同，意思是十个人。", "诗人": "shī（第一声）与 shì（第四声）声调不同，意思是写诗的人。", "使人": "shǐ（第三声）与 shì（第四声）声调不同，意思是让人。", "四人": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），意思是四个人。"}, "sentence_index": null, "correct_answer": "世人"}, "level_3": {"options": [{"text": "世人", "is_correct": true, "explanation": "正确：“世人”指世上所有的人，可以与“都”搭配，“想过好日子”是人的愿望。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有“想”的意愿，与“想过好日子”不合。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指人数总量，不作“都想过好日子”这类个人意愿的主语。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有愿望，句子说的是有愿望的人。"}], "explanations": {"世人": "正确：“世人”指世上所有的人，可以与“都”搭配，“想过好日子”是人的愿望。", "树": "语义：树没有“想”的意愿，与“想过好日子”不合。", "人口": "搭配：“人口”指人数总量，不作“都想过好日子”这类个人意愿的主语。", "石头": "语义：石头没有愿望，句子说的是有愿望的人。"}, "sentence_index": 0, "correct_answer": "世人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛结束后，场上的世人都欢呼起来。", "explanation": "这里应该用〈众人〉。世人指世上所有的人，不能用来指比赛场上在场的人；在场的人要说众人。"}, {"text": "我的世人都来参加婚礼了。", "explanation": "这里应该用〈朋友〉。世人指世上的人，不能用来指与“我”关系亲近、会来参加婚礼的人。"}, {"text": "飞机上的世人都系好了安全带。", "explanation": "这里应该用〈乘客〉。世人指世上所有的人，不能用来指一架飞机上的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96135, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "世人", "is_correct": true, "explanation": "世人（shì rén）：世上的人。"}, {"text": "石人", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是石头做的人像。"}, {"text": "死人", "is_correct": false, "explanation": "sǐ（第三声）与 shì（第四声）声母和声调都不同，意思是死去的人。"}, {"text": "私人", "is_correct": false, "explanation": "sī（第一声）与 shì（第四声）声母和声调都不同，意思是个人的、私有的人。"}, {"text": "食人", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是吃人。"}], "explanations": {"世人": "世人（shì rén）：世上的人。", "石人": "shí（第二声）与 shì（第四声）声调不同，意思是石头做的人像。", "死人": "sǐ（第三声）与 shì（第四声）声母和声调都不同，意思是死去的人。", "私人": "sī（第一声）与 shì（第四声）声母和声调都不同，意思是个人的、私有的人。", "食人": "shí（第二声）与 shì（第四声）声调不同，意思是吃人。"}, "sentence_index": null, "correct_answer": "世人"}, "level_3": {"options": [{"text": "世人", "is_correct": true, "explanation": "正确：“告诉”的对象是能听懂道理的人，“世人”指世上所有的人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子听不懂道理，不能作“告诉”的对象。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能理解“爱护地球”的道理，与句意不合。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“告诉”需要有理解力的人或群体作对象，“数字”不能与之搭配。"}], "explanations": {"世人": "正确：“告诉”的对象是能听懂道理的人，“世人”指世上所有的人。", "桌子": "语义：桌子听不懂道理，不能作“告诉”的对象。", "电脑": "语义：电脑不能理解“爱护地球”的道理，与句意不合。", "数字": "搭配：“告诉”需要有理解力的人或群体作对象，“数字”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "世人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班上的世人都在复习功课。", "explanation": "这里应该用〈同学〉。世人指世上所有的人，不能用来指一个班里的人。"}, {"text": "公司的世人都在开会。", "explanation": "这里应该用〈同事〉。世人指世上所有的人，不能用来指同一家公司的员工。"}, {"text": "这个小区的世人都很热情。", "explanation": "这里应该用〈邻居〉。世人指世上所有的人，不能用来指同一个小区的住户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.