INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个世人都希望天下太平。", "corrected_sentence": "世人都希望天下太平。", "error_description": "错误形式：“这个世人”，在“世人”前加了指示词和量词。正确形式：“世人都希望天下太平”。“世人”指世上所有的人，是泛指的名词，不能用“这个”来限定。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个世人都关心这次气候大会。", "corrected_sentence": "世人都关心这次气候大会。", "error_description": "错误形式：“三个世人”，在“世人”前加了数量词。正确形式：“世人都关心这次气候大会”。“世人”泛指世上所有的人，不能用“三个”这样的数量词来计数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
