INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "世上的人；一般人。", "primary_collocate": null, "pronunciation": "shì rén", "ipa": "ʂɻ̩˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "世人常常看重钱，不看重情。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别在意世人怎么说。", "target_word": "世人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世人总是容易忘记过去的错。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世人只看到他成功，没看到他的努力。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不在乎世人的看法。", "target_word": "世人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世人大多喜欢听好话。", "target_word": "世人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世人都怕死，他却不怕。", "target_word": "世人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个道理，世人很少明白。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世人只看外表，不看内心。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从不为了让世人喜欢而改变自己。", "target_word": "世人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "世上的一般人，常用来评论人们的看法和习性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世人", "is_correct": true, "explanation": "世人（shì rén）：世上的一般人。"}, {"text": "石人", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是石头做的人像。"}, {"text": "死人", "is_correct": false, "explanation": "sǐ（第三声）与 shì（第四声）声母和声调都不同，意思是死去的人。"}, {"text": "私人", "is_correct": false, "explanation": "sī（第一声）与 shì（第四声）声母和声调都不同，意思是个人的、私有的人。"}, {"text": "食人", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是吃人。"}], "explanations": {"世人": "世人（shì rén）：世上的一般人。", "石人": "shí（第二声）与 shì（第四声）声调不同，意思是石头做的人像。", "死人": "sǐ（第三声）与 shì（第四声）声母和声调都不同，意思是死去的人。", "私人": "sī（第一声）与 shì（第四声）声母和声调都不同，意思是个人的、私有的人。", "食人": "shí（第二声）与 shì（第四声）声调不同，意思是吃人。"}, "sentence_index": null, "correct_answer": "世人"}, "level_3": {"options": [{"text": "世人", "is_correct": true, "explanation": "正确：“世人”指世上的一般人，可以泛指人们常有的看法和习惯，与“常常看重钱”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有价值取向，不会“看重钱”或“看重情”。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器没有感情和价值判断，句子说的是人的看法。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指人数总量，不作“看重钱”这类倾向的主语。"}], "explanations": {"世人": "正确：“世人”指世上的一般人，可以泛指人们常有的看法和习惯，与“常常看重钱”相符。", "石头": "语义：石头没有价值取向，不会“看重钱”或“看重情”。", "机器": "语义：机器没有感情和价值判断，句子说的是人的看法。", "人口": "搭配：“人口”指人数总量，不作“看重钱”这类倾向的主语。"}, "sentence_index": 0, "correct_answer": "世人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧场里的世人都笑了起来。", "explanation": "这里应该用〈观众〉。世人指世上的一般人，不能用来指剧场里正在看演出的人。"}, {"text": "医院里的世人都在排队。", "explanation": "这里应该用〈病人〉。世人指世上的一般人，不能用来指医院里求诊的病人。"}, {"text": "这个社团的世人都很热情。", "explanation": "这里应该用〈成员〉。世人指世上的一般人，不能用来指某个社团的成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96136, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "世人", "is_correct": true, "explanation": "世人（shì rén）：世上的一般人。"}, {"text": "十人", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是十个人。"}, {"text": "诗人", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗的人。"}, {"text": "使人", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是让人。"}, {"text": "四人", "is_correct": false, "explanation": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），意思是四个人。"}], "explanations": {"世人": "世人（shì rén）：世上的一般人。", "十人": "shí（第二声）与 shì（第四声）声调不同，意思是十个人。", "诗人": "shī（第一声）与 shì（第四声）声调不同，意思是写诗的人。", "使人": "shǐ（第三声）与 shì（第四声）声调不同，意思是让人。", "四人": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），意思是四个人。"}, "sentence_index": null, "correct_answer": "世人"}, "level_3": {"options": [{"text": "世人", "is_correct": true, "explanation": "正确：“世人”泛指一般人，与“他却不怕”形成对比。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有怕死的心理，与句意不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有感情，不会怕死，与“他却不怕”的对比也不成立。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“怕死”的主语须是有生命的个体，“数字”不能作主语。"}], "explanations": {"世人": "正确：“世人”泛指一般人，与“他却不怕”形成对比。", "树": "语义：树没有怕死的心理，与句意不合。", "电脑": "语义：电脑没有感情，不会怕死，与“他却不怕”的对比也不成立。", "数字": "搭配：“怕死”的主语须是有生命的个体，“数字”不能作主语。"}, "sentence_index": 6, "correct_answer": "世人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "景区里的世人都很开心。", "explanation": "这里应该用〈游客〉。世人指世上的一般人，不能用来指景区里的游客。"}, {"text": "培训班的世人都在认真听讲。", "explanation": "这里应该用〈学员〉。世人指世上的一般人，不能用来指培训班里的学员。"}, {"text": "这个乐队的世人都在等新歌。", "explanation": "这里应该用〈粉丝〉。世人指世上的一般人，不能用来指某个乐队的粉丝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世人的常常议论别人的穿着。", "corrected_sentence": "世人常常议论别人的穿着。", "error_description": "错误形式：“世人的常常议论”，“世人”作主语时后面多加了“的”。正确形式：“世人常常议论别人的穿着”。“世人的”只能作定语，后面没有中心语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个世人都说他很傻。", "corrected_sentence": "世人都说他很傻。", "error_description": "错误形式：“每个世人”，“每个”不能修饰“世人”。正确形式：“世人都说他很傻”。“世人”指世上的人，是泛指的复数概念，不能分个体计算。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
