INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96137, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交友是找人做朋友。", "primary_collocate": null, "pronunciation": "jiāo yǒu", "ipa": "tɕi̯ɑʊ˥ i̯oʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在网上交友，认识了很多人。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件是专门用来交友的。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去俱乐部交友，不想一个人在家。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交友的时候，你最看重什么？", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来这里学汉语，也想交友。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到新城市后，很想交友。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上交友要小心，别告诉别人地址。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用这个网站交友已经两年了。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王参加了读书会，目的就是交友。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店常有交友活动。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交友软件", "label": "复合"}], "register": "中性", "sense_fingerprint": "交友：动词，主动去找人、通过某种方式认识新朋友，如网上交友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交友", "is_correct": true, "explanation": "“交友”指在网上结识新朋友，与“认识了很多人”相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”不能在网上进行，与“网上”不搭。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是户外活动，不能在网上进行。"}, {"text": "结识", "is_correct": false, "explanation": "配价：“结识”必须带宾语，“在网上结识”后面没有宾语，句子不成立。"}], "explanations": {"交友": "“交友”指在网上结识新朋友，与“认识了很多人”相符。", "洗澡": "语义：“洗澡”不能在网上进行，与“网上”不搭。", "散步": "语义：“散步”是户外活动，不能在网上进行。", "结识": "配价：“结识”必须带宾语，“在网上结识”后面没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "交友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家银行的交友很多。", "explanation": "这里应该用〈业务〉。银行办理的事务要说“业务”；“交友”只指个人结识朋友，不能用于银行。"}, {"text": "两家公司的交友很频繁。", "explanation": "这里应该用〈来往〉。公司之间的业务往来要说“来往”；“交友”只用于个人结识朋友。"}, {"text": "两地的文化交友越来越多。", "explanation": "这里应该用〈交流〉。两地之间的文化往来要说“交流”；“交友”只指个人结识朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交友", "is_correct": true, "explanation": "“交友”指结识朋友，与“网上交友要小心”的语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“网上”和“游泳”不搭，游泳不能在网上进行。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”不能用“网上”修饰，“网上睡觉”搭配不当。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步是身体运动，不能在网上进行。"}], "explanations": {"交友": "“交友”指结识朋友，与“网上交友要小心”的语境相符。", "游泳": "语义：“网上”和“游泳”不搭，游泳不能在网上进行。", "睡觉": "搭配：“睡觉”不能用“网上”修饰，“网上睡觉”搭配不当。", "跑步": "语义：跑步是身体运动，不能在网上进行。"}, "sentence_index": 6, "correct_answer": "交友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车交友很广。", "explanation": "这里误用了“交友”：它只指人结识朋友，汽车不能作主语。"}, {"text": "这本书很会交友。", "explanation": "这里误用了“交友”：它只指人结识朋友，书不能作主语。"}, {"text": "这个路灯交友很多。", "explanation": "这里误用了“交友”：它只指人结识朋友，路灯不能作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在社团里交友很多朋友。", "corrected_sentence": "她在社团里交友，认识了很多朋友。", "error_description": "错误：“交友很多朋友”。“交友”是动宾式复合词，本身已含“朋友”，后面不能再带宾语“朋友”。正确：先说“交友”，再用“认识了很多朋友”说明结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在网上交友三个朋友，都是摄影爱好者。", "corrected_sentence": "他在网上交友，认识了三个朋友，都是摄影爱好者。", "error_description": "错误：“交友三个朋友”。“交友”不能直接带数量短语加宾语。正确：先说“交友”，再用“认识了三个朋友”说明结果，保留目标词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "绝交", "is_correct": true, "explanation": "“绝交”指断绝朋友关系，与“交友”的意思正好相反。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”与“交友”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”与“交友”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”与“交友”没有反义关系。"}], "correct_answer": "绝交", "explanations": {"绝交": "“绝交”指断绝朋友关系，与“交友”的意思正好相反。", "吃饭": "“吃饭”与“交友”没有反义关系。", "读书": "“读书”与“交友”没有反义关系。", "旅行": "“旅行”与“交友”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "绝交", "is_correct": true, "explanation": "“绝交”指断绝朋友关系，与“交友”的意思正好相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“交友”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”与“交友”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“交友”没有反义关系。"}], "correct_answer": "绝交", "explanations": {"绝交": "“绝交”指断绝朋友关系，与“交友”的意思正好相反。", "睡觉": "“睡觉”与“交友”没有反义关系。", "写字": "“写字”与“交友”没有反义关系。", "游泳": "“游泳”与“交友”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结交朋友。", "primary_collocate": null, "pronunciation": "jiāo yǒu", "ipa": "tɕi̯ɑʊ˥ i̯oʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他喜欢交友，朋友遍布各地。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交友要真诚，不能只想着自己。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学是交友的好时候。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她性格开朗，交友很广。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱交友，家里常有客人。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交友不要看钱，要看人好不好。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，交友要慢慢来。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太会交友，总是一个人。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师教我们怎样交友。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很忙，没有时间交友。", "target_word": "交友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交友软件", "label": "复合"}], "register": "中性", "sense_fingerprint": "交友：动词，泛指与人结识并成为朋友，如爱交友、交友广", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交友", "is_correct": true, "explanation": "“交友”指结识朋友，与“朋友遍布各地”相符，是唯一能填入空格的词。"}, {"text": "独处", "is_correct": false, "explanation": "语义：独处指一个人待着，与“朋友遍布各地”的语境相反。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“喜欢”不能接“失眠”这类不由人控制的状态。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“喜欢”不能接“发烧”这类病理状态。"}], "explanations": {"交友": "“交友”指结识朋友，与“朋友遍布各地”相符，是唯一能填入空格的词。", "独处": "语义：独处指一个人待着，与“朋友遍布各地”的语境相反。", "失眠": "搭配：“喜欢”不能接“失眠”这类不由人控制的状态。", "发烧": "搭配：“喜欢”不能接“发烧”这类病理状态。"}, "sentence_index": 0, "correct_answer": "交友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个部门交友很密切。", "explanation": "这里应该用〈协作〉。部门之间的合作要说“协作”；“交友”只指个人结识朋友，不能用于部门。"}, {"text": "这家工厂的交友很少。", "explanation": "这里应该用〈交易〉。工厂之间的买卖要说“交易”；“交友”只指个人结识朋友，不能用于工厂。"}, {"text": "两国之间的交友越来越多。", "explanation": "这里应该用〈交流〉。国家之间的往来要说“交流”；“交友”只指个人之间结识朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交友", "is_correct": true, "explanation": "“交友”指人与人结识、交往的过程，与“要慢慢来”的语境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能说“慢慢来”。"}, {"text": "打嗝", "is_correct": false, "explanation": "搭配：“要慢慢来”多用于做事、发展类动作，不搭配“打嗝”这种生理反应。"}, {"text": "打雷", "is_correct": false, "explanation": "体貌：“打雷”是瞬间发生的现象，不能慢慢来。"}], "explanations": {"交友": "“交友”指人与人结识、交往的过程，与“要慢慢来”的语境相符。", "下雨": "语义：“下雨”是天气现象，不能说“慢慢来”。", "打嗝": "搭配：“要慢慢来”多用于做事、发展类动作，不搭配“打嗝”这种生理反应。", "打雷": "体貌：“打雷”是瞬间发生的现象，不能慢慢来。"}, "sentence_index": 6, "correct_answer": "交友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑交友很广。", "explanation": "这里误用了“交友”：它只指人结识朋友，电脑不能作主语。"}, {"text": "这把椅子很会交友。", "explanation": "这里误用了“交友”：它只指人结识朋友，椅子不能作主语。"}, {"text": "这栋大楼交友很多。", "explanation": "这里误用了“交友”：它只指人结识朋友，大楼不能作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作以后，我交友了不少朋友。", "corrected_sentence": "工作以后，我交了不少朋友。", "error_description": "错误：“交友了不少朋友”。“交友”是动宾式复合词，本身已含宾语“友”，后面不能再直接带宾语“朋友”。正确：工作以后，我交了不少朋友。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喜欢交友新朋友，常一起打篮球。", "corrected_sentence": "他喜欢交新朋友，常一起打篮球。", "error_description": "错误：“交友新朋友”。“交友”是动宾式复合词，后面不能再直接接宾语“新朋友”。正确：他喜欢交新朋友，常一起打篮球。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
