INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96139, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "侮辱是说难听的话，让别人觉得很丢脸。", "primary_collocate": null, "pronunciation": "wǔ rǔ", "ipa": "u˨˩˦ ɻu˨˩˦", "syllable_count": 2, "sentences": [{"text": "你不能用难听的话侮辱别人。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当着大家的面骂我，这是侮辱我。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你不要侮辱我的朋友。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骂了我一顿，我觉得他在侮辱我。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说的话太难听，侮辱了他的家人。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上骂人，侮辱别人，是不对的。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再这样侮辱我，我就不理你了。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有侮辱过任何人。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人说我的工作没用，他侮辱了我。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不应该用外号侮辱同学。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侮辱了", "label": "体标"}, {"form": "侮辱过", "label": "体标"}, {"form": "侮辱性", "label": "复合"}], "register": "中性", "sense_fingerprint": "用难听的话让别人丢脸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侮辱", "is_correct": true, "explanation": "侮辱指用难听的话或行为让人丢脸，与“用难听的话”相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，不能用“难听的话”来完成。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”是让人安心，与“难听的话”的伤害性相反。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”要说吉利的话，不能说成“用难听的话祝福”。"}], "explanations": {"侮辱": "侮辱指用难听的话或行为让人丢脸，与“用难听的话”相符。", "夸奖": "语义：“夸奖”是称赞，不能用“难听的话”来完成。", "安慰": "语义：“安慰”是让人安心，与“难听的话”的伤害性相反。", "祝福": "搭配：“祝福”要说吉利的话，不能说成“用难听的话祝福”。"}, "sentence_index": 0, "correct_answer": "侮辱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师侮辱了他的作业，说字写得太潦草。", "explanation": "这里应该用〈批评〉。侮辱的对象必须是人，指出作业的问题要说〈批评〉，不能说“侮辱作业”。"}, {"text": "我侮辱您，请帮我一个忙。", "explanation": "这里应该用〈拜托〉。侮辱是使人丧失尊严的言行，不能用来开口请人帮忙，请人帮忙要说〈拜托〉。"}, {"text": "这次失败侮辱了他，他很难过。", "explanation": "这里应该用〈打击〉。侮辱的主语应是人的言行，“失败”不能侮辱人；使人受挫要说〈打击〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侮辱", "is_correct": true, "explanation": "侮辱指用言行让人丢脸，与“再这样…我就不理你了”的责备语气相符。"}, {"text": "道歉", "is_correct": false, "explanation": "配价：“道歉”不能直接带“我”作宾语，要说“向我道歉”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表达感激，与后半句“我就不理你了”的恼怒语气不合。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是支持，与“就不理你了”的责备语气冲突。"}], "explanations": {"侮辱": "侮辱指用言行让人丢脸，与“再这样…我就不理你了”的责备语气相符。", "道歉": "配价：“道歉”不能直接带“我”作宾语，要说“向我道歉”。", "感谢": "语义：“感谢”表达感激，与后半句“我就不理你了”的恼怒语气不合。", "鼓励": "语义：“鼓励”是支持，与“就不理你了”的责备语气冲突。"}, "sentence_index": 6, "correct_answer": "侮辱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈侮辱他别熬夜，说身体要紧。", "explanation": "这里应该用〈劝〉。侮辱是伤人尊严的言行，不能用来规劝别人。"}, {"text": "我侮辱他的帮助，他帮了我很多。", "explanation": "这里应该用〈感谢〉。侮辱的对象是人，对“帮助”表达谢意要说〈感谢〉。"}, {"text": "我侮辱他的难处，所以原谅了他。", "explanation": "这里应该用〈理解〉。侮辱会伤害人，不能用于体谅别人的难处，应说〈理解〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当着大家的面侮辱了过我。", "corrected_sentence": "他当着大家的面侮辱了我。", "error_description": "错误：“了”和“过”不能连用在“侮辱”后面。正确：“侮辱了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有侮辱了我。", "corrected_sentence": "他从来没有侮辱过我。", "error_description": "错误：“没有”后面的动作应用“过”表示经历，不能用“了”。正确：“没有侮辱过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "尊重", "is_correct": true, "explanation": "“尊重”与“侮辱”构成反义，表示敬重对方。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”是深入探讨，与“侮辱”没有反义关系。"}, {"text": "发布", "is_correct": false, "explanation": "“发布”是公开宣布，与“侮辱”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”是使损坏的东西恢复正常，与“侮辱”没有反义关系。"}], "correct_answer": "尊重", "explanations": {"尊重": "“尊重”与“侮辱”构成反义，表示敬重对方。", "研究": "“研究”是深入探讨，与“侮辱”没有反义关系。", "发布": "“发布”是公开宣布，与“侮辱”没有反义关系。", "修理": "“修理”是使损坏的东西恢复正常，与“侮辱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "尊重", "is_correct": true, "explanation": "“尊重”与“侮辱”构成反义，表示敬重对方。"}, {"text": "登记", "is_correct": false, "explanation": "“登记”是把信息记录在册，与“侮辱”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”是使东西有条理，与“侮辱”没有反义关系。"}, {"text": "传递", "is_correct": false, "explanation": "“传递”是把东西交给别人，与“侮辱”没有反义关系。"}], "correct_answer": "尊重", "explanations": {"尊重": "“尊重”与“侮辱”构成反义，表示敬重对方。", "登记": "“登记”是把信息记录在册，与“侮辱”没有反义关系。", "整理": "“整理”是使东西有条理，与“侮辱”没有反义关系。", "传递": "“传递”是把东西交给别人，与“侮辱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用言语或行为使人丧失尊严、感到羞耻。", "primary_collocate": null, "pronunciation": "wǔ rǔ", "ipa": "u˨˩˦ ɻu˨˩˦", "syllable_count": 2, "sentences": [{"text": "坏人当众打人，想要侮辱他。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把别人的国旗扔在地上，是在侮辱这个国家。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用力推他，还笑他，这样侮辱人不对。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理当着客人的面骂员工，这是侮辱人。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让他跪下，是想侮辱他。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法是在侮辱老人。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说我没钱不配吃饭，真是侮辱人。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得警察检查得那么粗鲁，是在侮辱她。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何人侮辱别人的人格。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们笑着把水倒在他头上，故意侮辱他。", "target_word": "侮辱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侮辱了", "label": "体标"}, {"form": "侮辱过", "label": "体标"}, {"form": "侮辱性", "label": "复合"}], "register": "中性", "sense_fingerprint": "用言语或行为使人丧失尊严、感到羞耻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侮辱", "is_correct": true, "explanation": "侮辱指用行为使人丧失尊严，与“坏人当众打人”的恶意相符。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”是善意的援助，与“当众打人”的恶意不符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示肯定，与“坏人当众打人”的恶意相冲突。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”要说吉利的话，不能用于形容“坏人”打人的举动。"}], "explanations": {"侮辱": "侮辱指用行为使人丧失尊严，与“坏人当众打人”的恶意相符。", "帮助": "语义：“帮助”是善意的援助，与“当众打人”的恶意不符。", "赞美": "语义：“赞美”表示肯定，与“坏人当众打人”的恶意相冲突。", "祝福": "搭配：“祝福”要说吉利的话，不能用于形容“坏人”打人的举动。"}, "sentence_index": 0, "correct_answer": "侮辱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "员工侮辱经理的帮助，很高兴。", "explanation": "这里应该用〈感谢〉。侮辱是贬低人的言行，对别人的帮助表示谢意要说〈感谢〉。"}, {"text": "朋友侮辱他，说别难过。", "explanation": "这里应该用〈安慰〉。侮辱会伤人，与“说别难过”的关怀语气相反，应说〈安慰〉。"}, {"text": "老师侮辱我们，要我们注意安全。", "explanation": "这里应该用〈提醒〉。侮辱是使人丧失尊严的言行，不能用来引起对安全的注意，应说〈提醒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侮辱", "is_correct": true, "explanation": "侮辱指贬低人，与“说我没钱不配吃饭”的贬低语气相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“不配吃饭”的贬低语气相反。"}, {"text": "请教", "is_correct": false, "explanation": "语义：“请教”是向人讨教，与句中贬低他人的语气不符。"}, {"text": "信任", "is_correct": false, "explanation": "语义：“信任”是相信他人，与句中贬低他人的语气冲突。"}], "explanations": {"侮辱": "侮辱指贬低人，与“说我没钱不配吃饭”的贬低语气相符。", "表扬": "语义：“表扬”是称赞，与“不配吃饭”的贬低语气相反。", "请教": "语义：“请教”是向人讨教，与句中贬低他人的语气不符。", "信任": "语义：“信任”是相信他人，与句中贬低他人的语气冲突。"}, "sentence_index": 6, "correct_answer": "侮辱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师侮辱了他的作业，说写得很认真。", "explanation": "这里应该用〈表扬〉。侮辱是贬低人，不能用来夸奖作业写得认真，应说〈表扬〉。"}, {"text": "学生向老师侮辱问题，老师很耐心。", "explanation": "这里应该用〈请教〉。侮辱不能用于向老师提问，学生向老师提问要说〈请教〉。"}, {"text": "我们一见面就侮辱老人，问他身体好不好。", "explanation": "这里应该用〈问候〉。侮辱会伤害老人的尊严，表示关心、打招呼要说〈问候〉，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们当众把我侮辱。", "corrected_sentence": "他们当众把我侮辱了一番。", "error_description": "错误：“把”字句里动词“侮辱”不能单独结尾，后面要有其他成分。正确：“把我侮辱了一番”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有侮辱了别人。", "corrected_sentence": "他从来没有侮辱过别人。", "error_description": "错误：“从来没有”后表示经历的动词要用“过”，不能用“了”。正确：“没有侮辱过别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "残缺", "is_correct": true, "explanation": "“残缺”与“健全”构成反义，指有缺损、不完整。"}, {"text": "精彩", "is_correct": false, "explanation": "“精彩”形容出色，与“健全”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容范围广大，与“健全”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“健全”没有反义关系。"}], "correct_answer": "残缺", "explanations": {"残缺": "“残缺”与“健全”构成反义，指有缺损、不完整。", "精彩": "“精彩”形容出色，与“健全”没有反义关系。", "辽阔": "“辽阔”形容范围广大，与“健全”没有反义关系。", "清楚": "“清楚”形容明白、不模糊，与“健全”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "残缺", "is_correct": true, "explanation": "“残缺”与“健全”构成反义，指有缺损、不完整。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”指种类多、关系繁乱，与“健全”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”指有温度或感情亲切，与“健全”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容坡度大，与“健全”没有反义关系。"}], "correct_answer": "残缺", "explanations": {"残缺": "“残缺”与“健全”构成反义，指有缺损、不完整。", "复杂": "“复杂”指种类多、关系繁乱，与“健全”没有反义关系。", "温暖": "“温暖”指有温度或感情亲切，与“健全”没有反义关系。", "陡峭": "“陡峭”形容坡度大，与“健全”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（制度、组织、设施等）齐备完善，没有缺漏。", "primary_collocate": null, "pronunciation": "jiàn quán", "ipa": "tɕjɛn˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这家医院的各项制度很健全。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的体育设施不太健全。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的配套设施很健全，买菜看病都方便。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要有健全的规定，大家才知道怎么做。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的公共服务体系很健全。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的生活设施越来越健全了。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的规章不健全，所以常常出问题。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的组织很健全，每个部门都有人负责。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俱乐部的管理还不健全，下个月再改进。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学校的各项规章制度都很健全。", "target_word": "健全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不健全", "label": "否定"}], "register": "中性", "sense_fingerprint": "各方面齐备、完好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健全", "is_correct": true, "explanation": "健全指制度齐备完善，与“各项制度很健全”相符。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或事物惹人喜爱，不能说制度“很可爱”。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不用来形容制度。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”指性情柔和，与制度是否完备无关。"}], "explanations": {"健全": "健全指制度齐备完善，与“各项制度很健全”相符。", "可爱": "语义：“可爱”形容人或事物惹人喜爱，不能说制度“很可爱”。", "热情": "搭配：“热情”形容人的态度，不用来形容制度。", "温柔": "语义：“温柔”指性情柔和，与制度是否完备无关。"}, "sentence_index": 0, "correct_answer": "健全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯的亮度很健全，照得很清楚。", "explanation": "这里应该用〈明亮〉。健全指齐备、完好，不能形容亮度，灯光亮要说〈明亮〉。"}, {"text": "这篇文章的描写很健全，读起来很有画面感。", "explanation": "这里应该用〈生动〉。健全指齐备、完好，不能形容描写，文字形象鲜明要说〈生动〉。"}, {"text": "这件衣服的颜色很健全，穿上很精神。", "explanation": "这里应该用〈鲜艳〉。健全不用于形容颜色，颜色明亮要说〈鲜艳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健全", "is_correct": true, "explanation": "“不健全”指规章有缺漏，与“常常出问题”的因果相符。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人或言语，不能说“规章幽默”。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容声音或笑容，与规章的完善程度无关。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容人或气氛生动，与规章不完善、常出问题的语境不符。"}], "explanations": {"健全": "“不健全”指规章有缺漏，与“常常出问题”的因果相符。", "幽默": "搭配：“幽默”形容人或言语，不能说“规章幽默”。", "甜美": "语义：“甜美”形容声音或笑容，与规章的完善程度无关。", "活泼": "语义：“活泼”形容人或气氛生动，与规章不完善、常出问题的语境不符。"}, "sentence_index": 6, "correct_answer": "健全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首曲子的节奏很健全，听起来很舒服。", "explanation": "这里应该用〈明快〉。健全指齐备、完好，不能形容节奏，节奏轻快要说〈明快〉。"}, {"text": "她的笑容很健全，看着很舒服。", "explanation": "这里应该用〈灿烂〉。健全不用于形容表情，笑容明朗要说〈灿烂〉。"}, {"text": "这块蛋糕的奶油很健全，吃起来很甜。", "explanation": "这里应该用〈细腻〉。健全不用于形容口感，奶油细滑要说〈细腻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所医院的科室很健全过，看病很方便。", "corrected_sentence": "这所医院的科室很健全，看病很方便。", "error_description": "错误：形容词“健全”后面不能加“过”。正确：直接说“很健全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的医疗设施很健全地。", "corrected_sentence": "这个城市的医疗设施很健全。", "error_description": "错误：作谓语的形容词“健全”后面不加“地”。正确：“很健全”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
