INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "先前是现在以前的时候。", "primary_collocate": null, "pronunciation": "xiān qián", "ipa": "ɕi̯ɛn˥ tɕʰi̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "先前的房子很小，这个新家大多了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的样子和先前一样，没有变化。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起先前，我现在的工作轻松多了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先前的老师现在在另一所学校工作。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还记得先前的那次旅行。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的变化很大，不像先前那么安静了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把先前买的书都送给了朋友。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先前的计划不好，我们得换一个。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了今天，先前的困难都过去了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语比先前好多了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "先前：作名词，指现在以前的时间，常说“先前的……”“比先前”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96143, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先前", "is_correct": true, "explanation": "先前：现在以前的时间。名词。"}, {"text": "闲钱", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是闲钱，即暂时不用的钱。"}, {"text": "现钱", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现金。"}, {"text": "先遣", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，意思是先遣，指派先行的人或部队。"}], "explanations": {"先前": "先前：现在以前的时间。名词。", "闲钱": "xián（第二声）与 xiān（第一声）声调不同，意思是闲钱，即暂时不用的钱。", "现钱": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现金。", "先遣": "qiǎn（第三声）与 qián（第二声）声调不同，意思是先遣，指派先行的人或部队。"}, "sentence_index": null, "correct_answer": "先前"}, "level_3": {"options": [{"text": "先前", "is_correct": true, "explanation": "先前：指现在以前的时间，与“这个新家”形成对比，符合语境。"}, {"text": "现在", "is_correct": false, "explanation": "语义：“现在”指当下，不能指与“这个新家”相对的旧房子。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指以后的时间，与“这个新家”指眼下的住处相矛盾。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“下午”指一天中的时段，不能说“下午的房子”来表示以前的居所。"}], "explanations": {"先前": "先前：指现在以前的时间，与“这个新家”形成对比，符合语境。", "现在": "语义：“现在”指当下，不能指与“这个新家”相对的旧房子。", "将来": "语义：“将来”指以后的时间，与“这个新家”指眼下的住处相矛盾。", "下午": "搭配：“下午”指一天中的时段，不能说“下午的房子”来表示以前的居所。"}, "sentence_index": 0, "correct_answer": "先前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很先前，大家都很看好他。", "explanation": "先前是名词，不能直接用“很”作谓语，句子不成立。这里应该用〈前途〉，指将来的发展。"}, {"text": "队伍的先前站着一位老人。", "explanation": "这里应该用〈前面〉，指位置在前。先前指现在以前的时间，不能表示空间位置。"}, {"text": "先前我们再见面吧。", "explanation": "这里应该用〈以后〉，表示将来的时间。先前指过去，不能用于“再见面吧”这样的将来约定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先前", "is_correct": true, "explanation": "先前：指以前的时间，修饰“买的书”，与“送给了朋友”的已完成动作相符。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指以后的时间，与“都送给了朋友”的已完成动作相矛盾。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指还没到的时间，不能和已经发生的“送给了朋友”搭配。"}, {"text": "时候", "is_correct": false, "explanation": "搭配：“时候”不能单独修饰“买的书”，要说“……的时候”。"}], "explanations": {"先前": "先前：指以前的时间，修饰“买的书”，与“送给了朋友”的已完成动作相符。", "未来": "语义：“未来”指以后的时间，与“都送给了朋友”的已完成动作相矛盾。", "明天": "语义：“明天”指还没到的时间，不能和已经发生的“送给了朋友”搭配。", "时候": "搭配：“时候”不能单独修饰“买的书”，要说“……的时候”。"}, "sentence_index": 6, "correct_answer": "先前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个计划很先前，资金充足。", "explanation": "先前是名词，不能用“很”修饰，句子不成立。这里应该用〈前提〉，指事情成立的条件。"}, {"text": "先前你一定要来看我吧。", "explanation": "这里应该用〈将来〉，表示以后的时间。先前指过去，不能用于“一定要来看我吧”这样的将来约定。"}, {"text": "做这件事要分三步，先前要准备材料。", "explanation": "这里应该用〈首先〉，表示列举步骤时最先做的事。先前指较早的时间，不能用来排列步骤的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先前地朋友都搬到了南方。", "corrected_sentence": "先前的朋友都搬到了南方。", "error_description": "“先前”在这里是名词，修饰名词“朋友”，应用结构助词“的”。“地”用于修饰动词，不能用在名词前。正确：先前的朋友都搬到了南方。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的口语比先前地进步了不少。", "corrected_sentence": "他的口语比先前进步了不少。", "error_description": "“先前”是名词，不能直接加“地”修饰动词“进步”。“比先前”之后接动词短语时，“地”应删去。正确：他的口语比先前进步了不少。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
