INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96144, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "以前；较早的时候。", "primary_collocate": null, "pronunciation": "xiān qián", "ipa": "ɕi̯ɛn˥ tɕʰi̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "先前我不知道这件事，现在才明白。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先前住在北京，后来搬到了上海。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先前下过一场雨，路上还是湿的。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店先前很小，现在已经很大了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先前以为他是老师，其实是医生。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先前说好的时间，你怎么忘了？", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先前很胖，现在瘦多了。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先前来过这里的人，都说这儿很安静。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先前讲过这个问题，你再想想。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先前不喜欢吃鱼，现在天天都吃。", "target_word": "先前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "先前：作状语，放在动词或形容词前，表示比现在早的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先前", "is_correct": true, "explanation": "先前：以前，较早的时候。副词，放在动词或形容词前。"}, {"text": "闲钱", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是闲钱，即暂时不用的钱。"}, {"text": "现钱", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现金。"}, {"text": "先遣", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，意思是先遣，指派先行的人或部队。"}], "explanations": {"先前": "先前：以前，较早的时候。副词，放在动词或形容词前。", "闲钱": "xián（第二声）与 xiān（第一声）声调不同，意思是闲钱，即暂时不用的钱。", "现钱": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现金。", "先遣": "qiǎn（第三声）与 qián（第二声）声调不同，意思是先遣，指派先行的人或部队。"}, "sentence_index": null, "correct_answer": "先前"}, "level_3": {"options": [{"text": "先前", "is_correct": true, "explanation": "先前：指以前的时候，与“现在才明白”形成对比，符合语境。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即或很快，与“现在才明白”的晚到矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，不能修饰“不知道”这种已经存在的状态。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“现在才明白”中的“才”相矛盾。"}], "explanations": {"先前": "先前：指以前的时候，与“现在才明白”形成对比，符合语境。", "马上": "语义：“马上”表示立即或很快，与“现在才明白”的晚到矛盾。", "正在": "体貌：“正在”表示动作正在进行，不能修饰“不知道”这种已经存在的状态。", "已经": "语义：“已经”表示已经发生，与“现在才明白”中的“才”相矛盾。"}, "sentence_index": 0, "correct_answer": "先前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我们先前去超市，再去书店。", "explanation": "这里应该用〈先〉，表示动作的先后顺序。先前指过去的时间，不能和“明天”这样的将来时间词一起用。"}, {"text": "先前请大家在这里签名，然后再去办公室。", "explanation": "这里应该用〈首先〉，表示动作的先后顺序。先前指较早的时间，是“以前”的意思，不能表示“首先做某事”。"}, {"text": "先前我们一起去那家店吧。", "explanation": "这里应该用〈以后〉，表示将来的时间。先前指过去，不能用于“一起去那家店吧”这样的将来建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先前", "is_correct": true, "explanation": "先前：指以前的时候，与“现在瘦多了”形成对比，符合语境。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能描述持续的“很胖”这种状态。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”与“很”都是程度副词，不能叠用在形容词前面。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“很胖”这种长期状态不符。"}], "explanations": {"先前": "先前：指以前的时候，与“现在瘦多了”形成对比，符合语境。", "忽然": "语义：“忽然”表示突然发生，不能描述持续的“很胖”这种状态。", "十分": "搭配：“十分”与“很”都是程度副词，不能叠用在形容词前面。", "刚": "语义：“刚”表示刚刚发生，与“很胖”这种长期状态不符。"}, "sentence_index": 6, "correct_answer": "先前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先前请大家明天交作业。", "explanation": "先前指过去，与“明天”的将来时间矛盾，不能用于将来的要求。这里应该直接说“请大家明天交作业”。"}, {"text": "做这件事要分三步，先前要准备材料。", "explanation": "这里应该用〈一开始〉，表示事情最初的阶段，适用于分步骤说明。先前指较早的时间，不能用于安排步骤中的将来动作。"}, {"text": "先前我们马上出发吧。", "explanation": "这里应该用〈接下来〉，表示紧接着要发生的事。先前指过去，与“马上出发吧”这样的即将发生的动作不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很先前去过上海两次。", "corrected_sentence": "她先前去过上海两次。", "error_description": "“先前”是副词，前面不能加程度副词“很”，“很先前”不成词。正确：她先前去过上海两次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先前的没吃过火锅，现在很喜欢。", "corrected_sentence": "我先前没吃过火锅，现在很喜欢。", "error_description": "“先前”是副词，后面直接接动词“没吃过”，不能加结构助词“的”（“先前的”是名词用法，用来修饰名词）。正确：我先前没吃过火锅，现在很喜欢。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚集", "is_correct": true, "explanation": "聚集是聚在一处，与“分散”（散向各处）意思相反。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身启程，并不是“分散”的反义词。"}, {"text": "前进", "is_correct": false, "explanation": "前进指向前走，与“分散”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时不走，与“分散”没有反义关系。"}], "correct_answer": "聚集", "explanations": {"聚集": "聚集是聚在一处，与“分散”（散向各处）意思相反。", "出发": "出发指动身启程，并不是“分散”的反义词。", "前进": "前进指向前走，与“分散”没有反义关系。", "停留": "停留指暂时不走，与“分散”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚集", "is_correct": true, "explanation": "聚集是聚在一处，与“分散到各个角落”意思相反。"}, {"text": "启程", "is_correct": false, "explanation": "启程指出发上路，与“分散”没有反义关系。"}, {"text": "游荡", "is_correct": false, "explanation": "游荡指到处闲逛，与“分散”没有反义关系。"}, {"text": "上升", "is_correct": false, "explanation": "上升指往高处去，与“分散”没有反义关系。"}], "correct_answer": "聚集", "explanations": {"聚集": "聚集是聚在一处，与“分散到各个角落”意思相反。", "启程": "启程指出发上路，与“分散”没有反义关系。", "游荡": "游荡指到处闲逛，与“分散”没有反义关系。", "上升": "上升指往高处去，与“分散”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分散是从一个地方，散到很多地方。", "primary_collocate": null, "pronunciation": "fēn sàn", "ipa": "fən˥ san˥˩", "syllable_count": 2, "sentences": [{"text": "下课铃一响，同学们就分散到各个教室去了。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在公园里分散开，自己去玩了。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，观众慢慢分散了。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察一来，聚在路口的人就分散了。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的亲戚分散在世界各地。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊群在山坡上分散着吃草。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨落下来，广场上的人群很快分散了。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车到站后，旅客分散走向不同的出口。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到响声，小鸟一下子就分散开，飞走了。", "target_word": "分散", "complexity_tier": "T3", "furigana": "fēn sàn", "sentence_source": "generated"}, {"text": "放学以后，学生们很快分散到城市的各个角落。", "target_word": "分散", "complexity_tier": "T3", "furigana": "fēn sàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "分散了", "label": "完成体"}, {"form": "分散着", "label": "持续体"}, {"form": "分散过", "label": "经历体"}, {"form": "分散开", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或东西从一个地方向各处散开，不带宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "分散指从一处散向各处，与“同学们去各个教室”的语境相符。"}, {"text": "集中", "is_correct": false, "explanation": "语义：“集中”是聚到一处，与“到各个教室去”的散开义相反。"}, {"text": "聚集", "is_correct": false, "explanation": "语义：“聚集”也是聚在一处，不能说大家聚集到各个教室去。"}, {"text": "派", "is_correct": false, "explanation": "配价：“派”要有施事和受事，“同学们”不能自己被派到教室去。"}], "explanations": {"分散": "分散指从一处散向各处，与“同学们去各个教室”的语境相符。", "集中": "语义：“集中”是聚到一处，与“到各个教室去”的散开义相反。", "聚集": "语义：“聚集”也是聚在一处，不能说大家聚集到各个教室去。", "派": "配价：“派”要有施事和受事，“同学们”不能自己被派到教室去。"}, "sentence_index": 0, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把一大袋苹果分散给我们几个孩子。", "explanation": "这里应该用〈分给〉。“分散”指东西向各处散开，把苹果按份分给几个人要用“分给”。"}, {"text": "他一个人很快分散到了各地。", "explanation": "这里应该用〈走〉。“分散”指许多人或东西散向各处，一个人独自前往各地不能用“分散”。"}, {"text": "两个老朋友在路口分散了，各自回家。", "explanation": "这里应该用〈分开〉。“分散”多指许多人或东西散向各处，两个人分手只能用“分开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "分散表示人群向各处散去，符合大雨后人群散开的语境。"}, {"text": "集结", "is_correct": false, "explanation": "语义：“集结”是聚拢到一处，与大雨落下来后人群散开的意思相反。"}, {"text": "相聚", "is_correct": false, "explanation": "语义：“相聚”指朋友亲人见面团聚，不说一群陌生人“相聚”。"}, {"text": "送走", "is_correct": false, "explanation": "配价：“送走”要带受事，人群不能自己被“送走”。"}], "explanations": {"分散": "分散表示人群向各处散去，符合大雨后人群散开的语境。", "集结": "语义：“集结”是聚拢到一处，与大雨落下来后人群散开的意思相反。", "相聚": "语义：“相聚”指朋友亲人见面团聚，不说一群陌生人“相聚”。", "送走": "配价：“送走”要带受事，人群不能自己被“送走”。"}, "sentence_index": 6, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放学以后，朋友们很快分散到一起吃饭。", "explanation": "这里应该用〈聚集〉。“分散”是散向各处，与“到一起吃饭”矛盾。"}, {"text": "妈妈把一块大蛋糕分散成了两半，每人一半。", "explanation": "这里应该用〈切开〉。“分散”指东西向各处散开，把一整块蛋糕切成两半要说“切开”或“分开”。"}, {"text": "下课后，全班同学都分散到同一个教室里开会。", "explanation": "这里应该用〈集合〉。“分散”是从一处散向各处，大家都去同一个教室应说“集合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放学的时候，孩子们分散各个村子去了。", "corrected_sentence": "放学的时候，孩子们分散到各个村子去了。", "error_description": "错误：“分散”后漏了“到”。正确：“分散到＋地点”表示散向某处，少了“到”句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛一结束，观众就很快分散各个出口去了。", "corrected_sentence": "比赛一结束，观众就很快分散到各个出口去了。", "error_description": "错误：“分散”后漏了“到”。正确：“分散到＋地点”表示散向各处，应写“很快分散到各个出口去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "集中指聚在一起，与“使……散开”的分散义相反。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指搬动东西，与“分散”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏指保存珍贵的东西，与“分散”没有反义关系。"}, {"text": "发动", "is_correct": false, "explanation": "发动指启动或展开行动，与“分散”没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "集中指聚在一起，与“使……散开”的分散义相反。", "搬运": "搬运指搬动东西，与“分散”没有反义关系。", "收藏": "收藏指保存珍贵的东西，与“分散”没有反义关系。", "发动": "发动指启动或展开行动，与“分散”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "集中指聚在一起，与“使……散开”的分散义相反。"}, {"text": "选择", "is_correct": false, "explanation": "选择指挑出一个，与“分散”没有反义关系。"}, {"text": "包围", "is_correct": false, "explanation": "包围指从四周围住，与“分散”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理指把东西理顺，与“分散”没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "集中指聚在一起，与“使……散开”的分散义相反。", "选择": "选择指挑出一个，与“分散”没有反义关系。", "包围": "包围指从四周围住，与“分散”没有反义关系。", "整理": "整理指把东西理顺，与“分散”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由集中变为不集中；使散开。", "primary_collocate": null, "pronunciation": "fēn sàn", "ipa": "fən˥ san˥˩", "syllable_count": 2, "sentences": [{"text": "窗外的噪音分散了我的注意力。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会分散孩子写作业的注意力。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要把钱放在一起，要分散风险。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路口分散了围观的人群。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人把兵力分散了，我们就有机会。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做太多事会分散你的精力。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了分散对手的力量，球队改变了打法。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新路分散了市中心的车流。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把工厂分散到几个地方，减少损失。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学生分散到不同的教室考试，避免作弊。", "target_word": "分散", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分散了", "label": "完成体"}, {"form": "分散着", "label": "持续体"}, {"form": "分散过", "label": "经历体"}, {"form": "分散开", "label": "复合"}], "register": "中性", "sense_fingerprint": "使集中的东西散开，带宾语，常说分散注意力、风险、力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "分散注意力指使注意力散开，符合“窗外的噪音干扰我”的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：噪音不能“修理”注意力，“修理”要有能修的具体对象。"}, {"text": "消化", "is_correct": false, "explanation": "搭配：“消化”指吸收食物或理解知识，不能用于注意力，句意不通。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是高兴地纪念，与噪音干扰注意力的意思不符。"}], "explanations": {"分散": "分散注意力指使注意力散开，符合“窗外的噪音干扰我”的语境。", "修理": "语义：噪音不能“修理”注意力，“修理”要有能修的具体对象。", "消化": "搭配：“消化”指吸收食物或理解知识，不能用于注意力，句意不通。", "庆祝": "语义：“庆祝”是高兴地纪念，与噪音干扰注意力的意思不符。"}, "sentence_index": 0, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把这块大布分散成了三块，给三个孩子做衣服。", "explanation": "这里应该用〈分割〉。“分散”是使集中的东西散开，把一整块布剪成几块要说“分割”。"}, {"text": "妈妈把两个孩子分散了，让他们各玩各的。", "explanation": "这里应该用〈分开〉。“分散”用于许多人或东西散开，两个孩子只能用“分开”。"}, {"text": "教练把球员分散到一个房间休息。", "explanation": "这里应该用〈集合〉。“分散”是把集中的人或物散到各处，把球员都放进一个房间应说“集合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分散", "is_correct": true, "explanation": "分散指使对手的力量散开，符合“为了……球队改变了打法”的语境。"}, {"text": "增强", "is_correct": false, "explanation": "语义：“增强”是加强，与“为了分散对手的力量”的目的相反。"}, {"text": "增援", "is_correct": false, "explanation": "语义：“增援”是支援己方，用在对手身上，与“分散对手的力量”的目的相反。"}, {"text": "壮大", "is_correct": false, "explanation": "语义：“壮大”是使某一方增长，与“为了……对手”的目的不符。"}], "explanations": {"分散": "分散指使对手的力量散开，符合“为了……球队改变了打法”的语境。", "增强": "语义：“增强”是加强，与“为了分散对手的力量”的目的相反。", "增援": "语义：“增援”是支援己方，用在对手身上，与“分散对手的力量”的目的相反。", "壮大": "语义：“壮大”是使某一方增长，与“为了……对手”的目的不符。"}, "sentence_index": 6, "correct_answer": "分散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把考卷分散给每个学生。", "explanation": "这里应该用〈分发〉。“分散”是使集中的东西散开，把考卷发给每人要用“分发”。"}, {"text": "老师把吵架的两个学生分散了。", "explanation": "这里应该用〈分开〉。“分散”用于许多人或东西散开，两个人只能说“分开”。"}, {"text": "他们把全部精力分散在一件事上。", "explanation": "这里应该用〈集中〉。“分散”要分到多处，“全部精力都用在一件事上”应说“集中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放学的铃声一响，老师就分散着了聚在门口的学生。", "corrected_sentence": "放学的铃声一响，老师就分散了聚在门口的学生。", "error_description": "错误：“分散”后加了“着”，又带“了”，句子不通。正确：表示动作完成用“分散了”，不用“分散着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这阵大风把一大群鸽子分散了山谷各处。", "corrected_sentence": "这阵大风把一大群鸽子分散到了山谷各处。", "error_description": "错误：“分散”后漏了“到”。正确：“分散到＋地点”表示散向各处，少了“到”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
