INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96147, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "切实是实实在在，能做到。", "primary_collocate": null, "pronunciation": "qiè shí", "ipa": "tɕʰiɛ˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这个计划很切实，我们可以马上开始。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想出切实可行的办法。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们切实的帮助。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的建议很切实，大家都同意。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要切实解决工人的问题。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你提出一个切实的目标。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些办法切实有用。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想为老人做一些切实的事。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的想法不够切实，很难做到。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要切实保护环境。", "target_word": "切实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "切切实实", "label": "重叠"}, {"form": "切實", "label": "繁体"}], "register": "书面", "sense_fingerprint": "实实在在、能做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96147, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切实", "is_correct": true, "explanation": "切实：实实在在、能做到，与“可以马上开始”相呼应。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：“含糊”说计划不清楚，与“可以马上开始”矛盾。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”只形容人或物体的形体，不能用来形容计划。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容建筑等高起的物体，不能用来形容计划。"}], "explanations": {"切实": "切实：实实在在、能做到，与“可以马上开始”相呼应。", "含糊": "语义：“含糊”说计划不清楚，与“可以马上开始”矛盾。", "瘦小": "体貌：“瘦小”只形容人或物体的形体，不能用来形容计划。", "高耸": "搭配：“高耸”形容建筑等高起的物体，不能用来形容计划。"}, "sentence_index": 0, "correct_answer": "切实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山很切实，有八千米。", "explanation": "这里应该用〈高〉。切实指实实在在、能做到，形容山的高度要说高。"}, {"text": "这个西瓜很切实，大家都爱吃。", "explanation": "这里应该用〈甜〉。切实指实实在在、能做到，西瓜的味道要说甜。"}, {"text": "这幅画很切实，挂在客厅里很漂亮。", "explanation": "这里应该用〈好看〉。切实指实实在在、能做到，形容画的美观要说好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
