INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96149, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "初级是刚开始学，最简单的一级。", "primary_collocate": null, "pronunciation": "chū jí", "ipa": "ʈʂʰu˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我在学初级汉语，每天学十个字。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是给初级学生看的。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报了一个初级班，下周开始上课。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初级课的生词不多，也不太难。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的英语只有初级水平，不会说长句子。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初级班的同学都是刚开始学的人。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给初级学生准备了很多图片。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳班是初级的，我可以参加。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先上初级课，再上中级课。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初级考试一共有五十个问题。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "初級", "label": "繁体"}, {"form": "初级班", "label": "复合"}], "register": "中性", "sense_fingerprint": "初级：作定语，指学习中刚开始、最简单的一级，如初级汉语、初级班", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初级", "is_correct": true, "explanation": "初级：刚开始学、最简单的一级，与“每天学十个字”的入门课程相符。"}, {"text": "流利", "is_correct": false, "explanation": "语义：“流利”形容熟练程度高，与“每天学十个字”的入门学习状态相矛盾。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：“复杂”说内容难度大，与“每天学十个字”的入门学习相矛盾。"}, {"text": "大型", "is_correct": false, "explanation": "搭配：“大型”形容规模，不能用来修饰“汉语”这门课的学习程度。"}], "explanations": {"初级": "初级：刚开始学、最简单的一级，与“每天学十个字”的入门课程相符。", "流利": "语义：“流利”形容熟练程度高，与“每天学十个字”的入门学习状态相矛盾。", "复杂": "语义：“复杂”说内容难度大，与“每天学十个字”的入门学习相矛盾。", "大型": "搭配：“大型”形容规模，不能用来修饰“汉语”这门课的学习程度。"}, "sentence_index": 0, "correct_answer": "初级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们初级讨论了这个问题。", "explanation": "这里应该用〈初步〉，表示开始阶段、不深入，修饰“讨论”这类动作。初级是形容词，指等级最低，不能修饰动作。"}, {"text": "他的初级很扎实，学起来很快。", "explanation": "这里应该用〈基础〉，指事物的根本部分。初级指等级或阶段，不能用“扎实”来说明基础。"}, {"text": "他的初级很美好，我一直忘不了。", "explanation": "这里应该用〈初恋〉，指第一次恋爱。初级指等级或阶段，不能指恋爱经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初级", "is_correct": true, "explanation": "初级：刚开始学的阶段，与“准备了很多图片”帮助入门的语境相符。"}, {"text": "高等", "is_correct": false, "explanation": "搭配：“高等”修饰“教育”“学府”，不能说“高等学生”来表示学习程度。"}, {"text": "资深", "is_correct": false, "explanation": "搭配：“资深”指经验丰富，不能用来修饰刚开始学习的学生。"}, {"text": "私立", "is_correct": false, "explanation": "语义：“私立”说明学校的性质，与学生的学习程度无关。"}], "explanations": {"初级": "初级：刚开始学的阶段，与“准备了很多图片”帮助入门的语境相符。", "高等": "搭配：“高等”修饰“教育”“学府”，不能说“高等学生”来表示学习程度。", "资深": "搭配：“资深”指经验丰富，不能用来修饰刚开始学习的学生。", "私立": "语义：“私立”说明学校的性质，与学生的学习程度无关。"}, "sentence_index": 6, "correct_answer": "初级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们是初级见面。", "explanation": "这里应该用〈初次〉，表示第一次。初级指最低的一级或开始阶段，不能修饰“见面”。"}, {"text": "他的初级很简单，就是想帮助别人。", "explanation": "这里应该用〈初衷〉，指最初的想法。初级指等级或阶段，不能表示想法。"}, {"text": "他初级来北京的时候，一句汉语也不会说。", "explanation": "这里应该用〈最初〉，表示最开始的时候。初级指等级最低的一级，不能表示时间上的“开始时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一门很初级课。", "corrected_sentence": "这是一门初级课。", "error_description": "“初级”修饰名词“课”时是定语，前面不能直接加程度副词“很”。正确：这是一门初级课。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门课是初级地课，适合刚学的人。", "corrected_sentence": "这门课是初级课，适合刚学的人。", "error_description": "“初级”修饰名词“课”时不能用结构助词“地”（“地”用于修饰动词）。正确：这门课是初级课，适合刚学的人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
