INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最低的一级；刚开始的阶段。", "primary_collocate": null, "pronunciation": "chū jí", "ipa": "ʈʂʰu˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我的钢琴还在初级，需要多练习。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从初级开始，一级一级往上学。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在我们还在初级，别太急。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的初级很简单，我很快就过了。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从初级到高级，只用了两年。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语比赛分为初级、中级和高级。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的水平还停在初级，没有进步。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意也要从初级做起，先好好学习。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的技术还处于初级。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从初级学起，现在已经是高级了。", "target_word": "初级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "初級", "label": "繁体"}, {"form": "初级阶段", "label": "复合"}], "register": "中性", "sense_fingerprint": "初级：作名词，指最低的一级或刚开始的阶段，如处于初级、初级阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初级", "is_correct": true, "explanation": "初级：最低的一级或刚开始的阶段，与“还在……需要多练习”相符。"}, {"text": "顶峰", "is_correct": false, "explanation": "语义：“顶峰”指最高点，与“还在”学习并需要继续练习的状态矛盾。"}, {"text": "末期", "is_correct": false, "explanation": "语义：“末期”指最后的阶段，与“还在”学习的状态矛盾。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“结束”指学习已经完成，不能作“还在”之后的阶段名词。"}], "explanations": {"初级": "初级：最低的一级或刚开始的阶段，与“还在……需要多练习”相符。", "顶峰": "语义：“顶峰”指最高点，与“还在”学习并需要继续练习的状态矛盾。", "末期": "语义：“末期”指最后的阶段，与“还在”学习的状态矛盾。", "结束": "搭配：“结束”指学习已经完成，不能作“还在”之后的阶段名词。"}, "sentence_index": 0, "correct_answer": "初级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是初级结果，还要再检查。", "explanation": "这里应该用〈初步〉，指不完整、尚待深入的。初级指等级或阶段，不能用来说明结果的完整程度。"}, {"text": "这杯初级太烫了，等一会儿再喝。", "explanation": "这里应该用〈咖啡〉，指一种饮料。初级是抽象的等级或阶段，不能喝。"}, {"text": "这桌的初级很香，我想尝一尝。", "explanation": "这里应该用〈饭菜〉，指吃的东西。初级是等级或阶段，不能用“香”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初级", "is_correct": true, "explanation": "初级：刚开始学的阶段，与“停在”这一状态及“没有进步”的语境相符。"}, {"text": "高潮", "is_correct": false, "explanation": "语义：“高潮”指事情最热烈的时刻，不是能力或水平的阶段。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”指活动开始的时刻，不能用来说“停在”某一水平。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”是动作的结束，不能表示水平所处的阶段，不能说“停在完成”。"}], "explanations": {"初级": "初级：刚开始学的阶段，与“停在”这一状态及“没有进步”的语境相符。", "高潮": "语义：“高潮”指事情最热烈的时刻，不是能力或水平的阶段。", "开幕": "搭配：“开幕”指活动开始的时刻，不能用来说“停在”某一水平。", "完成": "搭配：“完成”是动作的结束，不能表示水平所处的阶段，不能说“停在完成”。"}, "sentence_index": 6, "correct_answer": "初级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们是初级见面。", "explanation": "这里应该用〈初次〉，表示第一次。初级指最低的一级或开始阶段，不能修饰“见面”。"}, {"text": "他的初级很甜蜜，我们都很羡慕。", "explanation": "这里应该用〈初恋〉，指第一次恋爱。初级指等级或阶段，不能表示恋爱。"}, {"text": "这个皮球的初级很圆，孩子很喜欢。", "explanation": "这里应该用〈外形〉，指物体的样子。初级是等级或阶段，不能用来形容形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的水平还在初级上。", "corrected_sentence": "他的水平还在初级。", "error_description": "“初级”作名词表示所处的阶段，直接说“在初级”，后面不加方位词“上”。正确：他的水平还在初级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从初级地开始，一步一步来。", "corrected_sentence": "我们从初级开始，一步一步来。", "error_description": "“初级”作名词，表示起点，后面不能加结构助词“地”（“地”用于修饰动词）。正确：我们从初级开始，一步一步来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期：指某件事进行到中后阶段，与“前期”相对，构成反义。"}, {"text": "工具", "is_correct": false, "explanation": "工具：是名词，但与“前期”的时间阶段义无反义或近义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水：是名词，但与“前期”的任何义项都没有反义或近义关系。"}], "correct_answer": "后期", "explanations": {"后期": "后期：指某件事进行到中后阶段，与“前期”相对，构成反义。", "工具": "工具：是名词，但与“前期”的时间阶段义无反义或近义关系。", "窗户": "窗户：是名词，但与“前期”的任何义项都没有反义或近义关系。", "雨水": "雨水：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期：指某件事进行到中后阶段，与“前期”相对，构成反义。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "音乐：是名词，但与“前期”的任何义项都没有反义或近义关系。"}], "correct_answer": "后期", "explanations": {"后期": "后期：指某件事进行到中后阶段，与“前期”相对，构成反义。", "桌子": "桌子：是名词，但与“前期”的任何义项都没有反义或近义关系。", "河流": "河流：是名词，但与“前期”的任何义项都没有反义或近义关系。", "音乐": "音乐：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前期是一件事刚开始的那段时间。", "primary_collocate": null, "pronunciation": "qián qī", "ipa": "tɕʰjɛn³⁵ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "工程的前期很辛苦，大家都没休息。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意前期要花很多钱。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前期我们什么都不懂，只能慢慢学。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目前期做得不错。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前期的准备做好了，后面就容易了。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语的前期，我每天都练习写字。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在前期只有五个人。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前期的工作很重要，不能马虎。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店的前期，他几乎每天都很晚回家。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在前期没有赚钱，后来才慢慢好起来。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前期准备", "label": "复合"}, {"form": "前期工作", "label": "复合"}, {"form": "前期投入", "label": "复合"}], "register": "中性", "sense_fingerprint": "一件事、一项工作刚开始的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前期", "is_correct": true, "explanation": "前期：指工程刚开始的那段时间，与“很辛苦”的语境相符。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：“辛苦”描述人的劳累，“利润”不能作“很辛苦”的主语。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是工程的阶段，句子说的是工程的时期。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能与“很辛苦”搭配，句子的主语应是指向人或过程的词。"}], "explanations": {"前期": "前期：指工程刚开始的那段时间，与“很辛苦”的语境相符。", "利润": "搭配：“辛苦”描述人的劳累，“利润”不能作“很辛苦”的主语。", "颜色": "语义：“颜色”不是工程的阶段，句子说的是工程的时期。", "价格": "搭配：“价格”不能与“很辛苦”搭配，句子的主语应是指向人或过程的词。"}, "sentence_index": 0, "correct_answer": "前期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一个前期，放在桌上很好看。", "explanation": "这里“前期”是抽象的时间阶段，不是可以买的东西，“买了一个前期”说不通；本词条指某件事刚开始的那段时间。"}, {"text": "这家公司的前期很好，以后一定会很成功。", "explanation": "这里应该用〈前景〉。前期指事情刚开始的那段时间，不指将来的发展；说未来的情况要用“前景”。"}, {"text": "这个项目有一场前期，非常辛苦。", "explanation": "这里应该用〈段〉。前期指一段时间，要用“段”；“场”用于比赛、雨、会议等活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前期", "is_correct": true, "explanation": "前期：指公司刚开始的那段时间，与“只有五个人”的语境相符。"}, {"text": "利息", "is_correct": false, "explanation": "语义：“利息”不表示时段，不能用于“在…只有五个人”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不能表示公司所处的阶段。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“账单”不能与“在…只有五个人”搭配。"}], "explanations": {"前期": "前期：指公司刚开始的那段时间，与“只有五个人”的语境相符。", "利息": "语义：“利息”不表示时段，不能用于“在…只有五个人”。", "温度": "语义：“温度”不能表示公司所处的阶段。", "账单": "搭配：“账单”不能与“在…只有五个人”搭配。"}, "sentence_index": 6, "correct_answer": "前期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他年轻有为，前期很光明。", "explanation": "这里应该用〈前途〉。前期指事情刚开始的那段时间，不指未来的发展；“光明”搭配的是“前途”。"}, {"text": "这位老师是我们学校的前期，教了很多年书。", "explanation": "这里应该用〈前辈〉。前期指一段时期，不指人；指资历深的人要用“前辈”。"}, {"text": "我把前期放进了书包，准备带去学校。", "explanation": "这里“前期”是抽象的时间阶段，不能放进书包；本词条指某件事刚开始的那段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个项目非常前期的准备做得很好。", "corrected_sentence": "这个项目前期的准备做得很好。", "error_description": "错误：“前期”是名词，前面不能加程度副词“非常”。应去掉“非常”，说“这个项目前期的准备做得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司的很前期工作很辛苦。", "corrected_sentence": "公司的前期工作很辛苦。", "error_description": "错误：“前期”是名词，前面不能加程度副词“很”。多余的“很”放在“前期工作”前是错误的，应说“公司的前期工作很辛苦”（“很”只修饰“辛苦”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期：指某一时期的后半段，与“前期”的前半段相对，构成反义。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园：是名词，但与“前期”的任何义项都没有反义或近义关系。"}], "correct_answer": "后期", "explanations": {"后期": "后期：指某一时期的后半段，与“前期”的前半段相对，构成反义。", "雨水": "雨水：是名词，但与“前期”的任何义项都没有反义或近义关系。", "钥匙": "钥匙：是名词，但与“前期”的任何义项都没有反义或近义关系。", "花园": "花园：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期：指某一时期的后半段，与“前期”的前半段相对，构成反义。"}, {"text": "书包", "is_correct": false, "explanation": "书包：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, {"text": "故事", "is_correct": false, "explanation": "故事：是名词，但与“前期”的任何义项都没有反义或近义关系。"}], "correct_answer": "后期", "explanations": {"后期": "后期：指某一时期的后半段，与“前期”的前半段相对，构成反义。", "书包": "书包：是名词，但与“前期”的任何义项都没有反义或近义关系。", "海洋": "海洋：是名词，但与“前期”的任何义项都没有反义或近义关系。", "故事": "故事：是名词，但与“前期”的任何义项都没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一时期的前半段。", "primary_collocate": null, "pronunciation": "qián qī", "ipa": "tɕʰjɛn³⁵ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "这个月前期天气很冷，后期会变暖。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唐朝前期很强大，后期慢慢变弱了。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前期，他们一直领先。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书前期的内容比较容易，后面越来越难。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年前期雨水多，后期比较干。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品前期比较简单，后期更成熟。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个世纪前期，世界发生了很大变化。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一年前期他很忙，后期才休息。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影前期很慢，后期才变得好看。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市前期发展很快，后期慢下来了。", "target_word": "前期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前期工作", "label": "复合"}, {"form": "前期作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "某个时期、朝代或过程的前半部分，与后期相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前期", "is_correct": true, "explanation": "前期：指这个月的前半段，与“天气很冷”、后期变暖的语境相符。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”不能说明天气，句子描述的是天气冷。"}, {"text": "销量", "is_correct": false, "explanation": "搭配：“销量”不能与“天气很冷”搭配。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能与“天气很冷”搭配。"}], "explanations": {"前期": "前期：指这个月的前半段，与“天气很冷”、后期变暖的语境相符。", "人口": "语义：“人口”不能说明天气，句子描述的是天气冷。", "销量": "搭配：“销量”不能与“天气很冷”搭配。", "工资": "搭配：“工资”不能与“天气很冷”搭配。"}, "sentence_index": 0, "correct_answer": "前期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电视剧的前期就是整部作品的内容。", "explanation": "这里应该用〈全程〉。前期指某一时期的前半段，不能指整个作品；表示从头到尾要用“全程”。"}, {"text": "这本书的前期写得很好，我想知道最后的结局。", "explanation": "这里用“前期”不自然。说书的开头部分要用〈前半部分〉或〈开头〉；前期多指时期或过程的前半段。"}, {"text": "我的前期是当一名医生。", "explanation": "这里应该用〈理想〉。前期指某一时期的前半段，不指将来的愿望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前期", "is_correct": true, "explanation": "前期：指这个世纪的前半段，与“世界发生了很大变化”的语境相符。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：“冠军”不是时段，不能修饰“这个世纪”。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”不表示时段，不能用于“这个世纪”。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘”不能与“这个世纪”搭配表示时段。"}], "explanations": {"前期": "前期：指这个世纪的前半段，与“世界发生了很大变化”的语境相符。", "冠军": "语义：“冠军”不是时段，不能修饰“这个世纪”。", "咖啡": "语义：“咖啡”不表示时段，不能用于“这个世纪”。", "窗帘": "搭配：“窗帘”不能与“这个世纪”搭配表示时段。"}, "sentence_index": 6, "correct_answer": "前期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的前期就是结局，大家都哭了。", "explanation": "这里应该用〈结尾〉。前期指某一时期的前半段，不能指作品的最后部分；“就是结局”把前期当成了结尾。"}, {"text": "他是我们班的前期班长，管了很多事。", "explanation": "这里应该用〈前任〉。前期指时期，不指人；“以前的班长”要说“前任班长”。"}, {"text": "这次比赛的前期就是三天，从头到尾只有这三天。", "explanation": "这里应该用〈整个赛程〉。前期指某一时期的前半段，不能指从头到尾的全部过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唐朝很前期的经济发展很快。", "corrected_sentence": "唐朝前期的经济发展很快。", "error_description": "错误：“前期”是名词，不能受程度副词“很”修饰。应去掉“很”，说“唐朝前期的经济发展很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市很前期的人口增长很快。", "corrected_sentence": "这座城市前期的人口增长很快。", "error_description": "错误：“前期”是名词，不能直接受程度副词“很”修饰。多余的“很”应去掉，说“这座城市前期的人口增长很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
