INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "千年是一千年的时间长度，指确切的一千年。", "primary_collocate": null, "pronunciation": "qiān nián", "ipa": "tɕʰi̯ɛn˥ ni̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这座古桥有千年的历史了。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树已经活了千年。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千年前，这里是一座小城。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事流传了千年，还有人在讲。", "target_word": "千年", "complexity_tier": "T3", "furigana": "zhè ge gù shi liú chuán le qiān nián, hái yǒu rén zài jiǎng.", "sentence_source": "generated"}, {"text": "这座寺庙在山上已经有千年了。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树的寿命可以超过千年。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千年的时间可以让河流改变方向。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这块石头躺在河里有千年了。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去千年里，这个国家发生了很多事。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书里读到了千年前的生活。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "千年来", "label": "复合"}], "register": "中性", "sense_fingerprint": "千年：确切的一千年时间长度，常与历史、年代连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96153, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "千年", "is_correct": true, "explanation": "千年：一千年，很长很长的时间。与所听音相同。"}, {"text": "前年", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，意思是前年（两年前）。"}, {"text": "青年", "is_correct": false, "explanation": "qīng 与 qiān 韵母不同（-ing 与 -an），意思是青年（年轻人）。"}, {"text": "牵连", "is_correct": false, "explanation": "lián 与 nián 声母不同（l 与 n），意思是牵连（连累）。"}], "explanations": {"千年": "千年：一千年，很长很长的时间。与所听音相同。", "前年": "qián（第二声）与 qiān（第一声）声调不同，意思是前年（两年前）。", "青年": "qīng 与 qiān 韵母不同（-ing 与 -an），意思是青年（年轻人）。", "牵连": "lián 与 nián 声母不同（l 与 n），意思是牵连（连累）。"}, "sentence_index": null, "correct_answer": "千年"}, "level_3": {"options": [{"text": "千年", "is_correct": true, "explanation": "正确：千年指一千年，与「古桥」的悠久历史相合。"}, {"text": "童年", "is_correct": false, "explanation": "语义：童年指人的幼年时期，古桥没有童年。"}, {"text": "青春", "is_correct": false, "explanation": "搭配：「青春」多指人的年华，不能用来说古桥的历史。"}, {"text": "白发", "is_correct": false, "explanation": "体貌：白发描写人的头发，不能用来形容古桥的历史。"}], "explanations": {"千年": "正确：千年指一千年，与「古桥」的悠久历史相合。", "童年": "语义：童年指人的幼年时期，古桥没有童年。", "青春": "搭配：「青春」多指人的年华，不能用来说古桥的历史。", "白发": "体貌：白发描写人的头发，不能用来形容古桥的历史。"}, "sentence_index": 0, "correct_answer": "千年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服值千年。", "explanation": "这里应该用〈千金〉。「值千金」形容价值极高；「千年」是时间长度，不能用来估价。"}, {"text": "我每个月的工资是千年。", "explanation": "这里应该用〈千元〉。「千元」是钱数，「千年」是时间，不能用来说工资。"}, {"text": "这块石头重千年。", "explanation": "这里应该用〈千克〉。「重」指重量，「千年」是时间，不能用来计重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "千年", "is_correct": true, "explanation": "正确：千年的时间足以让河流改变方向，符合语境。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是很长的时间，不能让河流改道。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：「电脑的时间」不成立，「电脑」不能作时间的定语。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是家具，不是时间，无法修饰「时间」。"}], "explanations": {"千年": "正确：千年的时间足以让河流改变方向，符合语境。", "早饭": "语义：早饭是一顿饭，不是很长的时间，不能让河流改道。", "电脑": "搭配：「电脑的时间」不成立，「电脑」不能作时间的定语。", "饭桌": "语义：饭桌是家具，不是时间，无法修饰「时间」。"}, "sentence_index": 6, "correct_answer": "千年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每周千年去一次健身房。", "explanation": "「千年」是一千年的时间长度，不能放在「每周……去一次」里表示频率，应删去，说「我每周去一次健身房」。"}, {"text": "他一口气吃掉了千年。", "explanation": "这里应该用〈千个〉。「千年」是时间，不能当作可以吃的数量。"}, {"text": "他的身高是千年。", "explanation": "这里应该用〈一米八〉之类的长度。「千年」是时间，不能表示身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古城已经有一千年个历史了。", "corrected_sentence": "这座古城已经有一千年的历史了。", "error_description": "量词错误：「一千年」后面不能再接量词「个」修饰「历史」，应说「一千年的历史」，不说「一千年个历史」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古城的历史很一千年了。", "corrected_sentence": "这座古城的历史有一千年了。", "error_description": "词类错误：程度副词「很」不能修饰时长词组「一千年」，应改用「有」，说「历史有一千年了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
