INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻非常漫长、感觉上很久的时间，并非确切的一千年。", "primary_collocate": null, "pronunciation": "qiān nián", "ipa": "tɕʰi̯ɛn˥ ni̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "她等这一天，好像等了千年。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，这一分钟像千年一样长。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千年的梦想，今天终于成真了。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你的这一夜，比千年还要长。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，等孩子回家的每一天都像千年。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这千年的孤独，只有月亮知道。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得考试前的一个小时好像过了千年。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千年的思念，在这一刻变成了眼泪。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对爱她的人来说，分开一天就是千年。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他盼了千年，才等到这封信。", "target_word": "千年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "千年来", "label": "复合"}], "register": "书面", "sense_fingerprint": "千年：比喻非常漫长、感觉上很久的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "千年", "is_correct": true, "explanation": "千年：比喻非常漫长的时间。与所听音相同。"}, {"text": "前年", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，意思是前年（两年前）。"}, {"text": "青年", "is_correct": false, "explanation": "qīng 与 qiān 韵母不同（-ing 与 -an），意思是青年（年轻人）。"}, {"text": "牵连", "is_correct": false, "explanation": "lián 与 nián 声母不同（l 与 n），意思是牵连（连累）。"}], "explanations": {"千年": "千年：比喻非常漫长的时间。与所听音相同。", "前年": "qián（第二声）与 qiān（第一声）声调不同，意思是前年（两年前）。", "青年": "qīng 与 qiān 韵母不同（-ing 与 -an），意思是青年（年轻人）。", "牵连": "lián 与 nián 声母不同（l 与 n），意思是牵连（连累）。"}, "sentence_index": null, "correct_answer": "千年"}, "level_3": {"options": [{"text": "千年", "is_correct": true, "explanation": "正确：千年在此表示非常漫长的时间，与「好像」的夸张相合。"}, {"text": "童年", "is_correct": false, "explanation": "语义：童年是人的幼年时期，不是可以等待的漫长时段。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是物件，「等了蜡烛」不能表示漫长的时段。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是家具，不是可以等待的时段。"}], "explanations": {"千年": "正确：千年在此表示非常漫长的时间，与「好像」的夸张相合。", "童年": "语义：童年是人的幼年时期，不是可以等待的漫长时段。", "蜡烛": "语义：蜡烛是物件，「等了蜡烛」不能表示漫长的时段。", "抽屉": "语义：抽屉是家具，不是可以等待的时段。"}, "sentence_index": 0, "correct_answer": "千年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子的面积是千年平方米。", "explanation": "这里应该用〈一千平方米〉之类的面积。「千年」是时间，不能作为面积的单位。"}, {"text": "这次考试我考了千年分。", "explanation": "这里应该用〈满分〉。「千年」是时间，不能用来计分。"}, {"text": "我只等了千年，你就来了。", "explanation": "这里应该用〈一会儿〉。「只」表示时间很短，与「千年」的漫长相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "千年", "is_correct": true, "explanation": "正确：千年表示漫长的时间，与「一个小时」形成夸张的对比，符合语境。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是物件，「过了蜡烛」不能表示时段的流逝。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：「过了晚饭」搭配不当，「过」后接的时段不能是一顿饭。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：「过」要求时间性的宾语，「厨房」是地点，不能充当。"}], "explanations": {"千年": "正确：千年表示漫长的时间，与「一个小时」形成夸张的对比，符合语境。", "蜡烛": "语义：蜡烛是物件，「过了蜡烛」不能表示时段的流逝。", "晚饭": "搭配：「过了晚饭」搭配不当，「过」后接的时段不能是一顿饭。", "厨房": "配价：「过」要求时间性的宾语，「厨房」是地点，不能充当。"}, "sentence_index": 6, "correct_answer": "千年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每月千年去一次超市。", "explanation": "「千年」比喻很长很长的时间，不能放在「每月……去一次」里表示频率，应删去，说「我每月去一次超市」。"}, {"text": "他一口气喝掉了千年的汽水。", "explanation": "这里应该用〈一大瓶〉之类的数量。「千年」是时间，不能用来表示饮料的量。"}, {"text": "他盼了千年的一个月，才等到这封信。", "explanation": "这里应该用〈很久〉。「千年」是比喻夸张，表示很长很长的时间，不能当作确切时长去限定具体的一个月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一刻，我觉得很千年。", "corrected_sentence": "这一刻，我觉得像过了千年。", "error_description": "词类错误：名词「千年」不能被程度副词「很」修饰，应说「像过了千年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我盼了一千年的，终于等到你的信。", "corrected_sentence": "我盼了一千年，终于等到你的信。", "error_description": "结构助词错误：「一千年」是时间词组，后面不能直接加「的」使句子不完整，应说「我盼了一千年，终于等到你的信」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
