INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96155, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占地方是东西太大，把地方挤满了。", "primary_collocate": null, "pronunciation": "zhàn dì fang", "ipa": "ʈʂan˥˩ ti˥˩ faŋ", "syllable_count": 3, "sentences": [{"text": "这张大桌子太占地方了。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小房间里放大沙发，特别占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱太大了，放在厨房里很占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧箱子堆在家里，真占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老式电视又大又重，很占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家不大，买大床会占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴放在客厅里太占地方，走路都不方便。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大书架摆满了屋子，太占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李箱这么大，放在车里占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间这么小，别再买这么大的柜子了，占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "东西体积太大，把屋子或空间挤满，使人觉得不方便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占地方", "is_correct": true, "explanation": "占地方：东西体积大，把屋子的空间挤满，与“大桌子”相合。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：桌子不会道歉，“道歉”需要有意识的人。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是人的情绪，不能用来描写桌子。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”只用于人或动物的身体，不能说桌子发胖。"}], "explanations": {"占地方": "占地方：东西体积大，把屋子的空间挤满，与“大桌子”相合。", "道歉": "语义：桌子不会道歉，“道歉”需要有意识的人。", "生气": "语义：“生气”是人的情绪，不能用来描写桌子。", "发胖": "体貌：“发胖”只用于人或动物的身体，不能说桌子发胖。"}, "sentence_index": 0, "correct_answer": "占地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议很占地方，开了一整天。", "explanation": "这里应该用〈占时间〉。占地方说东西体积大，会议耗费时间要用占时间。"}, {"text": "这个问题很占地方，大家讨论了一下午。", "explanation": "这里应该用〈棘手〉。占地方说东西体积大，问题难办要用棘手。"}, {"text": "考试前大家都很占地方，压力很大。", "explanation": "这里应该用〈紧张〉。占地方说东西体积大，人的心情要用紧张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占地方", "is_correct": true, "explanation": "占地方：钢琴体积大，放在客厅里挤占空间，与“走路都不方便”相合。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”是人离开本国，钢琴不会出国，句意不通。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”后要带活动之类的宾语，不能单独说“太参加”。"}, {"text": "发财", "is_correct": false, "explanation": "语义：“发财”指人致富，与钢琴占地方的意思无关。"}], "explanations": {"占地方": "占地方：钢琴体积大，放在客厅里挤占空间，与“走路都不方便”相合。", "出国": "语义：“出国”是人离开本国，钢琴不会出国，句意不通。", "参加": "配价：“参加”后要带活动之类的宾语，不能单独说“太参加”。", "发财": "语义：“发财”指人致富，与钢琴占地方的意思无关。"}, "sentence_index": 6, "correct_answer": "占地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行很占地方，花了我不少钱。", "explanation": "这里应该用〈耗钱〉。占地方说东西体积大，花费钱财要用耗钱。"}, {"text": "老师很占地方，学生们都很怕他。", "explanation": "这里应该用〈严格〉。占地方形容东西体积大，人的作风要用严格。"}, {"text": "这家店的服务很占地方，客人很满意。", "explanation": "这里应该用〈周到〉。占地方说东西体积大，服务细致要用周到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个衣柜太大了，放进卧室后很占地方过。", "corrected_sentence": "这个衣柜太大了，放进卧室后很占地方。", "error_description": "错误：“很占地方过”中的“过”用错。“过”表示经历，不能用在描写眼前状态的“很占地方”之后，应去掉“过”，说“很占地方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种大沙发一放进客厅，总是特别占地方了。", "corrected_sentence": "这种大沙发一放进客厅，总是特别占地方。", "error_description": "“了”误用：“总是”说的是惯常情况，句中没有已经发生的变化，句末不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
