INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96156, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占用空间；占据位置。", "primary_collocate": null, "pronunciation": "zhàn dì fang", "ipa": "ʈʂan˥˩ ti˥˩ faŋ", "syllable_count": 3, "sentences": [{"text": "你的包放在过道上，占地方，别人过不去。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷搭起来占地方，要选一块大空地。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小花盆不占地方，放在窗台上就行。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子书不占地方，一个手机就能装很多。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "折叠椅不占地方，不用时可以收起来。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机不大，放在阳台上也不占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租小房子的人，买东西都选不占地方的。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新书架很薄，一点也不占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大货车停在路边，太占地方，别的车过不去。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡袋可以压得很小，带着也不占地方。", "target_word": "占地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "物品或人占用一定的空间、位置，常说占不占地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占地方", "is_correct": true, "explanation": "占地方：包放在过道上，占去空间，别人因此过不去，与句意相合。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：“锻炼”是人的身体活动，包不能锻炼，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是人的行为，不能用来描述放在过道上的包。"}, {"text": "欢送", "is_correct": false, "explanation": "配价：“欢送”必须带宾语，如欢送某人，不能单独用在这里。"}], "explanations": {"占地方": "占地方：包放在过道上，占去空间，别人因此过不去，与句意相合。", "锻炼": "语义：“锻炼”是人的身体活动，包不能锻炼，句意不通。", "洗澡": "语义：“洗澡”是人的行为，不能用来描述放在过道上的包。", "欢送": "配价：“欢送”必须带宾语，如欢送某人，不能单独用在这里。"}, "sentence_index": 0, "correct_answer": "占地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛他很占地方，拿到了冠军。", "explanation": "这里应该用〈夺冠〉。占地方指占用空间，赢得比赛要说夺冠。"}, {"text": "他的话很占地方，半小时还没说完。", "explanation": "这里应该用〈啰嗦〉。占地方指占用空间，说话冗长要用啰嗦。"}, {"text": "他对朋友很占地方，总是处处为朋友着想。", "explanation": "这里应该用〈体贴〉。占地方指占用空间，对人关心周到要用体贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占地方", "is_correct": true, "explanation": "占地方：租小房子的人要挑体积小的东西，与“选不占地方的”相合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是人或动物的状态，不能用来描述买的东西，句意不通。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”只用于人或动物的体态，不能说东西发胖。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指学校或单位停止工作，东西不能放假。"}], "explanations": {"占地方": "占地方：租小房子的人要挑体积小的东西，与“选不占地方的”相合。", "生病": "语义：“生病”是人或动物的状态，不能用来描述买的东西，句意不通。", "发胖": "体貌：“发胖”只用于人或动物的体态，不能说东西发胖。", "放假": "语义：“放假”指学校或单位停止工作，东西不能放假。"}, "sentence_index": 6, "correct_answer": "占地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中一直占地方，最后赢了比赛。", "explanation": "这里应该用〈占上风〉。占地方指物体占用空间，比赛中处于优势要说占上风。"}, {"text": "今天天气很占地方，热得让人受不了。", "explanation": "这里应该用〈闷热〉。占地方指物体占用空间，不能形容天气。"}, {"text": "这次考试他很占地方，考了九十分。", "explanation": "这里应该用〈拿高分〉。占地方指占用空间，考试成绩好要说拿高分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种折叠桌收起来以后，一点也没占地方。", "corrected_sentence": "这种折叠桌收起来以后，一点也不占地方。", "error_description": "否定词错误：说物品一般的性质、状态要用“不”，“没”否定已发生的事；应说“一点也不占地方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把小椅子叠起来很薄，一般放进包里一点也不占地方了。", "corrected_sentence": "这把小椅子叠起来很薄，一般放进包里一点也不占地方。", "error_description": "“了”误用：“一般”说的是惯常情况，句中没有已经发生的变化，“一点也不占地方”后不能加“了”，应说“一点也不占地方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
