INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96157, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "反政府是不喜欢政府，要和政府对着干。", "primary_collocate": null, "pronunciation": "fǎn zhèng fǔ", "ipa": "fan˨˩˦ ʈʂəŋ˥˩ fu˨˩˦", "syllable_count": 3, "sentences": [{"text": "他说话总带着反政府的情绪，朋友都不敢多聊。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "这位歌手的歌词带有反政府的内容。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "他从小就有强烈的反政府情绪，谁劝也没用。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "你为什么抱有这么强的反政府立场呢？", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "爷爷年轻时持有反政府的观点，常和官员吵架。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "他有强烈的反政府想法，所以工作不太顺利。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "她不是坏人，只是持有反政府的态度。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "这个学生有很强的反政府倾向，老师很担心。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "他公开表达反政府的立场，政府很关注他。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}, {"text": "他们家的人都有反政府的倾向，吃饭时常谈政治。", "target_word": "反政府", "complexity_tier": "T3", "furigana": "fǎn zhèng fǔ", "sentence_source": "generated"}], "morphological_forms": [{"form": "反政府武装", "label": "复合"}, {"form": "反政府组织", "label": "复合"}], "register": "中性", "sense_fingerprint": "反政府|形容词|对政府态度不满，故意和政府作对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反政府", "is_correct": true, "explanation": "“反政府”指对政府持对立态度，与“朋友都不敢多聊”的语境相符。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐的情绪”与“朋友都不敢多聊”的语境相反。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“情绪”不能用“高大”来形容。"}, {"text": "学术", "is_correct": false, "explanation": "搭配：“学术”指学问研究，不能用来形容“情绪”。"}], "explanations": {"反政府": "“反政府”指对政府持对立态度，与“朋友都不敢多聊”的语境相符。", "欢乐": "语义：“欢乐的情绪”与“朋友都不敢多聊”的语境相反。", "高大": "搭配：“情绪”不能用“高大”来形容。", "学术": "搭配：“学术”指学问研究，不能用来形容“情绪”。"}, "sentence_index": 0, "correct_answer": "反政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对公司的决定很反政府。", "explanation": "这里应该用〈不满〉。对公司的决定不满要说“不满”；“反政府”只用于与政府作对。"}, {"text": "他对吵闹的声音很反政府。", "explanation": "这里应该用〈反感〉。对声音等厌恶要说“反感”；“反政府”只说对政府的对立。"}, {"text": "他对这份报告很反政府。", "explanation": "这里应该用〈怀疑〉。对报告的真实性存疑要说“怀疑”；“反政府”不能用于报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反政府", "is_correct": true, "explanation": "“反政府”指对政府持对立态度，与“持有……的态度”的语境相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“态度”不能是“数学的”，与句意不合。"}, {"text": "方形", "is_correct": false, "explanation": "语义：“方形的”是形状，不能修饰态度。"}, {"text": "空心", "is_correct": false, "explanation": "搭配：“态度”一般搭配“积极、消极、强硬”等，不搭配“空心的”。"}], "explanations": {"反政府": "“反政府”指对政府持对立态度，与“持有……的态度”的语境相符。", "数学": "语义：“态度”不能是“数学的”，与句意不合。", "方形": "语义：“方形的”是形状，不能修饰态度。", "空心": "搭配：“态度”一般搭配“积极、消极、强硬”等，不搭配“空心的”。"}, "sentence_index": 6, "correct_answer": "反政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市很反政府。", "explanation": "这里误用了“反政府”：它只表示与政府作对，不能用来形容超市这类非政府对象。"}, {"text": "这把椅子是反政府的。", "explanation": "这里误用了“反政府”：椅子没有政治立场，不能用“反政府”形容。"}, {"text": "他的手机很反政府。", "explanation": "这里误用了“反政府”：手机不是政府相关的对象，不能用“反政府”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "邻居的反政府了观点让大家都很担心。", "corrected_sentence": "邻居的反政府观点让大家都很担心。", "error_description": "错误：“反政府了观点”，正确：“反政府观点”。“反政府”是形容词，修饰名词时后面不能加动态助词“了”，直接放在“观点”前面即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那群人组织了一次反政府反政府集会，很多人都来看。", "corrected_sentence": "那群人组织了一次反政府集会，很多人都来看。", "error_description": "错误：“反政府反政府集会”，正确：“反政府集会”。“反政府”只需说一次，重复会使修饰语冗余，应直接说“一次反政府集会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
