INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96158, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "反对政府的。", "primary_collocate": null, "pronunciation": "fǎn zhèng fǔ", "ipa": "fan˨˩˦ ʈʂəŋ˥˩ fu˨˩˦", "syllable_count": 3, "sentences": [{"text": "反政府组织昨天发表了一份声明。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上有很多反政府的标语。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了一次反政府游行。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有一支反政府武装。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，反政府人员已经离开首都。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓了几个反政府分子。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反政府的声音越来越大。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过一篇反政府的文章。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个反政府网站已经关闭了。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反政府活动让这座城市很不安全。", "target_word": "反政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反政府武装", "label": "复合"}, {"form": "反政府组织", "label": "复合"}], "register": "中性", "sense_fingerprint": "反政府|形容词|定语，指反对政府的人、组织或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反政府", "is_correct": true, "explanation": "“反政府组织”指与政府对立的组织，与“发表了一份声明”的语境相符。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道，不能修饰“组织”发表声明。"}, {"text": "木制", "is_correct": false, "explanation": "搭配：“木制的”指材质，只能修饰物品，不搭配“组织”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体含水多，不能修饰“组织”发表声明。"}], "explanations": {"反政府": "“反政府组织”指与政府对立的组织，与“发表了一份声明”的语境相符。", "香甜": "语义：“香甜”形容味道，不能修饰“组织”发表声明。", "木制": "搭配：“木制的”指材质，只能修饰物品，不搭配“组织”。", "潮湿": "语义：“潮湿”形容空气或物体含水多，不能修饰“组织”发表声明。"}, "sentence_index": 0, "correct_answer": "反政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家企业是反政府的，由政府管理。", "explanation": "这里应该用〈国营〉。由政府管理的企业要说“国营”；“反政府”指与政府对抗，与“由政府管理”矛盾。"}, {"text": "今天的天气很反政府，我们别出门了。", "explanation": "这里应该用〈糟糕〉。天气不好要说“糟糕”；“反政府”只用于反对政府的人、组织或活动。"}, {"text": "他对学校的食堂很反政府。", "explanation": "这里应该用〈不满〉。对食堂、饭菜等的意见要说“不满”；“反政府”只针对政府。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反政府", "is_correct": true, "explanation": "“反政府的声音”指反对政府的言论，与“越来越大”的语境相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静的声音”与“越来越大”自相矛盾。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：“清淡”多形容味道，不搭配“声音”。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便的声音”没有意义，不能描述声音越来越大。"}], "explanations": {"反政府": "“反政府的声音”指反对政府的言论，与“越来越大”的语境相符。", "安静": "语义：“安静的声音”与“越来越大”自相矛盾。", "清淡": "搭配：“清淡”多形容味道，不搭配“声音”。", "方便": "语义：“方便的声音”没有意义，不能描述声音越来越大。"}, "sentence_index": 6, "correct_answer": "反政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市很反政府。", "explanation": "这里误用了“反政府”：它只表示与政府作对，不能用来形容超市这类非政府机构。"}, {"text": "这把椅子是反政府的。", "explanation": "这里误用了“反政府”：椅子没有政治立场，不能用“反政府”形容。"}, {"text": "这个花园很反政府。", "explanation": "这里误用了“反政府”：花园不是政治对象，不能用“反政府”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里有一些反政府们在活动。", "corrected_sentence": "城里有一些反政府分子在活动。", "error_description": "错误：“反政府们”，正确：“反政府分子”。“们”不能加在“反政府”后面表示人群；指从事反政府活动的人要用“分子”等名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次很反政府宣传让很多人感到不安。", "corrected_sentence": "这次反政府宣传让很多人感到不安。", "error_description": "错误：“很反政府宣传”，正确：“反政府宣传”。“反政府”作定语修饰名词时，前面不能加程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "反社会是做让大家受害的事，和大家对着干。", "primary_collocate": null, "pronunciation": "fǎn shè huì", "ipa": "fan˨˩˦ ʂɤ˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "他总是和大家对着干，大家都说他很反社会。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人做事很反社会，只想让别人受害。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意和大家作对，是反社会的人。", "target_word": "反社会", "complexity_tier": "T3", "furigana": "tā gùyì hé dàjiā zuòduì, shì fǎn shèhuì de rén.", "sentence_source": "generated"}, {"text": "他从小就很反社会，什么都要和别人对着干。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这种想法太反社会了。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她讨厌那种反社会的人，因为他们总伤害大家。", "target_word": "反社会", "complexity_tier": "T3", "furigana": "tā tǎoyàn nà zhǒng fǎn shèhuì de rén, yīnwèi tāmen zǒng shānghài dàjiā.", "sentence_source": "generated"}, {"text": "他做了很多让大家受害的事，真是反社会。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做太反社会了，大家都会生气。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反社会的做法，最后只会让大家受害。", "target_word": "反社会", "complexity_tier": "T3", "furigana": "fǎn shèhuì de zuòfǎ, zuìhòu zhǐ huì ràng dàjiā shòuhài.", "sentence_source": "generated"}, {"text": "他的想法很反社会，总想伤害别人。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反社会行为", "label": "复合"}, {"form": "反社会人格", "label": "复合"}], "register": "书面语", "sense_fingerprint": "做伤害大家的事、处处与大家作对（个人态度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反社会", "is_correct": true, "explanation": "正确：“反社会”指做损害大家的事、与大家对着干，与句中“和大家对着干”的描述一致。"}, {"text": "合群", "is_correct": false, "explanation": "语义：“合群”指愿意与大家相处，与“和大家对着干”相反。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”说性情平和，与“和大家对着干”的描述矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”描述身材，不能用来评价性格。"}], "explanations": {"反社会": "正确：“反社会”指做损害大家的事、与大家对着干，与句中“和大家对着干”的描述一致。", "合群": "语义：“合群”指愿意与大家相处，与“和大家对着干”相反。", "温和": "语义：“温和”说性情平和，与“和大家对着干”的描述矛盾。", "高": "体貌：“高”描述身材，不能用来评价性格。"}, "sentence_index": 0, "correct_answer": "反社会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很反社会，一紧张就说不出话，连陌生人都不敢见。", "explanation": "这里应该用〈胆怯〉。反社会指做让大家受害的事、与大家对着干，不指怕生或紧张。"}, {"text": "他性格很反社会，很少和同学说话。", "explanation": "这里应该用〈孤僻〉。反社会指危害大家、与大家对抗，不指不爱与人交往。"}, {"text": "这孩子很反社会，每次考试都能拿第一名。", "explanation": "这里应该用〈优秀〉。反社会是负面评价，与学习成绩无关，也不指与大家对着干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反社会", "is_correct": true, "explanation": "正确：句中“让大家受害的事”正是“反社会”的意思。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”指心地好，与“让大家受害的事”相反。"}, {"text": "热心", "is_correct": false, "explanation": "语义：“热心”指乐于帮助别人，与“让大家受害的事”矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外貌，不能用来评价做事的结果。"}], "explanations": {"反社会": "正确：句中“让大家受害的事”正是“反社会”的意思。", "善良": "语义：“善良”指心地好，与“让大家受害的事”相反。", "热心": "语义：“热心”指乐于帮助别人，与“让大家受害的事”矛盾。", "漂亮": "体貌：“漂亮”说外貌，不能用来评价做事的结果。"}, "sentence_index": 6, "correct_answer": "反社会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很反社会，认准的事谁也劝不动。", "explanation": "这里应该用〈固执〉。反社会指危害大家，不指认死理、不肯改变。"}, {"text": "他对朋友很反社会，从不帮忙。", "explanation": "这里应该用〈冷漠〉。反社会指危害社会、与大家对立，不指对朋友不热心。"}, {"text": "他遇事很反社会，从不敢说话。", "explanation": "这里应该用〈懦弱〉。反社会指主动危害大家，不指胆小、不敢表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个反社会地人让大家很头疼。", "corrected_sentence": "这个反社会的人让大家很头疼。", "error_description": "结构助词错误：修饰名词“人”要用“的”，不能用“地”（“地”用于修饰动词）。正确形式是“反社会的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他变得很反社会过，常常伤害身边的人。", "corrected_sentence": "他变得很反社会了，常常伤害身边的人。", "error_description": "体标错误：表示状态变化要用“了”，“过”表示经历，不能用于此处。正确形式是“变得很反社会了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
