INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96160, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96160, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "与社会规范对立，危害社会的。", "primary_collocate": null, "pronunciation": "fǎn shè huì", "ipa": "fan˨˩˦ ʂɤ˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "打人、偷东西都是反社会的行为。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何反社会的做法。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人认为他的作品内容反社会，不能出版。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他有反社会的性格。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织做了很多反社会的事。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，反社会的行为越来越多了。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要教孩子不要有反社会的想法。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "破坏公共设施是一种反社会的行为。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的内容太反社会，不适合孩子看。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在调查这个反社会的团体。", "target_word": "反社会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反社会行为", "label": "复合"}, {"form": "反社会人格", "label": "复合"}], "register": "书面语", "sense_fingerprint": "违背社会规范、危害社会的（行为、内容、性格）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反社会", "is_correct": true, "explanation": "正确：打人、偷东西危害他人和社会，符合“反社会”的意思。"}, {"text": "正当", "is_correct": false, "explanation": "语义：“正当”指合理合法，与“打人、偷东西”矛盾。"}, {"text": "文明", "is_correct": false, "explanation": "语义：“文明”指有礼貌、守规矩，与“打人、偷东西”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述身材或外形，不能用来评价行为。"}], "explanations": {"反社会": "正确：打人、偷东西危害他人和社会，符合“反社会”的意思。", "正当": "语义：“正当”指合理合法，与“打人、偷东西”矛盾。", "文明": "语义：“文明”指有礼貌、守规矩，与“打人、偷东西”矛盾。", "高大": "体貌：“高大”描述身材或外形，不能用来评价行为。"}, "sentence_index": 0, "correct_answer": "反社会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个人很好胜，做什么都要拿第一，大家都说他很反社会。", "explanation": "这里应该用〈好胜〉。反社会指违背社会规范、危害社会，不指争强好胜。"}, {"text": "他一个人住，很反社会，没有朋友。", "explanation": "这里应该用〈孤独〉。反社会指危害社会、违背社会规范，不指一个人生活、没有朋友。"}, {"text": "他对邻居很反社会，常常帮忙。", "explanation": "这里应该用〈友善〉。反社会与帮助他人相反，与“常常帮忙”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反社会", "is_correct": true, "explanation": "正确：“反社会”指危害社会的想法，正是学校要教育孩子避免的。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”是好的品质，与“不要有……的想法”的教育语境矛盾。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”是好的品质，学校不会要求孩子“不要有善良的想法”。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”描述身材，不能用来修饰“想法”。"}], "explanations": {"反社会": "正确：“反社会”指危害社会的想法，正是学校要教育孩子避免的。", "友好": "语义：“友好”是好的品质，与“不要有……的想法”的教育语境矛盾。", "善良": "语义：“善良”是好的品质，学校不会要求孩子“不要有善良的想法”。", "瘦弱": "体貌：“瘦弱”描述身材，不能用来修饰“想法”。"}, "sentence_index": 6, "correct_answer": "反社会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很反社会，常帮老人买菜。", "explanation": "这里应该用〈热心〉。反社会指危害社会，与帮助老人相反。"}, {"text": "他很反社会，从不请朋友吃饭。", "explanation": "这里应该用〈小气〉。反社会指危害社会，不指不请客。"}, {"text": "他很反社会，从不炫耀自己。", "explanation": "这里应该用〈谦虚〉。反社会指危害社会、违背社会规范，不指不爱炫耀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些人越来越反社会过，总和社会对着干。", "corrected_sentence": "这些人越来越反社会了，总和社会对着干。", "error_description": "体标错误：表示状态变化要用“了”，“过”表示经历，不能用于此处。正确形式是“越来越反社会了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个反社会地组织经常欺负周围的人。", "corrected_sentence": "这个反社会的组织经常欺负周围的人。", "error_description": "结构助词错误：修饰名词要用“的”，不能用“地”（“地”用于修饰动词）。正确形式是“反社会的组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
