INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "受欢迎是大家都喜欢你，愿意和你在一起。", "primary_collocate": null, "pronunciation": "shòu huān yíng", "ipa": "ʂou̯˥˩ xwan˥ iŋ˧˥", "syllable_count": 3, "sentences": [{"text": "他很会说话，所以很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李爱笑，在班上很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对人友好，在公司很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想受欢迎，就要多帮助别人。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁在你们班最受欢迎？", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱说谎的人不受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会讲笑话，每次聚会都很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的老师很受欢迎，每天都有学生来问问题。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟很受欢迎，朋友很多。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人太自私，就不会受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不受欢迎", "label": "否定"}, {"form": "最受欢迎", "label": "最高级"}], "register": "中性", "sense_fingerprint": "受欢迎：人被大家喜欢，愿意相处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0852457c-e1ba-4d09-aa2e-60b101208aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受欢迎", "is_correct": true, "explanation": "符合语境：前半句“很会说话”说明他受人喜欢，「很受欢迎」顺接。"}, {"text": "木讷", "is_correct": false, "explanation": "语义：“木讷”形容人不善言辞，与“很会说话”矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，与“会说话”没有关系，句子不通。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不能用来形容人。"}], "explanations": {"受欢迎": "符合语境：前半句“很会说话”说明他受人喜欢，「很受欢迎」顺接。", "木讷": "语义：“木讷”形容人不善言辞，与“很会说话”矛盾。", "矮小": "体貌：“矮小”形容身材，与“会说话”没有关系，句子不通。", "陡峭": "搭配：“陡峭”形容地势，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "受欢迎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的呼吸很受欢迎。", "explanation": "这里应该用〈平稳〉。受欢迎说的是人被大家喜欢，不用来形容呼吸的状态。"}, {"text": "他的牙齿很受欢迎。", "explanation": "这里应该用〈整齐〉。受欢迎说的是人被大家喜欢，不用来形容牙齿的样子。"}, {"text": "他的眼睛很受欢迎。", "explanation": "这里应该用〈明亮〉。受欢迎说的是人被大家喜欢，不用来形容眼睛的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
