INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96163, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "另见是告诉你去别的地方看相关的内容。", "primary_collocate": null, "pronunciation": "lìng jiàn", "ipa": "liŋ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "关于这个问题，另见第十页。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的用法另见下一课。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格表另见本书最后一页。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想知道更多，另见附录。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上写着：“语法另见第三课”。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图另见书后的附页。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的详细情况另见报告。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上写着：价格另见门口的牌子。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注意事项另见下页。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "答案另见课本最后一页。", "target_word": "另见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "另见：提示读者去别处查看相关内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0852457c-e1ba-4d09-aa2e-60b101208aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另见", "is_correct": true, "explanation": "符合语境：这里是书面注释，提示读者去第十页查看相关内容。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把语言转换成另一种语言，不能用来指向页码。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”表示去掉，与“提示查看”的意思相反。"}, {"text": "另有", "is_correct": false, "explanation": "搭配：“另有”后面接的是另外的事物，不能直接接“第十页”。"}], "explanations": {"另见": "符合语境：这里是书面注释，提示读者去第十页查看相关内容。", "翻译": "语义：“翻译”是把语言转换成另一种语言，不能用来指向页码。", "删除": "语义：“删除”表示去掉，与“提示查看”的意思相反。", "另有": "搭配：“另有”后面接的是另外的事物，不能直接接“第十页”。"}, "sentence_index": 0, "correct_answer": "另见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在车站另见了一位老同学。", "explanation": "这里应该用〈见面〉。另见是书面注释用语，表示提示读者查看别处，不表示与人见面。"}, {"text": "周末我去医院另见奶奶。", "explanation": "这里应该用〈看望〉。另见用于提示查阅内容，不能用于探望亲人。"}, {"text": "我们明天另见。", "explanation": "这里应该用〈明天见〉。另见只用于书面注释，不用作道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另见", "is_correct": true, "explanation": "符合语境：「另见报告」是书面注释格式，提示读者去报告中查看详情。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹调动作，不能用于情况与报告之间的关系。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，与“去报告中查看详情”的意思不相容。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”需要接具体的物体，不能用来接“报告”。"}], "explanations": {"另见": "符合语境：「另见报告」是书面注释格式，提示读者去报告中查看详情。", "煮": "语义：“煮”是烹调动作，不能用于情况与报告之间的关系。", "结束": "语义：“结束”表示终止，与“去报告中查看详情”的意思不相容。", "擦": "搭配：“擦”需要接具体的物体，不能用来接“报告”。"}, "sentence_index": 6, "correct_answer": "另见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师另见了我们的作业。", "explanation": "这里应该用〈批改〉。另见是提示读者去别处查看，不表示批改作业。"}, {"text": "他在会上另见了一份方案。", "explanation": "这里应该用〈提出〉。另见只用于注释，不能表示在会上提出方案。"}, {"text": "她另见了我写的文章。", "explanation": "这里应该用〈修改〉。另见是书面注释用语，不能用于修改文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
