INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面向国际、跨国传播信息的新闻机构或渠道。", "primary_collocate": null, "pronunciation": "guó jì méi tǐ", "ipa": "kwo˧˥ tɕi˥˩ mei˧˥ tʰi˨˩˦", "syllable_count": 4, "sentences": [{"text": "这家公司想办一个国际媒体。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一家国际媒体工作。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家国际媒体有很多国家的记者。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做国际媒体的记者。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际媒体用十种语言发布消息。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国际媒体的网站每天更新。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际媒体需要懂外语的编辑。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的梦想是进入一家国际媒体。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家国际媒体在三十个城市有办公室。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际媒体是向很多国家传播消息的渠道。", "target_word": "国际媒体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "国际媒体：面向多国传播信息的新闻机构或渠道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valid