INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际媒体", "is_correct": true, "explanation": "正确：国际媒体是新闻机构或渠道，可以被「办」，符合语境。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人，不能被办成新闻机构。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不能被办成机构。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：「办午饭」不是常见搭配，「办」不用于一顿饭。"}], "explanations": {"国际媒体": "正确：国际媒体是新闻机构或渠道，可以被「办」，符合语境。", "朋友": "语义：朋友是人，不能被办成新闻机构。", "钢笔": "语义：钢笔是书写工具，不能被办成机构。", "午饭": "搭配：「办午饭」不是常见搭配，「办」不用于一顿饭。"}, "sentence_index": 0, "correct_answer": "国际媒体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国际媒体的脚很大，穿四十码的鞋。", "explanation": "这里把〈国际媒体〉当作有脚的人。它是新闻机构或渠道，没有脚，也不会穿鞋。"}, {"text": "他的国际媒体生病了，去了医院。", "explanation": "这里把〈国际媒体〉当作会生病的人。它是新闻机构或渠道，不会生病，也不能去医院。"}, {"text": "我把国际媒体放进了冰箱。", "explanation": "〈国际媒体〉是新闻机构或渠道，不是可以拿来放进冰箱的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际媒体", "is_correct": true, "explanation": "正确：国际媒体需要懂外语的编辑，符合语境。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不需要懂外语的编辑。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是需要编辑的机构。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不需要编辑。"}], "explanations": {"国际媒体": "正确：国际媒体需要懂外语的编辑，符合语境。", "早餐": "语义：早餐是一顿饭，不需要懂外语的编辑。", "冰箱": "语义：冰箱是家电，不是需要编辑的机构。", "花园": "语义：花园是场所，不需要编辑。"}, "sentence_index": 6, "correct_answer": "国际媒体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国际媒体每天都去上学。", "explanation": "〈国际媒体〉是机构或渠道，不能去上学，这是拟人误用。"}, {"text": "国际媒体是一场刚刚结束的比赛。", "explanation": "这里应该用〈新闻机构〉。国际媒体指面向国际传播信息的机构或渠道，不是体育赛事。"}, {"text": "我们在国际媒体里种了一棵树。", "explanation": "〈国际媒体〉不是地点，不能说在它里面种树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一只国际媒体担任编辑。", "corrected_sentence": "她在一家国际媒体担任编辑。", "error_description": "量词错误：新闻机构应用量词「家」，不能用「只」，应说「一家国际媒体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她刚进着一家国际媒体。", "corrected_sentence": "她刚进了一家国际媒体。", "error_description": "体貌错误：表示已经进入的动作要用「了」，「进着」表示动作持续的状态，与「刚」的完成义相矛盾，应说「她刚进了一家国际媒体」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
