INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96167, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "围是站在四周，把中间的东西包起来。", "primary_collocate": null, "pronunciation": "wéi", "ipa": "weɪ˧˥", "syllable_count": 1, "sentences": [{"text": "孩子们围着老师听故事。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围着桌子坐下，开始吃饭。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人围在门口看热闹。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，我们围着火炉取暖。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们围过来问他问题。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者们把那位歌手围住了。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日时，朋友们围着他唱歌。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一回家，孩子们都围上去了。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边围了一群人，不知道出了什么事。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，一家人围着电视看比赛。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "围着", "label": "体标"}, {"form": "围了", "label": "体标"}, {"form": "围过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或动物聚在某人某物四周，把中间的人或东西围起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96167, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "围", "is_correct": true, "explanation": "围：wéi（第二声），表示站在四周把中间的人或东西包起来。"}, {"text": "位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是位置。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。"}, {"text": "味", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是味道。"}, {"text": "伟", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是伟大。"}], "explanations": {"围": "围：wéi（第二声），表示站在四周把中间的人或东西包起来。", "位": "wèi（第四声）与 wéi（第二声）声调不同，意思是位置。", "尾": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。", "味": "wèi（第四声）与 wéi（第二声）声调不同，意思是味道。", "伟": "wěi（第三声）与 wéi（第二声）声调不同，意思是伟大。"}, "sentence_index": null, "correct_answer": "围"}, "level_3": {"options": [{"text": "围", "is_correct": true, "explanation": "围：孩子们站在老师四周聚拢听故事，与句意相符。"}, {"text": "捆", "is_correct": false, "explanation": "语义：“捆”指用绳子束缚，与听故事的场景不合。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：“盖”的对象是覆盖物，不能用于老师。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”的宾语是穿戴物，不能用于人。"}], "explanations": {"围": "围：孩子们站在老师四周聚拢听故事，与句意相符。", "捆": "语义：“捆”指用绳子束缚，与听故事的场景不合。", "盖": "搭配：“盖”的对象是覆盖物，不能用于老师。", "戴": "搭配：“戴”的宾语是穿戴物，不能用于人。"}, "sentence_index": 0, "correct_answer": "围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人围在门口，等朋友来。", "explanation": "这里应该用〈站〉。“围”指多人或物聚拢在四周，一个人独自待着时要用“站”。"}, {"text": "几个人围住了我的话，不让我说完。", "explanation": "这里应该用〈打断〉。“围”不能用于言语，打断别人说话要用“打断”。"}, {"text": "妈妈围着我的脚，帮我穿鞋。", "explanation": "这里应该用〈蹲〉。“围”指人或动物聚拢在某人或某物四周，弯腰靠近时要用“蹲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96167, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "围", "is_correct": true, "explanation": "围：wéi（第二声），表示站在四周把中间的人或东西包起来。"}, {"text": "未", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。"}, {"text": "胃", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是胃脏。"}, {"text": "慰", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是安慰。"}, {"text": "委", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是委员。"}], "explanations": {"围": "围：wéi（第二声），表示站在四周把中间的人或东西包起来。", "未": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。", "胃": "wèi（第四声）与 wéi（第二声）声调不同，意思是胃脏。", "慰": "wèi（第四声）与 wéi（第二声）声调不同，意思是安慰。", "委": "wěi（第三声）与 wéi（第二声）声调不同，意思是委员。"}, "sentence_index": null, "correct_answer": "围"}, "level_3": {"options": [{"text": "围", "is_correct": true, "explanation": "围：大家聚拢在他四周唱歌，与过生日的场景相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能用于人。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”指收拢、收起，与唱歌不合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的宾语是果实或植物，不能用于人。"}], "explanations": {"围": "围：大家聚拢在他四周唱歌，与过生日的场景相符。", "穿": "搭配：“穿”的宾语是衣物，不能用于人。", "收": "语义：“收”指收拢、收起，与唱歌不合。", "摘": "搭配：“摘”的宾语是果实或植物，不能用于人。"}, "sentence_index": 6, "correct_answer": "围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一群孩子围进了教室，把座位都占满了。", "explanation": "这里应该用〈挤〉。“围”指聚拢在四周，不指进入或挤入；表示挤进去要用“挤”。"}, {"text": "小偷一个人围在门口，等主人出门。", "explanation": "这里应该用〈躲〉。“围”指多人或物聚拢在四周，一个人藏在门口等待要用“躲”。"}, {"text": "一面墙围住了风。", "explanation": "这里应该用〈挡〉。“围”指环绕、聚拢，不能用来表示阻挡风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED