INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "四周包住；环绕。", "primary_collocate": null, "pronunciation": "wéi", "ipa": "weɪ˧˥", "syllable_count": 1, "sentences": [{"text": "河水围着小岛流。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高高的山围着这个小村子。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子外面围着一圈白色的篱笆。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一堵矮墙围着那座老房子。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花园外面围了一道篱笆。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地四周都围着铁板。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一圈红色跑道围着学校的足球场。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想把这块空地围起来。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树下面围着一圈石头。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树林围着一个安静的小湖。", "target_word": "围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "围着", "label": "体标"}, {"form": "围了", "label": "体标"}, {"form": "围过", "label": "体标"}], "register": "中性", "sense_fingerprint": "物体、地形或设施在某处四周环绕、包住中间的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96168, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "围", "is_correct": true, "explanation": "围：wéi（第二声），表示物体在四周环绕、包住中间的地方。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。"}, {"text": "伟", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是伟大。"}, {"text": "慰", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是安慰。"}], "explanations": {"围": "围：wéi（第二声），表示物体在四周环绕、包住中间的地方。", "尾": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。", "伟": "wěi（第三声）与 wéi（第二声）声调不同，意思是伟大。", "慰": "wèi（第四声）与 wéi（第二声）声调不同，意思是安慰。"}, "sentence_index": null, "correct_answer": "围"}, "level_3": {"options": [{"text": "围", "is_correct": true, "explanation": "围：河水环绕着小岛流，与句意相符。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”指用肩膀承担，河水不能扛东西。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”要求持物者作主语，“河水拿着小岛”不成立。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象是可移动的物件，不能搬小岛。"}], "explanations": {"围": "围：河水环绕着小岛流，与句意相符。", "扛": "语义：“扛”指用肩膀承担，河水不能扛东西。", "拿": "配价：“拿”要求持物者作主语，“河水拿着小岛”不成立。", "搬": "搭配：“搬”的对象是可移动的物件，不能搬小岛。"}, "sentence_index": 0, "correct_answer": "围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他围了一杯茶，慢慢地喝。", "explanation": "这里应该用〈泡〉。“围”指环绕、包住某处，不能表示做茶；泡茶要用“泡”。"}, {"text": "他围了一封信，把它寄了出去。", "explanation": "这里应该用〈写〉。“围”指环绕、包住，不能用来表示写信；写信要用“写”。"}, {"text": "她围了一首歌给大家听。", "explanation": "这里应该用〈唱〉。“围”指环绕、包住某处，不能用于歌曲；唱歌要用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96168, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "围", "is_correct": true, "explanation": "围：wéi（第二声），表示物体在四周环绕、包住中间的地方。"}, {"text": "味", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是味道。"}, {"text": "未", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。"}, {"text": "胃", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是胃脏。"}], "explanations": {"围": "围：wéi（第二声），表示物体在四周环绕、包住中间的地方。", "味": "wèi（第四声）与 wéi（第二声）声调不同，意思是味道。", "未": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。", "胃": "wèi（第四声）与 wéi（第二声）声调不同，意思是胃脏。"}, "sentence_index": null, "correct_answer": "围"}, "level_3": {"options": [{"text": "围", "is_correct": true, "explanation": "围：红色跑道环绕着足球场，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”需要有生命的主体，跑道不能唱歌。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求能吃的主体和可食用的宾语，跑道不能吃足球场。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”需要有人做动作，跑道不能洗足球场。"}], "explanations": {"围": "围：红色跑道环绕着足球场，与句意相符。", "唱": "语义：“唱”需要有生命的主体，跑道不能唱歌。", "吃": "配价：“吃”要求能吃的主体和可食用的宾语，跑道不能吃足球场。", "洗": "语义：“洗”需要有人做动作，跑道不能洗足球场。"}, "sentence_index": 6, "correct_answer": "围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一堵墙围过来，把学生们关在外面。", "explanation": "这里应该用〈拦〉。“围”指环绕、包住，不能用来表示墙阻拦人。"}, {"text": "妈妈在丝巾上围了一个结。", "explanation": "这里应该用〈系〉。“围”指环绕、包住，打结要用“系”。"}, {"text": "游客围了一瓶水，把它装进了包里。", "explanation": "这里应该用〈买〉。“围”指环绕、包住，不能表示购买；买东西要用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想把这块空地围，种点花。", "corrected_sentence": "他们想把这块空地围起来，种点花。", "error_description": "错误：“把…围”后缺少补语“起来”。“把”字句中动词“围”后要带结果补语，应说“把这块空地围起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块草地四周围一圈栅栏。", "corrected_sentence": "这块草地四周围着一圈栅栏。", "error_description": "错误：“围一圈栅栏”少了“着”。表示状态时“围”后要带“着”，应说“围着一圈栅栏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
