INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所达到的程度或层次；人的思想修养水平。", "primary_collocate": null, "pronunciation": "jìng jiè", "ipa": "tɕiŋ˥˩ tɕje˥˩", "syllable_count": 2, "sentences": [{"text": "这首诗的境界很高。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的思想修养达到了很高的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的境界很深，让人想了很久。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书能让人的境界更高。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜做到了艺术的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生的境界不同，看事情的方法也不同。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章写出了一种安静的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做到无私，是一种很高的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的境界高，从不和人吵架。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把音乐演奏到了完美的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种境界", "label": "量词"}, {"form": "一个境界", "label": "量词"}], "register": "书面", "sense_fingerprint": "事物的层次或人的思想修养水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0852457c-e1ba-4d09-aa2e-60b101208aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96170, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "境界", "is_correct": true, "explanation": "正确：听到的是“境界”（jìngjiè），指事物的层次或人的思想修养水平。"}, {"text": "竞价", "is_correct": false, "explanation": "第二音节 jià 与 jiè 韵母不同，“竞价”意思是竞争出价。"}, {"text": "定界", "is_correct": false, "explanation": "dìng 与 jìng 声母不同（d 与 j），“定界”意思是划定边界。"}, {"text": "警戒", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，“警戒”意思是戒备、警惕。"}, {"text": "竞技", "is_correct": false, "explanation": "第二音节 jì 与 jiè 的区别在韵母（少了 e 音），“竞技”意思是体育比赛。"}], "explanations": {"境界": "正确：听到的是“境界”（jìngjiè），指事物的层次或人的思想修养水平。", "竞价": "第二音节 jià 与 jiè 韵母不同，“竞价”意思是竞争出价。", "定界": "dìng 与 jìng 声母不同（d 与 j），“定界”意思是划定边界。", "警戒": "jǐng（第三声）与 jìng（第四声）声调不同，“警戒”意思是戒备、警惕。", "竞技": "第二音节 jì 与 jiè 的区别在韵母（少了 e 音），“竞技”意思是体育比赛。"}, "sentence_index": null, "correct_answer": "境界"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：诗没有颜色的高低，“这首诗的颜色很高”说不通。"}, {"text": "境界", "is_correct": true, "explanation": "正确：“这首诗的境界很高”指诗的层次高，与句中“这首诗”相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，不能用于“诗”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：诗不会有工资，“这首诗的工资”说不通。"}], "explanations": {"颜色": "语义：诗没有颜色的高低，“这首诗的颜色很高”说不通。", "境界": "正确：“这首诗的境界很高”指诗的层次高，与句中“这首诗”相合。", "体重": "语义：“体重”指人或动物的重量，不能用于“诗”。", "工资": "语义：诗不会有工资，“这首诗的工资”说不通。"}, "sentence_index": 0, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家的境界不错，不用为钱发愁。", "explanation": "这里应该用〈境况〉。“境界”指事物的层次或修养水平，家庭的经济状况要用〈境况〉。"}, {"text": "这次旅行的境界很便宜。", "explanation": "这里应该用〈价钱〉。“境界”指层次或修养水平，不能表示价钱的高低。"}, {"text": "这间房子的境界很大。", "explanation": "这里应该用〈面积〉。“境界”指事物的层次或修养水平，房屋的大小要用〈面积〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体的大小，不能用于形容“安静”的文章。"}, {"text": "境界", "is_correct": true, "explanation": "正确：“一种安静的境界”指文章达到的意境层次，与“写出了”相合。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“安静”不能修饰“重量”，“安静的重量”说不通。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”是长短的度量，与“安静”的描述不合。"}], "explanations": {"体积": "语义：“体积”指物体的大小，不能用于形容“安静”的文章。", "境界": "正确：“一种安静的境界”指文章达到的意境层次，与“写出了”相合。", "重量": "搭配：“安静”不能修饰“重量”，“安静的重量”说不通。", "长度": "语义：“长度”是长短的度量，与“安静”的描述不合。"}, "sentence_index": 6, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项研究的境界很贵，花了三年。", "explanation": "这里应该用〈费用〉。“境界”指层次或修养水平，不能表示花费，研究的花费要用〈费用〉。"}, {"text": "这场比赛的境界很热闹。", "explanation": "这里应该用〈场面〉。“境界”不指热闹的场景，比赛的场面要用〈场面〉。"}, {"text": "这部电影的境界很长，我看了三个小时。", "explanation": "这里应该用〈时长〉。“境界”指事物的层次或修养水平，电影的长短要用〈时长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇散文写出了一张很高的境界，读后让人感动。", "corrected_sentence": "这篇散文写出了一种很高的境界，读后让人感动。", "error_description": "量词错误：“境界”应搭配“种”或“个”，“张”用于纸、桌子等平面的东西，不能修饰“境界”。正确为“一种很高的境界”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人有一棵很高的境界。", "corrected_sentence": "这位老人有一种很高的境界。", "error_description": "量词错误：“境界”不能用“棵”计量，应说“一种很高的境界”。“棵”用于树木等植物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
