INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "领土广大、人口众多或实力强大的国家。", "primary_collocate": null, "pronunciation": "dà guó", "ipa": "ta˥˩ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "大国在世界上有很大的影响。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个大国的领导人今天在北京见面了。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大国应该帮助小国，而不是欺负它们。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大国的经济和军事都很强，其他国家很重视它。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究大国关系的专家。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在联合国里，大国和小国都有自己的位置。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为大国，这个国家要对世界负责。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国常常要看大国的脸色做事。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大国的一个决定，可能会影响很多小国。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家土地大，人口多，是一个真正的大国。", "target_word": "大国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大国关系", "label": "复合"}, {"form": "大國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "领土广大、人口众多或实力强大的国家，多用于国际关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大国", "is_correct": true, "explanation": "大国指国际上有很大影响力的国家，符合“在世界上有很大的影响”的语境。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是能在世界上施加影响的主体。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天是时间，不能在世界上有影响。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不与“在世界上有很大的影响”搭配。"}], "explanations": {"大国": "大国指国际上有很大影响力的国家，符合“在世界上有很大的影响”的语境。", "花园": "语义：花园不是能在世界上施加影响的主体。", "白天": "语义：白天是时间，不能在世界上有影响。", "体重": "搭配：“体重”不与“在世界上有很大的影响”搭配。"}, "sentence_index": 0, "correct_answer": "大国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家跨国集团是一个大国，经济实力很强，其他国家很重视它。", "explanation": "这里应该用〈大企业〉。“大国”指国家，跨国集团不是国家，不能用“大国”。"}, {"text": "这个大国的人口只有几十个，土地也很小，其他国家都不重视它。", "explanation": "这里应该用〈小国〉。“大国”要求领土广大、人口众多或实力强大，人口少、土地小、又没有实力的应说“小国”。"}, {"text": "深圳是中国经济最强的大国。", "explanation": "这里应该用〈大城市〉。深圳是城市，不是国家；“大国”指国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大国", "is_correct": true, "explanation": "大国指国际上有影响力的国家，符合“作为大国，要对世界负责”的语境。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”与后面的“这个国家”指代不一致，不能说“作为公司，这个国家要对世界负责”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是个人身份，不能和“这个国家要对世界负责”搭配。"}, {"text": "员工", "is_correct": false, "explanation": "搭配：“员工”是单位里的身份，与“对世界负责”这种国家层面的责任搭配不当。"}], "explanations": {"大国": "大国指国际上有影响力的国家，符合“作为大国，要对世界负责”的语境。", "公司": "语义：“公司”与后面的“这个国家”指代不一致，不能说“作为公司，这个国家要对世界负责”。", "学生": "语义：“学生”是个人身份，不能和“这个国家要对世界负责”搭配。", "员工": "搭配：“员工”是单位里的身份，与“对世界负责”这种国家层面的责任搭配不当。"}, "sentence_index": 6, "correct_answer": "大国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "亚洲是一个土地很大的大国，人口也很多。", "explanation": "这里应该用〈大洲〉。亚洲是洲，不是国家。"}, {"text": "四川是一个土地很大的大国，人口也很多。", "explanation": "这里应该用〈省份〉。四川是省份，不是国家。"}, {"text": "这个村子土地大，人口多，是一个真正的大国。", "explanation": "这里应该用〈地区〉或〈城镇〉。“大国”只指国家，不能用来形容一个村子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大国地态度会影响这次会谈。", "corrected_sentence": "大国的态度会影响这次会谈。", "error_description": "错误：修饰“态度”时“大国”后用了“地”。正确：修饰名词要用“的”，应写“大国的态度”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的国家是一只大国，要对世界负责。", "corrected_sentence": "他们的国家是一个大国，要对世界负责。", "error_description": "错误：“大国”前用了量词“只”。正确：国家用量词“个”，应说“一个大国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
