INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96173, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大变是变化很大，和以前完全不一样。", "primary_collocate": null, "pronunciation": "dà biàn", "ipa": "ta˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "几年后，这座城市发生了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出国以后，生活经历了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的天气出现了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，家乡有了大变。", "target_word": "大变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次大变让大家都很吃惊。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨以后，河水发生了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家后，孩子的生活有了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大变，我们要保持冷静。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司去年遇到了大变，很多人走了。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次大变以后，他不再喝酒了。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "变得和以前完全不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大变", "is_correct": true, "explanation": "正确。“发生大变”指事物发生了巨大的变化，与“几年后，这座城市”相合。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不是事件或变化，不能说“发生了水果”，语境完全不合。"}, {"text": "大步", "is_correct": false, "explanation": "搭配：“发生”不与“大步”（迈步的幅度）搭配，这里说不通。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指人，不能说“这座城市发生了学生”，语义不通。"}], "explanations": {"大变": "正确。“发生大变”指事物发生了巨大的变化，与“几年后，这座城市”相合。", "水果": "语义：“水果”不是事件或变化，不能说“发生了水果”，语境完全不合。", "大步": "搭配：“发生”不与“大步”（迈步的幅度）搭配，这里说不通。", "学生": "语义：“学生”指人，不能说“这座城市发生了学生”，语义不通。"}, "sentence_index": 0, "correct_answer": "大变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近年来，家乡只发生了一点大变，几乎没什么不同。", "explanation": "这里应该用〈小变化〉。“大变”表示变化很大、完全不一样，和“几乎没什么不同”自相矛盾。"}, {"text": "这个班的成绩有了大变，只提高了一分。", "explanation": "这里应该用〈小幅提高〉。“大变”指变化很大，不能用来形容只提高一分。"}, {"text": "我们在公司门口买了一场大变。", "explanation": "这里应该用〈东西〉。“大变”指变化，不能作“买”的宾语，应说买“东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大变", "is_correct": true, "explanation": "正确。“搬家后，孩子的生活有了大变”，指生活发生了很大的变化。"}, {"text": "大雨", "is_correct": false, "explanation": "语义：“大雨”是天气现象，不能说“生活有了大雨”，语义不通。"}, {"text": "大米", "is_correct": false, "explanation": "语义：“大米”是食物，不能说“孩子的生活有了大米”，语境不合。"}, {"text": "大地", "is_correct": false, "explanation": "搭配：“生活”不能与“大地”搭配，“生活有了大地”说不通。"}], "explanations": {"大变": "正确。“搬家后，孩子的生活有了大变”，指生活发生了很大的变化。", "大雨": "语义：“大雨”是天气现象，不能说“生活有了大雨”，语义不通。", "大米": "语义：“大米”是食物，不能说“孩子的生活有了大米”，语境不合。", "大地": "搭配：“生活”不能与“大地”搭配，“生活有了大地”说不通。"}, "sentence_index": 6, "correct_answer": "大变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨晚刮起了大变，吹倒了不少树。", "explanation": "这里应该用〈大风〉。刮起的是风，“大变”指变化很大，不能用来说风。"}, {"text": "他去年得了一场大变，在医院住了两个月。", "explanation": "这里应该用〈大病〉。得病说“得了一场大病”，“大变”指变化很大，不能用来说病。"}, {"text": "明天我们要考一场大变，大家都很紧张。", "explanation": "这里应该用〈大考〉。要参加的重要考试说“大考”，“大变”不能指考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇在十年前经历了一座大变。", "corrected_sentence": "这个小镇在十年前经历了一次大变。", "error_description": "错误形式是“一座大变”，正确形式是“一次大变”。“座”用于山、楼房等大型固定物，不能用来数事件，表示一次变化应改用量词“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂经历了过一次大变。", "corrected_sentence": "这家工厂经历过一次大变。", "error_description": "错误形式是“经历了过”，正确形式是“经历过”。动态助词“了”和“过”不能同时用在同一个动词后面，表示曾经经历过只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
