INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "巨大的变化。", "primary_collocate": null, "pronunciation": "dà biàn", "ipa": "ta˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "社会正在经历大变。", "target_word": "大变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的政治发生了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大变来了，大家都要学新东西。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大变改变了他的一生。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这次大变中失去了工作。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从乡下到大城市，他的生活有了大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时代的大变让人们很不安。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一家人在大变中的故事。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，明年市场会有大变。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过那次大变，小镇不再安静了。", "target_word": "大变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "巨大的变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf99c4a1-fed7-4b69-aa16-1ad2464b8b20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大变", "is_correct": true, "explanation": "正确。“社会正在经历大变”，指社会正经历巨大的变化。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是具体物品，不能被“经历”，“社会正在经历桌子”不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”不是抽象的变化或事件，不能说“社会经历早饭”。"}, {"text": "大步", "is_correct": false, "explanation": "搭配：“经历”不与“大步”搭配，应说“经历大变”。"}], "explanations": {"大变": "正确。“社会正在经历大变”，指社会正经历巨大的变化。", "桌子": "语义：“桌子”是具体物品，不能被“经历”，“社会正在经历桌子”不通。", "早饭": "语义：“早饭”不是抽象的变化或事件，不能说“社会经历早饭”。", "大步": "搭配：“经历”不与“大步”搭配，应说“经历大变”。"}, "sentence_index": 0, "correct_answer": "大变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一场大变只改了一个字，几乎看不出来。", "explanation": "这里应该用〈小改动〉。“大变”指巨大的变化，不能用来形容只改一个字的小改动。"}, {"text": "这件小事只是一场大变，没有人在意。", "explanation": "这里应该用〈小变化〉。“大变”与“小事”自相矛盾，“大变”不能形容很小的事。"}, {"text": "我们在饭店里吃了一场大变。", "explanation": "这里应该用〈一顿饭〉。“大变”指变化，不能作“吃”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大变", "is_correct": true, "explanation": "正确。“时代的大变让人们很不安”，指时代发生了巨大的变化。"}, {"text": "大米", "is_correct": false, "explanation": "语义：“大米”是食物，不能作为“时代”的变化，句子不通。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是建筑，不能说“时代的大楼让人们很不安”，语义不合。"}, {"text": "大鞋", "is_correct": false, "explanation": "搭配：“时代”不能与“大鞋”搭配，句子说不通。"}], "explanations": {"大变": "正确。“时代的大变让人们很不安”，指时代发生了巨大的变化。", "大米": "语义：“大米”是食物，不能作为“时代”的变化，句子不通。", "大楼": "语义：“大楼”是建筑，不能说“时代的大楼让人们很不安”，语义不合。", "大鞋": "搭配：“时代”不能与“大鞋”搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "大变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨晚刮起了一场大变，吹倒了很多树。", "explanation": "这里应该用〈大风〉。刮起的是风，“大变”指巨大的变化，不能用来说风。"}, {"text": "他去年得了一场大变，在医院住了很久。", "explanation": "这里应该用〈大病〉。得病说“得了一场大病”，“大变”指巨大的变化，不能用来说病。"}, {"text": "下周我们要考一场大变，大家都很紧张。", "explanation": "这里应该用〈大考〉。要参加的重要考试说“大考”，“大变”不能指考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座大变让整个行业都变了样。", "corrected_sentence": "这场大变让整个行业都变了样。", "error_description": "错误形式是“这座大变”，正确形式是“这场大变”。“座”用于山、楼房等大型固定物，不能用来数事件，应改用量词“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个行业在那时曾经历了过一次大变。", "corrected_sentence": "这个行业在那时曾经历过一次大变。", "error_description": "错误形式是“经历了过”，正确形式是“经历过”。动态助词“了”和“过”不能同时用在同一个动词后面，表示曾经经历过只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdd46cc8-ec6e-4a89-a560-10cbb8f3b5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
