INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "室内是房子里面。", "primary_collocate": null, "pronunciation": "shì nèi", "ipa": "ʂɻ̩˥˩ nei̯˥˩", "syllable_count": 2, "sentences": [{"text": "今天下雨，我们在室内上课。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室内比室外热很多。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天室内有暖气，很舒服。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室内不能抽烟。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的室内很干净。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在室内玩游戏。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室内的温度是二十五度。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在室内穿拖鞋。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，比赛改在室内进行。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我们大多待在室内。", "target_word": "室内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "室内设计", "label": "复合"}, {"form": "室内游泳池", "label": "复合"}], "register": "中性", "sense_fingerprint": "室内：房子里面，与室外相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0852457c-e1ba-4d09-aa2e-60b101208aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "室内", "is_correct": true, "explanation": "正确。下雨天只能在房间里面上课，符合语境。"}, {"text": "水底", "is_correct": false, "explanation": "语义：下雨时不能在水底上课，与“今天下雨”的语境矛盾。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所不适合上课，与“上课”的场所不符。"}, {"text": "太空", "is_correct": false, "explanation": "语义：太空不适合上课，与“今天下雨”的日常语境矛盾。"}], "explanations": {"室内": "正确。下雨天只能在房间里面上课，符合语境。", "水底": "语义：下雨时不能在水底上课，与“今天下雨”的语境矛盾。", "厕所": "语义：厕所不适合上课，与“上课”的场所不符。", "太空": "语义：太空不适合上课，与“今天下雨”的日常语境矛盾。"}, "sentence_index": 0, "correct_answer": "室内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民们在室内种水稻。", "explanation": "这里应该用〈田里〉。水稻要种在田里，“室内”指房子里面。"}, {"text": "大船在室内航行。", "explanation": "这里应该用〈海上〉。船在水上航行，“室内”指房子里面。"}, {"text": "飞机在室内起飞了。", "explanation": "这里应该用〈跑道上〉。飞机从机场跑道起飞，“室内”指房子里面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "室内", "is_correct": true, "explanation": "正确。“室内的温度”指房间里面的温度，可以用“度”表示。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“二十五度”用于表示温度，“亮度”不用度数表示，二者不搭配。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳的温度远高于二十五度，不能说“太阳的温度是二十五度”。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块的温度一般在零度以下，与“二十五度”不符。"}], "explanations": {"室内": "正确。“室内的温度”指房间里面的温度，可以用“度”表示。", "亮度": "搭配：“二十五度”用于表示温度，“亮度”不用度数表示，二者不搭配。", "太阳": "语义：太阳的温度远高于二十五度，不能说“太阳的温度是二十五度”。", "冰块": "语义：冰块的温度一般在零度以下，与“二十五度”不符。"}, "sentence_index": 6, "correct_answer": "室内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民们在室内晒谷子。", "explanation": "这里应该用〈室外〉。晒谷子要在有阳光的户外，“室内”指房屋里面，没有阳光。"}, {"text": "月亮从室内升起来了。", "explanation": "这里应该用〈天空〉。月亮从天空升起，“室内”指房屋里面，不能作为月亮升起的地方。"}, {"text": "汽车在室内行驶。", "explanation": "这里应该用〈马路〉。汽车要在道路上行驶，“室内”指房屋里面，不能用来行驶汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们室内玩。", "corrected_sentence": "孩子们在室内玩。", "error_description": "错误在于漏掉介词“在”：“室内”作处所时，前面要加“在”。应说“孩子们在室内玩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请大家进入在室内。", "corrected_sentence": "请大家进入室内。", "error_description": "错误在于“在”放在动词“进入”之后：“进入”后直接接处所，不加“在”。应说“请大家进入室内”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2ad1601-a0b0-4ba0-b42e-cb359d3f8f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
