INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "密度是东西挤得有多紧。", "primary_collocate": null, "pronunciation": "mì dù", "ipa": "mi˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市人口很多，街上行人的密度很高。", "target_word": "密度", "complexity_tier": "T3", "furigana": "zhè gè chéng shì rén kǒu hěn duō, jiē shàng xíng rén de mì dù hěn gāo.", "sentence_source": "generated"}, {"text": "这片森林里树木的密度很大，阳光照不进来。", "target_word": "密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上车的密度太大了，车都走不动。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小区楼房的密度太高，住得不舒服。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁里人的密度太高了，我挤不上去。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种菜的时候，菜苗的密度不要太大。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市中心商店的密度比郊区大得多。", "target_word": "密度", "complexity_tier": "T3", "furigana": "chéng shì zhōng xīn shāng diàn de mì dù bǐ jiāo qū dà de duō.", "sentence_source": "generated"}, {"text": "这里的路灯密度很高，晚上一点也不黑。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上书的密度太大，再也放不下了。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校附近的饭馆密度很高，吃饭很方便。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口密度", "label": "复合"}, {"form": "高密度", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常义：人或东西挤在一起有多紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "正确：“密度”指行人分布的稀密，与“很高”搭配，说明街上人很多、很挤。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说深浅，不说“高”，“街上行人的颜色很高”不成立。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热，与街上行人的疏密无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是货物的钱数，不能用来形容行人。"}], "explanations": {"密度": "正确：“密度”指行人分布的稀密，与“很高”搭配，说明街上人很多、很挤。", "颜色": "搭配：“颜色”说深浅，不说“高”，“街上行人的颜色很高”不成立。", "温度": "语义：“温度”指冷热，与街上行人的疏密无关。", "价格": "语义：“价格”是货物的钱数，不能用来形容行人。"}, "sentence_index": 0, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区的密度很多，住得不舒服。", "explanation": "这里应该用〈人口〉。密度说“高”“大”，说人或东西数量多要用人口或人数。"}, {"text": "这个小区楼房之间的密度很近，住得不舒服。", "explanation": "这里应该用〈距离〉。密度说稀密，说远近要用距离，“密度很近”搭配不当。"}, {"text": "这个小区的密度太多了，楼道里挤得走不动。", "explanation": "这里应该用〈人数〉。密度是东西挤得有多紧，说人的多少要用人数，不能说“太多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "正确：“密度”比较的是稀密程度，“比郊区大得多”说的正是城市中心商店更密集。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说深浅，不能用“大得多”来比较。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：商店没有脾气，“脾气”不能拿来比较。"}, {"text": "性格", "is_correct": false, "explanation": "语义：商店没有性格，“性格”不适用于场所。"}], "explanations": {"密度": "正确：“密度”比较的是稀密程度，“比郊区大得多”说的正是城市中心商店更密集。", "颜色": "搭配：“颜色”说深浅，不能用“大得多”来比较。", "脾气": "语义：商店没有脾气，“脾气”不能拿来比较。", "性格": "语义：商店没有性格，“性格”不适用于场所。"}, "sentence_index": 6, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校附近的饭馆密度很贵，我们经常去吃。", "explanation": "这里应该用〈价格〉。密度说稀密，不说贵贱。"}, {"text": "学校附近的饭馆密度很好，我们经常去吃。", "explanation": "这里应该用〈质量〉。密度描述稀密程度，不用“好”来评价。"}, {"text": "学校附近的饭馆密度很广，我们经常去吃。", "explanation": "这里应该用〈分布〉。密度是稀密程度，说范围大小要用分布，不说“广”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个商场里顾客的密度很多，走路都困难。", "corrected_sentence": "这个商场里顾客的密度很大，走路都困难。", "error_description": "错误：“很多”。正确：“很大”。密度说大小高低，“多”说数量，不能用来形容密度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市中心的商店密度跟郊区高很多。", "corrected_sentence": "这个城市中心的商店密度比郊区高很多。", "error_description": "错误：“跟”。正确：“比”。比较密度的高低要用“比”，“跟”用于共同的动作或对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
