INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "单位体积物质的质量。", "primary_collocate": null, "pronunciation": "mì dù", "ipa": "mi˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "水的密度比油大，所以油浮在水上。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁的密度很大，所以铁块特别重。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰的密度比水小，所以冰能浮在水上。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们测一下这块石头的密度。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "密度等于质量除以体积。", "target_word": "密度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "金属的密度一般比木头大。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热空气的密度比冷空气小，所以会往上走。", "target_word": "密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料的密度低，用它做的箱子很轻。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头的密度比水小，放进水里就浮起来了。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "知道了质量和体积，就能算出密度。", "target_word": "密度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口密度", "label": "复合"}, {"form": "密度计", "label": "复合"}], "register": "中性", "sense_fingerprint": "科学义：单位体积物质的质量（质量÷体积）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "正确：“密度”可以比较大小，“水的密度比油大”说明同体积的水更重，所以油会浮在上面。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说深浅，不能用“大”来比较。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是钱数，与“浮在水上”的物理现象无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：水和油的名字不能比较大小，与句子的意思无关。"}], "explanations": {"密度": "正确：“密度”可以比较大小，“水的密度比油大”说明同体积的水更重，所以油会浮在上面。", "颜色": "搭配：“颜色”说深浅，不能用“大”来比较。", "价格": "语义：“价格”是钱数，与“浮在水上”的物理现象无关。", "名字": "语义：水和油的名字不能比较大小，与句子的意思无关。"}, "sentence_index": 0, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们称一下这块石头的密度。", "explanation": "这里应该用〈质量〉。称的是质量，密度要通过测量或计算得出，不能称。"}, {"text": "这块石头的密度很深，很好看。", "explanation": "这里应该用〈颜色〉。密度说“大”“高”，“深”说的是颜色的浓淡。"}, {"text": "这块石头的密度很贵，我们买不起。", "explanation": "这里应该用〈价格〉。密度说大小高低，不说“贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密度", "is_correct": true, "explanation": "正确：“密度”比较大小，“热空气的密度比冷空气小”正是热空气上升的原因。"}, {"text": "温度", "is_correct": false, "explanation": "语义：热空气的温度比冷空气小，与“热”的前提矛盾。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”只用于人或生物，空气没有年龄，与句意不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”说气味或口味，与空气往上走的原因无关，句子因果不通。"}], "explanations": {"密度": "正确：“密度”比较大小，“热空气的密度比冷空气小”正是热空气上升的原因。", "温度": "语义：热空气的温度比冷空气小，与“热”的前提矛盾。", "年龄": "语义：“年龄”只用于人或生物，空气没有年龄，与句意不符。", "味道": "语义：“味道”说气味或口味，与空气往上走的原因无关，句子因果不通。"}, "sentence_index": 6, "correct_answer": "密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "知道了路程和时间，就能算出密度。", "explanation": "这里应该用〈速度〉。速度由路程和时间算出，密度要用质量和体积算。"}, {"text": "知道了长和宽，就能算出密度。", "explanation": "这里应该用〈面积〉。面积由长和宽算出，密度不能由长和宽得出。"}, {"text": "知道了工作时间，就能算出密度。", "explanation": "这里应该用〈工资〉。工资由工作时间和单价共同算出，密度不能由时间得出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种塑料的密度很轻，所以它能浮在水上。", "corrected_sentence": "这种塑料的密度很小，所以它能浮在水上。", "error_description": "错误：“很轻”。正确：“很小”。密度说大小，“轻”说的是重量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种泡沫的密度跟水小，所以能浮在水上。", "corrected_sentence": "这种泡沫的密度比水小，所以能浮在水上。", "error_description": "错误：“跟”。正确：“比”。比较密度的高低要用“比”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
