INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写本是用手写下来的书。", "primary_collocate": null, "pronunciation": "xiě běn", "ipa": "ɕjɛ˨˩˦ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "写本是人用手一个字一个字写下来的书。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前没有机器，书都是写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸收藏了几本旧写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本写本上有很多小字。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抄写这本写本花了他三年。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看那本写本里写了什么。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本写本的纸已经黄了。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把写本放进了书架。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本写本是一位老人写的。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，有钱人才买得起写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "手写本", "label": "复合"}], "register": "书面语", "sense_fingerprint": "用手抄写成的书（书的制作方式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写本", "is_correct": true, "explanation": "正确：“写本”就是用手抄写成的书，与句中的描述一致。"}, {"text": "印刷本", "is_correct": false, "explanation": "语义：“印刷本”是印出来的，不是人用手一个字一个字写的。"}, {"text": "电子书", "is_correct": false, "explanation": "语义：“电子书”是电子格式，不是人用手写下来的。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“墨水”是书写材料，不是书，不能说“墨水是……的书”。"}], "explanations": {"写本": "正确：“写本”就是用手抄写成的书，与句中的描述一致。", "印刷本": "语义：“印刷本”是印出来的，不是人用手一个字一个字写的。", "电子书": "语义：“电子书”是电子格式，不是人用手写下来的。", "墨水": "搭配：“墨水”是书写材料，不是书，不能说“墨水是……的书”。"}, "sentence_index": 0, "correct_answer": "写本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在网上买了一本写本，是电子版的。", "explanation": "这里是〈电子书〉的意思。写本是用手写下来的书，不能指电子版的书。"}, {"text": "我每天看的那本写本是一份日历，挂在墙上。", "explanation": "这里是〈日历〉的意思。写本是用手写下来的书，不能指挂在墙上的日历。"}, {"text": "这本写本是机器印刷的，每页都一样。", "explanation": "这里应该用〈印刷本〉。写本是用手抄写成的书，与印刷本相对，不能说是机器印刷的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写本", "is_correct": true, "explanation": "正确：“写本”是手写的书，有纸，所以纸会发黄，符合句意。"}, {"text": "网页", "is_correct": false, "explanation": "语义：“网页”是屏幕上的内容，没有纸，纸不会发黄。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”没有纸，不可能“纸已经黄了”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”不能用量词“本”，“歌曲的纸”也说不通。"}], "explanations": {"写本": "正确：“写本”是手写的书，有纸，所以纸会发黄，符合句意。", "网页": "语义：“网页”是屏幕上的内容，没有纸，纸不会发黄。", "手机": "语义：“手机”没有纸，不可能“纸已经黄了”。", "歌曲": "搭配：“歌曲”不能用量词“本”，“歌曲的纸”也说不通。"}, "sentence_index": 6, "correct_answer": "写本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他递给我的那本写本，原来是一张名片。", "explanation": "这里是〈名片〉的意思。写本是用手写下来的书，不能指一张名片。"}, {"text": "这本写本是一张照片，挂在墙上。", "explanation": "这里是〈照片〉的意思。写本是用手写下来的书，不能指挂在墙上的照片。"}, {"text": "这本写本是一份广告，夹在报纸里。", "explanation": "这里是〈广告〉的意思。写本是用手写下来的书，不能指夹在报纸里的广告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在旧书店里找到了一张写本。", "corrected_sentence": "我在旧书店里找到了一本写本。", "error_description": "量词错误：“写本”是成册的书，应用“本”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些写本地字很小。", "corrected_sentence": "那些写本的字很小。", "error_description": "结构助词错误：“写本”修饰名词“字”要用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
