INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手写的书本，区别于印刷本。", "primary_collocate": null, "pronunciation": "xiě běn", "ipa": "ɕjɛ˨˩˦ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "学者们常研究写本，因为它保留了手迹。", "target_word": "写本", "complexity_tier": "T3", "furigana": "xuézhěmen cháng yánjiū xiěběn, yīnwèi tā bǎoliú le shǒujì.", "sentence_source": "generated"}, {"text": "博物馆里有一本很老的写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷本很多，写本却很少。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本写本的字很漂亮。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆看到了一本古代的写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写本和印刷本不一样，每本都有一点不同。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本写本是一百年前的，要小心拿。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一本古老的写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为没有印刷本，学者只能读写本。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本写本放在玻璃盒里，不能摸。", "target_word": "写本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "手写本", "label": "复合"}], "register": "书面语", "sense_fingerprint": "手写的书，与印刷本相对（版本类型）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写本", "is_correct": true, "explanation": "正确：“写本”是手写的书，才能保留手迹。"}, {"text": "印刷本", "is_correct": false, "explanation": "语义：“印刷本”是印刷出来的，不会保留手迹。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：“报纸”是印刷品，不保留作者的手迹。"}, {"text": "光盘", "is_correct": false, "explanation": "语义：“光盘”是存储数据的载体，不会保留手写的笔迹。"}], "explanations": {"写本": "正确：“写本”是手写的书，才能保留手迹。", "印刷本": "语义：“印刷本”是印刷出来的，不会保留手迹。", "报纸": "语义：“报纸”是印刷品，不保留作者的手迹。", "光盘": "语义：“光盘”是存储数据的载体，不会保留手写的笔迹。"}, "sentence_index": 0, "correct_answer": "写本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本写本是机器印出来的，每页都一样。", "explanation": "这里是〈印刷本〉的意思。写本指手写的书，与印刷本相对，不能用来指机器印刷的书。"}, {"text": "这本写本是我的作业本，上面画满了红叉。", "explanation": "这里是〈作业本〉的意思。写本指手写成册的书，不能用来指学生的作业本。"}, {"text": "这本写本是电子版的，可以在手机上看。", "explanation": "这里是〈电子书〉的意思。写本是手写成册的书，不能指电子版的书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写本", "is_correct": true, "explanation": "正确：“写本”是手写的书，有一百年历史、需要小心拿，符合句意。"}, {"text": "电子书", "is_correct": false, "explanation": "语义：“电子书”是电子格式，没有实物，不会“一百年前的”，也不需要“小心拿”。"}, {"text": "网页", "is_correct": false, "explanation": "语义：“网页”没有实物，不能说“要小心拿”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”不能用量词“本”，而且“要小心拿”不适合歌曲。"}], "explanations": {"写本": "正确：“写本”是手写的书，有一百年历史、需要小心拿，符合句意。", "电子书": "语义：“电子书”是电子格式，没有实物，不会“一百年前的”，也不需要“小心拿”。", "网页": "语义：“网页”没有实物，不能说“要小心拿”。", "歌曲": "搭配：“歌曲”不能用量词“本”，而且“要小心拿”不适合歌曲。"}, "sentence_index": 6, "correct_answer": "写本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅挂画是名家的写本，很值钱。", "explanation": "这里是〈字画〉的意思。写本是手写成册的书，不能指挂在墙上的字画。"}, {"text": "这本写本是今天的报纸，上面有很多新闻。", "explanation": "这里是〈报纸〉的意思。写本是手写成册的书，不能指印刷的报纸。"}, {"text": "这本写本是一首流行歌，我每天都在听。", "explanation": "这里是〈歌曲〉的意思。写本是手写成册的书，不能指一首歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆收藏了一张很老的写本。", "corrected_sentence": "图书馆收藏了一本很老的写本。", "error_description": "量词错误：“写本”是成册的书，应用“本”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些写本地内容很有价值。", "corrected_sentence": "这些写本的内容很有价值。", "error_description": "结构助词错误：“写本”修饰“内容”要用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
