INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96183, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "市两是一种量东西有多重的单位。", "primary_collocate": null, "pronunciation": "shì liǎng", "ipa": "ʂɻ̩⁵¹ ljɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这个苹果大约有四市两重。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我称二市两糖。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟只有一市两重。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这包盐是五市两。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每顿只喝二市两白酒。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店老板称了三市两枸杞。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肉不到八市两。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了七市两瓜子。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一小袋米大概三市两。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秤上显示这块蛋糕有六市两。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市兩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "称东西轻重时用的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市两", "is_correct": true, "explanation": "正确：“这个苹果大约有四市两重”，重量单位符合语境。"}, {"text": "斗", "is_correct": false, "explanation": "搭配：“斗”是容量单位，与“重”搭配不当。"}, {"text": "亩", "is_correct": false, "explanation": "语义：“亩”是面积单位，不能用来表示重量。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：“厘米”是长度单位，不能用来表示重量。"}], "explanations": {"市两": "正确：“这个苹果大约有四市两重”，重量单位符合语境。", "斗": "搭配：“斗”是容量单位，与“重”搭配不当。", "亩": "语义：“亩”是面积单位，不能用来表示重量。", "厘米": "语义：“厘米”是长度单位，不能用来表示重量。"}, "sentence_index": 0, "correct_answer": "市两"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了五市两的路。", "explanation": "这里应该用〈公里〉。市两只用于称重，不能表示路程的长度。"}, {"text": "妈妈给我五市两的零花钱。", "explanation": "这里应该用〈块〉。市两是重量单位，不能计量钱数。"}, {"text": "他今年已经五市两了。", "explanation": "这里应该用〈岁〉。市两是重量单位，不能表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市两", "is_correct": true, "explanation": "正确：“这块肉不到八市两”，用重量单位计量肉的分量，符合语境。"}, {"text": "公里", "is_correct": false, "explanation": "语义：“公里”是长度单位，不能用来计量肉的重量。"}, {"text": "毫米", "is_correct": false, "explanation": "语义：“毫米”是长度单位，不能用来计量肉的重量。"}, {"text": "立方米", "is_correct": false, "explanation": "搭配：“立方米”是体积单位，与称肉的重量说法搭配不当。"}], "explanations": {"市两": "正确：“这块肉不到八市两”，用重量单位计量肉的分量，符合语境。", "公里": "语义：“公里”是长度单位，不能用来计量肉的重量。", "毫米": "语义：“毫米”是长度单位，不能用来计量肉的重量。", "立方米": "搭配：“立方米”是体积单位，与称肉的重量说法搭配不当。"}, "sentence_index": 6, "correct_answer": "市两"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在门口等了六市两。", "explanation": "这里应该用〈分钟〉。市两是重量单位，不能用来计量时间。"}, {"text": "这栋楼有六市两高。", "explanation": "这里应该用〈米〉。市两只表示重量，不能表示高度。"}, {"text": "他每天早上跑六市两。", "explanation": "这里应该用〈公里〉。市两是重量单位，不能用来计量跑步的距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把芹菜大约有三个市两重。", "corrected_sentence": "这把芹菜大约有三市两重。", "error_description": "量词重复：“市两”前面不能再加“个”，应说“三市两”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块羊肉不到八个市两重。", "corrected_sentence": "这块羊肉不到八市两重。", "error_description": "量词重复：“市两”前面不能再加“个”，应说“八市两”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
