INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96184, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "市制重量单位，一市两为十钱，约合五十克。", "primary_collocate": null, "pronunciation": "shì liǎng", "ipa": "ʂɻ̩⁵¹ ljɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这包茶叶有三市两重。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一市两大约是五十克。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板给我称了五市两花生。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一市两等于十钱。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块金子只有二市两重。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副药里要放三市两红枣。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶一市两卖二十块。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天吃四市两米饭。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了六市两香菇。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一市斤等于十市两。", "target_word": "市两", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市兩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "市制重量单位，一市两约五十克", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市两", "is_correct": true, "explanation": "正确：“市两”是重量单位，“这包茶叶有三市两重”符合语境。"}, {"text": "寸", "is_correct": false, "explanation": "语义：“寸”是长度单位，不能用来表示重量。"}, {"text": "升", "is_correct": false, "explanation": "搭配：“升”是容量单位，与“重”搭配不当。"}, {"text": "尺", "is_correct": false, "explanation": "语义：“尺”是长度单位，不能用来表示重量。"}], "explanations": {"市两": "正确：“市两”是重量单位，“这包茶叶有三市两重”符合语境。", "寸": "语义：“寸”是长度单位，不能用来表示重量。", "升": "搭配：“升”是容量单位，与“重”搭配不当。", "尺": "语义：“尺”是长度单位，不能用来表示重量。"}, "sentence_index": 0, "correct_answer": "市两"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里来了三市两人，正在开会。", "explanation": "这里应该用〈位〉。市两只用于称重，计算人数要用“位”。"}, {"text": "我们家的房子有三市两大。", "explanation": "这里应该用〈平方米〉。市两只表示重量，不能描述房子的大小。"}, {"text": "他身高一市两，比同龄人矮很多。", "explanation": "这里应该用〈厘米〉。身高用长度单位，市两是重量单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市两", "is_correct": true, "explanation": "正确：“这种茶叶一市两卖二十块”，按重量计价，符合语境。"}, {"text": "公里", "is_correct": false, "explanation": "语义：“公里”是长度单位，不能用来计算茶叶的重量和价格。"}, {"text": "毫米", "is_correct": false, "explanation": "语义：“毫米”是长度单位，与茶叶的计价无关。"}, {"text": "平方米", "is_correct": false, "explanation": "搭配：“平方米”是面积单位，与按重量计价的说法搭配不当。"}], "explanations": {"市两": "正确：“这种茶叶一市两卖二十块”，按重量计价，符合语境。", "公里": "语义：“公里”是长度单位，不能用来计算茶叶的重量和价格。", "毫米": "语义：“毫米”是长度单位，与茶叶的计价无关。", "平方米": "搭配：“平方米”是面积单位，与按重量计价的说法搭配不当。"}, "sentence_index": 6, "correct_answer": "市两"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们等了三市两才上车。", "explanation": "这里应该用〈分钟〉。市两是重量单位，不能用来计量时间。"}, {"text": "今天的气温有六市两。", "explanation": "这里应该用〈度〉。市两只表示重量，不能表示气温。"}, {"text": "这块地一共有三市两。", "explanation": "这里应该用〈亩〉。市两是重量单位，不能用来计量土地面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋花生有三个市两重。", "corrected_sentence": "这袋花生有三市两重。", "error_description": "量词重复：“市两”本身就是量词，前面不能再加“个”，应说“三市两”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盒糖果有一个市两重。", "corrected_sentence": "这盒糖果有一市两重。", "error_description": "量词重复：“市两”本身就是量词，前面不能再加“个”，应说“一市两”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
