INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人坐的位置。", "primary_collocate": null, "pronunciation": "zuò wèi", "ipa": "tsuo˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "飞机上的座位很窄，腿伸不开。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车上有一个空座位。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会的座位已经卖完了。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我提前订了两个座位。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站起来，把座位让给了老人。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前排的座位比后排的贵。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在会议室里找了一个座位坐下。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育场里有五万个座位。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请回到你的座位上，比赛马上开始。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里没有座位，大家都站着。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个座位", "label": "量词"}, {"form": "座位号", "label": "复合"}], "register": "中性", "sense_fingerprint": "供人坐的位置，可以订、让、回到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ce3a876-3c1d-44d7-b39d-01649e9db7d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "座位", "is_correct": true, "explanation": "座位是供人坐的位置，可以“很窄”，也能让腿“伸不开”。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不能用“很窄、腿伸不开”来描述，与句意冲突。"}, {"text": "乘客", "is_correct": false, "explanation": "体貌：“很窄”用于物体的宽窄，不用来形容人的体型。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是有形的物体，无法“很窄”，与“腿伸不开”冲突。"}], "explanations": {"座位": "座位是供人坐的位置，可以“很窄”，也能让腿“伸不开”。", "行李": "语义：行李是物品，不能用“很窄、腿伸不开”来描述，与句意冲突。", "乘客": "体貌：“很窄”用于物体的宽窄，不用来形容人的体型。", "天气": "语义：天气不是有形的物体，无法“很窄”，与“腿伸不开”冲突。"}, "sentence_index": 0, "correct_answer": "座位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间宿舍住着四个座位。", "explanation": "这里应该用〈人〉。座位是供人坐的地方，不能用来住。"}, {"text": "他在工厂的座位很重要。", "explanation": "这里应该用〈岗位〉。座位只指供人坐的地方，工作岗位要用岗位。"}, {"text": "我订了两本座位。", "explanation": "这里应该用〈个〉。座位要用“个”计量，“本”用于书册。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座位", "is_correct": true, "explanation": "座位是供人坐的位子，与“找了一个……坐下”搭配。"}, {"text": "问题", "is_correct": false, "explanation": "语义：问题是抽象的，不能让人在上面“坐下”。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是一串地点信息，不能让人“找了”后“坐下”。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“找”的对象是具体的地方，“时间”不能被找来坐。"}], "explanations": {"座位": "座位是供人坐的位子，与“找了一个……坐下”搭配。", "问题": "语义：问题是抽象的，不能让人在上面“坐下”。", "地址": "语义：地址是一串地点信息，不能让人“找了”后“坐下”。", "时间": "搭配：“找”的对象是具体的地方，“时间”不能被找来坐。"}, "sentence_index": 6, "correct_answer": "座位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "停车场里有很多座位。", "explanation": "这里应该用〈车位〉。座位指供人坐的地方，停车的位置要用车位。"}, {"text": "这套房子有三个座位。", "explanation": "这里应该用〈卧室〉。座位只供人坐，房间要用卧室或房间。"}, {"text": "这名球员的座位在中场，最合适。", "explanation": "这里应该用〈位置〉。座位指供人坐的地方，球员在场上的站位要用位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在网上订了两张座位。", "corrected_sentence": "我昨天在网上订了两个座位。", "error_description": "“座位”计量用“个”，“张”不能用于座位，应为“两个座位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地铁里的座位都坐了满。", "corrected_sentence": "地铁里的座位都坐满了。", "error_description": "“坐满”是动补结构，“了”应放在“满”后，“坐了满”语序错误，应为“坐满了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
