INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "弥补是对已经做错的事、造成的过失或遗憾设法挽回补救。", "primary_collocate": null, "pronunciation": "mí bǔ", "ipa": "mi˧˥ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他做错了事，想马上弥补。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意做任何事来弥补我的错误。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一年的时间弥补了当年的过失。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你伤了朋友的心，要想办法弥补。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没陪孩子过生日，只好用礼物弥补。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个遗憾，他一直没有机会弥补。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向客户道歉，并努力弥补服务中的失误。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了就要弥补，不能只说对不起。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想弥补自己对家人犯的错。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，现在开始努力，还来得及弥补。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弥补了", "label": "体标"}, {"form": "弥补过", "label": "体标"}, {"form": "弥补不了", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "对做错的事、过失、遗憾设法补救、挽回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弥补", "is_correct": true, "explanation": "弥补：把做错的事补救回来，与“做错了事”和“马上”相合。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”是推迟，与“马上”矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是快乐、生活，不能说享受“错事”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏美好的事物，与“做错了事”不合。"}], "explanations": {"弥补": "弥补：把做错的事补救回来，与“做错了事”和“马上”相合。", "拖延": "语义：“拖延”是推迟，与“马上”矛盾。", "享受": "搭配：“享受”的对象是快乐、生活，不能说享受“错事”。", "欣赏": "语义：“欣赏”是赞赏美好的事物，与“做错了事”不合。"}, "sentence_index": 0, "correct_answer": "弥补"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师弥补了他的鞋子。", "explanation": "这里应该用〈擦〉。弥补用于补救过失或遗憾，擦鞋要用擦。"}, {"text": "他愤怒的时候，常常弥补心中的怒气。", "explanation": "这里应该用〈发泄〉。弥补是补救过失，释放怒气要用发泄。"}, {"text": "他弥补了犯错的学生，让他罚站。", "explanation": "这里应该用〈惩罚〉。弥补是补救过错，处罚犯错的人要用惩罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弥补", "is_correct": true, "explanation": "弥补：努力补救服务中的失误，与“失误”和“道歉”后的补救相合。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不说提高“失误”。"}, {"text": "加强", "is_correct": false, "explanation": "搭配：“加强”用于管理、能力，不说加强“失误”。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是为喜事举行活动，与“失误”相反。"}], "explanations": {"弥补": "弥补：努力补救服务中的失误，与“失误”和“道歉”后的补救相合。", "提高": "搭配：“提高”用于水平、质量，不说提高“失误”。", "加强": "搭配：“加强”用于管理、能力，不说加强“失误”。", "庆祝": "语义：“庆祝”是为喜事举行活动，与“失误”相反。"}, "sentence_index": 6, "correct_answer": "弥补"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在笔记本上弥补了一幅画。", "explanation": "这里应该用〈画〉。弥补用于补救过失或遗憾，在本子上画图要用画。"}, {"text": "他仔细检查后，弥补了报告里的一个图表。", "explanation": "这里应该用〈删除〉。弥补用于补救过失或遗憾，去掉报告里的图表要用删除。"}, {"text": "雾气弥补了整片山谷。", "explanation": "这里应该用〈笼罩〉。弥补是补救过失或补足缺口，雾气覆盖一片地方要用笼罩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做错了事，就该努力弥补了过失。", "corrected_sentence": "他做错了事，就该努力弥补过失。", "error_description": "“了”误用：“就该”表示应当去做，还没有发生，不能与表示已完成的“了”搭配。正确：就该努力弥补过失。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
